// Agent-health watchdog (#2541) — the piece that GENERATES the Glance "warning" from live agent state,
// not from a crash. A `bsc-wait` (an EXPECTED pause for the user) is calm while it's fresh — the project
// reads activity "waiting". But once a wait OVERSTAYS its welcome (no instructions for N minutes), it's a
// stall the user should be pulled to: it escalates the project to health "warning" (orange dot) with a
// duration reason ("<note> · Nm"), which the existing dot+reason pipeline renders for free.
//
// Deliberately NOT routed through errordb / the fault-triage fix loop (#2265): a "no instructions" stall
// needs the USER to act, not a fix dispatched to the director. It's an ephemeral, derived health overlay
// (like liveness, #2263) — it clears the instant the agent resumes. Pure; `now` is injected for testing.
import type { ProjectLite } from "@/features/glance/lib/glanceData";
import type { GHealth, GActivity, GRawNode } from "@/features/glance/lib/glanceGraph";
import { fleetPaneId } from "@/app/console/lib/paneIdentity";

/** A `bsc-wait` parked longer than this escalates from the calm "waiting" activity to an orange
 *  "warning" health. 10 min — long enough that a normal think/confirm pause stays calm. Overridable per
 *  call so a Settings field can drive it later (#2541 follow-up). */
export const STALL_WARN_MS = 10 * 60_000;

/** The minimal waiting-session shape the watchdog reads — a projection of `CoordState.waiting`. */
export interface WaitLite { session: string; reason: string; at: number }

/** The project (plan) key that owns a session/pane id — everything before the first ':' (pane ids are
 *  `<key>:<stream>` / `<key>:director` / `<key>:<repo>:triage`, all prefixed by the plan key, #2409). */
export function projectKeyOfSession(session: string): string {
  const i = session.indexOf(":");
  return i < 0 ? session : session.slice(0, i);
}

/**
 * Keep only the waits whose session still EXISTS (#3429) — the liveness guard the L0 watchdog was missing.
 *
 * `CoordState.waiting` is a replay of the coord log: an entry is cleared only by a LATER event from that
 * same session, and killing a pane emits none. So a wait parked by a long-dead agent stayed outstanding
 * forever while `now - w.at` only grew, pinning its project orange permanently — a `warning` that no longer
 * described anything. A session that no longer exists cannot be waiting on the user.
 *
 * `livePaneIds` is the same pruned set the L1 overlay reads (tab membership minus ended/disabled panes), so
 * both layers decide "does this session exist?" from one signal. Pure.
 */
export function liveWaits(waiting: WaitLite[], livePaneIds: ReadonlySet<string>): WaitLite[] {
  return waiting.filter((w) => livePaneIds.has(w.session));
}

const worse = (a: GHealth, b: GHealth): boolean => a === "error" && b !== "error";

/**
 * Escalate PARKED agents onto the Glance node axes (#2541 watchdog). Per project the OLDEST outstanding
 * `bsc-wait` decides: while it's under `warnMs` the project reads a calm activity "waiting"; once it
 * exceeds `warnMs` it escalates to health "warning" with a "<note> · Nm" reason. Only ever ESCALATES
 * health (never downgrades an already-worse state). Pure.
 *
 * Apply BEFORE the errordb fault overlay (`applyFaultHealth`) so a real error still beats a stall.
 */
export function applyStallHealth(projects: ProjectLite[], waiting: WaitLite[], now: number, warnMs = STALL_WARN_MS): ProjectLite[] {
  if (waiting.length === 0) return projects;
  const oldest = new Map<string, WaitLite>();
  for (const w of waiting) {
    const key = projectKeyOfSession(w.session);
    const prev = oldest.get(key);
    if (!prev || w.at < prev.at) oldest.set(key, w);
  }
  return projects.map((p) => {
    const w = oldest.get(p.id);
    if (!w) return p;
    const elapsed = now - w.at;
    if (elapsed < warnMs) return { ...p, activity: "waiting" }; // fresh, expected pause — stays calm
    const minutes = Math.max(1, Math.floor(elapsed / 60_000));
    const note = w.reason?.trim() || "no instructions";
    const health: GHealth = worse(p.health ?? "healthy", "warning") ? (p.health as GHealth) : "warning";
    return { ...p, activity: "waiting", health, reason: `${note} · ${minutes}m` };
  });
}

/** The live signals a fleet-drill (L1) node reads to lift off its planned rest state (#3252). All keyed by
 *  the node's PANE id (`fleetPaneId` → `<project>:<stream>` / `<project>:director`). */
export interface FleetLiveSignals {
  /** Launched-tab membership — the session cell exists + is openable (`livePaneIds`). */
  livePaneIds: ReadonlySet<string>;
  /** Per-pane run status — `"run"` while the session is actively working (the console's aggregate state). */
  paneStatus: Record<string, string>;
  /** Parked `bsc-wait` sessions (from `CoordState.waiting`). */
  waiting: WaitLite[];
  /** Panes STOPPED at a permission prompt / input wait (#4005) — Claude Code's `Notification` hook,
   *  recorded as `bsc-activity attn` and read back from `bsc logs pane-activity`. Keyed by pane id.
   *  Nothing else in the app could see this state: such a pane is not `run` and has no `bsc-wait`, so
   *  it fell through to plain `idle` and looked identical to a session that had simply finished. */
  attention?: ReadonlySet<string>;
  /** Sessions PARKED IN MAINTENANCE (#4010) — `bsc-maintain` (#1957): every owned issue is done, the
   *  worker stays alive and ready for the director to dispatch into. Keyed by pane id.
   *
   *  Modelled explicitly rather than left to fall through to `idle`, because a parked session's TUI is
   *  still alive: whether it reads `run` is a timing accident, and on the wrong side of that accident a
   *  finished worker keeps the building outline forever. */
  maintaining?: ReadonlySet<string>;
  /** Panes the auto-end marked FINISHED (#4027) — `bsc-done` → `endedPanes`, valued by the verdict
   *  plan.db gave (`done` / `needs-attention` / `blocked`), not the worker's say-so. Keyed by pane id.
   *
   *  Needed here because `livePaneIds` EXCLUDES ended panes, so without this an ended worker falls
   *  through to `off` — indistinguishable from one that never launched. */
  ended?: Record<string, { state: string }>;
  /** Epoch now — injected (impure in render). */
  now: number;
  /** Stall threshold; a wait beyond it escalates to `warning`. Defaults to {@link STALL_WARN_MS}. */
  warnMs?: number;
  /** QUARANTINED panes (#3916) — the warden hard-paused these: it killed the PTY and marked why. Keyed
   *  by pane id, valued by the summary the warden recorded. Until now quarantine was invisible in Glance
   *  (grep found no handling outside `resumeProject`'s comments), so a hard-paused worker read as a plain
   *  `off` node — indistinguishable from one that was simply never launched. */
  quarantined?: Record<string, { summary?: string }>;
  /** HELD streams (#3931) — the dependency gate refused to start these because an upstream has not
   *  landed. Keyed by STREAM id (not pane id: there is no pane, that is the point). Same argument as
   *  quarantine: a held stream has no session, so it fell through to a plain `off` node and was
   *  indistinguishable from one that was never planned — the user could not tell "waiting its turn"
   *  from "broken". A `deadlocked` stream is an ERROR (it can never start on its own); an ordinary
   *  held one stays `off` but now carries the reason that explains itself. */
  held?: Record<string, { reason: string; deadlocked: boolean }>;
}

/**
 * Overlay the LIVE session state onto a project's fleet-drill (L1) agent nodes (#3252, the #2541 axes) —
 * the agent twin of the L0 {@link applyStallHealth}. Each node is keyed by its pane id
 * `fleetPaneId(projectKey, node.id)`, and its OWN health/activity is set from what its session is doing NOW:
 *
 *   - not launched (NO session exists)           → off · idle
 *   - launched + running (`paneStatus === "run"`) → healthy · building
 *   - launched + parked on a fresh `bsc-wait`    → healthy · waiting
 *   - that wait overstayed `warnMs`              → warning · waiting (reason "<note> · Nm")
 *   - launched but quiet (between prompts)       → idle · idle  (it EXISTS but is not working)
 *
 * The `preview` node (not an agent) is left untouched. The director gets the same treatment via
 * `<project>:director`, so it finally moves off idle. Pure — apply to `rawNodes` BEFORE `buildGraph` so the
 * dependency rollup + inherited-health recompute over the live values.
 */
export function applyFleetLiveStatus(nodes: GRawNode[], projectKey: string, sig: FleetLiveSignals): GRawNode[] {
  const warnMs = sig.warnMs ?? STALL_WARN_MS;
  const waitByPane = new Map(sig.waiting.map((w) => [w.session, w] as const));
  return nodes.map((n) => {
    if (n.preview) return n; // not an agent — its own healthy/live state stands
    const paneId = fleetPaneId(projectKey, n.id);
    // FINISHED BY THE PLAN (#4124) — every issue this node owns is done.
    //
    // Completion was derived ONLY from runtime session signals: an `ended` verdict of `done`, or an
    // explicit maintenance park. Both are ephemeral — they describe a session, and a session ends. The
    // issues do not: a worker that finished its lane last week still finished it, whether or not
    // anything is running now. So the two QUIET branches below (no session / live but idle) read this
    // first, and a node whose work is done stops reporting `idle`, which is what a node with nothing to
    // do also reports. Live-WORKING and blocked-on-a-person states still outrank it: what a session is
    // doing right now is the more urgent fact, and a worker parked on a question is still parked.
    // Two sources, because neither is complete alone. The PLAN says every owned issue is closed. A
    // `maintain` record says the worker itself declared it finished and stood by (#1957) — durable
    // evidence it got there, and for a fleet whose plan.db carries no issue rows it is the ONLY
    // evidence. Measured: 34 panes have emitted `maintain`.
    const finished =
      (!!n.progress && n.progress.total > 0 && n.progress.done >= n.progress.total) ||
      !!sig.maintaining?.has(paneId);
    const asFinished = (reason: string) =>
      ({ ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason });
    // QUARANTINE FIRST (#3916): the warden kills the PTY when it quarantines, so a quarantined pane is
    // never in `livePaneIds` and would otherwise fall through to `off` — reading as "never launched"
    // rather than "hard-paused, here is why". It must outrank every other state: this is the one the
    // user has to act on, and Resume deliberately refuses to relaunch it.
    const q = sig.quarantined?.[paneId];
    if (q) {
      return {
        ...n,
        health: "error" as GHealth,
        activity: "idle" as GActivity,
        reason: q.summary?.trim() || "quarantined by the warden",
      };
    }
    // HELD BY THE DEPENDENCY GATE (#3931) — checked before the plain `off` fall-through for exactly the
    // reason quarantine is: a held stream has no pane, so it would render as an anonymous dark node and
    // the user would have no way to tell "waiting on its upstream" from "never planned". A DEADLOCK is
    // an error the user must fix (the plan's `dependsOn` has a cycle, so it can never start on its own);
    // an ordinary hold is not a fault, so it keeps `off` health and just explains itself.
    const h = sig.held?.[n.id];
    if (h && !sig.livePaneIds.has(paneId)) {
      return {
        ...n,
        health: (h.deadlocked ? "error" : "off") as GHealth,
        activity: "waiting" as GActivity,
        reason: h.reason,
      };
    }
    // FINISHED (#4027) — above the `off` fall-through on purpose, and for the same reason quarantine
    // and held are: `livePaneIds` excludes ended panes, so a worker that completed every issue it owned
    // would render as `off` — exactly what a NEVER-LAUNCHED node looks like. The one state that has
    // earned a distinct reading would be the one state that loses it.
    //
    // Only a `done` verdict reads complete. `needs-attention` / `blocked` are endings too, but they are
    // endings that want a person — they keep falling through to the states that say so.
    const endState = sig.ended?.[paneId]?.state;
    if (endState === "done") {
      return { ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason: "every owned issue complete" };
    }

    // NOT LAUNCHED — there is no session behind this node. That is `off`, not `idle`: the two states
    // were indistinguishable while both rendered idle, so a node with no session read as one that was
    // merely quiet, and its empty log view looked like a broken log rather than an absent session.
    // `off` = no session exists · `idle` = a session exists but is not working · `healthy` = working.
    if (!sig.livePaneIds.has(paneId)) {
      // #4124: `off` is "never launched". A worker that finished everything and whose session has since
      // been reclaimed is not that, and rendering it identically loses the one state that was earned.
      return finished
        ? asFinished("every owned issue complete — no session running")
        : { ...n, health: "off" as GHealth, activity: "idle" as GActivity };
    }
    // BLOCKED ON A PERSON (#4005) — a `bsc-wait` park, or a session stopped at a permission prompt.
    //
    // A wait used to read `healthy` (green, calm) for ten minutes and only then flip to `warning`.
    // Both readings were wrong in the same way: green says "nothing to do" about a session that is
    // waiting on YOU, and orange says "something is degrading" about a normal hand-off. It is neither
    // — it is a request, so it gets its own health. The elapsed-time note is kept, because how long it
    // has been waiting is still worth knowing; it is just no longer the thing that makes it visible.
    const wait = waitByPane.get(paneId);
    if (wait) {
      const elapsed = sig.now - wait.at;
      const note = wait.reason?.trim() || "no instructions";
      const minutes = Math.max(1, Math.floor(elapsed / 60_000));
      const reason = elapsed >= warnMs ? `${note} · ${minutes}m` : note;
      // #4046 — `healthy` health, `waiting` activity. Nothing is WRONG with a worker parked on a
      // question; it is doing a thing called waiting. The reason string still says what it waits on.
      return { ...n, health: "healthy" as GHealth, activity: "waiting" as GActivity, reason };
    }
    if (sig.attention?.has(paneId)) {
      return {
        ...n,
        health: "healthy" as GHealth,
        activity: "waiting" as GActivity,
        reason: "stopped for you — permission prompt or awaiting input",
      };
    }
    // PARKED IN MAINTENANCE (#4010) — before the run->building branch, deliberately. A maintaining
    // worker's session is still alive, so `paneStatus` may well read "run"; checked after, it would
    // keep the building outline forever despite having finished everything it owns.
    //
    // It stays BELOW the wait/attention branches: a park needs a person, standing-by does not. The
    // RECLAIMED case (session gone) is handled at the liveness gate instead, via `finished` — putting
    // this whole branch above that gate would have let maintenance outrank a `bsc-wait`.
    //
    // It renders as the PLAIN node — no outline, no pulse — because there is nothing for anyone to do
    // about it. The explanation rides in `reason`, which the hover title and the inspector's REASON
    // tile both show, so the state is still discoverable without being loud.
    if (sig.maintaining?.has(paneId)) {
      // #4027: `complete`, not `idle`. A worker standing by having finished everything it owns and one
      // that happens to be quiet are different facts, and they used to render as the same word.
      return { ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason: "maintenance — owned issues complete, standing by for dispatch" };
    }
    if (sig.paneStatus[paneId] === "run") return { ...n, health: "healthy" as GHealth, activity: "building" as GActivity };
    // Launched, but not working: the session EXISTS and is quiet ⇒ `idle` on both axes. It used to read
    // `healthy` here ("subtly live"), which collided with a genuinely working session — and left `idle`
    // free to be misread as the no-session state. Health now tracks existence + work, not mere launch.
    // #4042 — `healthy`, not `idle`: the session EXISTS and nothing is wrong, which is what healthy
    // means. The activity word still says `idle`, so "at rest" is not lost — the two axes just stop
    // saying the same thing twice.
    // #4124: a live session with nothing left to do is COMPLETE, not merely quiet. `idle` is the word
    // for "a session exists and is not working", which is true here but is the least of what is true.
    return finished
      ? asFinished("every owned issue complete")
      : { ...n, health: "healthy" as GHealth, activity: "idle" as GActivity };
  });
}

tests.src:
import { describe, it, expect } from "vitest";
import { ACTIVITY_META } from "@/features/glance/lib/glanceGraph";
import { applyStallHealth, applyFleetLiveStatus, liveWaits, projectKeyOfSession, STALL_WARN_MS, type WaitLite, type FleetLiveSignals } from "@/features/glance/lib/agentStall";
import type { ProjectLite } from "@/features/glance/lib/glanceData";
import type { GRawNode } from "@/features/glance/lib/glanceGraph";
import { fleetPaneId } from "@/app/console/lib/paneIdentity";

const T0 = 1_720_000_000_000; // a fixed "now" base
const projects: ProjectLite[] = [
  { id: "alpha", name: "Alpha", health: "healthy", activity: "building" },
  { id: "beta", name: "Beta", health: "off", activity: "building" },
];

describe("projectKeyOfSession", () => {
  it("takes the plan key prefix before the first ':' (worker / director / triage pane ids)", () => {
    expect(projectKeyOfSession("alpha:auth")).toBe("alpha");
    expect(projectKeyOfSession("alpha:director")).toBe("alpha");
    expect(projectKeyOfSession("alpha:own/web:triage")).toBe("alpha");
    expect(projectKeyOfSession("bare")).toBe("bare"); // no colon → whole id
  });
});

describe("applyStallHealth (#2541 watchdog)", () => {
  it("a FRESH wait is calm — activity 'waiting', health untouched", () => {
    const waiting: WaitLite[] = [{ session: "alpha:auth", reason: "awaiting review", at: T0 - 60_000 }]; // 1m
    const out = applyStallHealth(projects, waiting, T0);
    expect(out.find((p) => p.id === "alpha")).toMatchObject({ activity: "waiting", health: "healthy" });
    expect(out.find((p) => p.id === "beta")).toEqual(projects[1]); // no wait → untouched
  });

  it("an OVERSTAYED wait escalates to a 'warning' with a duration reason", () => {
    const waiting: WaitLite[] = [{ session: "beta:worker", reason: "no instructions", at: T0 - 12 * 60_000 }]; // 12m
    const out = applyStallHealth(projects, waiting, T0);
    expect(out.find((p) => p.id === "beta")).toMatchObject({ activity: "waiting", health: "warning", reason: "no instructions · 12m" });
  });

  it("falls back to a default note when the wait reason is empty", () => {
    const waiting: WaitLite[] = [{ session: "beta:worker", reason: "  ", at: T0 - STALL_WARN_MS - 1 }];
    const out = applyStallHealth(projects, waiting, T0);
    expect(out.find((p) => p.id === "beta")?.reason).toMatch(/^no instructions · \d+m$/);
  });

  it("uses the OLDEST outstanding wait per project (longest stall wins)", () => {
    const waiting: WaitLite[] = [
      { session: "beta:w1", reason: "recent", at: T0 - 2 * 60_000 },
      { session: "beta:w2", reason: "stuck", at: T0 - 30 * 60_000 }, // oldest → decides
    ];
    const out = applyStallHealth(projects, waiting, T0);
    expect(out.find((p) => p.id === "beta")).toMatchObject({ health: "warning", reason: "stuck · 30m" });
  });

  it("never DOWNGRADES an already-error project (error beats a stall)", () => {
    const errored: ProjectLite[] = [{ id: "beta", name: "Beta", health: "error", activity: "building", reason: "boom" }];
    const waiting: WaitLite[] = [{ session: "beta:w", reason: "waiting", at: T0 - 20 * 60_000 }];
    const out = applyStallHealth(errored, waiting, T0);
    expect(out[0].health).toBe("error"); // kept; only escalates, never downgrades
  });

  it("no waiting sessions → the input is returned untouched", () => {
    expect(applyStallHealth(projects, [], T0)).toBe(projects);
  });
});

// #3429 — the watchdog escalated on ANY outstanding wait, and nothing ever clears a wait whose session
// died (CoordState.waiting is a coord-log replay; only a later event from the SAME session removes an
// entry, and killing a pane emits none). So `now - w.at` grew forever and the project stayed orange.
describe("liveWaits — a dead session's wait is not a stall (#3429)", () => {
  const waiting: WaitLite[] = [
    { session: "alpha:auth", reason: "needs a decision", at: T0 },
    { session: "beta:store", reason: "parked", at: T0 },
  ];

  it("drops a wait whose pane is no longer live", () => {
    expect(liveWaits(waiting, new Set(["alpha:auth"]))).toEqual([waiting[0]]);
  });

  it("drops every wait when nothing is launched", () => {
    expect(liveWaits(waiting, new Set())).toEqual([]);
  });

  it("stops a long-dead wait from escalating its project to warning", () => {
    const stale: WaitLite[] = [{ session: "beta:store", reason: "parked", at: T0 }];
    const now = T0 + STALL_WARN_MS * 200; // ~38h, the cli-typer case
    // Unguarded, this pins beta orange forever…
    expect(applyStallHealth(projects, stale, now).find((p) => p.id === "beta")).toMatchObject({ health: "warning" });
    // …guarded by liveness, the project keeps whatever its own state says.
    expect(applyStallHealth(projects, liveWaits(stale, new Set()), now)).toBe(projects);
  });
});

describe("applyFleetLiveStatus (#3252 — fleet-drill live agent status)", () => {
  const PROJ = "proj";
  // A planned fleet at rest — director + one worker + the preview node, all seeded idle by buildOrgFleetData.
  const nodes: GRawNode[] = [
    { id: "director", slug: "director", role: "infra", health: "off", activity: "idle" },
    { id: "auth", slug: "auth", role: "service", health: "off", activity: "idle" },
    { id: "__preview__", slug: "preview", role: "client", health: "healthy", activity: "live", preview: true },
  ];
  const dir = fleetPaneId(PROJ, "director"); // "proj:director"
  const auth = fleetPaneId(PROJ, "auth");
  const sig = (over: Partial<FleetLiveSignals>): FleetLiveSignals => ({
    livePaneIds: new Set(), paneStatus: {}, waiting: [], now: T0, ...over,
  });
  const out = (over: Partial<FleetLiveSignals>) => applyFleetLiveStatus(nodes, PROJ, sig(over));
  const node = (r: GRawNode[], id: string) => r.find((n) => n.id === id)!;

  // No session behind the node ⇒ `off`, distinct from a session that exists and is merely quiet.
  // While both read `idle`, an absent session was indistinguishable from a resting one — and its
  // (correctly) empty log view looked like a broken log rather than a session that was never launched.
  it("an UNLAUNCHED agent reads OFF — no session exists", () => {
    const r = out({}); // nothing launched
    expect(node(r, "director")).toMatchObject({ health: "off", activity: "idle" });
    expect(node(r, "auth")).toMatchObject({ health: "off", activity: "idle" });
  });

  it("a launched + RUNNING agent reads healthy · building — INCLUDING the director", () => {
    const r = out({ livePaneIds: new Set([dir, auth]), paneStatus: { [dir]: "run", [auth]: "run" } });
    expect(node(r, "director")).toMatchObject({ health: "healthy", activity: "building" });
    expect(node(r, "auth")).toMatchObject({ health: "healthy", activity: "building" });
  });

  it("a launched but QUIET agent reads HEALTHY with an idle activity word (#4042)", () => {
    // #4042 removed the `idle` HEALTH state: a session that exists with nothing wrong IS healthy, and
    // the activity word already carries "at rest". Two axes, two facts, no overlap.
    const r = out({ livePaneIds: new Set([dir]) }); // launched, not running, not waiting
    expect(node(r, "director")).toMatchObject({ health: "healthy", activity: "idle" });
    // ...and it is still NOT the same as a node with NO session — that one is `off`, which is what the
    // dimming conveys. This contrast is the whole reason both states exist.
    expect(node(r, "auth")).toMatchObject({ health: "off", activity: "idle" });
  });

  // #4005 CHANGED both of these. A `bsc-wait` used to read `healthy` (green, calm) for ten minutes and
  // only then flip to `warning`. Both readings were wrong in the same way: green says "nothing to do"
  // about a session waiting on YOU, and orange says "something is degrading" about a normal hand-off.
  // It is a request, so it gets its own health from the first moment.
  it("a launched agent parked on a bsc-wait reads HEALTHY + waiting, with its reason (#4046)", () => {
    const r = out({ livePaneIds: new Set([auth]), waiting: [{ session: auth, reason: "awaiting review", at: T0 - 60_000 }] });
    expect(node(r, "auth")).toMatchObject({ health: "healthy", activity: "waiting", reason: "awaiting review" });
  });

  it("an OVERSTAYED wait still reads waiting, and adds the duration", () => {
    // How long it has been waiting is still worth knowing — it is just no longer the thing that
    // makes it visible in the first place.
    const r = out({ livePaneIds: new Set([auth]), waiting: [{ session: auth, reason: "no instructions", at: T0 - 12 * 60_000 }] });
    expect(node(r, "auth")).toMatchObject({ health: "healthy", activity: "waiting", reason: "no instructions · 12m" });
  });

  it("a pane STOPPED at a permission prompt reads HEALTHY + waiting (#4005/#4046)", () => {
    // The signal nothing in the app could see before: not `run`, no `bsc-wait`, so it fell through to
    // plain `idle` and looked exactly like a session that had simply finished.
    const r = out({ livePaneIds: new Set([auth]), attention: new Set([auth]) });
    expect(node(r, "auth")).toMatchObject({ health: "healthy", activity: "waiting" });
    expect(node(r, "auth").reason).toMatch(/permission/);
  });

  it("a bsc-wait outranks the permission signal — its reason is the specific one", () => {
    const r = out({
      livePaneIds: new Set([auth]),
      attention: new Set([auth]),
      waiting: [{ session: auth, reason: "awaiting review", at: T0 - 60_000 }],
    });
    expect(node(r, "auth").reason).toBe("awaiting review");
  });

  it("quarantine still outranks attention — that one is a fault the user must clear", () => {
    const r = out({ livePaneIds: new Set([auth]), attention: new Set([auth]), quarantined: { [auth]: { summary: "warden" } } });
    expect(node(r, "auth")).toMatchObject({ health: "error" });
  });

  it("an attention pane that is NOT launched stays off — no session, nothing to answer", () => {
    const r = out({ attention: new Set([auth]) });
    expect(node(r, "auth")).toMatchObject({ health: "off", activity: "idle" });
  });

  it("waiting beats running (a parked session isn't 'building' even if its pane still reads run)", () => {
    const r = out({ livePaneIds: new Set([auth]), paneStatus: { [auth]: "run" }, waiting: [{ session: auth, reason: "hold", at: T0 - 60_000 }] });
    expect(node(r, "auth").activity).toBe("waiting");
  });

  it("the preview node is left untouched (not an agent)", () => {
    const r = out({ livePaneIds: new Set([dir, auth]), paneStatus: { [dir]: "run" } });
    expect(node(r, "__preview__")).toEqual(nodes[2]); // healthy/live/preview, unchanged
  });
});

describe("applyFleetLiveStatus — quarantine is a first-class node state (#3916)", () => {
  const nodes = [{ id: "api" }, { id: "ui" }] as never as Parameters<typeof applyFleetLiveStatus>[0];
  const base = { livePaneIds: new Set<string>(), paneStatus: {}, waiting: [], now: 0 };

  it("shows a quarantined agent as ERROR with the warden's reason, not as `off`", () => {
    // The warden KILLS the PTY when it quarantines, so the pane is never live — without this overlay the
    // node fell through to `off`, reading as "never launched" rather than "hard-paused, here is why".
    const out = applyFleetLiveStatus(nodes, "proj", {
      ...base,
      quarantined: { "proj:ui": { summary: "wrote outside its lane" } },
    });
    const ui = out.find((n) => n.id === "ui")!;
    expect(ui.health).toBe("error");
    expect(ui.reason).toBe("wrote outside its lane");
    // An unquarantined, unlaunched sibling still reads `off` — the overlay is targeted, not blanket.
    expect(out.find((n) => n.id === "api")!.health).toBe("off");
  });

  it("falls back to a readable reason when the quarantine carries no summary", () => {
    const out = applyFleetLiveStatus(nodes, "proj", { ...base, quarantined: { "proj:api": {} } });
    expect(out.find((n) => n.id === "api")!.reason).toBe("quarantined by the warden");
  });

  it("is inert when nothing is quarantined (pre-#3916 behaviour byte-for-byte)", () => {
    expect(applyFleetLiveStatus(nodes, "proj", base)).toEqual(applyFleetLiveStatus(nodes, "proj", { ...base, quarantined: {} }));
  });
});

describe("applyFleetLiveStatus — held by the dependency gate (#3931)", () => {
  const node = (id: string): GRawNode => ({ id, slug: id, role: "service", health: "off", activity: "idle" });
  const base = { paneStatus: {}, waiting: [], now: Date.now() };

  it("a held stream explains itself instead of rendering as an anonymous dark node", () => {
    const [n] = applyFleetLiveStatus([node("play-screen")], "proj", {
      ...base,
      livePaneIds: new Set(),
      held: { "play-screen": { reason: "waiting on game-modes to land", deadlocked: false } },
    });
    expect(n.health).toBe("off");            // still no session — that part was never wrong
    expect(n.activity).toBe("waiting");
    expect(n.reason).toBe("waiting on game-modes to land");
  });

  it("a DEADLOCKED stream is an error — it can never start on its own", () => {
    const [n] = applyFleetLiveStatus([node("a")], "proj", {
      ...base,
      livePaneIds: new Set(),
      held: { a: { reason: "dependency cycle — cannot start (waiting on b)", deadlocked: true } },
    });
    expect(n.health).toBe("error");
    expect(n.reason).toContain("cycle");
  });

  it("a held stream that is somehow LIVE reports its real live state, not the stale hold", () => {
    // The held map is computed asynchronously; a stream released between the probe and the render must
    // not be painted as waiting.
    const [n] = applyFleetLiveStatus([node("a")], "proj", {
      ...base,
      livePaneIds: new Set(["proj:a"]),
      paneStatus: { "proj:a": "run" },
      held: { a: { reason: "waiting on b to land", deadlocked: false } },
    });
    expect(n.health).toBe("healthy");
    expect(n.activity).toBe("building");
  });

  it("QUARANTINE outranks a hold — it is the state the user must act on", () => {
    const [n] = applyFleetLiveStatus([node("a")], "proj", {
      ...base,
      livePaneIds: new Set(),
      quarantined: { "proj:a": { summary: "denied command" } },
      held: { a: { reason: "waiting on b to land", deadlocked: false } },
    });
    expect(n.health).toBe("error");
    expect(n.reason).toBe("denied command");
  });

  it("no held map ⇒ the pre-#3931 behaviour is unchanged", () => {
    const [n] = applyFleetLiveStatus([node("a")], "proj", { ...base, livePaneIds: new Set() });
    expect(n.health).toBe("off");
    expect(n.reason).toBeUndefined();
  });
});

describe("maintenance vs building (#4010)", () => {
  const PROJ = "proj";
  const nodes: GRawNode[] = [{ id: "auth", slug: "auth", role: "service", health: "off", activity: "idle" }];
  const auth = fleetPaneId(PROJ, "auth");
  const run = (over: Partial<FleetLiveSignals>) =>
    applyFleetLiveStatus(nodes, PROJ, { livePaneIds: new Set([auth]), paneStatus: {}, waiting: [], now: T0, ...over })[0];

  it("a working session reads building — the state that wears the outline", () => {
    expect(run({ paneStatus: { [auth]: "run" } })).toMatchObject({ health: "healthy", activity: "building" });
  });

  it("a PARKED session does not read as building, even while its pane still reads run", () => {
    // The #4010 point, unchanged: a maintaining worker's TUI is still alive, so `paneStatus` may well
    // be "run"; checked after the run->building branch it would keep breathing forever despite having
    // finished everything it owns.
    //
    // The WORD changed in #4027 — `complete`, not `idle`. Standing by having finished everything and
    // merely being quiet are different facts, and they used to render identically.
    const r = run({ paneStatus: { [auth]: "run" }, maintaining: new Set([auth]) });
    // #4034 — health is `complete` (blue) too now, not `idle` (grey). A finished worker and a resting
    // one are different states and used to share a colour.
    expect(r).toMatchObject({ health: "complete", activity: "complete" });
    expect(r.reason).toMatch(/maintenance/);
  });

  it("keeps the explanation on the node so the plain rendering is not information-free", () => {
    // It renders as the plain node deliberately — nothing for anyone to do — but hover and the
    // inspector's REASON tile still say why it is quiet.
    expect(run({ maintaining: new Set([auth]) }).reason).toMatch(/standing by/);
  });

  it("a bsc-wait still outranks maintenance — that one needs a person", () => {
    const r = run({ maintaining: new Set([auth]), waiting: [{ session: auth, reason: "awaiting review", at: T0 }] });
    expect(r).toMatchObject({ health: "healthy", activity: "waiting" });
  });

  it("quarantine still outranks maintenance", () => {
    const r = run({ maintaining: new Set([auth]), quarantined: { [auth]: { summary: "warden" } } });
    expect(r).toMatchObject({ health: "error" });
  });

  // REVERSED in #4124. This asserted `off`/`idle` on the reading that a park needs a live session to
  // park IN. But a `maintain` record cannot exist without one having run — `bsc-maintain` is emitted BY
  // the worker — so "unlaunched" was never what this state meant. What it means is: it ran, it finished
  // everything it owned, and its session has since been reclaimed (a standing-by session is the first
  // thing a reaper or a restart takes). Rendering that as `off` made it identical to a node that never
  // launched, which is how completion lost to idle on 34 panes.
  //
  // The park still does NOT outrank a `bsc-wait` or a quarantine — see the two tests above. Only the
  // never-launched reading changed.
  it("maintenance on a RECLAIMED node reads complete, not off (#4124)", () => {
    const r = applyFleetLiveStatus(nodes, PROJ, {
      livePaneIds: new Set(), paneStatus: {}, waiting: [], now: T0, maintaining: new Set([auth]),
    })[0];
    expect(r).toMatchObject({ health: "complete", activity: "complete" });
  });

  it("a node with NO maintain record and no session is still off", () => {
    // The never-launched reading has to survive: absent evidence is not completion.
    const r = applyFleetLiveStatus(nodes, PROJ, {
      livePaneIds: new Set(), paneStatus: {}, waiting: [], now: T0,
    })[0];
    expect(r).toMatchObject({ health: "off", activity: "idle" });
  });
});

describe("a finished worker reads COMPLETE (#4027)", () => {
  const PROJ = "proj";
  const nodes: GRawNode[] = [{ id: "auth", slug: "auth", role: "service", health: "off", activity: "idle" }];
  const auth = fleetPaneId(PROJ, "auth");
  const run = (over: Partial<FleetLiveSignals>) =>
    applyFleetLiveStatus(nodes, PROJ, { livePaneIds: new Set([auth]), paneStatus: {}, waiting: [], now: T0, ...over })[0];

  it("an ENDED-done worker reads complete, NOT off", () => {
    // The trap: `livePaneIds` excludes ended panes, so without a branch above the off fall-through a
    // worker that completed every issue renders identically to one that never launched.
    const r = applyFleetLiveStatus(nodes, PROJ, {
      livePaneIds: new Set(), paneStatus: {}, waiting: [], now: T0,
      ended: { [auth]: { state: "done" } },
    })[0];
    expect(r.activity).toBe("complete");
    expect(r.health).not.toBe("off");
  });

  it("a MAINTAINING worker reads complete, not idle", () => {
    // Standing by having finished everything vs merely being quiet are different facts; they used to
    // render as the same word.
    expect(run({ maintaining: new Set([auth]) })).toMatchObject({ activity: "complete" });
  });

  it("an ending that WANTS A PERSON does not read complete", () => {
    // `needs-attention` / `blocked` are endings too — but endings that need someone, so they keep
    // falling through to the states that say so rather than being dressed up as success.
    for (const state of ["needs-attention", "blocked"]) {
      const r = applyFleetLiveStatus(nodes, PROJ, {
        livePaneIds: new Set(), paneStatus: {}, waiting: [], now: T0, ended: { [auth]: { state } },
      })[0];
      expect(r.activity).not.toBe("complete");
    }
  });

  it("a never-launched worker still reads off — the distinction the branch exists to protect", () => {
    const r = applyFleetLiveStatus(nodes, PROJ, { livePaneIds: new Set(), paneStatus: {}, waiting: [], now: T0 })[0];
    expect(r).toMatchObject({ health: "off", activity: "idle" });
  });

  it("quarantine still outranks complete", () => {
    const r = run({ maintaining: new Set([auth]), quarantined: { [auth]: { summary: "warden" } } });
    expect(r).toMatchObject({ health: "error" });
  });

  it("complete never pulses — motion means 'look at this', and this needs nothing", () => {
    expect(ACTIVITY_META.complete.pulse).toBe(false);
    expect(ACTIVITY_META.complete.label).toBe("complete");
  });
});

