// The `algo-viz` kit's MOTION library as DATA (#2942/#3194, epic #3171) — the compare / swap / set /
// sorted (+ the search pair probe / found, #3220) animations authored as {@link KitAnimation} data,
// compiled by the kit-motion engine
// (`compileAnimationsCss`), NOT as hand-written CSS `@keyframes`. This is the epic's core vision: motion
// is data, so it's editable in the Designer's Animations menu instead of baked into a renderer's
// stylesheet.
//
// ── WHY THIS LIVES IN shared/ui/kit (not in either feature) ──────────────────────────────────────────
// It has EXACTLY TWO consumers, in two different features, and must be ONE definition (change `swap` once
// → every array visualization AND the Design-Studio kit shelf update in lockstep):
//   1. the Algorithms ArrayView renderer (`features/algorithms/.../arrayViewMotion.ts`,
//      `ensureArrayViewMotion`) — injects the compiled CSS into the live visualization; and
//   2. the Designs seed (`features/designs/lib/algoVizKit.ts` → `seed.ts`) — registers `algo-viz` as a
//      recoverable builtin kit so the set is visible + editable in the Design Studio's AnimationsMenu.
// Importing the Algorithms barrel from the Designs seed would eagerly pull the whole algorithms feature
// (its Workspace + graph) into the store-boot module graph and risks a designs↔algorithms seed cycle. The
// data is genuinely feature-agnostic viz-motion, so it lives HERE — a leaf both features import cheaply.
//
// ── THE STATE-TRIGGER SEAM (#3058) — "verb → data-state → animation" ─────────────────────────────────
// The current engine has no `trigger: "state"`; a state trigger is a KitAnimation whose `selector` IS the
// data-state (`[data-op="swap"]`). The engine compiles it to a rule
//
//     .algo-viz-anim-swap [data-op="swap"] { animation: bsc-algo-viz-swap …; }
//
// which plays whenever a DESCENDANT of the applying-class root matches that state — i.e. exactly when
// `ArrayView` stamps `data-op="swap"` on a cell. The renderer's root carries the applying classes; its
// cells only stamp `data-op` / `data-mark`. Change an animation's data here → every array visualization
// (and the kit's Design-Studio preview) updates, no renderer change.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The array-visualization motion kit id — `.algo-viz-anim-<name>` + `@keyframes bsc-algo-viz-<name>`. */
export const ALGO_VIZ_KIT_ID = "algo-viz";

/**
 * The `algo-viz` kit's animations as DATA (#2942), each a STATE trigger keyed on the data-state selector
 * `ArrayView` stamps — so the compiled rule fires on exactly `[data-op="compare"]` / `[data-op="swap"]`
 * / `[data-op="set"]` / `[data-mark="sorted"]`. Token-based colors + durations; the engine wraps every
 * applying rule in `@media (prefers-reduced-motion: no-preference)`, so reduced-motion is handled for
 * free. This is the single source of truth the ArrayView renderer AND the Designs `algo-viz` builtin kit
 * both consume — one definition, two consumers.
 */
export const ALGO_VIZ_ANIMATIONS: KitAnimation[] = [
  // compare — a highlight pulse on the two compared cells.
  {
    name: "compare",
    selector: '[data-op="compare"]',
    duration: "500ms",
    easing: "var(--ease-standard)",
    set: { "z-index": "1" },
    keyframes: {
      "0%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
      "45%": {
        "box-shadow": "0 0 0 2px color-mix(in oklch, var(--state-wait), transparent 45%)",
        "border-color": "var(--state-wait)",
      },
      "100%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
    },
  },
  // swap — the two cells lift, tint to the accent, and settle back as they exchange.
  {
    name: "swap",
    selector: '[data-op="swap"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": {
        transform: "translateY(0)",
        "border-color": "var(--accent)",
        background: "color-mix(in oklch, var(--accent), var(--bg-elev) 62%)",
      },
      "40%": { transform: "translateY(-12px) scale(1.05)" },
      "100%": { transform: "translateY(0)" },
    },
  },
  // set — a value flash (a fresh write into the cell).
  {
    name: "set",
    selector: '[data-op="set"]',
    duration: "500ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { background: "color-mix(in oklch, var(--accent), transparent 20%)" },
      "100%": { background: "var(--bg-elev)" },
    },
  },
  // probe — the SEARCH verb (#3220): ONE cell examined against an external target. Deliberately unlike
  // `compare` (which pulses a PAIR): a tight accent ring that closes in on the single cell, so a search
  // reads as "inspect this one" rather than "weigh these two".
  {
    name: "probe",
    selector: '[data-op="probe"]',
    duration: "460ms",
    easing: "var(--ease-standard)",
    set: { "z-index": "1" },
    keyframes: {
      "0%": { "box-shadow": "0 0 0 6px transparent", "border-color": "var(--border)" },
      "50%": {
        "box-shadow": "0 0 0 2px color-mix(in oklch, var(--accent), transparent 35%)",
        "border-color": "var(--accent)",
      },
      "100%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
    },
  },
  // found — the search's terminal hit (#3220): a one-shot pop as the target is located (its DURABLE accent
  // resting look is a static element style in arrayView.css, since the mark ends the trace).
  {
    name: "found",
    selector: '[data-mark="found"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": { transform: "scale(1)" },
      "45%": { transform: "scale(1.12)" },
      "100%": { transform: "scale(1)" },
    },
  },
  // sorted — a one-shot settle as a cell reaches its final place (its DURABLE green resting look is a
  // static element style in arrayView.css, since a mark persists across frames — this is only the motion).
  {
    name: "sorted",
    selector: '[data-mark="sorted"]',
    duration: "300ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { transform: "translateY(-3px)" },
      "100%": { transform: "translateY(0)" },
    },
  },
];

// The algorithms feature's graph-platform surface (#4219, epic #3604) — the modules a graph-loaded
// Algorithms workspace imports but does NOT redraw: the knowledge model, the graph hook, and the
// visualiser. Registered HERE, inside the feature, because the shell must not reach a feature's internals
// (#1545). The algorithms host calls this at module load, before the graph page loads.
//
// The viz panel stays code on purpose. It runs the instrumented executor (#3215) — real algorithm code
// driving an animation through `Traced<X>` — which is behaviour by any reading, and the least suitable
// thing in the feature to express as layout data.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
// acorn — the parser `viz/examples/vizInstrument` uses to instrument an algorithm's real code. Feature
// -scoped for the same reason as xterm: registration is eager, and a parser in the shell's set would be
// carried by every boot to serve one lens inside this feature.
import * as Acorn from "acorn";
import * as Knowledge from "@/features/algorithms/lib/knowledge";
import * as UseKnowledgeGraph from "@/features/algorithms/useKnowledgeGraph";
import * as VizPanel from "@/features/algorithms/viz/VizPanel";
import * as UseVizForImpl from "@/features/algorithms/viz/useVizForImpl";
// `record-link-debt` — the transport bar `vizpreview`/`vizstage` compose. It was registered nowhere, so
// both records threw the loader's named error on mount. It stays code for the same reason VizPanel does:
// it drives the instrumented executor's playhead, which is behaviour, not layout.
import * as TracePlayer from "@/features/algorithms/viz/TracePlayer";
// The librarian terminal is hosted by the studio-session surface — a cross-feature BARREL, which #1545
// permits and the live file already imports.
import * as StudioSessions from "@/features/studio-sessions";
import * as GraphPlatform from "@/features/algorithms/graphPlatform";
import * as Trace from "@/features/algorithms/lib/trace";
import * as TraceStream from "@/features/algorithms/lib/traceStream";
import * as Registry from "@/features/algorithms/viz/examples/registry";
import * as Binding from "@/features/algorithms/lib/binding";
import * as ArrayViewMotion from "@/features/algorithms/viz/renderers/arrayViewMotion";
import * as GraphViewMotion from "@/features/algorithms/viz/renderers/graphViewMotion";
import * as GraphLayout from "@/features/algorithms/viz/renderers/graphLayout";
import * as MatrixViewMotion from "@/features/algorithms/viz/renderers/matrixViewMotion";
import * as ScalarViewMotion from "@/features/algorithms/viz/renderers/scalarViewMotion";
import * as StackViewMotion from "@/features/algorithms/viz/renderers/stackViewMotion";
import * as TreeViewMotion from "@/features/algorithms/viz/renderers/treeViewMotion";
import * as TreeLayout from "@/features/algorithms/viz/renderers/treeLayout";

/** Register the Algorithms page's injected graph-platform modules by the specifiers it imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerAlgorithmsPlatform(): void {
  registerAppModule("acorn", Acorn);
  registerAppModule("@/features/algorithms/lib/knowledge", Knowledge);
  registerAppModule("@/features/algorithms/useKnowledgeGraph", UseKnowledgeGraph);
  registerAppModule("@/features/algorithms/viz/VizPanel", VizPanel);
  registerAppModule("@/features/algorithms/viz/useVizForImpl", UseVizForImpl);
  registerAppModule("@/features/algorithms/viz/TracePlayer", TracePlayer);
  registerAppModule("@/features/studio-sessions", StudioSessions);
  registerAppModule("@/features/algorithms/graphPlatform", GraphPlatform);
  registerAppModule("@/features/algorithms/lib/trace", Trace);
  registerAppModule("@/features/algorithms/lib/traceStream", TraceStream);
  registerAppModule("@/features/algorithms/viz/examples/registry", Registry);
  registerAppModule("@/features/algorithms/lib/binding", Binding);
  registerAppModule("@/features/algorithms/viz/renderers/arrayViewMotion", ArrayViewMotion);
  registerAppModule("@/features/algorithms/viz/renderers/graphViewMotion", GraphViewMotion);
  registerAppModule("@/features/algorithms/viz/renderers/graphLayout", GraphLayout);
  registerAppModule("@/features/algorithms/viz/renderers/matrixViewMotion", MatrixViewMotion);
  registerAppModule("@/features/algorithms/viz/renderers/scalarViewMotion", ScalarViewMotion);
  registerAppModule("@/features/algorithms/viz/renderers/stackViewMotion", StackViewMotion);
  registerAppModule("@/features/algorithms/viz/renderers/treeViewMotion", TreeViewMotion);
  registerAppModule("@/features/algorithms/viz/renderers/treeLayout", TreeLayout);
}

// The algorithms feature's store slice — the IMPLS the runtime resolver can reach.
//
// WHY A SLICE AND NOT `useKnowledgeGraph`. The Algorithms page already hydrates the live graph by
// polling `graph_dump` through that hook, and it stays the page's source. But `resolveGraphSource` is
// SYNCHRONOUS — `(specifier) => string | null`, reading a `getState()` snapshot — so it cannot invoke a
// Tauri command, and it lives in `shared/`, which may not import a feature. The only surface satisfying
// both is the app store, which is exactly how COMPONENTS already reach it (`hydrateComponents`, #3610).
// So this mirrors that path rather than inventing a second one.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { AlgoImpl } from "@/features/algorithms/lib/knowledge";
import { loadGraph } from "@/features/algorithms/lib/graphBridge";

export interface AlgorithmsSlice {
  /** Every implementation in the writable store — the set `resolveGraphSource` matches `provides` against.
   *  A CACHE, never persisted (#3610): it is re-read from the store at each boot. */
  algorithmImpls: AlgoImpl[];
  /** Read the librarian's writable store into memory. Idempotent; a no-op in a degraded environment. */
  hydrateAlgorithms: () => Promise<void>;
}

export const createAlgorithmsSlice: StateCreator<AppStore, [], [], AlgorithmsSlice> = (set) => ({
  algorithmImpls: [],
  hydrateAlgorithms: async () => {
    // `loadGraph` returns null on ANY failure — the web shell, the tests, an old `bsc` — so a degraded
    // environment simply resolves nothing rather than throwing during boot. Same contract the
    // Algorithms page already relies on.
    const graph = await loadGraph();
    if (!graph) return;
    set({ algorithmImpls: graph.implementations });
  },
});

import type { ConsoleProvider } from "@/app/console/lib/providers/types";

export const amazonQProvider: ConsoleProvider = {
  id: "amazonq",
  displayName: "Amazon Q Developer",
  buildLaunchCmd: () => "q",
  prereqProbe: "which q",
};

// The shipped analytics EMIT runtime (#3816, epic #3809 slice 3) — the fixed, audited code that turns a
// component's #3810 `analytics` manifest (DATA) into a `bsc usage record` (#3812) call when one of its
// actions fires. This is the seam that finally connects the two halves the epic left disconnected: the
// per-node CONTRACT (`ComponentRecord.analytics`) and the per-app SINK (`bsc usage record`).
//
// The load-bearing principle (inherited from #3283): CODE vs DATA. The component DECLARES what it emits;
// THIS runtime — fixed, shipped, never LLM-authored — does the emitting. There is no `track()`/`emit()`
// call in any authored component: emission is derived from the manifest at the render seam, so an app
// composed from instrumented nodes is instrumented BY CONSTRUCTION, uniformly, for free.
//
// It is host-agnostic on purpose: the SINK is injected. A generated app running in a Node/dev process
// spawns `bsc usage record` (the argv `usageRecordArgs` builds); a test collects; a browser logs. Absent
// a sink the whole path is inert — the dev-only / opt-in gate.

import type { AnalyticsEvent } from "@/features/designs/lib/model";

/** What `KitRenderer` reports when a bound handler fires (mirrors its `KitBindings.emit` argument): the
 *  node's component `type`, the action PROP that fired, and the args the underlying handler received. */
export interface ActionFire {
  type: string;
  prop: string;
  args: unknown[];
}

/** A resolved usage event, ready for the sink / the `bsc usage record` CLI. */
export interface UsageRecord {
  event: string;
  props: Record<string, unknown>;
}

/** Where resolved events go. Injected so the runtime is host-agnostic — see the file header. */
export type UsageSink = (rec: UsageRecord) => void;

/** A component-manifest lookup by a node's `type` (the host wires this to the components store; the
 *  shared renderer never reads the store itself). */
export type AnalyticsLookup = (type: string) => AnalyticsEvent[] | undefined;

/**
 * The convention that binds an action PROP to the event a component would declare for it: strip the
 * leading `on`, then PascalCase → snake_case (`onClick` → `click`, `onItemSelected` → `item_selected`,
 * `onFilterChanged` → `filter_changed`). Returns `undefined` for a non-action prop (one that is not
 * `on`-prefixed), which is the same "starts with `on`" shape the `no-analytics` doctor finding uses to
 * decide a component is interactive — so the finding and the runtime agree on what an action is.
 */
export function eventNameForProp(prop: string): string | undefined {
  if (!/^on[A-Z]/.test(prop)) return undefined;
  return prop
    .slice(2) // drop "on"
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1_$2") // acronym boundary: HTMLParser → HTML_Parser
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2") // camel boundary: ItemSelected → Item_Selected
    .toLowerCase();
}

/** A plain data object we can read a payload from — NOT an array and NOT a DOM `Event` (a click's
 *  `MouseEvent` carries no analytics payload, so it must not be mined for prop values). */
function isPlainPayload(v: unknown): v is Record<string, unknown> {
  if (typeof v !== "object" || v === null || Array.isArray(v)) return false;
  if (typeof Event !== "undefined" && v instanceof Event) return false;
  return true;
}

/**
 * Resolve a fired action to the usage event its component DECLARED — or `undefined` when the component
 * declared no matching event. It never invents an undeclared event: the manifest is the authority on
 * what an app reports.
 *
 * `props` are filled from the declared `PropSpec` NAMES, best-effort, from `args[0]` when that is a plain
 * data object (e.g. `onChange(nextValue)` where the value is an object, or a synthetic payload the host
 * passes). A DOM event or a scalar arg yields an EMPTY props map — the runtime records the event name
 * (the "what users do" signal `bsc usage summary` ranks) but does not fabricate a payload it cannot see.
 * This is the same honesty the prop validator publishes about what it can and cannot check.
 */
export function resolveAnalyticsEmit(
  manifest: AnalyticsEvent[] | undefined,
  prop: string,
  args: unknown[],
): UsageRecord | undefined {
  if (!manifest || manifest.length === 0) return undefined;
  const name = eventNameForProp(prop);
  if (!name) return undefined;
  const declared = manifest.find((e) => e.event === name);
  if (!declared) return undefined;

  const props: Record<string, unknown> = {};
  const payload = args[0];
  if (declared.props && isPlainPayload(payload)) {
    for (const p of declared.props) {
      if (Object.prototype.hasOwnProperty.call(payload, p.name)) props[p.name] = payload[p.name];
    }
  }
  return { event: declared.event, props };
}

/**
 * Build the exact argv `bsc usage record` (#3812) accepts, so the emit runtime's data-out shape IS the
 * CLI's input — a Node host can `spawn("bsc", usageRecordArgs(rec))` with no glue. `--props` is omitted
 * when the payload is empty (the CLI treats a missing `--props` as no payload).
 */
export function usageRecordArgs(rec: UsageRecord): string[] {
  const argv = ["usage", "record", "--event", rec.event];
  if (Object.keys(rec.props).length > 0) argv.push("--props", JSON.stringify(rec.props));
  return argv;
}

/**
 * Compose a manifest lookup + a sink into the hook `KitRenderer.emit` expects. A fire that resolves to no
 * declared event is a silent no-op — most action props are not instrumented, and that is fine.
 */
export function makeAnalyticsEmit(lookup: AnalyticsLookup, sink: UsageSink): (fire: ActionFire) => void {
  return (fire) => {
    const rec = resolveAnalyticsEmit(lookup(fire.type), fire.prop, fire.args);
    if (rec) sink(rec);
  };
}

/** Build an {@link AnalyticsLookup} from component records keyed by `name` — the studio host's bridge
 *  from its components store to the manifest-driven runtime. */
export function componentAnalyticsLookup(
  records: Iterable<{ name: string; analytics?: AnalyticsEvent[] }>,
): AnalyticsLookup {
  const byName = new Map<string, AnalyticsEvent[] | undefined>();
  for (const r of records) byName.set(r.name, r.analytics);
  return (type) => byName.get(type);
}

/** A sink that COLLECTS records — for tests and for a host that wants to batch/inspect before shipping. */
export function collectingSink(): UsageSink & { records: UsageRecord[] } {
  const records: UsageRecord[] = [];
  const sink = ((rec: UsageRecord) => {
    records.push(rec);
  }) as UsageSink & { records: UsageRecord[] };
  sink.records = records;
  return sink;
}

/** A sink that logs the `bsc usage record` argv — dev visibility. The real DB write is that CLI running
 *  in the app's OWN session, where `$BSC_USAGE_DB` is wired to the per-project `usage.db`. */
export const consoleUsageSink: UsageSink = (rec) => {
  // A deliberate dev-visibility sink; opt-in, never on by default.
  console.info("[usage] bsc", ...usageRecordArgs(rec));
};

