import { describe, it, expect } from "vitest";
import { DEMOABLE_KEYS, pickDemoable, snapshotAppState, isDemoableKey, mergeSnapshotInto } from "@/store/appState";

describe("app-state snapshot (#2272)", () => {
  it("snapshots only the demoable keys from a full-ish state", () => {
    const snap = snapshotAppState({
      blueprints: [{ id: "bp", name: "BP" }] as never,
      personas: [{ id: "p" }] as never,
      schedules: [{ id: "s" }] as never,
    });
    expect(Object.keys(snap).sort()).toEqual(["blueprints", "personas", "schedules"]);
  });

  it("NEVER carries a secret or the GitHub connection, even if present in the source", () => {
    const dirty = {
      githubToken: "ghp_secret",
      claudeApiKey: "sk-secret",
      openaiKey: "sk-o",
      geminiKey: "g",
      githubUser: { login: "me" },
      githubRepos: [{ full_name: "me/real" }],
      tabs: [{ id: "t" }],
      paneCwds: { p: "/c/Users/secret/path" },
      projectLocalRepos: { proj: "/c/Users/secret" },
      // a legitimately demoable field rides along
      blueprints: [{ id: "bp", name: "BP" }],
    };
    const snap = pickDemoable(dirty);
    expect(snap).toEqual({ blueprints: [{ id: "bp", name: "BP" }] });
    for (const secret of ["githubToken", "claudeApiKey", "openaiKey", "geminiKey", "githubUser", "githubRepos", "tabs", "paneCwds", "projectLocalRepos"]) {
      expect(secret in snap).toBe(false);
    }
  });

  it("drops bogus/injected keys from an untrusted payload (only known keys survive)", () => {
    const snap = pickDemoable({ personas: [{ id: "p" }], __proto__: { polluted: true }, notAKey: 1 });
    expect(Object.keys(snap)).toEqual(["personas"]);
  });

  it("tolerates non-object payloads", () => {
    expect(pickDemoable(null)).toEqual({});
    expect(pickDemoable("nope")).toEqual({});
    expect(pickDemoable(42)).toEqual({});
    expect(pickDemoable(undefined)).toEqual({});
  });

  it("skips keys that are present but undefined", () => {
    expect(pickDemoable({ blueprints: undefined, skills: [] })).toEqual({ skills: [] });
  });

  it("mergeSnapshotInto augments arrays by id, objects by key, and preserves built-ins (#2288)", () => {
    const state = {
      personas: [{ id: "director", builtin: true }, { id: "worker", builtin: true }],
      planFleet: { real: { streams: [] } },
      activeBlueprintId: "default",
    };
    const patch = mergeSnapshotInto(state, {
      personas: [{ id: "worker", builtin: true, edited: true }, { id: "demo-billing" }] as never,
      planFleet: { demoproj: { streams: [{ id: "s" }] } } as never,
      activeBlueprintId: "demo-bp" as never,
    });
    // Built-in "director" preserved; "worker" overridden by the incoming same-id; "demo-billing" added.
    expect((patch.personas as { id: string }[]).map((p) => p.id)).toEqual(["director", "worker", "demo-billing"]);
    expect((patch.personas as { edited?: boolean }[])[1].edited).toBe(true); // incoming won on the id collision
    // Map merges by key — real fleet kept, demo fleet added.
    expect(Object.keys(patch.planFleet as object).sort()).toEqual(["demoproj", "real"]);
    expect(patch.activeBlueprintId).toBe("demo-bp"); // scalar replaced
  });

  it("mergeSnapshotInto skips keys the snapshot doesn't set", () => {
    expect(mergeSnapshotInto({ personas: [{ id: "a" }] }, { blueprints: [] as never })).toEqual({ blueprints: [] });
  });

  it("isDemoableKey reflects the allowlist", () => {
    expect(isDemoableKey("blueprints")).toBe(true);
    expect(isDemoableKey("personas")).toBe(true);
    expect(isDemoableKey("githubToken")).toBe(false);
    expect(isDemoableKey("nope")).toBe(false);
  });

  it("the allowlist is free of obvious secrets/connection/machine keys", () => {
    const forbidden = [
      "githubToken", "repoGithubTokens", "claudeApiKey", "openaiKey", "geminiKey", "localBaseUrl",
      "tunnelRelayUrl", "githubConnected", "githubUser", "githubRepos", "projectLocalRepos",
      "tabs", "paneCwds", "paneRepos",
    ];
    for (const k of forbidden) expect(DEMOABLE_KEYS).not.toContain(k);
  });
});

implementations.code:
// The composed AppStore interface (#1634). It `extends` the per-feature slice interfaces
// (Skills/Mcp/Automations/Github/Tunnel — owned by their features) AND the per-domain core-state
// interfaces split out of the former monolith. Composition model is unchanged: every field still
// lives on AppStore; it is just sourced from focused per-domain modules.
//
// Where the rest lives:
//  - GitHub connection state    → GithubSlice    (@/features/github/store)
//  - Mobile tunnel state        → TunnelSlice    (@/features/tunnel/store)
//  - Automations CRUD           → AutomationsSlice (@/features/automations/store)
//  - MCP servers + hooks        → McpSlice       (@/features/mcp/store)
//  - Skills library/groups      → SkillsSlice    (@/features/skills/store)
import type { McpSlice } from "@/features/mcp/store";
import type { PersonasSlice } from "@/features/personas/store";
import type { OrgSlice } from "@/features/teams/store";
import type { NetworksSlice } from "@/features/networks";
import type { ComponentsSlice } from "@/features/designs/store";
import type { AlgorithmsSlice } from "@/features/algorithms/store";
import type { StudiosSlice } from "@/features/studio-sessions/store";
import type { SkillsSlice } from "@/features/skills/store";
import type { AutomationsSlice } from "@/features/automations/store";
import type { GithubSlice } from "@/features/github/store";
import type { TunnelSlice } from "@/features/tunnel/store";
import type { ConsoleState } from "@/store/types/console";
import type { ShellState } from "@/store/types/shell";
import type { LlmState } from "@/store/types/llm";
import type { ProjectsState } from "@/store/types/projects";
import type { PlanState } from "@/store/types/plan";
import type { SessionState } from "@/store/types/session";

export interface AppStore
  extends SkillsSlice,
    PersonasSlice,
    OrgSlice,
    NetworksSlice,
    ComponentsSlice,
    AlgorithmsSlice,
    StudiosSlice,
    McpSlice,
    AutomationsSlice,
    GithubSlice,
    TunnelSlice,
    ConsoleState,
    ShellState,
    LlmState,
    ProjectsState,
    PlanState,
    SessionState {}

// Appearance prefs that drive the design-token CSS variables at runtime (#486).
//
// The accent is a single hue threaded through two tokens — `--accent` (the bright
// interactive color) and `--accent-dim` (its muted partner) — which the rest of
// the palette derives from via color-mix. Offering a fixed set of hue presets (vs.
// a freeform picker) keeps the two tokens in lockstep at the lightness/chroma the
// design was tuned for, so every accent stays legible.
//
// Pure (no DOM access) so the mapping is unit-testable; the App applies the result
// to document.documentElement.

export interface AccentPreset {
  /** Stable id persisted in the store. */
  id: string;
  /** Label shown in the Appearance picker. */
  label: string;
  /** oklch hue angle for this accent. */
  hue: number;
}

/** The accent palette. `amber` (hue 70) is the historical default in tokens.css. */
export const ACCENT_PRESETS: AccentPreset[] = [
  { id: "amber",  label: "Amber",  hue: 70  },
  { id: "blue",   label: "Blue",   hue: 230 },
  { id: "green",  label: "Green",  hue: 145 },
  { id: "cyan",   label: "Cyan",   hue: 195 },
  { id: "purple", label: "Purple", hue: 300 },
  { id: "red",    label: "Red",    hue: 25  },
];

export const DEFAULT_ACCENT = "amber";

/** The two `--accent*` token values for an accent id. Lightness/chroma match the
 *  tokens.css defaults so only the hue changes; an unknown id falls back to the
 *  default so a corrupt persisted value can't blank the accent. */
export function accentVars(id: string): { accent: string; accentDim: string } {
  const p = ACCENT_PRESETS.find((x) => x.id === id)
    ?? ACCENT_PRESETS.find((x) => x.id === DEFAULT_ACCENT)!;
  return {
    accent: `oklch(0.80 0.14 ${p.hue})`,
    accentDim: `oklch(0.55 0.10 ${p.hue})`,
  };
}

