// Batched write-behind (#the-scan-cache-stops-spawning-a-process-per-batch) — collapse many small writes
// into few expensive ones.
//
// WHY THIS IS ITS OWN THING. The Design Studio's scan cache hung its durable write on the same 150ms timer
// as its store write. That was right for the store (an in-memory setState) and wrong for the cache (a
// PROCESS SPAWN): a full sweep fired ~400 of them — 157 SECONDS of process churn, measured — for data that
// only had to be correct by the time the sweep ended.
//
// The rule is small but it has three parts that are each easy to get wrong on their own, which is why it
// lives here rather than inline in a hook: coalesce by KEY (a component scanned twice in one window is one
// write, not two), fire on a SLOW clock, and never lose what the clock has not reached when the caller
// tears down. Written once, testable without React, and reusable for the next expensive sink — the app has
// several other places that spawn a process per event.
//
// It is write-BEHIND, so the caller accepts that a crash loses at most one window. That is only safe where
// the data can be recomputed; the scan cache qualifies because a lost entry is simply re-scanned.

/** A batch writer over keyed entries. Create one per sink, call {@link BatchWriter.queue} freely, and
 *  {@link BatchWriter.flush} on teardown. */
export interface BatchWriter<T> {
  /** Merge entries into the pending set and arm the timer if it is not already armed. */
  queue: (entries: Record<string, T>) => void;
  /** Write whatever is pending NOW and disarm — for a caller tearing down. No-op when nothing is pending. */
  flush: () => void;
  /** How many entries are waiting (for tests + diagnostics). */
  pending: () => number;
}

/**
 * Create a batch writer that calls `write` at most once per `ms`, carrying every entry queued in that
 * window.
 *
 * Entries are keyed, and a later value for the same key REPLACES the earlier one — a component scanned
 * twice inside one window should cost one write carrying its latest result, not two carrying a stale one
 * and then a fresh one.
 *
 * The timer is armed on the FIRST queue after a write, not reset on each one: a debounce that restarts on
 * every entry would never fire during a steady stream of results, which is exactly the shape of a sweep.
 */
export function makeBatchWriter<T>(write: (batch: Record<string, T>) => void, ms: number): BatchWriter<T> {
  let pending: Record<string, T> = {};
  let timer: ReturnType<typeof setTimeout> | null = null;

  const flush = () => {
    if (timer) { clearTimeout(timer); timer = null; }
    const keys = Object.keys(pending);
    if (keys.length === 0) return;
    const batch = pending;
    pending = {};
    write(batch);
  };

  return {
    queue(entries) {
      Object.assign(pending, entries);
      // `??=` not a reset: re-arming on every entry is a debounce, and a debounce never fires while
      // results keep arriving — which is the whole duration of a sweep.
      timer ??= setTimeout(flush, ms);
    },
    flush,
    pending: () => Object.keys(pending).length,
  };
}

tests.src:
// #the-scan-cache-stops-spawning-a-process-per-batch — the write-behind rule.
//
// The regression this guards leaves the stored data perfectly correct and simply costs ~400 process spawns
// per sweep (measured: 157.1s). Nothing about the result would reveal it, so the assertions here are about
// the WRITE COUNT — the same shape as #4132's store-commit-count test one layer down.
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { makeBatchWriter } from "@/shared/lib/core/batchWriter";

beforeEach(() => vi.useFakeTimers());
afterEach(() => vi.useRealTimers());

describe("makeBatchWriter", () => {
  it("collapses many queues into ONE write per window", () => {
    const write = vi.fn();
    const w = makeBatchWriter<number>(write, 5_000);
    for (let i = 0; i < 40; i++) w.queue({ [`c${i}`]: i });

    expect(write).not.toHaveBeenCalled();          // nothing yet — this is the fix
    vi.advanceTimersByTime(5_000);
    expect(write).toHaveBeenCalledTimes(1);        // was 40 spawns before
    expect(Object.keys(write.mock.calls[0][0])).toHaveLength(40);
  });

  it("keeps the LATEST value for a key queued twice in one window", () => {
    // A component scanned twice inside one window is one write carrying its latest result — not two,
    // and certainly not one carrying the stale one.
    const write = vi.fn();
    const w = makeBatchWriter<string>(write, 1_000);
    w.queue({ a: "old" });
    w.queue({ a: "new", b: "x" });
    vi.advanceTimersByTime(1_000);
    expect(write).toHaveBeenCalledWith({ a: "new", b: "x" });
  });

  it("ARMS on the first queue rather than resetting — a debounce would never fire mid-sweep", () => {
    // The trap: `timer = setTimeout(...)` on every queue restarts the clock, so a steady stream of
    // results (exactly what a sweep is) defers the write until the stream STOPS. Here the window is
    // honoured from the first entry.
    const write = vi.fn();
    const w = makeBatchWriter<number>(write, 1_000);
    w.queue({ a: 1 });
    vi.advanceTimersByTime(600);
    w.queue({ b: 2 });                  // arrives mid-window
    vi.advanceTimersByTime(400);        // …the ORIGINAL window elapses
    expect(write).toHaveBeenCalledTimes(1);
    expect(write).toHaveBeenCalledWith({ a: 1, b: 2 });
  });

  it("writes again for the NEXT window — one slow write per window, not one ever", () => {
    const write = vi.fn();
    const w = makeBatchWriter<number>(write, 1_000);
    w.queue({ a: 1 });
    vi.advanceTimersByTime(1_000);
    w.queue({ b: 2 });
    vi.advanceTimersByTime(1_000);
    expect(write).toHaveBeenCalledTimes(2);
    expect(write.mock.calls[1][0]).toEqual({ b: 2 });
  });

  it("flush() writes what the clock has not reached, and disarms", () => {
    // The teardown case. Those results really happened and their signatures are already marked scanned,
    // so dropping them would leave work that never re-queues AND never reaches the sink.
    const write = vi.fn();
    const w = makeBatchWriter<number>(write, 5_000);
    w.queue({ a: 1 });
    w.flush();
    expect(write).toHaveBeenCalledTimes(1);

    vi.advanceTimersByTime(10_000);
    expect(write).toHaveBeenCalledTimes(1);   // the armed timer was cancelled, not left to double-write
  });

  it("flush() with nothing pending writes NOTHING — no spawn for no work", () => {
    const write = vi.fn();
    makeBatchWriter<number>(write, 1_000).flush();
    expect(write).not.toHaveBeenCalled();
  });

  it("reports what is waiting", () => {
    const w = makeBatchWriter<number>(vi.fn(), 1_000);
    expect(w.pending()).toBe(0);
    w.queue({ a: 1, b: 2 });
    expect(w.pending()).toBe(2);
    w.flush();
    expect(w.pending()).toBe(0);
  });
});

