import { describe, it, expect } from "vitest";
import {
  mkStageSection, reorderStages, addStage, deleteStage,
  toggleDep, setOutput, setStageField, depCandidates,
} from "@/features/planner/blueprints/blueprintEdit";
import { STAGE_KINDS, DISPOSITIONS, defaultDisposition } from "@/features/planner/blueprints/blueprintCatalog";
import { STAGE_DEFS } from "@/features/planner/stages/blueprints";

describe("blueprintCatalog (#609)", () => {
  it("uses our `ui` key (not the design's `ux`)", () => {
    expect(STAGE_KINDS.ui).toBeTruthy();
    expect((STAGE_KINDS as Record<string, unknown>).ux).toBeUndefined();
  });
  it("default dispositions map sensibly and exist", () => {
    expect(defaultDisposition("streams")).toBe("issues");
    expect(defaultDisposition("skills")).toBe("skill-index");
    expect(defaultDisposition("discovery")).toBe("knowledge");
    expect(defaultDisposition("stack")).toBe("plan-file");
    for (const k of ["issues", "skill-index", "knowledge", "plan-file"]) expect(DISPOSITIONS[k]).toBeTruthy();
  });
});

describe("blueprintEdit — mkStageSection (#609)", () => {
  it("known kind keeps its runtime gate (from STAGE_DEFS) + gets a default output", () => {
    const s = mkStageSection("streams");
    expect(s.key).toBe("streams");
    expect(s.gateRule).toEqual(STAGE_DEFS.streams.gateRule); // runtime preserved
    expect(s.output).toBe("issues");
  });
  it("unknown kind is synthesized as an informational stage", () => {
    const s = mkStageSection("stack");
    expect(s.key).toBe("stack");
    expect(s.name).toBe(STAGE_KINDS.stack.title);
    expect(s.gateRule).toBeUndefined(); // informational — no runtime gate
    expect(s.output).toBe("plan-file");
  });
});

describe("blueprintEdit — stage ops (#609)", () => {
  const base = () => [mkStageSection("discovery"), mkStageSection("ui"), mkStageSection("streams")];

  it("reorderStages moves by index; out-of-range is a no-op", () => {
    const a = base();
    expect(reorderStages(a, 0, 2).map((s) => s.key)).toEqual(["ui", "streams", "discovery"]);
    expect(reorderStages(a, 0, 9)).toBe(a);
  });

  it("addStage appends a fresh stage", () => {
    expect(addStage(base(), "skills").map((s) => s.key)).toEqual(["discovery", "ui", "streams", "skills"]);
  });

  it("deleteStage removes it and scrubs deps by key when no twin remains", () => {
    // informational kinds start with empty deps (known kinds carry STAGE_DEFS deps).
    let a = [mkStageSection("discovery"), mkStageSection("stack"), mkStageSection("docs")];
    a = toggleDep(a, a[2].uid, "stack"); // docs depends on stack
    expect(a[2].deps).toContain("stack");
    const out = deleteStage(a, a[1].uid); // delete stack
    expect(out.map((s) => s.key)).toEqual(["discovery", "docs"]);
    expect(out.find((s) => s.key === "docs")!.deps).not.toContain("stack");
  });

  it("toggleDep adds then removes", () => {
    const a = [mkStageSection("discovery"), mkStageSection("stack")]; // empty deps
    const on = toggleDep(a, a[1].uid, "discovery");
    expect(on[1].deps).toContain("discovery");
    expect(toggleDep(on, a[1].uid, "discovery")[1].deps).not.toContain("discovery");
  });

  it("setOutput + setStageField", () => {
    let a = base();
    a = setOutput(a, a[0].uid, "scratch");
    expect(a[0].output).toBe("scratch");
    a = setStageField(a, a[0].uid, { name: "Kickoff", prompt: "hi" });
    expect(a[0].name).toBe("Kickoff");
    expect(a[0].prompt).toBe("hi");
  });

  it("depCandidates returns only earlier stages", () => {
    const a = base();
    expect(depCandidates(a, a[0].uid)).toEqual([]);
    expect(depCandidates(a, a[2].uid).map((s) => s.key)).toEqual(["discovery", "ui"]);
  });
});

implementations.code:
// ── Blueprint display helpers (#…): the blueprint's OWN hued icon tile, a visibility
// pill (draft / private gist / public gist), and a shortened gist link. ────────────────────────
//
// The tile used to be keyed off the lifecycle `category`, which #3785 removed from the model — and
// which had degenerated anyway: every packaged blueprint was `greenfield`, so all six cards drew the
// same glyph, the same hue, and the same meaningless "greenfield" badge. A blueprint is a
// goal/domain route now, so it carries its own `icon`/`h` (CRM → hub, HR → group, …) and the card
// renders those, exactly as the setup page already did.
import { timeAgoMs, truncate } from "@/shared/lib/core/format";
import type { Blueprint, BlueprintGist, BlueprintStage } from "@/features/planner/stages/blueprints";

/** The fallback accent hue for a blueprint that declares no `h` — matches the setup page's `?? 70`. */
export const DEFAULT_BLUEPRINT_HUE = 70;

/** A blueprint's accent colour, from its own hue. */
export function blueprintHue(h?: number): string {
  return `oklch(0.75 0.13 ${h ?? DEFAULT_BLUEPRINT_HUE})`;
}

/** The icon NAME a blueprint's tile renders (an `<Ic>` glyph). A blueprint that declares none falls
 *  back to `category` — the generic grid glyph, which is what `Ic` itself resolves an unknown name
 *  to, made explicit here so the fallback is visible at the call site rather than a surprise.
 *  (Deliberately NOT the name's initial: `Ic` renders SVG paths, never letters, so an initial would
 *  silently resolve to this same generic glyph anyway.) */
export function blueprintIcon(b: Pick<Blueprint, "icon">): string {
  return b.icon ?? "category";
}
export function prettyGist(g?: BlueprintGist): string | undefined {
  if (!g) return undefined;
  if (g.url) {
    const s = g.url.replace(/^https?:\/\//, "").replace(/^www\./, "");
    return truncate(s, 32, 30);
  }
  return g.id ? `gist · ${g.id.slice(0, 7)}` : undefined;
}

/** A blueprint surfaced in the Projects page — a saved library or built-in blueprint. */
export interface BpItem {
  id: string;          // library blueprint id
  name: string;
  pitch: string;
  icon: string;        // the blueprint's own `<Ic>` glyph name
  h?: number;          // the blueprint's own accent hue
  stages: number;
  sections: BlueprintStage[];   // the blueprint's sections — drives the gate-row preview
  builtIn?: boolean;   // a code-owned app template (can't be deleted)
  gistLabel?: string;
  updatedLabel: string;
  sort: number;        // recency key (epoch ms)
}

/** Build the blueprint list surfaced in the rail: ALL blueprints — the built-in app templates AND
 *  the user's saved library — so a blueprint can be SELECTED for the next project right here
 *  (#blueprints). */
export function buildBlueprintItems(blueprints: Blueprint[]): BpItem[] {
  const items: BpItem[] = [];
  for (const b of blueprints) {
    const hasGist = !!b.gist?.id;
    const sortMs = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
    items.push({
      id: b.id, name: b.name,
      pitch: b.pitch ?? b.desc ?? "",
      icon: blueprintIcon(b), h: b.h,
      stages: b.sections.length, sections: b.sections,
      builtIn: b.origin === "built-in",
      gistLabel: hasGist ? prettyGist(b.gist) : undefined,
      updatedLabel: timeAgoMs(sortMs), sort: sortMs,
    });
  }
  return items;
}

