    expect(p({ kind: "issue", number: 20 })).toBe("t0p2");
    expect(p({ kind: "file", path: "src/ui/Form.tsx" })).toBe("t0p2");
  });

  it("detects a wait-for ring between two panes via their owned globs/issues", () => {
