// graphEdge (#2222, graph design-language #2221) — the shared line-type; anchor + ports routing (#2226).
import { describe, it, expect } from "vitest";
import { graphEdge, type EdgeBox } from "@/shared/lib/graph/edgePath";

const A: EdgeBox = { x: 0, y: 0, w: 100, h: 40 };   // center (50,20), right border x=100
const B: EdgeBox = { x: 200, y: 0, w: 100, h: 40 };  // center (250,20), left border x=200

describe("graphEdge — anchor routing (#2222)", () => {
  it("leaves the source border facing the target and ends short of the target border", () => {
    const g = graphEdge(A, B);
    // Source anchor = right border of A (+3 outset) at the shared y.
    expect(g.d.startsWith("M 103 20 ")).toBe(true);
    // The curve ends 9px short of B's left border (200 + 3 outset = 197 → 188).
    expect(g.d.endsWith("188 20")).toBe(true);
  });

  it("puts the arrow tip on the target border, not at the curve end", () => {
    const g = graphEdge(A, B);
    expect(g.arrow.startsWith("M 197 20 ")).toBe(true); // tip at the border (197), curve stopped at 188
  });

  it("places the label near the midpoint of the run", () => {
    const g = graphEdge(A, B);
    expect(g.labelX).toBeGreaterThan(103);
    expect(g.labelX).toBeLessThan(197);
    expect(g.labelY).toBeCloseTo(20, 6); // straight horizontal edge, no bow
  });

  it("bows the curve off the straight line", () => {
    const straight = graphEdge(A, B);
    const bowed = graphEdge(A, B, { bow: 24 });
    expect(bowed.labelY).not.toBeCloseTo(straight.labelY, 1); // perpendicular offset moved the midpoint
  });

  it("omits the source arrow unless doubleEnded", () => {
    expect(graphEdge(A, B).arrowStart).toBeUndefined();
    const g = graphEdge(A, B, { doubleEnded: true });
    expect(g.arrowStart?.startsWith("M 103 20 ")).toBe(true); // a second arrow at the source border
  });
});

describe("graphEdge — ports routing (#2226, layered graphs)", () => {
  it("leaves the right edge at the vertical middle and enters the left edge (clean columnar flow)", () => {
    const g = graphEdge(A, B, { routing: "ports" });
    expect(g.d.startsWith("M 100 20 ")).toBe(true);  // right edge of A (x=100), no outset, vertical middle
    expect(g.d.endsWith("200 20")).toBe(true);        // straight to B's left port (x=200), no gap
  });

  it("puts the arrow tip on the target port with horizontal control handles", () => {
    const g = graphEdge(A, B, { routing: "ports" });
    expect(g.arrow.startsWith("M 200 20 ")).toBe(true); // tip at the left port
    // Control handles are horizontal (k=50): "M 100 20 C 150 20 150 20 200 20".
    expect(g.d).toBe("M 100 20 C 150 20 150 20 200 20");
  });

  it("routes ports differently from anchor for the same boxes", () => {
    expect(graphEdge(A, B, { routing: "ports" }).d).not.toBe(graphEdge(A, B).d);
  });
});

implementations.code:
// Resume for a pane whose PTY is ALREADY ALIVE (#3998).
//
// Every Resume site in the app ultimately relies on `pty_create` to launch the agent — but
// `pty_create` returns before it ever reads `init_cmd` when a session already exists for the pane
// ("reconnect to existing session"). So for a live pane, the carefully-resolved
// `claude --continue 2>/dev/null || claude` is computed, handed to the backend, and thrown away.
// The pane gets a Ctrl+L repaint of its bash prompt and nothing else. That is why Resume appeared to
// do nothing on a session whose agent had already exited.
//
// `TerminalView` never remounts such a pane either: it is portal-hosted keyed by `paneId`, so the
// `runId` bump a resume performs re-keys the SLOT, not the terminal. Only a pane in a placeholder
// state (ended / disabled / dormant) unmounts and remounts.
//
// So the fix cannot live in the launch path — the launch path is unreachable. It has to act on the
// live shell directly: ask what the pane is actually doing, and if it is sitting at a prompt, type
// the resume command into it.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { useAppStore, paneHarness } from "@/store";

/** `claude --continue`, degrading to a fresh session when there is no conversation to resume (#3937).
 *  Defined here rather than in `app/console/lib/resumeClaude.ts` so BOTH the mount-time launch path
 *  and this live-shell path emit the byte-identical command — a resumed pane must not depend on which
 *  of the two routes happened to reach it. stderr is dropped because claude's "no session" message is
 *  expected on the first `--continue` of a fresh worktree. */
export const CONTINUE_OR_FRESH = "claude --continue 2>/dev/null || claude";

/** The same command for ANY harness — `<harness> --continue`, degrading to a fresh session.
 *
 *  `CONTINUE_OR_FRESH` above hardcodes `claude`, which was correct while every agent pane was a
 *  Claude pane. It is not any more: a fleet stream wired to a local model runs on `bsc-agent`
 *  (#173), and `bsc-agent` accepts `--continue`/`-c` deliberately mirroring claude's (see
 *  `crates/bsc-agent/src/main.rs`). Resuming such a pane with the claude command launched CLAUDE —
 *  the configured local model was never reached, and nothing said so.
 *
 *  Kept as a function beside the constant rather than replacing it: two callers import the constant
 *  by name, and a Claude pane must keep emitting the byte-identical string it always has. */
export function continueOrFresh(harness: string): string {
  const h = harness.trim();
  return h ? `${h} --continue 2>/dev/null || ${h}` : CONTINUE_OR_FRESH;
}

/** What the backend reports for one pane (`pty_pane_runtime`). */
export type PaneRuntime = {
  paneId: string;
  /** A PTY session exists — `pty_create` would RECONNECT rather than launch. */
  live: boolean;
  /** Its shell has a live descendant, i.e. something is running in it. */
  busy: boolean;
};

/** Why a pane was or wasn't started, for logging and tests. */
export type ResumeOutcome = "started" | "already-running" | "not-live";

/**
 * Decide what a resume should do with each pane, given the backend's runtime report.
 *
 * Pure so the policy is testable without a live PTY. The three cases:
 *  - `not-live`     — no PTY yet. Do nothing: the pane's mount will run the normal launch path,
 *                     which handles `--continue` properly. Typing into a shell that doesn't exist
 *                     would be dropped anyway.
 *  - `already-running` — the shell has a descendant. Do nothing. This is the guard that stops a
 *                     resume from injecting a second `claude` into an agent that is mid-turn, and it
 *                     is why the backend probe asks about DESCENDANTS rather than trying to spot a
 *                     process named `claude` (which is `node.exe` on Windows).
 *  - `started`      — live, at a prompt. Type the resume command in.
 */
export function planResume(runtimes: readonly PaneRuntime[]): Map<string, ResumeOutcome> {
  const out = new Map<string, ResumeOutcome>();
  for (const r of runtimes) {
    out.set(r.paneId, !r.live ? "not-live" : r.busy ? "already-running" : "started");
  }
  return out;
}

/**
 * Make sure claude is running in each of `paneIds` whose PTY is alive but idle.
 *
 * Batched: the backend's busy check walks the process table, so asking about every pane at once costs
 * one walk instead of N — a project-wide resume touches dozens of panes.
 *
 * Returns the per-pane outcome so callers can report "started N" honestly instead of claiming a
 * resume that didn't happen.
 */
export async function ensureClaudeRunning(paneIds: readonly string[]): Promise<Map<string, ResumeOutcome>> {
  if (paneIds.length === 0) return new Map();
  const runtimes = await safeInvoke<PaneRuntime[]>("pty_pane_runtime", { paneIds: [...paneIds] }, []);
  const plan = planResume(runtimes);

  const started: string[] = [];
  for (const [paneId, outcome] of plan) {
    if (outcome !== "started") continue;
    // A plain write, NOT `injectPrompt`: that wraps text in bracketed-paste markers for claude's TUI,
    // and this is going to a bash prompt, where the markers would be echoed as literal characters.
    // The trailing newline is the Enter that runs it.
    // THE PANE'S OWN HARNESS, not claude's. This types a command into a live shell, and typing
    // `claude --continue` into a `bsc-agent` pane starts the wrong program — which exits, the pane
    // goes idle, the reaper reclaims it, and the relaunch does it again. Observed as a session that
    // would not start, on a terminal left showing the typed command.
    //
    // `resolveInitCmd` was made harness-aware and THIS path was not — even though this module's own
    // docs say both routes must emit the byte-identical command. Same derivation as the launch.
    const harness = paneHarness(useAppStore.getState(), paneId);
    await safeInvoke("pty_write", { paneId, data: `${continueOrFresh(harness)}\n` }, undefined);
    started.push(paneId);
  }
  if (started.length > 0) {
    log.info(`resume: started the agent in ${started.length} idle pane(s): ${started.join(", ")}`);
  }
  return plan;
}

