import { describe, it, expect } from "vitest";
import { flowPermissionRules, PUSH_WRITE_RULES } from "@/features/planner/fleet/flowPermissions";
import { DEFAULT_FLOW, LOCAL_ONLY_PUSH, type AgentFlow } from "@/features/planner/fleet/agentFlow";

const flow = (p: Partial<AgentFlow>): AgentFlow => ({ ...DEFAULT_FLOW, ...p });

describe("flowPermissionRules", () => {
  it("auto-pr contributes no rules (broad Bash allow permits push + PR)", () => {
    expect(flowPermissionRules(flow({ push: "auto-pr" }))).toEqual({ askToolRules: [], denyToolRules: [] });
  });

  it("push-confirm + hard gate asks before push and PR", () => {
    const r = flowPermissionRules(flow({ push: "push-confirm", gate: "hard" }));
    expect(r.askToolRules).toEqual([...PUSH_WRITE_RULES]);
    expect(r.denyToolRules).toEqual([]);
  });

  it("push-confirm + soft gate contributes no enforced rules (kickoff asks)", () => {
    expect(flowPermissionRules(flow({ push: "push-confirm", gate: "soft" }))).toEqual({ askToolRules: [], denyToolRules: [] });
  });

  it("commit-only denies push and PR but leaves commits local", () => {
    const r = flowPermissionRules(flow({ push: "commit-only" }));
    expect(r.denyToolRules).toEqual([...PUSH_WRITE_RULES]);
    expect(r.askToolRules).toEqual([]);
  });

  it("none denies push and PR (no GitHub propagation)", () => {
    expect(flowPermissionRules(flow({ push: "none" })).denyToolRules).toEqual([...PUSH_WRITE_RULES]);
  });

  it("local denies push and PR — nothing reaches a remote", () => {
    const r = flowPermissionRules(flow({ push: "local" }));
    expect(r.denyToolRules).toEqual([...PUSH_WRITE_RULES]);
    expect(r.askToolRules).toEqual([]);
  });

  it("undefined flow resolves to DEFAULT_FLOW (local) — push and PR denied", () => {
    expect(flowPermissionRules(undefined)).toEqual({ askToolRules: [], denyToolRules: [...PUSH_WRITE_RULES] });
  });

  // The guarantee asserted from ONE list, so a push policy added later without a decision here
  // shows up as a failure rather than as a silent remote write.
  it("every LOCAL_ONLY_PUSH policy denies push and PR under both gates", () => {
    for (const push of LOCAL_ONLY_PUSH) {
      for (const gate of ["soft", "hard"] as const) {
        const r = flowPermissionRules(flow({ push, gate }));
        expect(r.denyToolRules, `${push}/${gate} must deny`).toEqual([...PUSH_WRITE_RULES]);
        expect(r.askToolRules, `${push}/${gate} must not merely ask`).toEqual([]);
      }
    }
  });

  it("FAILS CLOSED — an unrecognized push policy denies rather than permitting", () => {
    // The old `default` branch returned no rules, which under the broad Bash allow PERMITS push+PR.
    const r = flowPermissionRules(flow({ push: "not-a-real-policy" as never }));
    expect(r.denyToolRules).toEqual([...PUSH_WRITE_RULES]);
  });

  it("grants push commands only to the policies that actually push", () => {
    for (const push of LOCAL_ONLY_PUSH) {
      expect(flowGrantedPushCommands(flow({ push })), `${push} must grant nothing`).toEqual([]);
    }
    expect(flowGrantedPushCommands(flow({ push: "auto-pr" }))).toEqual(["git push", "gh pr create"]);
  });

  it("gate is ignored unless push is push-confirm", () => {
    // a hard gate on an auto-pr flow must not start blocking/asking
    expect(flowPermissionRules(flow({ push: "auto-pr", gate: "hard" }))).toEqual({ askToolRules: [], denyToolRules: [] });
  });
});

import { flowGrantedPushCommands } from "@/features/planner/fleet/flowPermissions";

describe("flowGrantedPushCommands — reconcile with the role gate (#304)", () => {
  it("auto-pr grants git push + gh pr create (lifts the worker role's gh-pr deny)", () => {
    expect(flowGrantedPushCommands(flow({ push: "auto-pr" }))).toEqual(["git push", "gh pr create"]);
  });

  it("push-confirm also grants them (the flow's ask tier then prompts)", () => {
    expect(flowGrantedPushCommands(flow({ push: "push-confirm", gate: "hard" }))).toEqual(["git push", "gh pr create"]);
  });

  it("commit-only and none grant nothing — the role's denies hold", () => {
    expect(flowGrantedPushCommands(flow({ push: "commit-only" }))).toEqual([]);
    expect(flowGrantedPushCommands(flow({ push: "none" }))).toEqual([]);
  });

  it("never grants gh pr merge or other role-denied writes", () => {
    for (const p of ["auto-pr", "push-confirm", "commit-only", "none"] as const) {
      const g = flowGrantedPushCommands(flow({ push: p }));
      expect(g).not.toContain("gh pr merge");
      expect(g).not.toContain("gh repo delete");
    }
  });
});

implementations.code:
// Pure logic for the console focus queue — the ordered set of panes (across all
// tabs) that finished a turn (run -> idle) and await a response, cycled through
// with Ctrl+Shift+N or auto-advance on reply. A pane stays queued (even while you
// view it) until you actually send it a response; advancing just moves the cursor,
// switching tabs when the next waiting pane lives on a different tab.

/** A pane's global identity: which tab it's on and its index within that tab. */
export interface QueuedPane {
  tab: number;
  pane: number;
}

// ── Role-aware focus targeting (#392) ─────────────────────────────────────────
//
// Which panes the autofocus queue pulls your attention to. With a director/worker
// fleet, you usually want only the DIRECTOR to surface — workers run dark and
// escalate via bsc-ask (which flips their pane to awaiting-input through the
// coordinator), so genuine worker questions still reach you. A plain console
// (no role) always queues, except under "none".

export type FocusTarget =
  | "director"   // default: the integrator + plain consoles; workers run dark
  | "workers"    // workers + plain consoles (debug worker behavior)
  | "fleet"      // every fleet role (director + workers) + consoles
  | "everything" // every idle pane, whatever its role
  | "none";      // nothing auto-queues (fully manual)

/** The presets, in display order — for a picker control. */
export const FOCUS_TARGETS: FocusTarget[] = ["director", "workers", "fleet", "everything", "none"];

/** Default focus target — surface the director; let workers run dark. */
export const DEFAULT_FOCUS_TARGET: FocusTarget = "director";

/** Human label for a focus target. */
export function focusTargetLabel(t: FocusTarget): string {
  switch (t) {
    case "director": return "Director";
    case "workers": return "Workers";
    case "fleet": return "Director + workers";
    case "everything": return "Everything";
    case "none": return "None";
  }
}

/**
 * Whether a pane that just went idle should join the focus queue, given the active
 * target. A role-less pane (a plain console — `role` undefined/empty) always queues
 * except under "none", so single-console behavior is unchanged for every target but
 * "none". A fleet pane queues only when its role matches the target.
 *
 * @param role the pane's session role (`paneRoles[pid]`), or undefined for a plain console.
 * @param target the active focus target.
 */
export function shouldFocus(role: string | undefined, target: FocusTarget): boolean {
  if (target === "none") return false;
  if (!role) return true;                       // plain console — always queue (except "none")
  switch (target) {
    case "everything": return true;
    case "director":   return role === "director";
    case "workers":    return role === "worker";
    case "fleet":      return role === "director" || role === "worker";
  }
}

// ── Configurable auto-focus modes (#434) ──────────────────────────────────────
//
// Controls WHEN focus auto-advances after you send a message to the active pane.
// Replaces the old `autoAdvanceOnReply` boolean (still exported for back-compat).

export type ConsoleAutoFocusMode =
  | "cycle-on-reply" // advance to the next queued pane each time you reply (was `true`)
  | "off";           // no automatic advance; use Ctrl+Shift+N manually (was `false`)

/** The presets, in display order — for a picker control. */
export const AUTO_FOCUS_MODES: ConsoleAutoFocusMode[] = ["cycle-on-reply", "off"];

/** Default auto-focus mode: cycle on reply (the original behavior). */
export const DEFAULT_AUTO_FOCUS_MODE: ConsoleAutoFocusMode = "cycle-on-reply";

/** Human label for an auto-focus mode. */
export function autoFocusModeLabel(m: ConsoleAutoFocusMode): string {
  switch (m) {
    case "cycle-on-reply": return "Cycle on reply";
    case "off":            return "Off (manual)";
  }
}

const samePane = (a: QueuedPane, b: QueuedPane) => a.tab === b.tab && a.pane === b.pane;

/**
 * Append a pane to the waiting queue, de-duplicated and order-preserving. Returns
 * the same array reference when nothing changes (so the store can skip a needless
 * update).
 *
 * @param queue current waiting queue.
 * @param entry pane that just went idle.
 */
export function enqueue(queue: QueuedPane[], entry: QueuedPane): QueuedPane[] {
  if (entry.pane < 0 || queue.some((q) => samePane(q, entry))) return queue;
  return [...queue, entry];
}

/** Remove a pane (attended, or back to "run"); same reference if not present. */
export function removeFromQueue(queue: QueuedPane[], entry: QueuedPane): QueuedPane[] {
  return queue.some((q) => samePane(q, entry)) ? queue.filter((q) => !samePane(q, entry)) : queue;
}

/**
 * The next pane to move to when cycling the queue, relative to the pane you're on.
 * Round-robins through the waiting panes — the current one is NOT removed (a pane
 * leaves only when you respond to it), so cycling can land back on it later.
 *
 * @param queue waiting panes.
 * @param current the pane you're on (focused, or maximized).
 * @returns the next waiting pane (possibly on another tab), or null when there's
 *   nowhere else to go (empty queue, or the only queued pane is the current one).
 */
export function nextInCycle(queue: QueuedPane[], current: QueuedPane): QueuedPane | null {
  if (queue.length === 0) return null;
  const idx = queue.findIndex((q) => samePane(q, current));
  if (idx === -1) return queue[0];                 // current isn't waiting → first waiting pane
  const next = queue[(idx + 1) % queue.length];
  return samePane(next, current) ? null : next;     // only the current pane is queued → nowhere to go
}

/**
 * Prune the queue to the panes still waiting, across every tab whose live status
 * we have. After #187 every tab's panes stay mounted, so the caller can supply a
 * per-tab waiting set for every tab — a queued entry stays iff its pane appears
 * in its tab's set. Tabs absent from the map (no live data — e.g. an empty
 * workspace mid-transition) leave their entries alone, since we don't want a
 * temporarily-missing tab to silently drop queued panes.
 *
 * @param queue current waiting queue.
 * @param waitingByTab live waiting indices per tab (idle panes that should stay queued).
 * @returns the pruned queue, or the same reference when nothing changed.
 */
export function reconcileQueue(
  queue: QueuedPane[],
  waitingByTab: ReadonlyMap<number, ReadonlySet<number>>,
): QueuedPane[] {
  const pruned = queue.filter((q) => {
    const waiting = waitingByTab.get(q.tab);
    return waiting === undefined || waiting.has(q.pane);
  });
  return pruned.length === queue.length ? queue : pruned;
}

tests.src:
import { describe, it, expect } from "vitest";
import {
  enqueue, removeFromQueue, nextInCycle, reconcileQueue,
  shouldFocus, FOCUS_TARGETS, DEFAULT_FOCUS_TARGET, focusTargetLabel,
  AUTO_FOCUS_MODES, DEFAULT_AUTO_FOCUS_MODE, autoFocusModeLabel,
  type QueuedPane,
} from "@/app/console/lib/focusQueue";

const p = (tab: number, pane: number): QueuedPane => ({ tab, pane });

describe("enqueue", () => {
  it("appends a new pane in FIFO order", () => {
    expect(enqueue([p(0, 1), p(0, 2)], p(0, 3))).toEqual([p(0, 1), p(0, 2), p(0, 3)]);
  });

  it("de-duplicates an already-queued pane (same reference)", () => {
    const q = [p(0, 1), p(0, 2)];
    expect(enqueue(q, p(0, 2))).toBe(q);
  });

  it("treats the same pane index on different tabs as distinct", () => {
    expect(enqueue([p(0, 2)], p(1, 2))).toEqual([p(0, 2), p(1, 2)]);
  });

  it("ignores negative pane indices", () => {
    const q = [p(0, 1)];
    expect(enqueue(q, p(0, -1))).toBe(q);
  });
});

describe("removeFromQueue", () => {
  it("removes a queued pane", () => {
    expect(removeFromQueue([p(0, 1), p(0, 2), p(0, 3)], p(0, 2))).toEqual([p(0, 1), p(0, 3)]);
  });

  it("is a no-op (same reference) for an absent pane", () => {
    const q = [p(0, 1), p(0, 2)];
    expect(removeFromQueue(q, p(0, 9))).toBe(q);
    expect(removeFromQueue(q, p(1, 1))).toBe(q); // same index, different tab
  });
});

describe("nextInCycle", () => {
  it("moves to the next waiting pane after the current one", () => {
    expect(nextInCycle([p(0, 5), p(0, 6), p(0, 7)], p(0, 5))).toEqual(p(0, 6));
  });

  it("wraps around to the front", () => {
    expect(nextInCycle([p(0, 5), p(0, 6), p(0, 7)], p(0, 7))).toEqual(p(0, 5));
  });

  it("returns a waiting pane on another tab", () => {
    expect(nextInCycle([p(0, 5), p(1, 2)], p(0, 5))).toEqual(p(1, 2));
  });

  it("starts at the front when the current pane isn't queued", () => {
    expect(nextInCycle([p(0, 5), p(0, 6), p(0, 7)], p(0, 9))).toEqual(p(0, 5));
  });

  it("returns null when the only queued pane is the current one", () => {
    expect(nextInCycle([p(0, 5)], p(0, 5))).toBeNull();
  });

  it("returns null for an empty queue", () => {
    expect(nextInCycle([], p(0, 3))).toBeNull();
  });
});

describe("reconcileQueue", () => {
  // After #187 every tab is mounted, so the caller can pass live waiting sets
  // for ALL tabs in one go. Callers from #77 wire this up so background-tab
  // panes get pruned the same way active-tab panes do.
  const w = (entries: Record<number, number[]>): Map<number, Set<number>> =>
    new Map(Object.entries(entries).map(([t, panes]) => [Number(t), new Set(panes)]));

  it("drops a tab's panes that are no longer waiting", () => {
    expect(reconcileQueue([p(0, 1), p(0, 2), p(0, 3)], w({ 0: [1, 3] })))
      .toEqual([p(0, 1), p(0, 3)]);
  });

  it("prunes across multiple tabs in one sweep", () => {
    // p(0,3) no longer idle on tab 0; p(1,5) no longer idle on tab 1 — both go.
    const q = [p(0, 1), p(1, 5), p(0, 3), p(1, 2)];
    expect(reconcileQueue(q, w({ 0: [1], 1: [2] }))).toEqual([p(0, 1), p(1, 2)]);
  });

  it("returns the same reference when nothing is pruned", () => {
    const q = [p(0, 1), p(0, 2)];
    expect(reconcileQueue(q, w({ 0: [1, 2] }))).toBe(q);
  });

  it("empties when nothing on a single-tab queue is waiting", () => {
    expect(reconcileQueue([p(0, 1), p(0, 2)], w({ 0: [] }))).toEqual([]);
  });

  it("leaves tabs absent from the map alone (no live data → no assumption)", () => {
    // Tab 1 not in the map → its entries survive even if the caller has no
    // status info for them. Defensive against transient empty-state moments.
    const q = [p(0, 1), p(1, 2)];
    expect(reconcileQueue(q, w({ 0: [1] }))).toEqual([p(0, 1), p(1, 2)]);
  });
});

describe("shouldFocus (role-aware focus targeting #392)", () => {
  it("default target is director", () => {
    expect(DEFAULT_FOCUS_TARGET).toBe("director");
  });

  it("a plain console (no role) always queues except under 'none'", () => {
    for (const t of FOCUS_TARGETS) {
      expect(shouldFocus(undefined, t)).toBe(t !== "none");
      expect(shouldFocus("", t)).toBe(t !== "none");
    }
  });

  it("'none' queues nothing — not even the director or a console", () => {
    expect(shouldFocus("director", "none")).toBe(false);
    expect(shouldFocus("worker", "none")).toBe(false);
    expect(shouldFocus(undefined, "none")).toBe(false);
  });

  it("'director' queues only director panes (workers run dark)", () => {
    expect(shouldFocus("director", "director")).toBe(true);
    expect(shouldFocus("worker", "director")).toBe(false);
    expect(shouldFocus("triage", "director")).toBe(false);
  });

  it("'workers' queues only worker panes", () => {
