import { describe, it, expect } from "vitest";
import { buildGhStructure, type Section } from "@/features/planner/github/ghStructure";

// Minimal section factory — only `k` and `content` matter to the structure.
const sec = (k: Section["k"], content = ""): Section => ({
  k, content, title: k, state: content ? "drafted" : "pending",
});

describe("buildGhStructure", () => {
  it("creates one repo node per linked repository, id-prefixed", () => {
    const s = buildGhStructure([sec("goal", "A tool.")], ["acme/api", "acme/web"], "My Project");
    expect(s.repos.map(r => r.node)).toEqual([
      { id: "repo:acme/api", label: "acme/api" },
      { id: "repo:acme/web", label: "acme/web" },
    ]);
  });

  it("creates a single project node labelled with the title", () => {
    const s = buildGhStructure([], [], "My Project");
    expect(s.project).toEqual({ id: "project", label: "My Project" });
  });

  it("gives a repo no issues when no features section is present", () => {
    const s = buildGhStructure([sec("goal", "A tool.")], ["acme/api"], "P");
    expect(s.repos[0].issues).toEqual([]);
  });

  it("yields no repo issues when the features content is invalid JSON", () => {
    const s = buildGhStructure([sec("features", "not json")], ["acme/api"], "P");
    expect(s.repos[0].issues).toEqual([]);
  });

  it("has no repos when none are linked", () => {
    const s = buildGhStructure([sec("goal", "A tool.")], [], "P");
    expect(s.repos).toEqual([]);
  });
});

describe("buildGhStructure — issues generated from features (#plan-db)", () => {
  it("nests one node per FEATURE under the repo (slug = id, name = label)", () => {
    const features = JSON.stringify([
      { slug: "endpoint", name: "Add endpoint" },
      { slug: "ui", name: "Wire UI", dependsOn: ["endpoint"] },
    ]);
    const st = buildGhStructure([sec("features", features)], ["o/web"], "Proj");
    expect(st.repos[0].issues.map(i => i.label)).toEqual(["Add endpoint", "Wire UI"]);
    expect(st.repos[0].issues.map(i => i.id)).toEqual(["issue:o/web:endpoint", "issue:o/web:ui"]);
  });

  it("routes every feature-issue to the default (first) repo — features carry no repo", () => {
    const features = JSON.stringify([
      { slug: "a", name: "first" },
      { slug: "b", name: "second" },
    ]);
    const st = buildGhStructure([sec("features", features)], ["o/web", "o/api"], "Proj");
    expect(st.repos.find(r => r.node.label === "o/web")!.issues.map(i => i.label)).toEqual(["first", "second"]);
    expect(st.repos.find(r => r.node.label === "o/api")!.issues).toEqual([]);
  });

  it("namespaces issue ids by repo so the same slug is distinct per repo", () => {
    const features = JSON.stringify([{ slug: "a", name: "first" }]);
    const st = buildGhStructure([sec("features", features)], ["o/web"], "Proj");
    expect(st.repos[0].issues.map(i => i.id)).toEqual(["issue:o/web:a"]);
  });
});

import { describe, it, expect } from "vitest";
import { pendingStageConfirms, stageConfirmKeys } from "@/features/planner/stages/planStageDerive";
import type { SectionState } from "@/features/planner/github/ghStructure";

type S = { k: string; state: SectionState };
const sec = (k: string, state: SectionState): S => ({ k, state });

// The four core context topics, all present + drafted (the common "planner finished discovery" case).
const coreDrafted: S[] = [
  sec("goal", "drafted"), sec("scope", "drafted"),
  sec("stack", "drafted"), sec("architecture", "drafted"),
];

describe("pendingStageConfirms — one-click stage approval (#807-followup)", () => {
  it("context: nothing to confirm — context files gate on GENERATION, not confirmation (#1028)", () => {
    const sections = [...coreDrafted, sec("api", "drafted"), sec("schema", "confirmed")];
    expect(pendingStageConfirms("discovery", sections)).toEqual([]);
  });

  it("structure: nothing to confirm — milestone phases were removed (#1912)", () => {
    // The Structure stage no longer confirms a `phases` roadmap anchor; it gates on featuresDefined.
    expect(pendingStageConfirms("streams", [sec("phases", "drafted")])).toEqual([]);
    expect(pendingStageConfirms("streams", [])).toEqual([]);
  });

  it("count-gated stages (streams, features, …) have nothing to confirm by section", () => {
    expect(pendingStageConfirms("streams", coreDrafted)).toEqual([]);
    expect(pendingStageConfirms(undefined, coreDrafted)).toEqual([]);
  });
});

describe("stageConfirmKeys — gateless active-stage approval (#954)", () => {
  it("confirms a GATELESS active stage by its own key so the frontier advances", () => {
    // A gateless informational stage (no gateRule) with nothing for pendingStageConfirms to find:
    // approve must confirm the stage itself.
    expect(stageConfirmKeys("cleanup", [], /*activeHasGate*/ false, /*confirmed*/ false)).toEqual(["cleanup"]);
  });

  it("does NOT re-confirm a gateless stage that's already confirmed", () => {
    expect(stageConfirmKeys("cleanup", [], false, true)).toEqual([]);
  });

  it("a GATED active stage confirms nothing extra by key (it completes via its gate)", () => {
    expect(stageConfirmKeys("deployment", [], /*activeHasGate*/ true, false)).toEqual([]);
  });

  it("a GATED streams/context confirms nothing extra by key — they complete via their gate (#1912)", () => {
    // structure (gated) gates on featuresDefined now — no phases anchor to confirm
    expect(stageConfirmKeys("streams", [sec("phases", "drafted")], /*activeHasGate*/ true, false)).toEqual([]);
    // context (gated) → no confirm step; the files are done once written (#1028)
    expect(stageConfirmKeys("discovery", coreDrafted, /*activeHasGate*/ true, false)).toEqual([]);
  });

  it("a GATELESS context/structure (e.g. an IMPORTED blueprint) confirms ITS OWN key, not the anchors", () => {
    // Imported blueprints lose their gateRules, so even a `context`/`structure` stage is gateless and
    // completes via confirmed:<its-key>.
    expect(stageConfirmKeys("discovery", coreDrafted, /*activeHasGate*/ false, false)).toEqual(["discovery"]);
    expect(stageConfirmKeys("streams", [sec("phases", "drafted")], /*activeHasGate*/ false, false)).toEqual(["streams"]);
  });

  it("no active stage ⇒ nothing to confirm", () => {
    expect(stageConfirmKeys(undefined, [], false, false)).toEqual([]);
  });
});

