// The graph layout (#3224) — a pure, deterministic placement of node ids for the SVG GraphView. Split out
// of the renderer so the renderer file exports only its component (fast-refresh) and the layout is
// unit-testable on its own.

/** The svg viewBox is VIEW × VIEW; the layout circle has this radius. */
export const GRAPH_VIEW = 320;
const RADIUS = 116;

const PAD = 38; // inset for the coordinate layout so nodes don't touch the frame edge

/** Place every id evenly on a circle, starting at the top (−90°). Pure + deterministic. */
export function circularLayout(ids: readonly string[]): Record<string, { x: number; y: number }> {
  const cx = GRAPH_VIEW / 2;
  const cy = GRAPH_VIEW / 2;
  const n = Math.max(1, ids.length);
  const pos: Record<string, { x: number; y: number }> = {};
  ids.forEach((id, i) => {
    const t = (i / n) * 2 * Math.PI - Math.PI / 2;
    pos[id] = { x: cx + RADIUS * Math.cos(t), y: cy + RADIUS * Math.sin(t) };
  });
  return pos;
}

/** A spatial layout from the nodes' own `x`/`y` (a road network, a grid) — scaled + padded to fit the
 *  viewBox. Returns `null` unless EVERY node has coordinates (so the caller can fall back to circular). */
export function coordinateLayout(
  nodes: readonly { id: string; x?: number; y?: number }[],
): Record<string, { x: number; y: number }> | null {
  if (nodes.length === 0 || !nodes.every((n) => n.x !== undefined && n.y !== undefined)) return null;
  const xs = nodes.map((n) => n.x as number);
  const ys = nodes.map((n) => n.y as number);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);
  const spanX = Math.max(...xs) - minX || 1;
  const spanY = Math.max(...ys) - minY || 1;
  const inner = GRAPH_VIEW - 2 * PAD;
  const pos: Record<string, { x: number; y: number }> = {};
  for (const n of nodes) {
    pos[n.id] = {
      x: PAD + (((n.x as number) - minX) / spanX) * inner,
      y: PAD + (((n.y as number) - minY) / spanY) * inner,
    };
  }
  return pos;
}

/** The layout GraphView uses — the nodes' own coordinates when they all carry them (A*'s spatial graph),
 *  else an even circle. */
export function layoutFor(
  nodes: readonly { id: string; x?: number; y?: number }[],
): Record<string, { x: number; y: number }> {
  return coordinateLayout(nodes) ?? circularLayout(nodes.map((n) => n.id));
}

// A MODULE SYSTEM for graph records (epic #3604) — the replacement for vendoring.
//
// Before this, `componentLoader` treated every record as *source to re-bundle*: `loaderPlugin` pulled
// each graph sibling INTO the entry's esbuild build, recursively, so a page and its panels compiled as
// one module. That has three costs, and they compound:
//   - mounting a page recompiles the page AND its whole subtree, every mount (the host has no compiled
//     cache — only the last-good render gate);
//   - editing one leaf invalidates every ancestor that vendored it;
//   - a record vendored into two parents becomes TWO module instances, which is why a registry with
//     load-bearing module-init side effects (`stageScreens`) could not be migrated.
//
// The fix is to treat records as MODULES. The obstacle is that `require` has to be synchronous while
// esbuild-wasm is asynchronous, so this splits into two phases — which is what a linker is:
//
//   1. LINK (async, [`linkGraphModules`]) — compile the entry standalone with every import external,
//      scan the emitted `require("…")` specifiers, ask the resolver which are records, compile those,
//      recurse. Compilation is memoized by EXACT SOURCE TEXT, so an unchanged record never recompiles.
//   2. EVAL (sync, [`makeGraphRequire`]) — a Node-style `require` over the linked set: graph module
//      first, then the app registry, then a named error.
//
// Scanning the COMPILED output rather than the TSX is deliberate: esbuild already emits exactly one
// `require()` per external import, so there is no second import parser to keep in sync with the first.
//
// SCOPE NOTE — the evaluated-exports cache is per LOAD, not global. That keeps module-instance
// semantics identical to vendoring (one instance per page load), so this slice changes performance and
// invalidation WITHOUT changing identity. Making instances global is a real improvement and a separate
// decision: it is what would let `stageScreens` migrate, and it deserves its own slice rather than
// riding along invisibly inside a performance change.

/** One linked graph module: the source it came from and the CommonJS esbuild produced for it. */
export interface LinkedModule {
  specifier: string;
  source: string;
  cjs: string;
}

/** Compile one self-standing module's source to CommonJS with every import left external. Injected so
 *  the linker is unit-testable without esbuild (the real compile is browser-only). */
export type CompileFn = (source: string) => Promise<string>;

/** Resolve a specifier to a graph record's source, or `null`/`undefined` when it is not a record. Same
 *  contract as the loader's `GraphSourceResolver` — one resolver, so `provides` overrides (#3660) and
 *  `@/components/<id>` siblings both keep working here. */
export type SourceResolver = (specifier: string) => string | null | undefined;

/**
 * Every specifier the compiled module `require`s. Matches the `require("x")` / `require('x')` calls
 * esbuild emits for external imports.
 *
 * Deliberately a scan of the OUTPUT, not the input: the output has one call per external import in a
 * single fixed shape, whereas the input is TSX with type-only imports, re-exports and side-effect
 * imports that a hand-rolled parser gets wrong. #4188 and #4224 each removed a static check that was
 * more permissive than the runtime; this avoids adding a third.
 *
 * Duplicates are collapsed and order is preserved (first occurrence wins), so a caller can rely on it
 * for a deterministic link order.
 */
export function scanRequires(cjs: string): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const m of cjs.matchAll(/\brequire\(\s*["']([^"']+)["']\s*\)/g)) {
    const spec = m[1];
    if (!seen.has(spec)) {
      seen.add(spec);
      out.push(spec);
    }
  }
  return out;
}

/** The process-wide compile cache, keyed `specifier` + NUL + `source` (a NUL separator, so a
 *  specifier containing the delimiter cannot forge another entry's key). Keying on the EXACT source (not just
 *  the specifier) is what makes it safe to keep forever: an edited record is a different key, so a
 *  stale entry is unreachable rather than wrong. */
const compileCache = new Map<string, string>();

const cacheKey = (specifier: string, source: string) => `${specifier}\u0000${source}`;

/** Compile through the cache. Exported for the loader so the ENTRY is memoized on the same terms as
 *  its dependencies — the entry is the one a host re-mounts most often. */
export async function compileCached(specifier: string, source: string, compile: CompileFn): Promise<string> {
  const key = cacheKey(specifier, source);
  const hit = compileCache.get(key);
  if (hit !== undefined) return hit;
  const cjs = await compile(source);
  compileCache.set(key, cjs);
  return cjs;
}

/** How many records are compiled in the cache — diagnostics + the test that proves a second mount
 *  compiles nothing. */
export function compileCacheSize(): number {
  return compileCache.size;
}

/** Drop the compile cache (tests, and a hard reset path). */
export function __resetCompileCache(): void {
  compileCache.clear();
}

/** The specifier the entry module is linked under. Not a real import path — nothing can `require` it,
 *  which is the point: the entry is reachable only as the link root. */
export const ENTRY_SPECIFIER = "\u0000graph-entry";

/**
 * LINK PHASE. Compile `entrySource` and, transitively, every graph record it reaches, returning the
 * linked set keyed by specifier. The entry is present under {@link ENTRY_SPECIFIER}.
 *
 * Traversal is breadth-first over a `seen` set, so an import CYCLE between records terminates here as
 * well as during eval — a cycle is a normal shape for modules and must not hang the linker.
 *
 * A specifier the resolver does not claim is left alone: it stays external and `require` resolves it
 * against the app registry at eval time. That is what keeps platform modules (React, the store, the
 * registered primitives) as the single live instance they have to be.
 */
export async function linkGraphModules(
  entrySource: string,
  resolveSource: SourceResolver | undefined,
  compile: CompileFn,
): Promise<LinkResult> {
  const linked = new Map<string, LinkedModule>();
  const failures: CompileFailure[] = [];
  const entryCjs = await compileCached(ENTRY_SPECIFIER, entrySource, compile);
  linked.set(ENTRY_SPECIFIER, { specifier: ENTRY_SPECIFIER, source: entrySource, cjs: entryCjs });

  const queue = scanRequires(entryCjs);
  const seen = new Set<string>();
  while (queue.length) {
    const spec = queue.shift() as string;
    if (seen.has(spec) || linked.has(spec)) continue;
    seen.add(spec);
    const source = resolveSource?.(spec);
    if (source == null) continue; // not a record → external → the app registry answers it
    let cjs: string;
    try {
      cjs = await compileCached(spec, source, compile);
    } catch (e) {
      // AN OVERRIDE THAT WILL NOT COMPILE IS DECLINED, not fatal. The entry above is compiled outside
      // this loop and still throws — that is the page's OWN source, and a page that cannot compile has
      // no render to salvage. But everything in here is a record shadowing something the registry can
      // answer, so one bad record must cost its own surface rather than the whole page.
      //
      // This is the same principle as the unsatisfiable-closure prune below, for the other way a record
      // fails. It was worth a page: the `graphcomponent` record compiled clean standalone and failed when
      // vendored, and because the throw escaped the link phase it took the entire Projects page down with
      // "Build failed with 2 errors" and no indication of which of its 241 closure members was at fault.
      // Naming the specifier here is half the fix — the diagnosis took a log dive to reach.
      failures.push({ specifier: spec, error: String(e).slice(0, 200) });
      continue;
    }
    linked.set(spec, { specifier: spec, source, cjs });
    queue.push(...scanRequires(cjs));
  }
  return { linked, failures };
}

/** An override that would not COMPILE — declined during the link phase so the registry answers instead. */
export interface CompileFailure {
  specifier: string;
  error: string;
}

/** What {@link linkGraphModules} produced: the modules it linked, and the overrides it had to decline
 *  because their source does not compile. Both halves matter to the caller — the second is the only
 *  place a broken record is NAMED, and without it the page reports a build error against a closure of
 *  hundreds with nothing to point at. */
export interface LinkResult {
  linked: Map<string, LinkedModule>;
  failures: CompileFailure[];
}

/** One override the prune declined, for the caller to log. `specifier` is the module the record claimed;
 *  `missing` is the first specifier in its closure that nothing could answer. */
export interface DeclinedOverride {
  specifier: string;
  missing: string;
}

/** What {@link pruneUnsatisfiableOverrides} produced: the linked set to evaluate, and what it declined. */
export interface PruneResult {
  linked: Map<string, LinkedModule>;
  declined: DeclinedOverride[];
}

/**
 * PRUNE PHASE — decline a graph module whose own closure cannot be resolved, so `require` falls back to
 * the platform module it was overriding instead of the page dying.
 *
 * THE FAILURE THIS EXISTS FOR. `provides` is a GLOBAL override and resolution is graph-first (#3660), so
 * a record claiming `@/shared/hooks/usePageTabs` wins over the registered one everywhere. That is correct
 * when the record can stand on its own — and catastrophic when it cannot: a harvested module whose own
 * imports were never registered takes down EVERY page whose closure touches that specifier. Measured on
 * a live store: 67 of 544 overrides in that state, and the two that mattered killed Glance and Console
 * outright ("`glancepage` failed to load: import `@/shared/lib/core/arrayMove` is not a registered app
 * module").
 *
 * An override that cannot resolve its own imports is not a working override. Declining it is not a
 * workaround for a bad record — it is the honest reading of what the record can currently deliver.
 *
 * ONLY WHERE THERE IS A FALLBACK. A module is declined only if `isAvailable(specifier)` — i.e. the
 * platform genuinely has something to answer with. A specifier with no registered module (a
 * `@/components/<id>` sibling, an entry) is left in place so the page still fails loudly; inventing a
 * fallback that does not exist would turn a named error into a blank screen.
 *
 * ONE PASS, and the reason it needs no fixed point is the load-bearing insight: a dependency that is
 * ITSELF available can never be the cause of a failure. If module A imports B and B is an override with
 * a platform fallback, then B resolves either as a graph module or — if B is declined too — as the
 * bundled one. Either way A's import of B resolves, so the walk stops at B instead of inheriting its
 * problems. Only a dependency with NO fallback (a `@/components/<id>` sibling) propagates, and those are
 * never declined, so the outcome is stable after a single sweep and independent of map order.
 *
 * Getting this wrong is not academic: descending through available dependencies declines A as well as B,
 * which silently reverts a perfectly good migration because something one hop away was broken.
 *
 * Pure: a map plus a predicate. No esbuild, no DOM, no store — which is what lets the rule be tested.
 */
export function pruneUnsatisfiableOverrides(
  linked: Map<string, LinkedModule>,
  isAvailable: (specifier: string) => boolean,
): PruneResult {
  const kept = new Map(linked);
  const declined: DeclinedOverride[] = [];

  /** The first specifier in `spec`'s closure that nothing can answer, or null when it is satisfiable.
   *  `seen` guards an import CYCLE, which is a normal module shape the linker and the eval cache both
   *  already tolerate. */
  const firstUnreachable = (spec: string): string | null => {
    const seen = new Set<string>([spec]);
    const queue = [...scanRequires(linked.get(spec)?.cjs ?? "")];
    while (queue.length) {
      const dep = queue.shift() as string;
      if (seen.has(dep)) continue;
      seen.add(dep);
      // Has a fallback ⇒ always resolvable ⇒ stop here (see the one-pass note above).
      if (isAvailable(dep)) continue;
      const mod = linked.get(dep);
      // No fallback and not a graph module ⇒ nothing can answer it. This is the failure.
      if (!mod) return dep;
      // No fallback but IS a graph module (a sibling) ⇒ its failure is our failure; keep walking.
      queue.push(...scanRequires(mod.cjs));
    }
    return null;
  };

  for (const spec of kept.keys()) {
    // The ENTRY is never declined: it is the thing being loaded, it overrides nothing, and there is no
    // module to fall back to. Its unresolved imports are a real failure and must still throw.
    if (spec === ENTRY_SPECIFIER) continue;
    // Nothing to fall back to ⇒ leave it in place and let the page fail loudly. Declining here would
    // swap a named error for a blank screen.
    if (!isAvailable(spec)) continue;
    const missing = firstUnreachable(spec);
    if (missing) declined.push({ specifier: spec, missing });
  }
  for (const d of declined) kept.delete(d.specifier);
  return { linked: kept, declined };
}

/** Evaluate CommonJS with an injected `require`, returning its `module.exports`. Kept here (rather than
 *  reusing the loader's) so the eval + cache insertion order below is one readable unit. */
function evaluate(cjs: string, require: (s: string) => unknown): Record<string, unknown> {
  const module = { exports: {} as Record<string, unknown> };
  // `new Function` runs graph-authored code in the app context — the premise of graph-as-source (#3604),
  // and the reason every mount is wrapped in an error boundary + fallback.
  const factory = new Function("require", "module", "exports", cjs);
  factory(require, module, module.exports);
  return module.exports;
}

/**
 * EVAL PHASE. Build the `require` a linked module runs against.
 *
 * Resolution order — **graph first**, which is what keeps `provides` overrides (#3660) working: a
 * record that provides `@/shared/ui/Button` must win over the bundled Button, and it only can if the
 * graph is consulted before the registry.
 *
 *   1. an already-evaluated graph module → its exports
 *   2. a linked-but-not-yet-evaluated graph module → evaluate it now
 *   3. `appRequire` — the registry, which throws a NAMED error for an unregistered specifier
 *
 * CYCLE SAFETY, Node's rule: the module's `exports` object is placed in the cache BEFORE its factory
 * runs, so a module that (transitively) requires itself gets the partially-filled object instead of
 * recursing forever. That is exactly how CommonJS has always behaved, including its one sharp edge —
 * a cyclic importer sees whatever was assigned before the cycle closed.
 */
export function makeGraphRequire(
  linked: Map<string, LinkedModule>,
  appRequire: (specifier: string) => unknown,
  onEvalFailure?: (specifier: string, error: unknown) => void,
): (specifier: string) => unknown {
  const evaluated = new Map<string, Record<string, unknown>>();

  const require = (specifier: string): unknown => {
    const done = evaluated.get(specifier);
    if (done !== undefined) return done;
    const mod = linked.get(specifier);
    if (!mod) return appRequire(specifier);
    const exports: Record<string, unknown> = {};
    evaluated.set(specifier, exports); // BEFORE evaluating — the cycle guard
    let produced: unknown;
    try {
      produced = evaluate(mod.cjs, require);
    } catch (e) {
      // A GRAPH MODULE THAT THROWS WHILE EVALUATING FALLS BACK TO THE REGISTRY. It compiled and linked;
      // it simply cannot RUN — the commonest cause being a build-time-only form, since `import.meta.glob`
      // is a Vite transform that esbuild emits verbatim and that is not a function at runtime.
      //
      // Eval, not source, is the right place to judge it: 19 records contain `import.meta.glob` and most
      // WORK, because the call sits in a path the page never takes. A source-level check declined those
      // too and regressed the Planning page. Throwing is the only honest signal that this record cannot
      // stand up.
      //
      // The entry is exempt — `evaluateEntry` calls `evaluate` on it directly, not through here — so a
      // page's own source still fails loudly rather than resolving to a shadow of itself.
      evaluated.delete(specifier);
      onEvalFailure?.(specifier, e);
      return appRequire(specifier);
    }
    // esbuild's CJS output assigns `module.exports = …` wholesale, so the object the factory ends up
    // with is usually NOT the one seeded above. Copy the result onto the seeded object so a cyclic
    // importer that already captured the seed still observes the finished exports.
    if (produced !== exports) {
      Object.assign(exports, produced);
      evaluated.set(specifier, produced as Record<string, unknown>);
    }
    return evaluated.get(specifier);
  };

  return require;
}

/** Evaluate the linked entry and return its exports — the whole eval phase in one call. */
export function evaluateEntry(
  linked: Map<string, LinkedModule>,
  appRequire: (specifier: string) => unknown,
  onEvalFailure?: (specifier: string, error: unknown) => void,
): Record<string, unknown> {
  const require = makeGraphRequire(linked, appRequire, onEvalFailure);
  return require(ENTRY_SPECIFIER) as Record<string, unknown>;
}

tests.src:
// The graph module system (epic #3604) — the linker that replaced vendoring.
//
// Every piece here is driven with an INJECTED compiler, never esbuild: the real compile is
// browser-only, and the properties worth pinning (what gets compiled, how often, resolution order,
// cycle termination) are all about the link/eval algebra rather than about codegen. The browser check
// is what proves a page still renders; these prove it links.
import { describe, it, expect, beforeEach } from "vitest";
import {
  scanRequires,
  linkGraphModules,
  makeGraphRequire,
  evaluateEntry,
  compileCacheSize,
  __resetCompileCache,
  ENTRY_SPECIFIER,
  type CompileFn,
} from "@/shared/lib/runtime/graphModules";

/** A fake compiler: emits CJS that records its own requires, and counts how many times it ran. */
function fakeCompiler() {
  const calls: string[] = [];
  const compile: CompileFn = async (source) => {
    calls.push(source);
    return source; // the "source" IS the CJS in these tests — it already contains require() calls
  };
  return { compile, calls };
}

beforeEach(() => __resetCompileCache());

describe("scanRequires", () => {
  it("finds every require specifier, de-duplicated, in first-seen order", () => {
    const cjs = `require("react"); const a = require('@/store'); require("react"); require( "@/components/x" )`;
    expect(scanRequires(cjs)).toEqual(["react", "@/store", "@/components/x"]);
  });

  it("returns nothing for a module with no imports", () => {
    expect(scanRequires("module.exports = {};")).toEqual([]);
  });

  it("does not match a bare word that merely contains 'require'", () => {
    // `prerequire(...)` is not a require call — \\b anchors the match so a substring cannot fake one.
    expect(scanRequires('prerequire("nope")')).toEqual([]);
  });
});

describe("linkGraphModules", () => {
  it("compiles the entry and every graph record it transitively reaches, and NOTHING else", async () => {
    const { compile, calls } = fakeCompiler();
    const graph: Record<string, string> = {
      "@/components/panel": 'require("@/components/leaf"); require("react");',
      "@/components/leaf": 'require("@/store");',
    };
    const { linked } = await linkGraphModules(
      'require("@/components/panel"); require("react");',
      (s) => graph[s] ?? null,
      compile,
    );

    expect([...linked.keys()].sort()).toEqual([ENTRY_SPECIFIER, "@/components/leaf", "@/components/panel"].sort());
    // `react` and `@/store` are NOT records — they stay external for the registry to answer.
    expect(linked.has("react")).toBe(false);
    expect(linked.has("@/store")).toBe(false);
    expect(calls).toHaveLength(3);
  });

  it("terminates on an import CYCLE between records", async () => {
    const { compile } = fakeCompiler();
    const graph: Record<string, string> = {
      "@/components/a": 'require("@/components/b");',
      "@/components/b": 'require("@/components/a");',
    };
    const { linked } = await linkGraphModules('require("@/components/a");', (s) => graph[s] ?? null, compile);
    expect([...linked.keys()].sort()).toEqual([ENTRY_SPECIFIER, "@/components/a", "@/components/b"].sort());
  });

  it("with no resolver, links only the entry — every import stays external", async () => {
    const { compile, calls } = fakeCompiler();
    const { linked } = await linkGraphModules('require("@/components/panel");', undefined, compile);
    expect([...linked.keys()]).toEqual([ENTRY_SPECIFIER]);
    expect(calls).toHaveLength(1);
  });

  it("MEMOIZES by exact source: a second link of the same page compiles nothing", async () => {
    const { compile, calls } = fakeCompiler();
    const graph: Record<string, string> = { "@/components/panel": 'require("@/store");' };
    const entry = 'require("@/components/panel");';
    await linkGraphModules(entry, (s) => graph[s] ?? null, compile);
    expect(calls).toHaveLength(2);
    await linkGraphModules(entry, (s) => graph[s] ?? null, compile);
    expect(calls, "a re-mount recompiles nothing — the whole point of the cache").toHaveLength(2);
    expect(compileCacheSize()).toBe(2);
  });

  it("invalidates ONLY the record that changed — its ancestors are not recompiled", async () => {
    const { compile, calls } = fakeCompiler();
    const entry = 'require("@/components/panel");';
    let panel = 'require("@/store"); // v1';
    const resolve = (s: string) => (s === "@/components/panel" ? panel : null);

    await linkGraphModules(entry, resolve, compile);
    expect(calls).toHaveLength(2); // entry + panel

    panel = 'require("@/store"); // v2 — edited';
    await linkGraphModules(entry, resolve, compile);
    // Exactly ONE new compile: the edited panel. The entry's source did not change, so its cached
    // output is reused — under vendoring this was impossible, because the panel was INSIDE the entry's
    // build and editing it invalidated every ancestor.
    expect(calls).toHaveLength(3);
    expect(calls[2]).toBe(panel);
  });

  it("DECLINES an override that will not compile instead of failing the whole link", async () => {
    // THE Projects-page bug. `graphcomponent` compiled clean standalone and failed when vendored, and
    // because the throw escaped the link phase it took the entire page down — 241 closure members, one
    // broken, and the report was "Build failed with 2 errors" with nothing to point at.
    //
    // A record in the closure is by definition shadowing something the registry can answer, so a bad one
    // must cost its OWN surface and let `require` fall back. Same principle as the unsatisfiable-closure
    // prune, for the other way a record fails.
    const graph: Record<string, string> = {
      "@/components/ok": 'require("@/store");',
      "@/shared/lib/runtime/GraphComponent": "!!! not valid source !!!",
    };
    const compile: CompileFn = async (src) => {
      if (src.startsWith("!!!")) throw new Error("Build failed: unexpected token");
      return src;
    };
    const { linked, failures } = await linkGraphModules(
      'require("@/components/ok"); require("@/shared/lib/runtime/GraphComponent");',
      (s) => graph[s] ?? null,
      compile,
    );
    // The good half linked; the entry survived.
    expect(linked.has(ENTRY_SPECIFIER)).toBe(true);
    expect(linked.has("@/components/ok")).toBe(true);
    // The broken override is absent from the linked set, so `require` falls through to the registry…
    expect(linked.has("@/shared/lib/runtime/GraphComponent")).toBe(false);
    // …and it is NAMED, which is the half that turns the next diagnosis into a read instead of a hunt.
    expect(failures).toEqual([
      { specifier: "@/shared/lib/runtime/GraphComponent", error: expect.stringContaining("Build failed") },
    ]);
  });

  it("still THROWS when the ENTRY itself will not compile", async () => {
    // The entry is the page's own source. There is no fallback for it and nothing to salvage, so the
    // decline above must not quietly swallow a broken page into an empty render.
    const compile: CompileFn = async () => { throw new Error("Build failed: entry is broken"); };
    await expect(linkGraphModules("!!! broken entry !!!", undefined, compile)).rejects.toThrow("entry is broken");
  });
});

describe("makeGraphRequire — resolution order and cycles", () => {
  const linkedOf = (mods: Record<string, string>) =>
    new Map(Object.entries(mods).map(([specifier, cjs]) => [specifier, { specifier, source: cjs, cjs }]));

  it("falls back to the REGISTRY when a graph module throws while evaluating", () => {
    // The Projects page, one layer past the compile fix. `import.meta.glob` is a VITE transform: esbuild
    // emits `import_meta.glob(...)` verbatim, so a record using it links fine and dies at eval with
    // "is not a function", taking the page with it.
    //
    // Judged at EVAL and not by reading the source, which was my first attempt and was wrong: 19 records
    // contain that call and most WORK, because it sits in a path the page never takes. Declining them all
    // regressed the Planning page. Throwing is the only honest evidence that a record cannot stand up.
    const appRequire = (s: string) => ({ from: "registry", s });
    const linked = linkedOf({
      "@/features/planner/stages/planTopics": 'throw new TypeError("import_meta.glob is not a function");',
    });
    const declined: string[] = [];
    const require = makeGraphRequire(linked, appRequire, (spec) => declined.push(spec));

    expect(require("@/features/planner/stages/planTopics")).toEqual({
      from: "registry",
      s: "@/features/planner/stages/planTopics",
    });
    expect(declined).toEqual(["@/features/planner/stages/planTopics"]);
  });

  it("does not cache the half-evaluated exports of a module that threw", () => {
    // The cycle guard seeds `exports` BEFORE evaluating. If a throw left that seed behind, the next
    // require would hand back an empty object instead of the registry's real module — a silent, much
    // worse failure than the one being fixed.
    let attempts = 0;
    const appRequire = (s: string) => ({ from: "registry", s });
    const linked = linkedOf({ "@/x": 'throw new Error("boom");' });
    const require = makeGraphRequire(linked, appRequire, () => { attempts++; });

    expect(require("@/x")).toEqual({ from: "registry", s: "@/x" });
    expect(require("@/x"), "the second require also reaches the registry").toEqual({ from: "registry", s: "@/x" });
    expect(attempts, "…by re-evaluating and failing again, not by serving a poisoned cache entry").toBe(2);
  });

  it("resolves a graph module BEFORE the app registry — this is what keeps `provides` overrides working (#3660)", () => {
    const appRequire = (s: string) => ({ from: "registry", s });
    const linked = linkedOf({ "@/shared/ui/data/Chip": 'module.exports = { from: "graph" };' });
    const require = makeGraphRequire(linked, appRequire);
    expect(require("@/shared/ui/data/Chip")).toEqual({ from: "graph" });
    // anything the graph does not claim still falls through to the registry
    expect(require("react")).toEqual({ from: "registry", s: "react" });
  });

  it("evaluates each module ONCE per load, however many importers it has", () => {
    let evals = 0;
    (globalThis as unknown as { __count: () => void }).__count = () => { evals += 1; };
    const linked = linkedOf({
      "@/components/shared": 'globalThis.__count(); module.exports = { v: 1 };',
      "@/components/a": 'module.exports = { s: require("@/components/shared") };',
      "@/components/b": 'module.exports = { s: require("@/components/shared") };',
    });
    const require = makeGraphRequire(linked, () => ({}));
    const a = require("@/components/a") as { s: unknown };
    const b = require("@/components/b") as { s: unknown };
    expect(evals).toBe(1);
    expect(a.s, "both importers observe the SAME instance").toBe(b.s);
  });

  it("a cycle terminates: the module record is cached BEFORE its factory runs (Node's rule)", () => {
    const linked = linkedOf({
      "@/components/a": 'exports.name = "a"; exports.b = require("@/components/b");',
      "@/components/b": 'exports.name = "b"; exports.a = require("@/components/a");',
    });
    const require = makeGraphRequire(linked, () => ({}));
    const a = require("@/components/a") as { name: string; b: { name: string; a: unknown } };
    expect(a.name).toBe("a");
    expect(a.b.name).toBe("b");
    // b captured a's exports object mid-construction — the classic CommonJS partial view. It is a real
    // object rather than a hang, which is the property that matters.
    expect(a.b.a).toBeDefined();
  });

  it("propagates the registry's NAMED error for an unregistered specifier — never a silent stub", () => {
    const appRequire = (s: string) => {
      throw new Error(`runtime loader: import "${s}" is not a registered app module.`);
    };
    const require = makeGraphRequire(linkedOf({}), appRequire);
    expect(() => require("@/nope")).toThrow(/not a registered app module/);
  });
});

describe("evaluateEntry", () => {
  it("runs the linked entry and returns its exports", async () => {
    const { compile } = fakeCompiler();
    const graph: Record<string, string> = { "@/components/panel": 'module.exports = { Panel: "P" };' };
    const { linked } = await linkGraphModules(
      'const p = require("@/components/panel"); module.exports = { default: p.Panel };',
      (s) => graph[s] ?? null,
      compile,
    );
    expect(evaluateEntry(linked, () => ({}))).toEqual({ default: "P" });
  });
});

// #an-incomplete-override-falls-back-instead-of-killing-the-page — declining an override that cannot
// stand up.
//
// The rule under test is a trade between two bad outcomes, and the tests are written to pin WHICH one it
// picks in each case:
//   · a broken override that still wins  ⇒ every page touching that specifier dies (the reported bug)
//   · an override declined too eagerly   ⇒ a working graph migration silently reverts to bundled code
// So: decline only when the closure genuinely cannot resolve AND the platform has something to answer
// with. Everything else is left exactly as the linker produced it.
import { describe, it, expect } from "vitest";
import { pruneUnsatisfiableOverrides, ENTRY_SPECIFIER, type LinkedModule } from "@/shared/lib/runtime/graphModules";

/** A linked module whose compiled CJS requires `deps` — the shape `scanRequires` reads. */
const mod = (specifier: string, deps: string[] = []): LinkedModule => ({
  specifier,
  source: "",
  cjs: deps.map((d) => `require("${d}");`).join("\n") || "module.exports = {};",
});

const linkOf = (...mods: LinkedModule[]) => new Map(mods.map((m) => [m.specifier, m]));
/** The platform registry for a test: these specifiers resolve to real bundled modules. */
const registry = (...specs: string[]) => (s: string) => specs.includes(s);

describe("pruneUnsatisfiableOverrides", () => {
  it("declines an override whose closure reaches nothing, naming what was missing", () => {
    // The REPORTED case: an impl provides `usePageTabs`, its code imports `arrayMove`, and nothing
    // anywhere can answer `arrayMove`. Before this, that killed every page importing usePageTabs.
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/shared/hooks/usePageTabs"]),
      mod("@/shared/hooks/usePageTabs", ["@/shared/lib/core/arrayMove"]),
    );
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry("@/shared/hooks/usePageTabs"));

    expect(kept.has("@/shared/hooks/usePageTabs")).toBe(false);
    expect(declined).toEqual([{ specifier: "@/shared/hooks/usePageTabs", missing: "@/shared/lib/core/arrayMove" }]);
    // The entry survives — dropping the override is precisely what lets it evaluate.
    expect(kept.has(ENTRY_SPECIFIER)).toBe(true);
  });

  it("declines the Console case too — the bug was never Glance-specific", () => {
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/shared/lib/fleet/coordination"]),
      mod("@/shared/lib/fleet/coordination", ["@/shared/lib/fleet/coordinationDeadlock"]),
    );
    const { declined } = pruneUnsatisfiableOverrides(linked, registry("@/shared/lib/fleet/coordination"));
    expect(declined.map((d) => d.missing)).toEqual(["@/shared/lib/fleet/coordinationDeadlock"]);
  });

  it("KEEPS a healthy override — graph-first (#3660) still wins when the record can stand alone", () => {
    // The half that must not regress: a record that provides a module and resolves its own imports is
    // still the one that renders.
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/shared/ui/controls/Button"]),
      mod("@/shared/ui/controls/Button", ["react"]),
    );
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry("@/shared/ui/controls/Button", "react"));
    expect(kept.has("@/shared/ui/controls/Button")).toBe(true);
    expect(declined).toEqual([]);
  });

  it("keeps an override whose closure runs through ANOTHER healthy graph module", () => {
    // Transitivity in the good direction: a record → record → platform chain is fully resolvable and
    // must not be mistaken for a dead end just because the middle link is not in the registry.
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/a"]),
      mod("@/a", ["@/components/panel"]),
      mod("@/components/panel", ["react"]),
    );
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry("@/a", "react"));
    expect(declined).toEqual([]);
    expect(kept.size).toBe(3);
  });

  it("leaves an unsatisfiable module ALONE when the platform has no fallback — it must still fail loudly", () => {
    // A `@/components/<id>` sibling overrides nothing. Declining it would swap a named error for a blank
    // page, which is strictly worse: there is no bundled module to fall back to.
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/components/panel"]),
      mod("@/components/panel", ["@/nope"]),
    );
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry(/* nothing available */));
    expect(kept.has("@/components/panel")).toBe(true);
    expect(declined).toEqual([]);
  });

  it("never declines the ENTRY — it overrides nothing and has nowhere to fall back to", () => {
    const linked = linkOf(mod(ENTRY_SPECIFIER, ["@/missing"]));
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry(ENTRY_SPECIFIER));
    expect(kept.has(ENTRY_SPECIFIER)).toBe(true);
    expect(declined).toEqual([]);
  });

  it("terminates on an import CYCLE between records rather than hanging", () => {
    // Cycles are a normal module shape — the linker and the eval cache both tolerate them, so the walk
    // here has to as well.
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/a"]),
      mod("@/a", ["@/b"]),
      mod("@/b", ["@/a"]),
    );
    const { declined } = pruneUnsatisfiableOverrides(linked, registry("@/a", "@/b"));
    expect(declined).toEqual([]);
  });

  it("declines only the BROKEN member of a cycle — the other one still has a fallback", () => {
    // `@/b` is broken; `@/a` merely imports it. Since `@/b` has a platform fallback, `@/a`'s import of
    // it resolves either way, so `@/a` is untouched.
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/a"]),
      mod("@/a", ["@/b"]),
      mod("@/b", ["@/a", "@/gone"]),
    );
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry("@/a", "@/b"));
    expect(declined.map((d) => d.specifier)).toEqual(["@/b"]);
    expect(kept.has("@/a")).toBe(true);
  });

  it("does NOT punish a module for a broken neighbour that has its own fallback", () => {
    // The over-eager failure mode, pinned: `@/a`'s only unresolved import is `@/b`, and `@/b` is itself
    // broken. `@/b` is declined and falls back to the platform, so `@/a` still resolves and must be
    // KEPT — declining it too would silently revert a perfectly good migration one hop away.
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/a"]),
      mod("@/a", ["@/b"]),
      mod("@/b", ["@/gone"]),
    );
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry("@/a", "@/b"));
    expect(declined.map((d) => d.specifier)).toEqual(["@/b"]);
    expect(kept.has("@/a")).toBe(true);
  });

  it("DOES propagate through a sibling, which has no fallback of its own", () => {
    // The other direction: `@/components/panel` cannot fall back, so an override that reaches it
    // inherits its failure and is declined — otherwise the page would still die on the sibling.
    const linked = linkOf(
      mod(ENTRY_SPECIFIER, ["@/a"]),
      mod("@/a", ["@/components/panel"]),
      mod("@/components/panel", ["@/gone"]),
    );
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry("@/a"));
    expect(declined).toEqual([{ specifier: "@/a", missing: "@/gone" }]);
    expect(kept.has("@/components/panel")).toBe(true);   // still there, still failing loudly
  });

  it("is a no-op on a fully healthy link — the common path costs nothing and changes nothing", () => {
    const linked = linkOf(mod(ENTRY_SPECIFIER, ["react"]), mod("@/x", ["react"]));
    const { linked: kept, declined } = pruneUnsatisfiableOverrides(linked, registry("@/x", "react"));
    expect(declined).toEqual([]);
    expect([...kept.keys()]).toEqual([ENTRY_SPECIFIER, "@/x"]);
  });
});

