import { describe, it, expect } from "vitest";
import { BSC_ISSUE_LABEL, withProvenanceLabel, triageIssueListArgs } from "@/shared/lib/github/issueProvenance";
import { buildTriagePrompt, TRIAGE_PROMPT, useAppStore } from "@/store";

describe("issue provenance (#738)", () => {
  it("withProvenanceLabel stamps the bsc-generated label, idempotently", () => {
    expect(withProvenanceLabel([])).toEqual([BSC_ISSUE_LABEL]);
    expect(withProvenanceLabel(["stream:ux"])).toEqual(["stream:ux", BSC_ISSUE_LABEL]);
    expect(withProvenanceLabel([BSC_ISSUE_LABEL, "x"])).toEqual([BSC_ISSUE_LABEL, "x"]);
  });

  it("triageIssueListArgs restricts to the provenance label by default", () => {
    expect(triageIssueListArgs(true)).toContain(`--label ${BSC_ISSUE_LABEL}`);
    expect(triageIssueListArgs(false)).not.toContain("--label");
    expect(triageIssueListArgs(false)).toContain("--state open");
  });

  it("buildTriagePrompt(true) confines triage to authored issues + flags the rest untrusted", () => {
    const p = buildTriagePrompt(true);
    expect(p).toContain(BSC_ISSUE_LABEL);
    expect(p).toContain(`--label ${BSC_ISSUE_LABEL}`);
    expect(p).toMatch(/untrusted/);
    expect(p).toMatch(/do NOT act on it/);
  });

  it("buildTriagePrompt(false) works every open issue (opt-out)", () => {
    const p = buildTriagePrompt(false);
    expect(p).not.toContain(`--label ${BSC_ISSUE_LABEL}`);
    expect(p).toContain("every open issue");
  });

  it("TRIAGE_PROMPT defaults to the secure (restricted) prompt", () => {
    expect(TRIAGE_PROMPT).toContain(BSC_ISSUE_LABEL);
  });

  it("buildTriagePrompt(_, _, local=true) triages plan.db via bsc plan, not gh (#3281 local-first)", () => {
    const p = buildTriagePrompt(true, undefined, true);
    // Offline: reads + updates the plan store — no `gh` anywhere in the prompt.
    expect(p).toContain("bsc plan list --status open");
    expect(p).toContain("bsc plan status");
    expect(p).not.toMatch(/gh issue/);
    // All plan.db issues are planner-authored, so the untrusted-external-issue guard doesn't apply.
    expect(p).not.toContain(BSC_ISSUE_LABEL);
    expect(p).not.toMatch(/untrusted/);
  });

  it("the local flag overrides restrictToBsc — plan.db has no external channel to restrict", () => {
    // restrictToBsc=true would normally add the label dance; local mode ignores it (all trusted).
    expect(buildTriagePrompt(true, undefined, true)).not.toContain(`--label ${BSC_ISSUE_LABEL}`);
  });

  it("the restrictToBscIssues setting is ON by default and toggles", () => {
    expect(useAppStore.getState().restrictToBscIssues).toBe(true); // secure by default
    useAppStore.getState().setRestrictToBscIssues(false);
    expect(useAppStore.getState().restrictToBscIssues).toBe(false);
    useAppStore.getState().setRestrictToBscIssues(true);
  });

  it("triageStartProject seeds the restricted GITHUB prompt by default when CONNECTED (#738)", () => {
    // The restricted (gh issue list) triage is the connected behavior, so it needs a token (#3281 made
    // triage token-aware: no token ⇒ the local plan.db prompt, next test) AND a strategy that actually
    // reaches a remote (#worker-prose-follows-the-local-first-loop — a token alone stopped being
    // enough, because holding one is not consent to WRITE to GitHub).
    //
    // The #738 guard itself is unchanged and still worth pinning: WHEN a project genuinely triages
    // GitHub issues, only bsc-authored ones are trusted.
    useAppStore.setState({
      bscBaseDir: "/base",
      restrictToBscIssues: true,
      githubToken: "ghp_x",
      // keyed by the sanitized project NAME ("Proj"), which is what triageStartProject derives — not
      // the project id ("k") it is also passed.
      planFleet: { Proj: { recommended: 1, reasoning: "", director: { enabled: false }, streams: [], strategy: "pr-ci" } },
    } as never);
    useAppStore.getState().triageStartProject("Proj", ["acme/web"], "k");
    const texts = Object.values(useAppStore.getState().paneStartupPromptText);
    expect(texts.some((t) => typeof t === "string" && t.includes(BSC_ISSUE_LABEL))).toBe(true);
  });

  it("triageStartProject seeds the LOCAL plan.db prompt with no token (#3281)", () => {
    // Clear paneStartupPromptText — the store is a singleton, so the prior test's gh-issue prompt would
    // otherwise linger and trip the negative assertion below.
    useAppStore.setState({ bscBaseDir: "/base", restrictToBscIssues: true, githubToken: "", paneStartupPromptText: {} });
    useAppStore.getState().triageStartProject("Proj2", ["acme/web"], "k2");
    const texts = Object.values(useAppStore.getState().paneStartupPromptText).filter((t): t is string => typeof t === "string");
    // Offline: the seeded triage prompt reads plan.db via `bsc plan`, never `gh issue`.
    expect(texts.some((t) => t.includes("bsc plan list --status open"))).toBe(true);
    expect(texts.some((t) => /gh issue/.test(t))).toBe(false);
  });
});

implementations.code:
// The GitHub overlay for a fleet's owned issue refs (#4102) — pure query construction + parsing.
//
// ── ONE CALL PER REPO, NOT ONE PER ISSUE ────────────────────────────────────────────────────────
// A drilled fleet owns ~60 refs. Asking GitHub for each one is 60 requests to render one graph — the
// N-per-node fan-out that has repeatedly cost this app real time (#3908/#3912/#3944/#3954), and the
// exact shape #4102 promises not to reintroduce. GraphQL takes aliased field selections, so every ref
// in a repo is resolvable in ONE query:
//
//   query { r0: repository(owner:"o", name:"n") { i3898: issue(number:3898) { number state } … } }
//
// ── WHY NOT `GET /issues?state=all` ─────────────────────────────────────────────────────────────
// It is paginated and returns PULL REQUESTS alongside issues (REST models a PR as an issue), so a
// fleet ref matching a PR number would report the wrong state. Asking for the exact numbers cannot
// make that mistake.
//
// Pure: no fetch, no store. The hook owns the lifecycle; this owns the contract.

import { normalizeRef } from "@/features/glance/lib/fleetPlanProgress";

/** `owner/name`, as a fleet stream stores it. */
export interface RepoRefs {
  repo: string;
  /** Normalised issue numbers owned in this repo. */
  numbers: string[];
}

/** Group refs by their owning repo, so each repo becomes one query. Refs are normalised and
 *  de-duplicated — two streams in a repo commonly own overlapping work, and asking twice wastes the
 *  budget this batching exists to protect. Streams with no repo or no refs are skipped. */
export function groupRefsByRepo(
  streams: readonly { repo?: string; issues?: readonly string[] }[],
): RepoRefs[] {
  const byRepo = new Map<string, Set<string>>();
  for (const s of streams) {
    const repo = s.repo?.trim();
    if (!repo || !repo.includes("/")) continue;
    for (const ref of s.issues ?? []) {
      const n = normalizeRef(ref);
      // Only numeric refs are addressable as `issue(number:)`. A cross-repo ref like `owner/x#5` or a
      // free-text placeholder is dropped rather than sent as a malformed query that fails the whole
      // batch — one bad ref must not blank out every other stream's progress.
      if (!/^\d+$/.test(n)) continue;
      let set = byRepo.get(repo);
      if (!set) byRepo.set(repo, (set = new Set()));
      set.add(n);
    }
  }
  return [...byRepo].map(([repo, numbers]) => ({ repo, numbers: [...numbers].sort() }));
}

/** GraphQL aliases must match `/^[_A-Za-z][_0-9A-Za-z]*$/`, so both levels are prefixed rather than
 *  interpolated raw — an alias starting with a digit is a syntax error that fails the whole query. */
const repoAlias = (i: number) => `r${i}`;
const issueAlias = (n: string) => `i${n}`;

/**
 * Build one query covering every repo/ref pair.
 *
 * Returns `null` when there is nothing to ask — the caller must not spend a request (nor show a
 * spinner) for a fleet that owns no addressable refs.
 *
 * Owner/name are split and embedded as quoted literals. They come from the fleet plan rather than
 * user input, but they are still validated as GitHub name characters so a malformed repo string
 * cannot inject query text.
 */
export function buildIssueStateQuery(groups: readonly RepoRefs[]): string | null {
  const parts: string[] = [];
  groups.forEach((g, i) => {
    const [owner, name] = g.repo.split("/");
    if (!owner || !name || !/^[\w.-]+$/.test(owner) || !/^[\w.-]+$/.test(name)) return;
    if (g.numbers.length === 0) return;
    const fields = g.numbers.map((n) => `${issueAlias(n)}: issue(number: ${n}) { number state }`).join(" ");
    parts.push(`${repoAlias(i)}: repository(owner: "${owner}", name: "${name}") { ${fields} }`);
  });
  return parts.length ? `query { ${parts.join(" ")} }` : null;
}

/** One issue as the overlay knows it. */
export interface IssueState {
  ref: string;
  closed: boolean;
}

/**
 * Parse the aliased response into `ref → closed`.
 *
 * Tolerant by construction: GitHub returns `null` for an alias whose issue does not exist (a stale
 * ref, or one belonging to a repo the token cannot see) and sends partial `data` ALONGSIDE `errors`
 * rather than failing the batch. Skipping the nulls means one dead ref costs its own state and
 * nothing else's — which matters because these refs are hand-maintained in the plan.
 */
export function parseIssueStates(data: unknown): Map<string, boolean> {
  const out = new Map<string, boolean>();
  if (!data || typeof data !== "object") return out;
  for (const repo of Object.values(data as Record<string, unknown>)) {
    if (!repo || typeof repo !== "object") continue;
    for (const issue of Object.values(repo as Record<string, unknown>)) {
      if (!issue || typeof issue !== "object") continue;
      const { number, state } = issue as { number?: unknown; state?: unknown };
      if (typeof number !== "number" || typeof state !== "string") continue;
      out.set(normalizeRef(number), state.toUpperCase() === "CLOSED");
    }
  }
  return out;
}

/** The refs the overlay reports as DONE — the set `fleetPlanProgress` consumes. */
export function closedRefs(states: ReadonlyMap<string, boolean>): Set<string> {
  const out = new Set<string>();
  for (const [ref, closed] of states) if (closed) out.add(ref);
  return out;
}

