// The `matrix` viz kit's MOTION wiring (#3221, epic #3220/#2942) — injects the compiled motion CSS
// (read / write / region) into the live MatrixView. The animation DATA itself now lives in a SHARED,
// feature-agnostic home (`@/shared/ui/kit/matrixVizAnimations`, #3242) so BOTH consumers read ONE
// definition: this renderer AND the Designs `matrix-viz` builtin kit — see that module's doc for the why
// and the state-trigger seam. `MatrixView`'s root carries the applying classes ({@link
// MATRIX_VIZ_ANIM_CLASSES}); its cells only stamp `data-op`/`data-mark`.
import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { MATRIX_VIZ_KIT_ID, MATRIX_VIZ_ANIMATIONS } from "@/shared/ui/kit/matrixVizAnimations";

// Re-export the shared data so this renderer's public surface (and the algorithms barrel) is unchanged.
export { MATRIX_VIZ_KIT_ID, MATRIX_VIZ_ANIMATIONS };

/** The applying classes the renderer's root carries so the state-scoped rules match its cells. */
export const MATRIX_VIZ_ANIM_CLASSES: string = MATRIX_VIZ_ANIMATIONS.map((a) =>
  animClassName({ kit: MATRIX_VIZ_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS — produced ONCE by the engine from {@link MATRIX_VIZ_ANIMATIONS}. Pure. */
export const MATRIX_VIZ_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: MATRIX_VIZ_KIT_ID, animations: MATRIX_VIZ_ANIMATIONS }]),
);

const STYLE_ID = "bsc-matrix-viz-animations";

/** Inject the compiled matrix motion CSS into a dedicated managed `<style>` (idempotent). `doc` is param'd
 *  for tests. Mirrors `ensureArrayViewMotion` on its own style id. */
export function ensureMatrixViewMotion(doc: Document = document): void {
  if (!MATRIX_VIZ_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== MATRIX_VIZ_MOTION_CSS) el.textContent = MATRIX_VIZ_MOTION_CSS;
}

// The `matrix-viz` kit's MOTION library as DATA (#3221/#3242, epic #3220/#2942) — the read / write /
// region animations authored as {@link KitAnimation} data, compiled by the kit-motion engine
// (`compileAnimationsCss`). The 2-D twin of `algoVizAnimations`.
//
// ── WHY THIS LIVES IN shared/ui/kit (not in the algorithms feature) ───────────────────────────────────
// Like the array set (#3194), it has EXACTLY TWO consumers in two features and must be ONE definition:
//   1. the Algorithms MatrixView renderer (`features/algorithms/.../matrixViewMotion.ts`) — injects the
//      compiled CSS into the live visualization; and
//   2. the Designs seed (`features/designs/lib/matrixVizKit.ts` → `seed.ts`) — registers `matrix-viz` as
//      a recoverable builtin kit so the set is visible + editable in the Design Studio's AnimationsMenu.
// Importing the Algorithms barrel from the Designs seed would eagerly pull the whole algorithms feature
// into the store-boot module graph and risk a designs↔algorithms seed cycle — so the feature-agnostic
// viz-motion data lives HERE, a leaf both features import cheaply (#3242).
//
// STATE-TRIGGER SEAM (#3058): each animation's `selector` IS the data-state MatrixView stamps
// (`[data-op="write"]`, …), so the compiled rule fires when a cell reaches that state. The renderer's root
// carries the applying classes; cells only stamp `data-op` / `data-mark`.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The matrix-visualization motion kit id — `.matrix-viz-anim-<name>` + `@keyframes bsc-matrix-viz-<name>`. */
export const MATRIX_VIZ_KIT_ID = "matrix-viz";

/** The matrix kit's animations as DATA — read (a highlight pulse on an examined cell), write (a pop as a
 *  value lands — the workhorse of transpose/rotate/reflect), region (a block tint fading out). Token-based
 *  colours; the engine wraps each in `prefers-reduced-motion: no-preference`. The single source of truth
 *  the MatrixView renderer AND the Designs `matrix-viz` builtin kit both consume. */
export const MATRIX_VIZ_ANIMATIONS: KitAnimation[] = [
  // read — a quick ring on the cell being examined.
  {
    name: "read",
    selector: '[data-op="read"]',
    duration: "450ms",
    easing: "var(--ease-standard)",
    set: { "z-index": "1" },
    keyframes: {
      "0%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
      "45%": {
        "box-shadow": "0 0 0 2px color-mix(in oklch, var(--state-wait), transparent 45%)",
        "border-color": "var(--state-wait)",
      },
      "100%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
    },
  },
  // write — a cell pops + tints to the accent as its new value lands (a swapped / rotated cell).
  {
    name: "write",
    selector: '[data-op="write"]',
    duration: "440ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": {
        transform: "scale(1.16)",
        background: "color-mix(in oklch, var(--accent), var(--bg-elev) 45%)",
        "border-color": "var(--accent)",
      },
      "100%": { transform: "scale(1)" },
    },
  },
  // region — a rectangular block tints and fades (a submatrix / layer highlight).
  {
    name: "region",
    selector: '[data-op="region"]',
    duration: "600ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { background: "color-mix(in oklch, var(--info), transparent 78%)" },
      "100%": { background: "var(--bg-elev)" },
    },
  },
];

// Catalog/installed derivation for the MCP screen. Pure (no React/Tauri): splits the catalog into
// the always-available "Built-in tools" set vs the downloadable browse list, dedupes already-
// installed servers, and free-text filters. Shared by the screen's installed + catalog views.

import { MCP_CATALOG, type CatalogItem } from "@/shared/data/mcpCatalog";
import { BUILTIN_MCP_SERVERS, type McpServer } from "@/features/mcp/lib/mcpServers";

/** Catalog entries for the built-in servers (#1196) — shown as always-available, never downloadable. */
export const builtInCatalog: CatalogItem[] = MCP_CATALOG.filter(
  c => c.builtIn || BUILTIN_MCP_SERVERS.some(b => b.name.toLowerCase() === c.name.toLowerCase()),
);

/** Lowercased names of the installed servers, for catalog dedupe. */
export function installedNameSet(servers: McpServer[]): Set<string> {
  return new Set(servers.map(e => e.name.toLowerCase()));
}

/** The downloadable/browsable catalog: every entry that isn't built-in (those live in the
 *  Built-in tools section) and isn't already installed. */
export function browsableCatalog(servers: McpServer[]): CatalogItem[] {
  const installed = installedNameSet(servers);
  return MCP_CATALOG.filter(c => !c.builtIn && !installed.has(c.name.toLowerCase()));
}

/** Count for the Catalog tab badge: catalog entries not yet installed (built-ins included, matching
 *  the original badge). */
export function catalogTabCount(servers: McpServer[]): number {
  const installed = installedNameSet(servers);
  return MCP_CATALOG.filter(c => !installed.has(c.name.toLowerCase())).length;
}

/** Free-text filter over a catalog list by name + description (empty query → unchanged). */
export function filterCatalog(items: CatalogItem[], query: string): CatalogItem[] {
  const q = query.trim().toLowerCase();
  return q ? items.filter(c => c.name.toLowerCase().includes(q) || c.desc.toLowerCase().includes(q)) : items;
}

// MCP server catalog. MCP_CATALOG is the first-party MCP server catalog the MCP screen browses
// and the planner's `<mcp_assign>` path installs from (#858). The live server list, health, and
// call stats come from the store / backend at runtime — not from this file.

/** A browseable catalog entry (shared shape for MCP servers + hooks). */
export interface CatalogItem {
  name: string;
  by: string;
  icon: string;
  desc: string;
  /** External download/repo link (#858). First-party servers install from source (not npm/PyPI),
   *  so the card surfaces a GitHub link (to `main`) for download + setup. */
  link?: string;
  /** One-line setup hint shown with the download link (clone + build/run). */
  install?: string;
  /** Built-in/always-available server (#1196) — ships compiled in the app bundle (a native sidecar),
   *  so it has NO download/build step and is exposed to the planner by default. The MCP screen shows
   *  it as built-in instead of a download card. */
  builtIn?: boolean;
}

// The catalog DATA is externalized to `@data/mcp/catalog.json` (#2146, epic #2027 tail) — the single
// source, editable without touching code and part of the exportable app-config bundle; the config-dir
// copy (#2047) overlays the embedded default via `overlayFile`. This module keeps the TYPE + accessor.
//
// The first-party MCP servers (#858) install from source via the download link. Generic third-party
// servers (Sentry/Linear/Postgres/Slack/Stripe/Brave/SQLite/Notion) were pruned from the browse list
// (#870) so the catalog features our first-party servers. Their templates (lib/mcpServers.ts) stay —
// the planner's `<mcp_assign name="…" />` path still wires a working config for well-known names even
// though they're no longer browseable.
import catalogEmbedded from "@data/mcp/catalog.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

export const MCP_CATALOG: CatalogItem[] = overlayFile("mcp/catalog.json", catalogEmbedded as CatalogItem[]);

// The planner's live extensions.md (#1054). The planner + director are exposed to EVERY installed
// MCP server (so the planner can call them while planning — e.g. research sources for a skill — and
// decide which workers need them); each worker gets only the servers its stream was assigned, on
// top of the global baseline. This renders that guidance from the actual installed set, replacing
// the static catalogue the Rust setup used to write. Pure (no React/Tauri) so it's unit-testable
// and shared by the launch path; the counterpart to blueprintSkills.buildSkillContext.

import { type McpServer } from "@/features/mcp";
import { MCP_CATALOG, type CatalogItem } from "@/shared/data/mcpCatalog";
import { writeProjectFile } from "@/shared/lib/core/projectFiles";

/** A one-line description for a server name — its catalog blurb if known, else a generic note. */
function describe(name: string, catalog: CatalogItem[]): string {
  const hit = catalog.find((c) => c.name.toLowerCase() === name.toLowerCase());
  return hit?.desc ?? "(custom server — see the MCP screen for its config)";
}

/**
 * Render the planner's extensions.md from the installed servers it is exposed to. `servers` is the
 * runnable installed set (see {@link resolveAllInstalledMcp}); `catalog` supplies descriptions.
 */
export function buildMcpContext(servers: McpServer[], catalog: CatalogItem[] = MCP_CATALOG): string {
  const available = servers.length
    ? servers.map((s) => `- **${s.name}** — ${describe(s.name, catalog)}`).join("\n")
    : "_No MCP servers installed yet. Browse and download one from the MCP screen; it appears here automatically._";
  return `# Extensions (MCP servers)

These MCP servers are installed and **exposed to you (the planner) right now** — you can call their
tools directly while planning (for example, to research real sources before authoring a skill). The
director sees the same set.

## Available now

${available}

## Assigning servers to workers

Each worker sees the **global** servers plus only the servers you assign to its stream. Assign by
adding the server name to that stream's \`mcp\` list in the fleet plan, e.g. \`"mcp": ["Research"]\`
(written with \`bsc plan fleet set\`). Use this to give one worker a tool its lane needs without
handing it to the whole fleet; for a tool every worker needs, scope it project-wide with
\`bsc plan mcp add <name>\` instead.

## Installing more

Some servers are **built in** (e.g. **Research**) — always available, no install needed. Others
install from source: browse and download them in the MCP screen, and a downloaded server shows up
here automatically and becomes assignable. Never invent secret env values; the user fills any
tokens/keys in the MCP screen.
`;
}

/** Write the project hub's extensions.md from the installed servers (#1054). */
export async function writeProjectMcpContext(args: { projectKey: string; servers: McpServer[] }): Promise<void> {
  await writeProjectFile(args.projectKey, "extensions.md", buildMcpContext(args.servers));
}

