// The mcp feature's graph-platform surface (#3656, epic #3604) — the feature-internal modules a graph-loaded
// MCP page imports but does NOT redraw: the install/version/catalog/telemetry logic, the `./shared` grab-bag
// (the useGhProjects hook + the drawer/row/card helpers), and the install-status hook. Registered HERE,
// inside the feature, because the shell must not reach a feature's internals (#1545). The mcp host calls this
// synchronously before the graph page loads. Mirrors the fleet/automations/security/github/skills platforms.
// (`@/features/mcp` — the barrel with HooksView/telemetry — is registered by the AUTOMATIONS platform; these
// are the mcp INTERNALS, a disjoint set of specifiers.)
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as McpInstall from "@/features/mcp/lib/mcpInstall";
import * as McpServers from "@/features/mcp/lib/mcpServers";
import * as Hooks from "@/features/mcp/lib/hooks";
import * as McpTelemetry from "@/features/mcp/lib/mcpTelemetry";
import * as Shared from "@/features/mcp/shared";
import * as GraphPlatform from "@/features/mcp/graphPlatform";
import * as SessionConfig from "@/features/mcp/lib/sessionConfig";
import * as HookTelemetry from "@/features/mcp/lib/hookTelemetry";
import * as MigrateExtensions from "@/features/mcp/lib/migrateExtensions";
// ── Reached only THROUGH a migrated logic module (retire-the-first-19-logic-modules) ─────────────
// A module that becomes an algorithm record stops being resolved by Vite and starts being resolved by
// the LOADER, so its own imports become the graph's problem. None of these were registered before,
// because no record imported them DIRECTLY — each arrives transitively with the hook that was retired.

/** Register the mcp page's injected graph-platform modules by the specifiers it imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerMcpPlatform(): void {
  registerAppModule("@/features/mcp/lib/mcpInstall", McpInstall);
  registerAppModule("@/features/mcp/lib/mcpServers", McpServers);
  registerAppModule("@/features/mcp/lib/hooks", Hooks);
  registerAppModule("@/features/mcp/lib/mcpTelemetry", McpTelemetry);
  registerAppModule("@/features/mcp/shared", Shared);
  registerAppModule("@/features/mcp/graphPlatform", GraphPlatform);
  registerAppModule("@/features/mcp/lib/sessionConfig", SessionConfig);
  registerAppModule("@/features/mcp/lib/hookTelemetry", HookTelemetry);
  registerAppModule("@/features/mcp/lib/migrateExtensions", MigrateExtensions);
}

// Shared helpers for downloadable (first-party) MCP servers — the bridge between a
// catalog entry's GitHub download link and the on-disk install path its run config
// points at. Pure (no React/Tauri) so the MCP screen, the planner-assign path,
// and the planning-page panel all resolve `{dir}` the same way.

import { MCP_CATALOG } from "@/shared/data/mcpCatalog";
import { mcpInstallDir } from "@/shared/lib/core/projectPaths";

/** Repo slug from a GitHub link: the last non-empty path segment. */
export function repoNameFromLink(link: string): string {
  return link.replace(/\/+$/, "").split("/").pop() ?? "";
}

/** The catalog download link for a server name, if it's a downloadable (first-party)
 *  server that installs from source; `undefined` for built-in/remote servers. */
export function catalogLink(name: string): string | undefined {
  return MCP_CATALOG.find((c) => c.name === name)?.link;
}

/** The repo slug (== install dir name) for a downloadable server, or "" if it isn't one.
 *  This is the `name` arg `mcp_clone` / `mcp_build` / `mcp_status` take. */
export function mcpRepoName(name: string): string {
  const link = catalogLink(name);
  return link ? repoNameFromLink(link) : "";
}

/** The on-disk install dir for a downloadable server, or "" if it isn't downloadable
 *  or `baseDir` is empty. `~/.base-studio-code/mcp/<repo>`. */
export function mcpDirForServer(name: string, baseDir: string): string {
  const link = catalogLink(name);
  return link && baseDir ? mcpInstallDir(baseDir, repoNameFromLink(link)) : "";
}

/**
 * Substitute the `{dir}` placeholder in a server def's `args` with its real on-disk
 * install path. No-op when the def has no `{dir}`, the server isn't downloadable, or
 * `baseDir` is empty — so a literal `{dir}` never reaches a launched config (the bug
 * the planner-assign path had: it skipped this and launched `--directory {dir}`).
 */
export function resolveMcpInstallDir<T extends { args?: string }>(def: T, name: string, baseDir: string): T {
  const dir = mcpDirForServer(name, baseDir);
  if (dir && def.args?.includes("{dir}")) {
    return { ...def, args: def.args.replace("{dir}", dir) };
  }
  return def;
}

