import { describe, it, expect } from "vitest";
import { buildMcpServers } from "@/features/planner/lib/mcpPaneData";
import type { McpServer } from "@/features/mcp/lib/mcpServers";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";

const mcp = (over: Partial<McpServer>): McpServer => ({
  id: "e", name: "x", enabled: true, projects: [], transport: "stdio", command: "", args: "", env: [], ...over,
});

const fleet: FleetPlan = {
  recommended: 2, reasoning: "", director: { enabled: true, role: "integrator" },
  streams: [
    { id: "auth", name: "Auth", repo: "o/r", owns: [], issues: [], dependsOn: [] },
    { id: "api", name: "API", repo: "o/r", owns: [], issues: [], dependsOn: [] },
  ],
};

describe("buildMcpServers", () => {
  it("includes globals + project-scoped MCP servers, excludes other projects", () => {
    const servers: McpServer[] = [
      mcp({ id: "g", name: "Compliance", projects: [] }),
      mcp({ id: "p", name: "Dependency Graph", projects: ["proj"] }),
      mcp({ id: "other", name: "Complexity Analyzer", projects: ["nope"] }),
    ];
    expect(buildMcpServers(servers, "proj", fleet).map((s) => s.id)).toEqual(["g", "p"]);
  });

  it("joins catalog metadata and resolves the launch command for stdio + http", () => {
    const stdio = buildMcpServers([mcp({ id: "c", name: "Dependency Graph", command: "node", args: "/b/mcp/dependency-graph-mcp-server/dist/index.js" })], "p", fleet)[0];
    expect(stdio.desc).toMatch(/dependency/i);
    expect(stdio.official).toBe(false);     // first-party, not @modelcontextprotocol
    expect(stdio.downloadable).toBe(true);
    expect(stdio.cmd).toBe("node /b/mcp/dependency-graph-mcp-server/dist/index.js");

    const http = buildMcpServers([mcp({ id: "u", name: "Remote", transport: "http", url: "https://x/sse" })], "p", fleet)[0];
    expect(http.cmd).toBe("https://x/sse");
    expect(http.downloadable).toBe(false);
    expect(http.status).toBe("ready"); // remote is ready once enabled
  });

  it("an enabled project server reaches the whole fleet (director + every worker)", () => {
    const s = buildMcpServers([mcp({ id: "c", name: "Compliance", projects: ["p"] })], "p", fleet)[0];
    expect(s.scope).toBe("fleet");
    expect(s.agents).toEqual(["director", "auth", "api"]);
  });

  it("a disabled server is configured but not granted (no scope, no agents)", () => {
    const s = buildMcpServers([mcp({ id: "c", name: "Compliance", enabled: false })], "p", fleet)[0];
    expect(s.scope).toBe("—");
    expect(s.agents).toEqual([]);
  });

  it("downloadable status follows the install-state map; defaults to 'available'", () => {
    const exts = [mcp({ id: "c", name: "Complexity Analyzer" }), mcp({ id: "d", name: "Dependency Graph" })];
    const built = buildMcpServers(exts, "p", fleet, { c: "ready" });
    expect(built.find((s) => s.id === "c")!.status).toBe("ready");
    expect(built.find((s) => s.id === "d")!.status).toBe("available");
  });

  it("excludes the director from agents when the fleet has no director", () => {
    const noDir: FleetPlan = { ...fleet, director: { enabled: false } };
    expect(buildMcpServers([mcp({ id: "c", name: "Compliance" })], "p", noDir)[0].agents).toEqual(["auth", "api"]);
  });
});

implementations.code:
// MCP server model + per-session resolution + `.mcp.json` payload + catalog templates.
//
// An MCP server is an external process (stdio) or endpoint (http) Claude connects to.
// Pure (no React / Tauri) so it's shared by the store, the MCP screen, and TerminalView.
// Split out of the former unified `extensions.ts` (mcp + hook discriminated union).

import builtinServersEmbedded from "@data/mcp/builtin-servers.json";
import catalogTemplatesEmbedded from "@data/mcp/catalog-templates.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

export type McpTransport = "stdio" | "http";

/** A user-configured MCP server. Scoped per-server via {@link McpServer.projects}. */
export interface McpServer {
  id: string;
  name: string;
  enabled: boolean;
  /** `[]` = every project (global); otherwise the project ids it applies to. */
  projects: string[];
  transport: McpTransport;
  command?: string;   // stdio binary
  args?: string;      // stdio args (space-split at write time)
  url?: string;       // http endpoint
  env?: Array<[string, string]>;
}

/**
 * Built-in MCP servers (#1196) — shipped compiled in the app bundle (native sidecars), so they're
 * **always available** with no download/build/Docker and need no store entry. `command` is a marker
 * the Rust side rewrites to the bundled binary's absolute path when writing `.mcp.json` (Claude Code
 * spawns `.mcp.json` commands directly, with no PATH/shell-rc). They behave like a global, enabled
 * server: the planner/director see them, and every session (incl. workers) gets them by default.
 *
 * The DATA is externalized to `@data/mcp/builtin-servers.json` (#2146, epic #2027 tail) — editable
 * without touching code + part of the exportable config bundle; the config-dir copy (#2047) overlays
 * the embedded default via `overlayFile`.
 */
export const BUILTIN_MCP_SERVERS: McpServer[] = overlayFile("mcp/builtin-servers.json", builtinServersEmbedded as McpServer[]);

/** Prepend the built-in servers, skipping any a user entry already shadows by name (case-insensitive).
 *  Tolerates a nameless entry (malformed persisted state, #2515) — it shadows nothing.
 *
 *  This is the CATALOGUE view — "everything that exists" — and it is no longer how a session is
 *  resolved; {@link resolvePersonaMcp} is. The `onlyEnabled` knob went with the old global set.
 *  Kept because the Teams panel and the planner both need to list what can be assigned. */
function withBuiltins(servers: McpServer[]): McpServer[] {
  const taken = new Set(servers.map(s => s.name?.toLowerCase()).filter((n): n is string => !!n));
  const builtins = BUILTIN_MCP_SERVERS.filter(b => !taken.has(b.name.toLowerCase()));
  return [...builtins, ...servers];
}

/**
 * THE ONE RESOLVER: the servers a session gets, given the MCP ids its PERSONA carries.
 *
 * This replaced three functions that each answered the same question differently —
 * `resolveMcpServers` (project scoping via `McpServer.projects[]`), `resolveStreamMcp` (per-stream
 * assignment) and a per-pane `paneMcpServers` override read straight at launch. A skill already
 * worked this way, and an MCP server is the same kind of thing: injectable capability an agent
 * draws on. One mechanism, one place to look.
 *
 * TWO WAYS IN, and the distinction is deliberate:
 *
 *   AMBIENT — an ENABLED built-in reaches every session. These ship with the app (research,
 *     compliance) and are its own capability, not something anybody chose, the same way packaged
 *     personas are seeded rather than authored. A new persona is therefore useful immediately
 *     instead of starting with nothing.
 *
 *   CARRIED — anything named in `personaMcp`, whether it is a stored server or a bundled one.
 *     Carrying is INTENT, so a carried server is included regardless of its `enabled` toggle —
 *     the same reasoning the old per-stream assignment used, and it is what lets a DISABLED
 *     built-in (`builtin-channel-mock`) go to the marketer alone rather than to the whole fleet.
 *     That assignment is what replaced the hand-carved channel-mock special case.
 *
 * A half-configured entry is skipped either way (`toMcpPayload` non-null: stdio needs a command,
 * http needs a url), so a broken line never reaches a session .mcp.json.
 */
export function resolvePersonaMcp(all: McpServer[], personaMcp: string[] = []): McpServer[] {
  const carried = new Set(personaMcp);
  const out: McpServer[] = [];
  const seen = new Set<string>();
  // Ambient first, so the built-ins keep a stable position in the generated .mcp.json and a diff
  // of that file stays readable across launches.
  for (const e of [...BUILTIN_MCP_SERVERS, ...all]) {
    const ambient = e.enabled && BUILTIN_MCP_SERVERS.some((b) => b.id === e.id);
    if (!ambient && !carried.has(e.id)) continue;
    if (seen.has(e.id) || toMcpPayload(e) === null) continue;
    seen.add(e.id);
    out.push(e);
  }
  return out;
}
/**
 * Every server that EXISTS and could be assigned — stored plus bundled, enable-toggle ignored.
 *
 * The catalogue, not a session's set: the Teams panel lists it so a server can be seen before any
 * persona carries it, and the planner sees everything installed so it can decide who needs what.
 * "Exists" means it has a runnable config (`toMcpPayload` non-null), so a half-configured entry is
 * never offered as assignable.
 */
export function resolveAllInstalledMcp(all: McpServer[]): McpServer[] {
  return withBuiltins(all).filter(e => toMcpPayload(e) !== null);
}
// ── Backend payload ───────────────────────────────────────────────────────────
// Shape handed to `ensure_session_settings`; field names match the Rust struct.

export interface McpServerPayload {
  name: string;
  transport: McpTransport;
  command?: string;
  args: string[];
  url?: string;
  env: Array<[string, string]>;
}

/** An MCP server → its `.mcp.json` payload, or null if it's incomplete
 *  (stdio without a command, http without a url). */
export function toMcpPayload(e: McpServer): McpServerPayload | null {
  if (e.transport === "http") {
    if (!e.url) return null;
    return { name: e.name, transport: "http", args: [], url: e.url, env: e.env ?? [] };
  }
  if (!e.command) return null;
  return {
    name: e.name,
    transport: "stdio",
    command: e.command,
    args: (e.args ?? "").split(/\s+/).filter(Boolean),
    env: e.env ?? [],
  };
}

/** The `$BSC_AGENT_MCP` config bsc-agent reads (#1078 P3) — its MCP client is **stdio-only**, so
 *  http servers are dropped; `env` becomes a plain object (matching the Rust `McpServerCfg`). */
export interface BscAgentMcpCfg {
  name: string;
  command: string;
  args: string[];
  env: Record<string, string>;
}

export function toBscAgentMcp(payloads: McpServerPayload[]): BscAgentMcpCfg[] {
  return payloads
    .filter((p) => p.transport === "stdio" && !!p.command)
    .map((p) => ({
      name: p.name,
      command: p.command as string,
      args: p.args,
      env: Object.fromEntries(p.env),
    }));
}

// ── Catalog templates ─────────────────────────────────────────────────────────
// Pre-filled config for well-known catalog entries (keyed by catalog item name).
// Unknown names fall back to a blank stdio server the user completes.
//
// The DATA is externalized to `@data/mcp/catalog-templates.json` (#2419, epic #2027 tail) — editable
// without touching code + part of the exportable config bundle; the config-dir copy (#2047) overlays
// the embedded default via `overlayFile`. What the entries mean:
// - First-party servers (#858) — downloaded to ~/.base-studio-code/mcp/<repo>, so the command runs
//   the built entrypoint from there. `{dir}` is replaced with the resolved clone path when the entry
//   is added (addFromCatalog); the user downloads + builds via the card.
// - `python -m uv` (not a bare `uv`): uv is installed as a Python module and its console-script shim
//   often isn't on PATH on a fresh machine — `python -m uv` runs without any PATH setup (#887).
// - Built-in native servers (#1005 Compliance, #1196 Research): no download/build/Docker.
//   `bsc-compliance-mcp` / `bsc-research-mcp` are markers the Rust side rewrites to the bundled
//   binary's absolute path when writing .mcp.json. Kept in the templates so the planner's
//   `<mcp_assign name="…" />` path also resolves them to the native binary.
// - Well-known third-party servers (Postgres/Slack/Sentry/…) — pruned from the browse catalog (#870)
//   but kept here so the planner's `<mcp_assign name="…" />` (planExtensions.ts) still resolves them
//   to a working config.
// (`as unknown` for the `env` pairs: JSON can't express the `[string, string]` tuple type.)
const MCP_CATALOG_TEMPLATES: Record<string, Partial<McpServer>> =
  overlayFile("mcp/catalog-templates.json", catalogTemplatesEmbedded as unknown as Record<string, Partial<McpServer>>);

/** A ready-to-add MCP server (minus id) for a catalog entry — disabled + global
 *  by default; the caller assigns the id and the user fills any blank config. */
export function mcpFromCatalog(name: string): Omit<McpServer, "id"> {
  const t = MCP_CATALOG_TEMPLATES[name] ?? { transport: "stdio" as McpTransport, command: "", args: "" };
  return {
    name,
    enabled: false,
    projects: [],
    transport: t.transport ?? "stdio",
    command: t.command,
    args: t.args,
    url: t.url,
    env: t.env,
  };
}

/** A blank custom MCP server, ready for the add-custom form. */
export function blankMcpServer(): Omit<McpServer, "id"> {
  return { name: "", enabled: false, projects: [], transport: "stdio", command: "", args: "", env: [] };
}

