describe("cross-kit base-motion resolution (#3451)", () => {
  // The app's foundational motion is owned ONCE by the `base` kit; react-ui (and any other kit)
  // REFERENCES it by name. Resolution therefore has to leave its own kit — the behaviour this covers.
  const lift: KitAnimation = { name: "lift", trigger: "hover", keyframes: { from: { transform: "translateY(0)" }, to: { transform: "translateY(-1px)" } } };
  const baseKit = mkKit({ id: BASE_KIT_ID, name: "Base", animations: [lift] });
  const reactUi = mkKit({ id: "react-ui", animations: [] });

  it("resolves a name the component's OWN kit does not define from the base kit", () => {
    const btn = mkComp({ id: "btn", name: "Button", kitId: "react-ui", animations: ["lift"] });
    const defs = resolveComponentAnimationDefs(btn, [reactUi, baseKit]);
    expect(defs.map((d) => d.name)).toEqual(["lift"]);
    expect(defs[0].keyframes).toEqual(lift.keyframes);
  });

  it("keeps the OWNING kit on a base-resolved def, so every consumer shares one keyframes block", () => {
    // THE load-bearing assertion. `kit` names both `@keyframes bsc-<kit>-<name>` and the
    // `.<kit>-anim-<name>` class the preview stamps. Restamping to the CONSUMER would duplicate the
    // keyframes per kit and defeat propagation — and, if only one side were restamped, the class would
    // not match the compiled rule and the animation would silently play nothing.
    const btn = mkComp({ id: "btn", name: "Button", kitId: "react-ui", animations: ["lift"] });
    expect(resolveComponentAnimationDefs(btn, [reactUi, baseKit])[0].kit).toBe(BASE_KIT_ID);
  });

  it("prefers a kit's OWN definition over the base one of the same name (override wins)", () => {
    const ownLift: KitAnimation = { name: "lift", keyframes: { from: { opacity: "0" }, to: { opacity: "1" } } };
    const overriding = mkKit({ id: "react-ui", animations: [ownLift] });
    const btn = mkComp({ id: "btn", name: "Button", kitId: "react-ui", animations: ["lift"] });
    const [def] = resolveComponentAnimationDefs(btn, [overriding, baseKit]);
    expect(def.keyframes).toEqual(ownLift.keyframes);
    expect(def.kit, "an own def stays namespaced to its own kit").toBe("react-ui");
  });

  it("drops a name defined by NEITHER the own kit nor base (no dangling ref)", () => {
    const btn = mkComp({ id: "btn", name: "Button", kitId: "react-ui", animations: ["nope"] });
    expect(resolveComponentAnimationDefs(btn, [reactUi, baseKit])).toEqual([]);
  });

  it("still stamps an INLINE def with the component's own kit (unchanged by the fallback)", () => {
    const btn = mkComp({ id: "btn", name: "Button", kitId: "react-ui", animations: [fade] });
    expect(resolveComponentAnimationDefs(btn, [reactUi, baseKit])[0].kit).toBe("react-ui");
  });

  it("resolves a base component's own animations without changing their kit", () => {
    const dot = mkComp({ id: "dot", name: "Dot", kitId: BASE_KIT_ID, animations: ["lift"] });
    expect(resolveComponentAnimationDefs(dot, [reactUi, baseKit])[0].kit).toBe(BASE_KIT_ID);
  });

  it("exposes the base shelf to a try-on from another kit (react-ui's own library is empty now)", () => {
    // Without the base shelf, `resolveNamedAnimation` could not find a base motion the component does
    // not already bind — so clicking it in the AnimationsMenu would preview nothing.
    const btn = mkComp({ id: "btn", name: "Button", kitId: "react-ui", animations: [] });
    const found = resolveNamedAnimation(btn, reactUi, [reactUi, baseKit], "lift");
    expect(found?.name).toBe("lift");
    expect(found?.kit).toBe(BASE_KIT_ID);
  });
});

// The buildability PREDICATE (#4130) must stay exactly `componentPreviewFiles(...) !== null`.
//
// `analyzeGraphHealth` (and its Rust twin `bsc ui doctor`) decide "spec or implementation" with
// `componentBuildable`, which answers off cached indexes instead of building a preview bundle. If the two
// ever disagree the graph accuses a component the preview renders happily — the #3486/#2954 failure mode —
// so this pins them together over a library shaped like the real one, in several sibling arrangements.
import { describe, it, expect } from "vitest";
import reactUiArtifact from "@data/components/react-ui.json";
import { componentPreviewFiles, componentBuildable, type KitArtifact } from "@/features/designs/lib/componentPreview";
import type { ComponentRecord } from "@/features/designs/lib/model";

const ARTIFACT = reactUiArtifact as unknown as KitArtifact;
const BUILTIN = ARTIFACT.components.find((c) => c.source)!;

const comp = (o: Partial<ComponentRecord> & Pick<ComponentRecord, "id">): ComponentRecord =>
  ({
    name: o.id, kitId: "k", role: "primitive", version: "", used: 0, tags: [], variants: ["default"],
    composes: [], props: [], whenUse: [], whenNot: [], src: "", srcText: "", ...o,
  }) as ComponentRecord;

// One record per shape the predicate has to get right.
const LIBRARY: ComponentRecord[] = [
  comp({ id: "builtin", src: BUILTIN.src }),                                     // in the artifact
  comp({ id: "spec", srcText: "import { X } from \"@/x\";\n<X …/>" }),           // usage snippet
  comp({ id: "empty" }),                                                          // nothing at all
  comp({ id: "explicit", source: "export const A = () => null;" }),              // explicit source, trusted
  // NOTE the path form: a sibling resolves by `stripExt(src)` against the `@/…` specifier, so its `src`
  // is src/-RELATIVE (`u/M.tsx`), matching the artifact keys — a store record's `src/`-prefixed path is the
  // known mismatch #3660 sidesteps by keying on the specifier.
  comp({ id: "module", src: "u/M.tsx", srcText: "export const M = () => null;" }),
  comp({ id: "sibimport", src: "src/u/S.tsx", srcText: "import { M } from \"@/u/M\";\nexport const S = () => M;" }),
  comp({ id: "badimport", src: "src/u/B.tsx", srcText: "import { Z } from \"@/nope/Z\";\nexport const B = () => Z;" }),
  comp({ id: "typeonly", src: "src/u/T.tsx", srcText: "import type { P } from \"@/nope/P\";\nexport const T = () => null;" }),
  comp({ id: "elided", src: "src/u/E.tsx", srcText: "export const E = () => { … };" }),
  comp({ id: "provider", src: "src/u/P.tsx", provides: "@/shared/ui/Prov", source: "export const P = () => null;" }),
  comp({ id: "consumer", src: "src/u/C.tsx", srcText: "import { P } from \"@/shared/ui/Prov\";\nexport const C = () => P;" }),
];

const SHAPES: Array<[string, readonly ComponentRecord[]]> = [
  ["whole library", LIBRARY],
  ["no siblings", []],
  ["single sibling", [LIBRARY[4]]],
];

describe("componentBuildable", () => {
  for (const [label, siblings] of SHAPES) {
    it(`agrees with componentPreviewFiles for every record — ${label}`, () => {
      for (const c of LIBRARY) {
        expect(componentBuildable(c, ARTIFACT, siblings), c.id).toBe(
          componentPreviewFiles(c, ARTIFACT, siblings) !== null,
        );
      }
    });
  }

  it("covers both verdicts, so the agreement above is not vacuously true", () => {
    const verdicts = LIBRARY.map((c) => componentBuildable(c, ARTIFACT, LIBRARY));
    expect(verdicts).toContain(true);
    expect(verdicts).toContain(false);
  });

  it("resolves a sibling import only when that sibling is actually present", () => {
    const s = LIBRARY.find((c) => c.id === "sibimport")!;
    expect(componentBuildable(s, ARTIFACT, LIBRARY)).toBe(true);   // `module` is there
    expect(componentBuildable(s, ARTIFACT, [s])).toBe(false);      // alone ⇒ nothing to resolve `@/u/M`
  });

  it("does not let a component resolve an import against ITSELF", () => {
    // `sibByBase` excludes the component under test; a cached whole-array index must honour that.
    const self = comp({ id: "self", src: "u/M.tsx", srcText: "import { M } from \"@/u/M\";\nexport const M2 = () => M;" });
    expect(componentBuildable(self, ARTIFACT, [self])).toBe(
      componentPreviewFiles(self, ARTIFACT, [self]) !== null,
    );
  });

  it("is stable across repeated calls with the same arrays (the identity caches are not stateful)", () => {
    const first = LIBRARY.map((c) => componentBuildable(c, ARTIFACT, LIBRARY));
    const second = LIBRARY.map((c) => componentBuildable(c, ARTIFACT, LIBRARY));
    expect(second).toEqual(first);
  });
});

// The seed-projection COVERAGE guard (`record-src-reconcile`).
//
// `projectComponent` is an ALLOWLIST: a field it does not name is dropped. That is fine for a field
// nothing carries, and silent data loss for a field a packaged record actually holds.
//
// WHY THE EXISTING ROUND-TRIP TEST CANNOT CATCH THIS. `seedRoundTrip.test.ts` asserts
// `seed === load(push(seed))` — but `SEED_COMPONENTS` is itself built by running each raw JSON through
// `projectComponent` (see `seed.ts`). Both sides of that equation therefore drop an unknown field
// IDENTICALLY, and the equation holds trivially. Verified by removing `srcDivergence` from the
// allowlist: the round-trip suite stayed green (7/7) while the field was being dropped from the seed
// entirely — so the app would never have seen it, and 70 annotated records would have carried a reason
// that existed only in the JSON on disk. That is the same shape as #4188/#4224: a check more permissive
// than the thing it stands for.
//
// So this asserts the coverage directly, against the RAW seed JSON rather than the projected form: every
// key any packaged record actually carries must survive the projection.
import { describe, it, expect } from "vitest";
import { projectComponent } from "@/features/designs/lib/componentBridge";
import type { ComponentRecord } from "@/features/designs/lib/model";

// The RAW records — deliberately NOT `SEED_COMPONENTS`, which is already projected and so cannot show
// what the projection discarded.
const raw = import.meta.glob<Partial<ComponentRecord>>("@data/components/app/**/*.json", {
  eager: true,
  import: "default",
});
const RECORDS = Object.values(raw).filter((r) => r && (r as { id?: string }).id);

/** Keys a record may carry that the projection is EXPECTED to drop, each with the reason.
 *  Anything not listed here is either projected or a bug — this list is the deliberate part. */
const INTENTIONALLY_DROPPED = new Set<string>([
  // The legacy spelling of `folder` (#4107 slice B). The projection reads it and re-emits it AS
  // `folder`, so the key itself legitimately does not survive under its old name.
  "group",
]);

describe("seed projection coverage (`record-src-reconcile`)", () => {
  it("has records to check — the glob still resolves", () => {
    // Non-vacuity: an empty glob would make the assertion below pass while checking nothing, which is
    // precisely the failure mode this file exists to close.
    expect(RECORDS.length).toBeGreaterThan(300);
  });

  it("EVERY key a packaged record carries survives `projectComponent`", () => {
    const carried = new Set<string>();
    for (const r of RECORDS) for (const k of Object.keys(r)) carried.add(k);

    const dropped: string[] = [];
    for (const key of carried) {
      if (INTENTIONALLY_DROPPED.has(key)) continue;
      // Project a record that actually carries the key, so a projection reading it conditionally
      // (`folder ?? group`) is exercised the way the real seed exercises it.
      const sample = RECORDS.find((r) => (r as Record<string, unknown>)[key] !== undefined)!;
      const projected = projectComponent(sample) as unknown as Record<string, unknown>;
      if (projected[key] === undefined) dropped.push(key);
    }

    expect(
      dropped,
      `these keys are on packaged records but dropped by projectComponent — add them to the allowlist ` +
        `(or to INTENTIONALLY_DROPPED with a reason):\n  ${dropped.join("\n  ")}`,
    ).toEqual([]);
  });

  it("carries `srcDivergence` — the field this guard was written for", () => {
    // A named regression test for the specific field, so the general check above cannot be weakened
    // without this also failing.
    const projected = projectComponent({ id: "x", name: "X", srcDivergence: "because" }) as ComponentRecord;
    expect(projected.srcDivergence).toBe("because");
  });
});

