// A default import of packaged data JSON must yield the DATA, not the module namespace.
//
// This is the bug that broke `mcppage` and `planningpage` in a browser while `npm run gate` stayed
// green. esbuild compiles `import x from "spec"` to `__toESM(require("spec")).default`, and `__toESM`
// passes a module through ONLY if it carries `__esModule` — otherwise it wraps as
// `{...mod, default: mod}`, so `.default` is the namespace. Vite's eager-glob namespaces have no
// `__esModule`, so every default import of a packaged data JSON inside a record resolved to an object
// where the code expected its contents:
//
//   MODELS.map is not a function · PLAN_STAGES.map · MCP_CATALOG.filter · BUILTIN_MCP_SERVERS.filter
//
// Most degraded (the loader declined the override and fell back to the bundled module), which is why
// only two pages actually died — and why it went unnoticed: the failure was mostly SILENT.
//
// The registration was necessary but not sufficient, and nothing tested the sufficient half. This does.
import { describe, it, expect } from "vitest";
import { registerPlatformModules } from "@/app/runtime/appModules";
import { resolveAppModule, isAppModule } from "@/shared/lib/runtime/moduleRegistry";

/** esbuild's interop helper, reproduced exactly — this is the consumer whose contract we must satisfy. */
function toESM(mod: unknown): Record<string, unknown> {
  const m = mod as Record<string, unknown>;
  return m && m.__esModule ? m : { ...(m ?? {}), default: m };
}
/** What a record's default import of `spec` actually evaluates to at runtime. */
const defaultImport = (spec: string) => toESM(resolveAppModule(spec)).default;

describe("a default import of packaged data JSON yields the data", () => {
  registerPlatformModules();

  it("registers the data JSON at all", () => {
    expect(isAppModule("@data/console/models.json")).toBe(true);
  });

  it.each([
    ["@data/console/models.json", "MODELS"],
    ["@data/mcp/catalog.json", "MCP_CATALOG"],
    ["@data/mcp/builtin-servers.json", "BUILTIN_MCP_SERVERS"],
  ])("%s resolves to an ARRAY, not a namespace (%s)", (spec) => {
    if (!isAppModule(spec)) return;            // a data file may be renamed; the shape test is the point
    const value = defaultImport(spec);
    expect(Array.isArray(value), `${spec} → ${Object.prototype.toString.call(value)}`).toBe(true);
  });

  it("the namespace itself still has no __esModule — the wrapper is what supplies it", () => {
    // Pins the ROOT CAUSE rather than the symptom. If Vite ever starts emitting `__esModule`, this
    // fails and tells the next reader that `asEsModule` may have become unnecessary — instead of the
    // wrapper quietly persisting as cargo with nobody able to say why it exists.
    const raw = import.meta.glob<unknown>("@data/console/models.json", { eager: true });
    const ns = Object.values(raw)[0] as Record<string, unknown>;
    expect("__esModule" in ns).toBe(false);
    expect("default" in ns).toBe(true);
  });

  it("a module that ALREADY declares __esModule is not rewrapped", () => {
    // `asEsModule` must leave a genuine CJS-interop module alone; double-wrapping would bury its default.
    const already = { __esModule: true, default: [1, 2, 3] };
    expect(toESM(already).default).toBe(already.default);
  });
});

implementations.code:
// The Glance morph GRID (#3361, directional placement #3367) — pure, React-free geometry + placement
// for the in-graph terminal morphs, so the layout is unit-testable without rendering a terminal.
//
// THE MODEL: morphs stay IN the graph (a node grows into its live session in place — that is the whole
// point of the morph, #2534). What changes is that a morph no longer free-floats at its own node's
// coords, where two open morphs would sit on top of each other. Instead each occupies a discrete cell of
// a lattice, so non-overlap is guaranteed by construction rather than by a soft push-apart relaxation.
//
// THE FIRST OPENED NODE DEFINES THE GRID. Its morph lands exactly where a single morph lands today —
// centred on its own node — and that box becomes cell (0,0). The origin is derived from the ANCHOR NODE
// (an id) rather than frozen as raw coords, so the grid tracks the graph if the layout recomputes (the
// live-status overlays rebuild the model every poll).
//
// THE LATTICE IS SIGNED (#3367). Cells extend every way from the anchor — (-1,0) is one cell LEFT,
// (0,-1) one cell UP.
//
// PLACEMENT IS UNIFORMITY-FIRST, DIRECTION SECOND (#3525). #3367 placed each node in the free cell whose
// direction from the anchor best matched its node's direction. That kept a lone node on its own side but
// let the block spread into a sparse, non-square arrangement — three left-hand nodes could sit in a
// 1×3 column with gaps rather than collapsing into a tight tile. A newly opened node now first looks for
// the cell that keeps the OPEN BLOCK most uniform — a compact, near-square rectangle with no interior
// holes — and only uses direction to break ties BETWEEN equally-compact cells. So the block still leans
// toward the side its nodes sit on (a left-heavy graph opens a left-leaning block), but it always reads
// as a tidy tile grid rather than a scatter. The trade is deliberate: an individual left-hand node may
// land in the anchor's own column when that is what completes the square, because a uniform block beats
// a strictly-sided but ragged one.
import type { MorphRect } from "@/features/glance/lib/glancePush";
import { NW, NH } from "@/features/glance/lib/glanceGraph";

/** A cell's DEFAULT size, in WORLD units (it renders at world-size × the current zoom). Matches the
 *  pre-grid single-morph card, so opening one node is visually unchanged. */
export const CELL_W = 760, CELL_H = 520;
/** Resize bounds for the shared cell (world units). A resize drives EVERY cell — a per-morph size would
 *  break the non-overlap guarantee the grid exists to provide. */
export const CELL_MIN_W = 380, CELL_MIN_H = 280, CELL_MAX_W = 1600, CELL_MAX_H = 1100;
/** Gutter between cells, world units — wide enough that two cards read as separate panels. */
export const GRID_GAP = 28;
/** How far out the placement search looks for a free cell. Ring 6 spans 169 cells — far past any
 *  plausible number of simultaneously open sessions, so this is a termination guard, not a cap. */
export const MAX_RING = 6;
/** The most cells a compact block can be off a perfect square before direction stops mattering — unused
 *  as a tunable now that compactness is lexicographically primary (#3525); kept exported for callers/tests
 *  that referenced the old direction-vs-distance trade. */
export const RING_PENALTY = 0.35;

/** The shared cell size — mutated as one by any morph's resize handles. */
export interface CellSize { w: number; h: number }

export const DEFAULT_CELL: CellSize = { w: CELL_W, h: CELL_H };

/** A lattice position. SIGNED: a negative col is LEFT of the anchor, a negative row is ABOVE it. */
export interface GridCell { col: number; row: number }

/** Which node holds which cell. */
export interface MorphPlacement extends GridCell { nodeId: string }

/** As much of a node as the grid geometry needs. */
export interface GridAnchorNode { x: number; y: number }

/**
 * Cell (0,0)'s top-left, in world coords: the cell CENTRED on the anchor node — byte-identical to the
 * pre-grid morph's own box (`node.x + NW/2 - CARD_W/2`). This is what makes opening the first node look
 * exactly as it always has; the grid only becomes visible from the second morph on.
 */
export function gridOrigin(anchor: GridAnchorNode, cell: CellSize = DEFAULT_CELL): { x: number; y: number } {
  return { x: anchor.x + NW / 2 - cell.w / 2, y: anchor.y + NH / 2 - cell.h / 2 };
}

/** The world box of a lattice cell. Signed, so `col: -1` sits one full cell + gap to the LEFT. */
export function cellRect(anchor: GridAnchorNode, at: GridCell, cell: CellSize = DEFAULT_CELL): MorphRect {
  const o = gridOrigin(anchor, cell);
  return {
    left: o.x + at.col * (cell.w + GRID_GAP),
    top: o.y + at.row * (cell.h + GRID_GAP),
    w: cell.w,
    h: cell.h,
  };
}

/** Every cell at Chebyshev distance `r` from the origin — the square "ring" at radius r. Ring 0 is the
 *  origin itself; ring 1 is the eight neighbours. Deterministically ordered (by col, then row). */
export function ringCells(r: number): GridCell[] {
  if (r <= 0) return [{ col: 0, row: 0 }];
  const out: GridCell[] = [];
  for (let col = -r; col <= r; col++) {
    for (let row = -r; row <= r; row++) {
      if (Math.max(Math.abs(col), Math.abs(row)) === r) out.push({ col, row });
    }
  }
  return out;
}

/** How well a cell's direction from the origin matches the unit vector (ux,uy): the cosine of the angle
 *  between them, in [-1, 1]. The origin cell has no direction, so it scores 0. */
function alignment(at: GridCell, ux: number, uy: number): number {
  const len = Math.hypot(at.col, at.row);
  if (len === 0) return 0;
  return (at.col * ux + at.row * uy) / len;
}

const key = (at: GridCell) => `${at.col},${at.row}`;

/** The two numbers that make a placement UNIFORM (#3525), for the occupied set INCLUDING the candidate.
 *  Compared lexicographically, smaller = more uniform:
 *   1. `maxDim` — the longer side of the bounding box. Minimising it caps how far the block can stretch
 *      in any one direction, so N cells collapse toward a √N-square instead of a long strip.
 *   2. `holes` — empty cells inside that box (`area − filled`). With `maxDim` fixed, the fewest holes
 *      wins, so a candidate that fills a gap always beats one that opens the block up. */
function uniformity(cells: readonly GridCell[]): { maxDim: number; holes: number } {
  let minC = Infinity, maxC = -Infinity, minR = Infinity, maxR = -Infinity;
  for (const c of cells) {
    if (c.col < minC) minC = c.col;
    if (c.col > maxC) maxC = c.col;
    if (c.row < minR) minR = c.row;
    if (c.row > maxR) maxR = c.row;
  }
  const w = maxC - minC + 1, h = maxR - minR + 1;
  return { maxDim: Math.max(w, h), holes: w * h - cells.length };
}

/**
 * Place `nodeId` in the free cell that keeps the open block most UNIFORM, breaking ties by `delta` — its
 * node's world offset FROM THE ANCHOR NODE (#3525, was direction-first in #3367).
 *
 * For each free cell the candidate occupied set is scored by {@link uniformity} (compact, hole-free
 * first); among equally-uniform cells the one whose direction best matches `delta` wins, so the block
 * still leans toward the side its nodes sit on. This is what makes N morphs collapse into a tidy tile
 * grid (a 2×2, then 3×3, …) rather than the sparse strips direction-first could leave — while a
 * left-heavy graph still opens a left-leaning block.
 *
 * The FIRST placement is always the anchor itself at (0,0). A `delta` of zero — the anchor node itself
 * re-opening — takes (0,0) back when free; every other node is scored, so a freed centre is filled only
 * when it is also the most uniform choice.
 *
 * Placed morphs are NEVER moved: placement decides where a morph goes when it OPENS. Re-ranking every
 * morph on each open would make a terminal being read jump, which is worse than an imperfect
 * arrangement. Re-placing an already-placed node is a no-op.
 */
export function placeByDirection(
  placements: readonly MorphPlacement[],
  nodeId: string,
  delta: { dx: number; dy: number },
  maxRing: number = MAX_RING,
): MorphPlacement[] {
  if (placements.some((p) => p.nodeId === nodeId)) return placements.slice();
  if (placements.length === 0) return [{ nodeId, col: 0, row: 0 }];

  const taken = new Set(placements.map(key));
  const len = Math.hypot(delta.dx, delta.dy);

  // The anchor node re-opening (zero delta) belongs at the centre when it is free — the block was built
  // around (0,0). Otherwise it falls through to the uniform scoring like any node.
  if (len === 0 && !taken.has(key({ col: 0, row: 0 }))) {
    return [...placements, { nodeId, col: 0, row: 0 }];
  }
  const ux = len === 0 ? 0 : delta.dx / len;
  const uy = len === 0 ? 0 : delta.dy / len;
  const occupied = placements.map((p) => ({ col: p.col, row: p.row }));

  // Score every free cell out to `maxRing`. Compactness is lexicographically PRIMARY: a smaller longer
  // side wins, then fewer holes, so the block collapses toward a square with no gaps. Direction only
  // separates cells that are equally uniform, and a deterministic (col,row) order settles the rest so
  // the same graph always lays out identically.
  // From ring 0: the origin is a candidate too, so a centre freed by the anchor's morph closing gets
  // filled when that keeps the block compact (it is normally `taken`, hence skipped). The zero-delta
  // anchor re-open above already claimed a free (0,0), so this only reconsiders it for other nodes.
  let best: { cell: GridCell; maxDim: number; holes: number; align: number } | null = null;
  for (let r = 0; r <= maxRing; r++) {
    for (const c of ringCells(r)) {
      if (taken.has(key(c))) continue;
      const { maxDim, holes } = uniformity([...occupied, c]);
      const align = alignment(c, ux, uy);
      const better =
        !best
        || maxDim < best.maxDim
        || (maxDim === best.maxDim && holes < best.holes)
        || (maxDim === best.maxDim && holes === best.holes && align > best.align + 1e-9)
        || (maxDim === best.maxDim && holes === best.holes && Math.abs(align - best.align) <= 1e-9
            && (c.col < best.cell.col || (c.col === best.cell.col && c.row < best.cell.row)));
      if (better) best = { cell: c, maxDim, holes, align };
    }
  }
  // Every ring out to maxRing is full — refuse rather than overlap. Unreachable in practice (169 cells).
  return best ? [...placements, { nodeId, ...best.cell }] : placements.slice();
}

/** Drop `nodeId`'s placement. The survivors keep their cells — closing one morph never moves another. */
export function releaseCell(placements: readonly MorphPlacement[], nodeId: string): MorphPlacement[] {
  return placements.filter((p) => p.nodeId !== nodeId);
}

/** The node ids currently holding a cell, in placement order. */
export function occupants(placements: readonly MorphPlacement[]): string[] {
  return placements.map((p) => p.nodeId);
}

/**
 * The bounding box of every open morph — the single region the graph parts around. Null when none are
 * open (so the neighbours snap back).
 *
 * Unions the boxes the morphs REPORT rather than deriving them from placements: a morph releases its box
 * the instant it starts collapsing, several hundred ms before it unmounts, so the graph parts back in
 * step with the shrink instead of lagging a full exit animation behind it.
 */
export function unionRects(rects: readonly MorphRect[]): MorphRect | null {
  if (rects.length === 0) return null;
  const left = Math.min(...rects.map((r) => r.left));
  const top = Math.min(...rects.map((r) => r.top));
  const right = Math.max(...rects.map((r) => r.left + r.w));
  const bottom = Math.max(...rects.map((r) => r.top + r.h));
  return { left, top, w: right - left, h: bottom - top };
}

/** Clamp a proposed shared cell size to the resize bounds. */
export function clampCell(w: number, h: number): CellSize {
  return {
    w: Math.min(Math.max(w, CELL_MIN_W), CELL_MAX_W),
    h: Math.min(Math.max(h, CELL_MIN_H), CELL_MAX_H),
  };
}

tests.src:
import { describe, it, expect } from "vitest";
import {
  gridOrigin, cellRect, ringCells, unionRects, placeByDirection, releaseCell, occupants, clampCell,
  CELL_W, CELL_H, GRID_GAP, DEFAULT_CELL,
  CELL_MIN_W, CELL_MIN_H, CELL_MAX_W, CELL_MAX_H,
  type MorphPlacement, type GridCell,
} from "@/features/glance/lib/morphGrid";
import { NW, NH } from "@/features/glance/lib/glanceGraph";
import type { MorphRect } from "@/features/glance/lib/glancePush";

const ANCHOR = { x: 100, y: 100 };
/** Do two world boxes overlap at all? The property the whole grid exists to guarantee. */
const overlaps = (a: MorphRect, b: MorphRect) =>
  a.left < b.left + b.w && b.left < a.left + a.w && a.top < b.top + b.h && b.top < a.top + a.h;

/** Place `id` at world offset (dx,dy) from the anchor node — the shape the workspace passes in. */
const place = (ps: MorphPlacement[], id: string, dx: number, dy: number) =>
  placeByDirection(ps, id, { dx, dy });
/** The cell `id` ended up in. */
const cellOf = (ps: MorphPlacement[], id: string): GridCell => {
  const p = ps.find((x) => x.nodeId === id)!;
  return { col: p.col, row: p.row };
};
/** An anchor placement to build on — "root" occupies (0,0). */
const rooted = () => place([], "root", 0, 0);

describe("gridOrigin (#3361 — the first opened node defines the grid)", () => {
  it("centres cell (0,0) on the anchor node — byte-identical to the pre-grid single morph's own box", () => {
    // The morph used to compute `node.x + NW/2 - CARD_W/2`. Opening ONE node must look unchanged.
    expect(gridOrigin(ANCHOR)).toEqual({
      x: ANCHOR.x + NW / 2 - CELL_W / 2,
      y: ANCHOR.y + NH / 2 - CELL_H / 2,
    });
  });

  it("re-centres when the shared cell is resized, so the grid stays anchored on the node", () => {
    expect(gridOrigin(ANCHOR, { w: 400, h: 300 })).toEqual({
      x: ANCHOR.x + NW / 2 - 200,
      y: ANCHOR.y + NH / 2 - 150,
    });
  });
});

describe("cellRect (#3367 — a SIGNED lattice)", () => {
  it("places cell (0,0) at the origin", () => {
    const o = gridOrigin(ANCHOR);
    expect(cellRect(ANCHOR, { col: 0, row: 0 })).toEqual({ left: o.x, top: o.y, w: CELL_W, h: CELL_H });
  });

  it("puts NEGATIVE cells left of / above the anchor — the whole point of #3367", () => {
    const o = gridOrigin(ANCHOR);
    expect(cellRect(ANCHOR, { col: -1, row: 0 }).left).toBe(o.x - (CELL_W + GRID_GAP));
    expect(cellRect(ANCHOR, { col: 0, row: -1 }).top).toBe(o.y - (CELL_H + GRID_GAP));
    expect(cellRect(ANCHOR, { col: 1, row: 0 }).left).toBe(o.x + (CELL_W + GRID_GAP));
    expect(cellRect(ANCHOR, { col: 0, row: 1 }).top).toBe(o.y + (CELL_H + GRID_GAP));
  });

  it("NEVER overlaps any other cell — the guarantee the grid exists to provide", () => {
    const rects = [{ col: 0, row: 0 }, ...ringCells(1), ...ringCells(2)].map((c) => cellRect(ANCHOR, c));
    for (let a = 0; a < rects.length; a++) {
      for (let b = a + 1; b < rects.length; b++) {
        expect(overlaps(rects[a], rects[b])).toBe(false);
      }
    }
  });

  it("still never overlaps at the MAXIMUM cell size", () => {
    const cell = { w: CELL_MAX_W, h: CELL_MAX_H };
    const rects = [{ col: 0, row: 0 }, ...ringCells(1)].map((c) => cellRect(ANCHOR, c, cell));
    for (let a = 0; a < rects.length; a++) {
      for (let b = a + 1; b < rects.length; b++) {
        expect(overlaps(rects[a], rects[b])).toBe(false);
      }
    }
  });

  it("tracks the anchor node — the grid moves with the graph rather than freezing at open time", () => {
    const moved = { x: ANCHOR.x + 500, y: ANCHOR.y - 250 };
    const at = { col: -2, row: 1 };
    expect(cellRect(moved, at).left - cellRect(ANCHOR, at).left).toBe(500);
    expect(cellRect(moved, at).top - cellRect(ANCHOR, at).top).toBe(-250);
  });
});

describe("ringCells (#3367)", () => {
  it("ring 0 is the origin; ring 1 is the eight neighbours; ring r has 8r cells", () => {
    expect(ringCells(0)).toEqual([{ col: 0, row: 0 }]);
    expect(ringCells(1)).toHaveLength(8);
    expect(ringCells(2)).toHaveLength(16);
    expect(ringCells(3)).toHaveLength(24);
  });

  it("every cell in ring r is at Chebyshev distance exactly r", () => {
    for (const c of ringCells(3)) expect(Math.max(Math.abs(c.col), Math.abs(c.row))).toBe(3);
  });
});

// ── #3525: placement is UNIFORMITY-first (a tidy tile block), DIRECTION second (the block leans toward
//    the side its nodes sit). Replaces the direction-first #3367 contract, which left sparse strips. ──
/** The bounding box of a set of cells + how many of its cells are empty. */
const blockShape = (ps: MorphPlacement[]) => {
  const cols = ps.map((p) => p.col), rows = ps.map((p) => p.row);
  const w = Math.max(...cols) - Math.min(...cols) + 1;
  const h = Math.max(...rows) - Math.min(...rows) + 1;
  return { w, h, maxDim: Math.max(w, h), holes: w * h - ps.length };
};
/** The mean cell of the block — used to assert which SIDE of the anchor the block leans to. */
const centroid = (ps: MorphPlacement[]) => ({
  col: ps.reduce((a, p) => a + p.col, 0) / ps.length,
  row: ps.reduce((a, p) => a + p.row, 0) / ps.length,
});

describe("placeByDirection (#3525 — uniformity first, direction second)", () => {
  it("the first opened node anchors the grid at (0,0)", () => {
    expect(rooted()).toEqual([{ nodeId: "root", col: 0, row: 0 }]);
  });

  it("a SECOND node opens adjacent to the anchor on its side — a tight 2×1, never a diagonal", () => {
    // Two nodes: the most uniform block is a 2×1 with no holes; direction picks WHICH side.
    expect(cellOf(place(rooted(), "n", 0, -900), "n")).toEqual({ col: 0, row: -1 });
    expect(cellOf(place(rooted(), "s", 0, 900), "s")).toEqual({ col: 0, row: 1 });
    expect(cellOf(place(rooted(), "e", 900, 0), "e")).toEqual({ col: 1, row: 0 });
    expect(cellOf(place(rooted(), "w", -900, 0), "w")).toEqual({ col: -1, row: 0 });
  });

  it("a DIAGONALLY-placed node still opens to an ADJACENT cell — a 2×1 beats a hole-y 2×2 (#3525)", () => {
    // Under direction-first (#3367) a NE node took the diagonal (1,-1), leaving a 2×2 with two gaps.
    // Uniformity-first prefers a gap-free 2×1: the block is adjacent, and stays on the node's side.
    for (const [dx, dy] of [[700, -700], [-700, -700], [700, 700], [-700, 700]] as const) {
      const ps = place(rooted(), "d", dx, dy);
      expect(blockShape(ps)).toMatchObject({ maxDim: 2, holes: 0 }); // adjacent, no diagonal gap
    }
  });

  it("collapses N opened nodes into a tight SQUARE — 4 → an exact 2×2, 9 → an exact 3×3", () => {
    // The heart of #3525: a filled square with NO holes, not a strip or a scatter.
    let four = rooted();
    for (const [id, dx, dy] of [["e", 900, 0], ["w", -900, 0], ["s", 0, 900]] as const) four = place(four, id, dx, dy);
    expect(blockShape(four)).toEqual({ w: 2, h: 2, maxDim: 2, holes: 0 });

    let nine = rooted();
    const dirs: [string, number, number][] = [
      ["e", 900, 0], ["w", -900, 0], ["n", 0, -900], ["s", 0, 900],
      ["ne", 700, -700], ["nw", -700, -700], ["se", 700, 700], ["sw", -700, 700],
    ];
    for (const [id, dx, dy] of dirs) nine = place(nine, id, dx, dy);
    expect(blockShape(nine)).toEqual({ w: 3, h: 3, maxDim: 3, holes: 0 });
  });

  it("never leaves an interior gap while the block is still growing", () => {
    // 'checks for a pattern before filling its slot': at every step the block is as dense as possible,
    // so holes (if any) are only the unfilled tail of the last row — always fewer than a full side.
    let ps = rooted();
    for (let i = 1; i <= 12; i++) {
      ps = place(ps, `x${i}`, ((i % 3) - 1) * 900, (Math.floor(i / 3) - 2) * 900);
      const { maxDim, holes } = blockShape(ps);
      expect(holes).toBeLessThan(maxDim); // at most a partial last row/col, never an interior void
    }
  });

  it("the block LEANS toward the side its nodes sit on — direction survives as the tiebreak", () => {
    // Individual cells may sit in the anchor's column when that completes the square, but the block's
    // centre of mass is unambiguously on the nodes' side. (Direction-first kept every cell strictly
    // sided; #3525 trades that for a uniform block that still points the right way.)
    let west = rooted();
    for (let i = 0; i < 6; i++) west = place(west, `w${i}`, -900, (i - 3) * 30);
    expect(centroid(west).col).toBeLessThan(0);

    let north = rooted();
    for (let i = 0; i < 6; i++) north = place(north, `n${i}`, (i - 3) * 30, -900);
    expect(centroid(north).row).toBeLessThan(0);
  });

  it("breaks a uniformity tie by direction — two equally-compact cells go to the matching side", () => {
    // After the anchor, a west and an east node are each a valid 2×1; direction sends them opposite ways.
    const w = cellOf(place(rooted(), "w", -900, 0), "w");
    const e = cellOf(place(rooted(), "e", 900, 0), "e");
    expect(w.col).toBeLessThan(0);
    expect(e.col).toBeGreaterThan(0);
  });

  it("never places two morphs in the same cell", () => {
    let ps = rooted();
    const dirs: [string, number, number][] = [
      ["a", -900, 0], ["b", 900, 0], ["c", 0, -900], ["d", 0, 900],
      ["e", -700, -700], ["f", 700, 700], ["g", -700, 700], ["h", 700, -700],
      ["i", -900, -30], ["j", -900, 30],
    ];
    for (const [id, dx, dy] of dirs) ps = place(ps, id, dx, dy);
    const keys = ps.map((p) => `${p.col},${p.row}`);
    expect(new Set(keys).size).toBe(keys.length);
  });

  it("is STABLE — placing another node never moves an existing one", () => {
    let ps = rooted();
    ps = place(ps, "west", -900, 0);
    const before = cellOf(ps, "west");
    ps = place(ps, "east", 900, 0);
    ps = place(ps, "north", 0, -900);
    expect(cellOf(ps, "west")).toEqual(before);
    expect(cellOf(ps, "root")).toEqual({ col: 0, row: 0 });
  });

  it("re-placing an already-placed node is a no-op, not a second cell", () => {
    let ps = place(rooted(), "west", -900, 0);
    ps = place(ps, "west", -900, 0);
    expect(ps.filter((p) => p.nodeId === "west")).toHaveLength(1);
  });

  it("fills a freed CENTRE to keep the block compact (#3525 — uniformity beats keeping (0,0) reserved)", () => {
    // Under direction-first (#3367) the freed anchor cell was left empty so a directional node wouldn't
    // 'steal' it. Uniformity-first fills it: leaving a hole in the middle of the block is exactly the
    // sparseness this change removes. The two morphs end up a gap-free 2×1.
    let ps = rooted();
    ps = place(ps, "west", -900, 0);                     // (-1,0)
    ps = releaseCell(ps, "root");                        // the anchor's own morph closed; (0,0) is free
    ps = place(ps, "east", 900, 0);
    const open = ps.filter((p) => p.nodeId !== "root");
    expect(blockShape(open)).toMatchObject({ maxDim: 2, holes: 0 });
    expect(open.some((p) => p.col === 0 && p.row === 0)).toBe(true); // the gap got filled
  });

  it("but the ANCHOR node itself (zero delta) takes the centre back when it re-opens", () => {
    let ps = rooted();
    ps = place(ps, "west", -900, 0);
    ps = releaseCell(ps, "root");
    ps = place(ps, "root", 0, 0);
    expect(cellOf(ps, "root")).toEqual({ col: 0, row: 0 });
  });

  it("does not mutate its input", () => {
    const ps = rooted();
    place(ps, "west", -900, 0);
    expect(ps).toEqual([{ nodeId: "root", col: 0, row: 0 }]);
  });
});

describe("releaseCell / occupants (#3361)", () => {
  it("drops one placement and leaves the others exactly where they were", () => {
    let ps = rooted();
    ps = place(ps, "west", -900, 0);
    ps = place(ps, "east", 900, 0);
    const westCell = cellOf(ps, "west");
    ps = releaseCell(ps, "east");
    expect(occupants(ps)).toEqual(["root", "west"]);
    expect(cellOf(ps, "west")).toEqual(westCell);        // no reflow — a terminal being read must not jump
  });

  it("releasing an absent node changes nothing, and does not mutate", () => {
    const ps = rooted();
    expect(releaseCell(ps, "zzz")).toEqual(ps);
    expect(ps).toHaveLength(1);
  });

  it("occupants lists the node ids in placement order", () => {
    expect(occupants(place(rooted(), "west", -900, 0))).toEqual(["root", "west"]);
    expect(occupants([])).toEqual([]);
  });
});

describe("unionRects (#3361 — the graph parts around ONE region)", () => {
  it("is null with nothing open, so the neighbours snap back", () => {
    expect(unionRects([])).toBeNull();
  });

  it("returns a single rect unchanged — parting around one morph is unchanged behaviour", () => {
    const r = cellRect(ANCHOR, { col: 0, row: 0 });
    expect(unionRects([r])).toEqual(r);
  });

  it("bounds cells on BOTH sides of the anchor (a negative col extends the region left)", () => {
    const u = unionRects([cellRect(ANCHOR, { col: -1, row: 0 }), cellRect(ANCHOR, { col: 0, row: 0 })])!;
    const o = gridOrigin(ANCHOR);
    expect(u.left).toBe(o.x - (CELL_W + GRID_GAP));
    expect(u.w).toBe(CELL_W * 2 + GRID_GAP);
    expect(u.h).toBe(CELL_H);
  });

  it("spans rows above and below", () => {
    const u = unionRects([cellRect(ANCHOR, { col: 0, row: -1 }), cellRect(ANCHOR, { col: 0, row: 1 })])!;
    expect(u.h).toBe(CELL_H * 3 + GRID_GAP * 2);
  });
});

describe("clampCell (#3361 — a shared cell size, bounded)", () => {
  it("passes a sane size through", () => {
    expect(clampCell(800, 600)).toEqual({ w: 800, h: 600 });
  });

  it("clamps to the resize bounds", () => {
    expect(clampCell(10, 10)).toEqual({ w: CELL_MIN_W, h: CELL_MIN_H });
    expect(clampCell(99999, 99999)).toEqual({ w: CELL_MAX_W, h: CELL_MAX_H });
  });

  it("the default cell is within its own bounds", () => {
    expect(clampCell(DEFAULT_CELL.w, DEFAULT_CELL.h)).toEqual(DEFAULT_CELL);
  });
});

