// #3610 / #4086 — the persisted snapshot must NOT carry a `bsc`-owned library.
//
// Zustand `persist` re-`JSON.stringify`s the whole partialized snapshot on EVERY store write. #3610
// found `components` (~592 KB) riding along on every unrelated tick and freezing the app; #4086 found
// the same shape in `blueprints` (395 KB), `skills` (71 KB), `personas` (33 KB) and `teams` (6 KB) —
// together 96% of a 519 KB file. Each is REPLACED from its own SQLite store at boot, so the persisted
// copy was a second source that could only drift.
//
// These guard that they stay out, and that genuine UI/settings state stays in.
import { describe, it, expect } from "vitest";
import { persistedState, migrateAutoResumeOff } from "@/store/persist";
import { useAppStore } from "@/store";

describe("persistedState — the persist allowlist (#3610)", () => {
  it("does NOT persist any bsc-owned library (each re-hydrates from its store at boot)", () => {
    const snap = persistedState(useAppStore.getState());
    // Paired with the hydrate that owns each one — a field may only be dropped BECAUSE something
    // else restores it, so the pairing is the actual invariant.
    for (const [field, owner] of [
      ["components", "hydrateComponents"],
      ["blueprints", "store/index.ts blueprint list --full"],
      ["skills", "hydrateSkills"],
      ["skillGroups", "hydrateSkills"],
      ["personas", "hydratePersonas"],
      ["teams", "hydrateOrgs"],
    ]) {
      expect(field in snap, `${field} must stay out of persist — ${owner} restores it`).toBe(false);
    }
  });

  it("a fat bsc-owned library added to the store does NOT grow the persisted snapshot (#4086)", () => {
    // The generalization of the #3610 proof: the heavy libraries no longer ride along on every write.
    const before = JSON.stringify(persistedState(useAppStore.getState())).length;
    const fat = (n: number) => Array.from({ length: n }, (_, i) => ({ id: `x${i}`, body: "y".repeat(4000) }));
    useAppStore.setState({ blueprints: fat(100) as never, skills: fat(30) as never, personas: fat(20) as never });
    expect(JSON.stringify(persistedState(useAppStore.getState())).length).toBe(before);
  });

  it("a full 600 KB component library added to the store does NOT grow the persisted snapshot", () => {
    // The direct proof of the fix, independent of any seed sizes: inject a fully-hydrated library and
    // show the serialized snapshot is byte-for-byte unchanged — i.e. the heavy blob no longer rides
    // along on every write. Before the fix this delta was ~600 KB per write.
    const before = JSON.stringify(persistedState(useAppStore.getState())).length;
    const fatLibrary = Array.from({ length: 154 }, (_, i) => ({ id: `c${i}`, srcText: "x".repeat(4000) }));
    useAppStore.setState({ components: fatLibrary as never });
    const after = JSON.stringify(persistedState(useAppStore.getState())).length;
    expect(after).toBe(before);
    expect("components" in persistedState(useAppStore.getState())).toBe(false);
  });

  it("still persists genuine UI + settings + library state (not an over-broad deletion)", () => {
    const snap = persistedState(useAppStore.getState());
    // A representative field from every domain that MUST survive a restart.
    for (const key of [
      "activeWorkspace", "tabs", "keybindings",           // shell / console UI
      "githubToken", "githubState",                        // github
      "planFleet", "planStages",                           // planner
      "kits", "kitUsage", "kitDispatches",                 // kit state (kept: small caches + durable queue)
    ]) {
      expect(key in snap).toBe(true);
    }
  });

  it("returns a plain projection, not the whole store (no store methods leak in)", () => {
    const snap = persistedState(useAppStore.getState()) as Record<string, unknown>;
    expect(typeof snap.setWorkspace).toBe("undefined");
    expect(typeof snap.navigate).toBe("undefined");
  });
});

// #restart-does-not-resume-sessions — the v1→v2 flip that actually reaches existing installs.
describe("migrateAutoResumeOff (persist v1 → v2)", () => {
  it("turns a persisted `true` OFF on the upgrade — the case every existing install is in", () => {
    // This is the whole point of the migration. `autoResumeClaude` defaulted TRUE, so the persisted
    // snapshot carries an explicit `true` that is rehydrated OVER the new default — moving the default
    // alone would have left every affected install auto-resuming exactly as before.
    expect(migrateAutoResumeOff({ autoResumeClaude: true }, 1).autoResumeClaude).toBe(false);
  });

  it("leaves an already-off install alone", () => {
    expect(migrateAutoResumeOff({ autoResumeClaude: false }, 1).autoResumeClaude).toBe(false);
  });

  it("does NOT re-flip a deliberate re-enable — it is one-time, keyed on the upgrade", () => {
    // The setting survives so it can be switched back on. If this ran on every load, turning it on in
    // Settings would silently revert at the next restart and read as the toggle being broken.
    expect(migrateAutoResumeOff({ autoResumeClaude: true }, 2).autoResumeClaude).toBe(true);
    expect(migrateAutoResumeOff({ autoResumeClaude: true }, 3).autoResumeClaude).toBe(true);
  });

  it("tolerates a snapshot that never had the field", () => {
    expect(migrateAutoResumeOff({}, 1)).toEqual({});
  });
});

// ── the role must be as durable as everything derived from it ────────────────────────────────────
//
// `a-fleet-pane-comes-back-uncaged-after-an-app-restart`. `paneRoles` and `panePersonas` were the
// only pane-identity fields left OUT of the allowlist, while every value derived from the role —
// the profile, the write globs, the flow, the repo, the stream, the cwd — was persisted beside
// them. After a restart `paneRole()` resolved undefined, `sandboxPlanFor` computed backend "none",
// and a fleet pane relaunched on the host with no cage and no role gate. MEASURED: a director came
// back as `claude --model sonnet` with `/proc/<pid>/ns/mnt` equal to the host's.
//
// A studio pane survived the same restart caged, which is what hid this: `paneRole()` falls back to
// `studioRoleForPaneId`, so a studio role is derivable from the pane id. A fleet role is not.

describe("persistedState — a pane's isolation survives a restart", () => {
  it("persists the ROLE, not only the things derived from it", () => {
    const snap = persistedState(useAppStore.getState());
    // The pairing IS the invariant: each derived field is only meaningful alongside the role that
    // produced it, so persisting one without the other is what made the set incoherent.
    for (const derived of ["paneProfiles", "paneRoleGlobs", "paneFlows", "paneRepos"]) {
      expect(derived in snap, `${derived} is persisted, so the role that produced it must be too`).toBe(true);
    }
    expect("paneRoles" in snap, "the role decides whether the pane gets a cage at all").toBe(true);
    expect("panePersonas" in snap, "a persona may narrow the role's floor; losing it widens the session").toBe(true);
  });

  it("carries a fleet pane's role across a persist round-trip", () => {
    // The end-to-end shape of the failure: assign a director, serialize the way zustand does,
    // and read the role back. Undefined here is exactly what produced an uncaged director.
    useAppStore.setState({
      paneRoles: { "network-monitor:director": "director" },
      panePersonas: { "network-monitor:director": "director" },
    } as never);

    const rehydrated = JSON.parse(JSON.stringify(persistedState(useAppStore.getState())));

    expect(rehydrated.paneRoles?.["network-monitor:director"]).toBe("director");
    expect(rehydrated.panePersonas?.["network-monitor:director"]).toBe("director");
  });
});

// ── a chosen provider must be as durable as the model it launches (#175) ─────────────────────────
//
// `paneProviders` and `paneModels` are both in `PANE_KEYED_MAPS`, but only `paneModels` was in this
// allowlist. Every read falls back `paneProviders[paneId] ?? "claude"`, so after a restart a pane KEPT
// the local model it had been given and silently reverted to Claude Code — which cannot run it.
// `fleetStartProject` re-derives a fleet pane's provider through `effectiveHarness` at launch, which is
// why the fleet path never showed this: a manually-chosen pane has nothing to re-derive it from.

describe("persistedState — a pane's chosen provider survives a restart (#175)", () => {
  it("persists paneProviders alongside paneModels", () => {
    const snap = persistedState(useAppStore.getState());
    expect("paneModels" in snap).toBe(true);
    expect("paneProviders" in snap, "paneModels is persisted, so the provider that runs it must be too").toBe(true);
  });

  it("carries a manually-chosen local provider + model across a persist round-trip", () => {
    // The end-to-end shape of the failure: assign a local provider/model to a pane, serialize the
    // way zustand does, and read them back. A provider missing here is exactly what made the pane
    // fall back to "claude" and get handed a model id it cannot run.
    useAppStore.setState({
      paneProviders: { "studio-code:blueprint": "ollama" },
      paneModels: { "studio-code:blueprint": "qwen3.5:9b" },
    } as never);

    const rehydrated = JSON.parse(JSON.stringify(persistedState(useAppStore.getState())));

    expect(rehydrated.paneProviders?.["studio-code:blueprint"]).toBe("ollama");
    expect(rehydrated.paneModels?.["studio-code:blueprint"]).toBe("qwen3.5:9b");
  });
});


// A reaped session must not come back on the next launch (#a-reaped-session-comes-back-on-restart).
describe("dormancy survives a restart", () => {
  it("persists dormantPanes, so only sessions live at shutdown come back", () => {
    const pane = "village-animal-hospital:director";
    // Driven through the REAL action rather than a hand-built snapshot, so this exercises the same
    // path the backend's `pty-reaped` listener takes.
    useAppStore.getState().reapPane(pane);
    expect(useAppStore.getState().dormantPanes[pane]).toBe(true);

    // The layout persists in full, so EVERY pane in `tabs` auto-launches on boot unless something
    // per-pane says otherwise. `endedPanes`/`disabledPanes` already said so; `dormantPanes` did not,
    // which is why seventeen sessions relaunched when two were wanted.
    expect(persistedState(useAppStore.getState()).dormantPanes).toHaveProperty(pane, true);
  });

  it("clears on resume, so a resumed pane is not dormant forever", () => {
    const pane = "twitter-clone-test:api";
    useAppStore.getState().reapPane(pane);
    expect(persistedState(useAppStore.getState()).dormantPanes).toHaveProperty(pane, true);

    useAppStore.getState().resumePane(pane);
    // DELETED, not stored as `false`. This file exists because a persisted blob is re-stringified on
    // every store write; one key per REAPED pane is bounded, one per pane ever seen is not.
    expect(persistedState(useAppStore.getState()).dormantPanes).not.toHaveProperty(pane);
  });
});

// #4088 — the Glance triaged marker moved from app-state.json into projects.db.
//
// The marker gates the ENTIRE Glance network (`filterTriaged`, #2541): an untriaged project does not
// appear at all. Living only in the persisted zustand blob meant no `bsc` command could read or repair
// it, an app-state reset silently emptied the graph, and a missing node could only be diagnosed by
// reading a raw JSON blob — which is exactly what happened to `network-monitor` and `studio-code`.
import { describe, it, expect, vi, beforeEach } from "vitest";

const setDbTriaged = vi.fn();
vi.mock("@/features/planner/list/projectsDbBridge", async (orig) => ({
  ...(await orig<Record<string, unknown>>()),
  setDbTriaged: (...a: unknown[]) => setDbTriaged(...a),
}));

import { useAppStore } from "@/store";
import { persistedState } from "@/store/persist";

beforeEach(() => {
  setDbTriaged.mockReset();
  useAppStore.setState({ triagedProjects: {} });
});

describe("the triaged marker is durable, not a persisted blob (#4088)", () => {
  it("is NOT in the persist allowlist — projects.db owns it now", () => {
    expect("triagedProjects" in persistedState(useAppStore.getState())).toBe(false);
  });

  it("writes through to projects.db when a project is triaged", () => {
    useAppStore.getState().markProjectTriaged("network-monitor");
    expect(setDbTriaged).toHaveBeenCalledWith("network-monitor");
    expect(useAppStore.getState().triagedProjects["network-monitor"]).toBeTypeOf("number");
  });

  it("keeps the FIRST timestamp — re-triaging never rewrites history", () => {
    useAppStore.setState({ triagedProjects: { alpha: 111 } });
    useAppStore.getState().markProjectTriaged("alpha");
    expect(useAppStore.getState().triagedProjects.alpha).toBe(111);
  });

  it("ignores an empty key rather than writing a junk row", () => {
    useAppStore.getState().markProjectTriaged("");
    expect(setDbTriaged).not.toHaveBeenCalled();
    expect(Object.keys(useAppStore.getState().triagedProjects)).toEqual([]);
  });

  it("hydrate UNIONS the db set in without dropping a marker set this session", () => {
    // The upgrade path: a marker that exists only in the pre-#4088 cache must survive hydration, or a
    // project the user already worked disappears from Glance the first time they launch.
    useAppStore.setState({ triagedProjects: { "set-this-session": 999 } });
    useAppStore.getState().hydrateTriaged({ "from-db": 111, "set-this-session": 222 });
    const out = useAppStore.getState().triagedProjects;
    expect(out["from-db"]).toBe(111);
    expect(out["set-this-session"]).toBe(999); // the in-memory marker wins, nothing is lost
  });
});

implementations.code:
// The frontend ↔ persona store bridge (#2094). The desktop Personas library and every live console
// session + the planner share ONE global store (`~/.base-studio-code/personas/<id>.json`), reached
// here — and from a session's own shell — through the SAME `bsc persona …` CLI, over the generic `bsc`
// bridge (#2114). Personas are GLOBAL (no project key) so every call passes `null` as the projectKey.
// This is the only place the personas feature touches Tauri, so the pure model in `persona.ts` stays
// React/Tauri-free.
//
// Source-of-truth: the persona store. The Zustand slice is a write-through cache — `loadPersonas`
// hydrates it on boot (then `reconcilePersonas` re-seeds the packaged built-ins), and each library
// mutation pushes through here. Written verbatim: the store never imposes a schema, so a persona
// round-trips byte-for-byte.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import { log } from "@/shared/lib/core/log";
import type { Persona } from "@/features/personas/lib/persona";

/**
 * Load every persona from the store via `bsc persona list --full`. Returns `null` when the bridge is
 * unreachable (no Tauri host — tests, the web shell, or an old binary) so the caller keeps its seeded
 * in-memory built-ins rather than blanking the library. NOT `bscJson` (its degrade-to-fallback would
 * return an empty array, which would then blank the seeded set).
 */
export async function loadPersonas(): Promise<Persona[] | null> {
  try {
    const out = await bsc(null, ["persona", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<Persona>[];
    // Defensive: keep only well-formed rows (id + name + role), defaulting the rest so an odd file
    // never crashes hydration.
    return (rows ?? [])
      .filter((p): p is Persona => typeof p.id === "string" && !!p.id)
      .map((p) => ({
        id: p.id, name: p.name ?? "Untitled", blurb: p.blurb ?? "",
        role: p.role ?? "reviewer", startPrompt: p.startPrompt ?? "", skills: p.skills ?? [],
        responsibilities: p.responsibilities, model: p.model, pooled: p.pooled, builtin: p.builtin,
        // The CAPABILITY half. Rebuilding a persona field-by-field silently dropped these, so a
        // persona that round-tripped through the app lost its floor — and the next `pushPersona`
        // wrote the floorless copy back over the store. Anything added to `Persona` that matters at
        // launch has to be listed HERE too; the projection is allow-list shaped by design (an odd
        // file must not crash hydration), which makes omission the default failure.
        floor: p.floor, derivesFrom: p.derivesFrom,
      }));
  } catch {
    return null;
  }
}

/** Write-through a persona upsert (`bsc persona set` reads the JSON on stdin). Fire-and-forget; never
 *  throws, so an old bundled `bsc` without the `persona` subcommand degrades to store-only silently. */
export async function pushPersona(persona: Persona): Promise<void> {
  try {
    await bscWrite(null, ["persona", "set"], persona);
  } catch (err) {
    // Deliberately NOT silent any more. This used to swallow everything as "store unreachable —
    // cache-only", which was true for an old binary without the subcommand and WRONG for the case
    // that now exists: the narrow-only floor clamp REFUSING a write. A refused write means the
    // in-memory library and the store disagree about what an agent may do, and the disagreement
    // resolves toward the store at the next launch — so it has to be visible.
    log.warn(`persona push refused for '${persona.id}': ${String(err)}`);
  }
}

/** Write-through a persona removal (`bsc persona remove <id>`). Never throws (see {@link pushPersona}). */
export async function dropPersona(id: string): Promise<void> {
  try { await bscRun(null, ["persona", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

// The personas feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
//
// Registered HERE, inside the feature, because the shell must not reach a feature's internals (#1545)
// and eager-importing them from `app/` would de-lazy the whole feature at boot. The feature's BARREL
// calls this at module load, so the shadow catalogue's `ensurePlatform: () => import("@/features/personas")`
// is what registers them — the same shape `registerAutomationsPlatform` already uses.
//
// These files STAY on disk: registration is not migration. It makes a record that imports them
// loadable, which is the prerequisite for migrating the modules that import THEM.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Persona from "@/features/personas/lib/persona";

let done = false;

/** Register this feature's injected graph-platform modules by the specifiers a record imports. Idempotent. */
export function registerPersonasPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/personas/lib/persona", Persona);
}

// The shadow catalogue registers this feature's graph-platform modules by importing
// `./graphPlatform` DIRECTLY and calling its register function (see `shadowPages.ts`). This barrel
// therefore has NO import-time side effect — it is re-exports only, which is what lets it be a
// record rather than a file that must run to be correct.

// Personas feature (#2094) — the CRUD-able agent-identity library (behavior: start prompt + skills +
// model, over a referenced role). Public API barrel.
export { PersonasPanel } from "@/features/personas/PersonasPanel";
export { PersonaEditor } from "@/features/personas/PersonaEditor";
export { PersonaSummary } from "@/features/personas/PersonaSummary";
export { createPersonasSlice, type PersonasSlice } from "@/features/personas/store";
export { BUILTIN_PERSONAS, blankPersona, personaSlug, reconcilePersonas, type Persona } from "@/features/personas/lib/persona";

// Personas feature store slice (#2094) — the CRUD-able agent-identity library, a WRITE-THROUGH cache
// over the global persona store (`~/.base-studio-code/personas/`, reached via `bsc persona` — see
// personaBridge.ts). The desktop UI, live sessions, and the planner share ONE store. On boot
// `hydratePersonas` loads through the bridge + reconciles the packaged built-ins; every mutation below
// pushes through. The persisted `personas` in app-state is just a fast first-paint cache; hydrate is
// authoritative. Behavior identity only: the ROLE it references (permissions) lives in `sessionRoles.ts`.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import { MODEL_IDS, type ModelId } from "@/app/console/lib/models";
import { BUILTIN_PERSONAS, blankPersona, personaSlug, reconcilePersonas, type Persona } from "@/features/personas/lib/persona";
import { loadPersonas, pushPersona, dropPersona } from "@/features/personas/lib/personaBridge";

export interface PersonasSlice {
  /** The persona library — packaged built-ins (reconciled on load) + user-authored. */
  personas: Persona[];
  /** Hydrate the library from the global persona store on boot (#2094): load via the bridge, reconcile
   *  the packaged built-ins, and push any newly-seeded built-in back so the store has it. No-op (keeps
   *  the seeded set) when the bridge is unreachable — tests, the web shell, or an old binary. */
  hydratePersonas: () => Promise<void>;
  /** Create a user persona (optionally on a given role) and return its new id. */
  addPersona: (role?: SessionRole) => string;
  /** Clone any persona (incl. a built-in) into a new editable user persona; returns the new id. */
  clonePersona: (id: string) => string;
  /** Patch a persona's editable fields (name/blurb/prompt/skills/model/role). Built-ins keep their
   *  builtin identity; only user personas can be deleted. */
  updatePersona: (id: string, patch: Partial<Omit<Persona, "id" | "builtin">>) => void;
  /** Remove a USER persona (built-ins are not deletable — no-op). */
  removePersona: (id: string) => void;
  /** Adopt a persona onto a console PANE (#2094 wire-up): stamp its role (the permission floor),
   *  model, and start prompt onto the pane so the pane's NEXT launch runs as that persona, and mark
   *  perms stale so the "relaunch to apply" nudge shows. Skills are attached to the persona but not
   *  applied here yet (the per-session skill-override path is a refinement). No-op for an unknown id. */
  applyPersonaToPane: (paneId: string, personaId: string) => void;
}

/** Mint a fresh, collision-free user-persona id from a name (or a generic seed). */
function mintPersonaId(existing: Persona[], name: string): string {
  const base = `persona-${personaSlug(name)}`;
  if (!existing.some((p) => p.id === base)) return base;
  let n = 2;
  while (existing.some((p) => p.id === `${base}-${n}`)) n++;
  return `${base}-${n}`;
}

export const createPersonasSlice: StateCreator<AppStore, [], [], PersonasSlice> = (set, get) => ({
  personas: BUILTIN_PERSONAS,

  hydratePersonas: async () => {
    const loaded = await loadPersonas();
    if (!loaded) return; // bridge unreachable — keep the seeded built-ins
    const reconciled = reconcilePersonas(loaded);
    set({ personas: reconciled });
    // Converge the store — the source of truth a session/planner reads — with the reconciled library.
    // Push a built-in that the store lacks (first run / a newly-packaged persona) OR whose stored copy
    // drifted from the packaged prose (the #2185 upgrade path: worker/director seeded empty by an older
    // app now carry their real fleet protocol). User edits are preserved by reconcile, so only genuine
    // drift re-pushes.
    const loadedById = new Map(loaded.map((p) => [p.id, p]));
    for (const p of reconciled) {
      const before = loadedById.get(p.id);
      if (!before || (p.builtin && before.startPrompt !== p.startPrompt)) void pushPersona(p);
    }
  },

  addPersona: (role = "reviewer") => {
    const id = mintPersonaId(get().personas, "new persona");
    const persona = blankPersona(id, role);
    set((s) => ({ personas: [...s.personas, persona] }));
    void pushPersona(persona);
    return id;
  },

  clonePersona: (id) => {
    const src = get().personas.find((p) => p.id === id);
    if (!src) return id;
    const name = `${src.name} copy`;
    const newId = mintPersonaId(get().personas, name);
    const clone: Persona = { ...src, id: newId, name, builtin: false };
    set((s) => ({ personas: [...s.personas, clone] }));
    void pushPersona(clone);
    return newId;
  },

  updatePersona: (id, patch) => {
    let updated: Persona | undefined;
    set((s) => ({
      personas: s.personas.map((p) => {
        if (p.id !== id) return p;
        updated = { ...p, ...patch, id: p.id, builtin: p.builtin };
        return updated;
      }),
    }));
    if (updated) void pushPersona(updated);
  },

  removePersona: (id) => {
    const target = get().personas.find((p) => p.id === id);
    if (!target || target.builtin) return; // built-ins are not deletable
    set((s) => ({ personas: s.personas.filter((p) => p.id !== id) }));
    void dropPersona(id);
  },

  applyPersonaToPane: (paneId, personaId) => {
    const persona = get().personas.find((p) => p.id === personaId);
    if (!persona) return;
    set((s) => ({
      paneRoles: { ...s.paneRoles, [paneId]: persona.role },
      // The persona ITSELF, not just its role. The role alone was lossy: a persona derived from
      // `worker` with a narrowed floor launched with the full worker capability, because the
      // narrowing lives on the persona and only the role name was being stored.
      panePersonas: { ...s.panePersonas, [paneId]: persona.id },
      // Validated, not cast. The persona store is verbatim — `bsc persona set` will write any string
      // — and an unrecognized tier injects no `--model` at all, so blind-casting it would leave the
      // pane menu showing a model the session is not running. The fleet path already validates the
      // same way (`fleetStartProject`); this is the pane-adopt half of it.
      paneModels: persona.model && (MODEL_IDS as readonly string[]).includes(persona.model)
        ? { ...s.paneModels, [paneId]: persona.model as ModelId }
        : s.paneModels,
      paneStartupPromptText: persona.startPrompt
        ? { ...s.paneStartupPromptText, [paneId]: persona.startPrompt }
        : s.paneStartupPromptText,
      // Settings.json (the role gate) is read at session start — flag the pane so it shows the
      // "relaunch to apply" nudge, exactly like a profile edit (#799).
      panePermsStale: { ...s.panePermsStale, [paneId]: true },
    }));
  },
});

