    expect(t).toBeTruthy();
    expect(t.optional).toBe(true);
    expect(t.hasOutputFile).toBe(true);
    expect(t.defaultEnabled).toBe(false);
    expect(t.dependsOn).toEqual(["discovery"]);
  });
});

