/**
 * FNV-1a 32-bit hash — the canonical hash for the planner-sync protocol.
 *
 * Operates on UTF-8 bytes via TextEncoder for cross-platform parity: Rust
 * hashes &str bytes directly (UTF-8); JS must encode first. The Math.imul +
 * >>> 0 form is the only correct 32-bit overflow pattern in JavaScript (a plain
 * `*` promotes to float64 and loses precision past 53 bits; Math.imul gives the
 * correct low 32 bits of the integer product).
 *
 * Pinned test vectors in src/lib/plannerCore.fixtures.json (fnv1a32 section).
 */
export function fnv1a32(s: string): number {
  let h = 0x811c9dc5;
  const bytes = new TextEncoder().encode(s);
  for (const b of bytes) {
    h ^= b;
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h;
}

/** Lowercase 8-char hex representation of an fnv1a32 result. */
export function fnv1a32hex(s: string): string {
  return fnv1a32(s).toString(16).padStart(8, "0");
}

export { fnv1a32, fnv1a32hex } from "@/features/planner/lib/plannerCore/hash";
export type { CanonicalFile, PlanManifest, CanonicalSectionState, PlanMeta } from "@/features/planner/lib/plannerCore/types";
export { buildManifest, diffManifests } from "@/features/planner/lib/plannerCore/manifest";
export type { ManifestDiff } from "@/features/planner/lib/plannerCore/manifest";
export { projectId, phaseId, issueId, nodeId } from "@/features/planner/lib/plannerCore/ids";

import { fnv1a32hex } from "@/features/planner/lib/plannerCore/hash";
import type { CanonicalFile, PlanManifest } from "@/features/planner/lib/plannerCore/types";

/** Build a manifest from a list of canonical files (order-independent). */
export function buildManifest(projectId: string, files: CanonicalFile[]): PlanManifest {
  const map: Record<string, string> = {};
  for (const f of files) {
    map[f.relpath] = fnv1a32hex(f.content);
  }
  return { projectId, files: map };
}

export interface ManifestDiff {
  /**
   * Relpaths where the remote differs from (or is absent in) the local manifest.
   * These are the files the local peer should request from remote to catch up.
   */
  pull: string[];
  /** Relpaths present only in the local manifest (remote doesn't have them yet). */
  localOnly: string[];
}

/**
 * Diff two manifests to find which files need to move in each direction.
 * `pull` = files to request from remote (changed or absent locally).
 * `localOnly` = files present locally but absent in remote.
 * Both lists are sorted for determinism.
 */
export function diffManifests(local: PlanManifest, remote: PlanManifest): ManifestDiff {
  const pull: string[] = [];
  const localOnly: string[] = [];
  const localSet = new Set(Object.keys(local.files));

  for (const [relpath, remoteHash] of Object.entries(remote.files)) {
    if (local.files[relpath] !== remoteHash) pull.push(relpath);
    localSet.delete(relpath);
  }
  for (const relpath of localSet) localOnly.push(relpath);

  return { pull: pull.sort(), localOnly: localOnly.sort() };
}

/** One file in the canonical plan representation — the atomic sync unit. */
export interface CanonicalFile {
  /** Relative path within the project hub (e.g. "goal.md", "phases.json"). */
  relpath: string;
  /** Raw text content (UTF-8). */
  content: string;
}

/**
 * Compact reconciliation payload: relpath → lowercase 8-char hex FNV-1a 32-bit hash.
 * Both peers exchange this to discover which files differ without transferring content.
 */
export interface PlanManifest {
  /** Stable project identifier (e.g. "proj-bf9cf968"). */
  projectId: string;
  /** Map from relpath to content hash. */
  files: Record<string, string>;
}

/**
 * Canonical section-state vocabulary (the unified cross-device spec).
 *
 * Desktop vocab map:
 *   pending   → surfaced   (Claude has written the section; user hasn't confirmed)
 *   drafted   → drafted    (Claude has drafted it; in-progress)
 *   confirmed → confirmed  (User explicitly confirmed)
 *
 * _skipped.md entries are individually mapped to "skipped".
 *
 * See plannerCore.fixtures.json (sectionStates section) for the pinned mapping.
 */
export type CanonicalSectionState = "surfaced" | "drafted" | "confirmed" | "skipped";

/** Metadata stored in plan.json — stable identity and per-section states. */
export interface PlanMeta {
  /** Stable "proj-{hex}" identifier (hash-derived from the sanitized title). */
  projectId: string;
  /** Human-readable project title (the sanitized form). */
  title: string;
  /** Per-section canonical states, keyed by section key (e.g. "goal", "scope"). */
  sectionStates: Record<string, CanonicalSectionState>;
}

// The planner feature's PUBLIC API — domain only (`delete-the-planner-ui-keep-the-planner`).
//
// This barrel used to export the ProjectsWorkspace and mount the whole planner screen. That screen is
// gone: planning is the director's job now — the architect runs discovery with the user, then creates a
// director that completes the plan and designs its team. What is NOT gone is the planner's domain, and
// this file is the boundary that keeps it reachable.
//
// EVERY EXPORT HERE IS REACT-FREE, and that is the invariant worth stating: eleven modules outside this
// feature import through this barrel (#1545 lets them reach nothing else), so a UI export creeping back
// in would pull React into the store's type graph and into Glance. The rule is mechanical — if it
// imports react, it does not belong here.
//
// The functions the screen used to drive are all reachable headlessly now: `bsc plan` for the plan,
// `bsc publish` for the GitHub structure, `bsc fleet start` for the fleet.

// The canonical file shape the tunnel reads for its payload parity harness.
export type { CanonicalFile } from "@/features/planner/lib/plannerCore";
// The `plan` store_state builder (#3760) — the plan domain is planner-published, not projected by
// useStoreProjector, so the tunnel harness reaches it here like every other domain.
export { buildPlanBoardPayload, type PlanBoardPayload } from "@/features/planner/session/planBoardProjection";
// Gist install/publish — extension bundles, shared with the studio + designs share flows.
export {
  validateManifest, wrapExtension, encodeShareCode, decodeShareCode,
  type ExtensionManifest, type ValidateResult,
} from "@/features/planner/lib/gist/manifest";
export { installFromGist, publishGist } from "@/features/planner/lib/gist/gist";
// The project APPLICATION ARCHITECTURE (#3802/#3786) — Glance surfaces it on each project node, and
// reaches the TYPE through the barrel rather than the deep `lib/classifyConfig` path.
export type { AppType } from "@/features/planner/lib/classifyConfig";
// Fleet flow rules — the console launch reads them to scope a worker's git/gh permissions.
export { flowPermissionRules, flowGrantedPushCommands } from "@/features/planner/fleet/flowPermissions";
// The durable projects-DB bridge (#2995/#3966) — the app shell's boot migration and Glance's project
// list both go through here, not through the persisted draft cache.
export { addDbProject, setDbTriaged } from "@/features/planner/list/projectsDbBridge";
export { listDbProjects, type DbProject } from "@/features/planner/list/projectsDbBridge";
// Director drive — the app's director pump reads these to decide when to nudge a stalled fleet.
export {
  resolveDirectorDrive, askKey,
  requestKey,
  shouldRemind,
  ASK_REMINDER_MS, DEFAULT_HEARTBEAT_MS, INJECT_COOLDOWN_MS,
} from "@/features/planner/fleet/directorDrive";

// Planner introduction kickoff selection (#1240). Pure helpers so mode selection + pitch
// composition are unit-testable; the Rust `planner_intro_prompt` command returns the per-mode
// template text, and the launch bakes the composed result as a fresh-only startup prompt.

import type { BlueprintMode } from "@/features/planner/stages/blueprints";

export type PlannerIntroMode = "new" | "existing";

/**
 * Whether the planner should take the "existing repos" orientation — for BOTH the intro greeting
 * and the generated CLAUDE.md spec (`setup_workspaces`). True when the project is already saved OR
 * the blueprint's lifecycle is `operate` (transform / harden / maintain — work against existing
 * repos). #1286: keying off the blueprint **mode**, not just save-state, fixes an operate-mode
 * project on a fresh draft — or right after a greenfield→transform lifecycle switch — being
 * mis-oriented as a new greenfield one. (A saved greenfield project is unchanged: still "existing".)
 */
export function plannerTreatAsExisting({ isSaved, mode }: { isSaved: boolean; mode?: BlueprintMode }): boolean {
  return isSaved || mode === "operate";
}

/** Pick the intro mode from the session signals — mirrors the planner.rs CLAUDE.md branch
 *  (an existing project, else a new greenfield project). */
export function plannerIntroMode({ isExisting }: { isExisting: boolean }): PlannerIntroMode {
  return isExisting ? "existing" : "new";
}

/** Compose the startup prompt: the mode's intro, plus the user's pitch for a NEW project so the
 *  planner acknowledges it instead of asking what they're building, plus (for the one-shot
 *  `bsc-agent` runtime) the FIRST active stage's directive so a weak local model actually BEGINS the
 *  stage instead of greeting and then waiting to be advanced (#qwen). An empty intro (e.g. the
 *  command failed) yields `""` so the launch falls back to its plain `initCmd`.
 *
 *  `firstStageDirective` is omitted for Claude Code, which receives each stage's directive via the
 *  app's runtime injection as it advances — there the greeting is deliberately greeting-only. */
export function composePlannerIntro(
  intro: string, mode: PlannerIntroMode, pitch: string, firstStageDirective?: string,
): string {
  if (!intro.trim()) return "";
  let out = intro;
  if (mode === "new" && pitch.trim()) {
    out += `\n\n---\nThe user has already shared this pitch — acknowledge it and reflect your understanding back instead of asking what they're building:\n\n${pitch.trim()}`;
  }
  if (firstStageDirective?.trim()) {
    out += `\n\n---\nThe app drives this plan one stage at a time. Your FIRST stage is below — after you greet the user, BEGIN it now (don't wait to be advanced):\n\n${firstStageDirective.trim()}`;
  }
  return out;
}

