import { describe, it, expect } from "vitest";
import { plannerIntroMode, composePlannerIntro, plannerTreatAsExisting } from "@/features/planner/session/plannerIntro";

describe("plannerIntro — mode selection (#1240)", () => {
  it("existing project → existing, else new", () => {
    expect(plannerIntroMode({ isExisting: true })).toBe("existing");
    expect(plannerIntroMode({ isExisting: false })).toBe("new");
  });
});

describe("plannerTreatAsExisting — orientation follows blueprint mode (#1286)", () => {
  it("an operate-mode blueprint is 'existing' even on a fresh draft (the switch bug)", () => {
    // Draft (not saved) + operate lifecycle (transform/harden/maintain) → existing orientation.
    expect(plannerTreatAsExisting({ isSaved: false, mode: "operate" })).toBe(true);
  });
  it("a create-mode draft stays a new greenfield project", () => {
    expect(plannerTreatAsExisting({ isSaved: false, mode: "create" })).toBe(false);
    expect(plannerTreatAsExisting({ isSaved: false, mode: undefined })).toBe(false); // absent ⇒ create
  });
  it("a saved project stays 'existing' regardless of mode (no behavior change for saved projects)", () => {
    expect(plannerTreatAsExisting({ isSaved: true, mode: "create" })).toBe(true);
    expect(plannerTreatAsExisting({ isSaved: true, mode: "operate" })).toBe(true);
  });
  it("composes with plannerIntroMode: a just-switched draft transform gets the existing intro", () => {
    const treat = plannerTreatAsExisting({ isSaved: false, mode: "operate" });
    expect(plannerIntroMode({ isExisting: treat })).toBe("existing");
  });
});

describe("plannerIntro — compose (#1240)", () => {
  it("appends the pitch only for a new project that has one", () => {
    const composed = composePlannerIntro("INTRO", "new", "build a todo app");
    expect(composed).toContain("INTRO");
    expect(composed).toContain("build a todo app");
  });

  it("ignores the pitch for non-new modes and when blank", () => {
    expect(composePlannerIntro("INTRO", "existing", "build a todo app")).toBe("INTRO");
    expect(composePlannerIntro("INTRO", "new", "   ")).toBe("INTRO");
  });

  it("an empty intro yields an empty prompt (launch falls back to initCmd)", () => {
    expect(composePlannerIntro("", "new", "x")).toBe("");
    expect(composePlannerIntro("   ", "existing", "")).toBe("");
  });

  it("bakes the first stage directive (bsc-agent) so the planner begins instead of waiting (#qwen)", () => {
    const composed = composePlannerIntro("INTRO", "existing", "", "Drive the discovery checklist; create goal.md, scope.md.");
    expect(composed).toContain("INTRO");
    expect(composed).toContain("BEGIN it now");
    expect(composed).toContain("Drive the discovery checklist");
  });

  it("composes the pitch AND the first-stage directive together for a new project", () => {
    const composed = composePlannerIntro("INTRO", "new", "build a todo app", "Start discovery now.");
    expect(composed).toContain("build a todo app");
    expect(composed).toContain("Start discovery now.");
  });

  it("omits the directive block when none is passed (Claude Code path is unchanged)", () => {
    expect(composePlannerIntro("INTRO", "existing", "")).toBe("INTRO");
    expect(composePlannerIntro("INTRO", "existing", "", "   ")).toBe("INTRO"); // blank directive ignored
  });
});

implementations.code:
// plannerLaunch — how the PLANNER session launches under the selected LLM provider / fleet harness.
//
// The planner is plan-only (role gate #219) and, like the fleet, can run on either Claude Code or the
// model-agnostic `bsc-agent` runtime (#1078). When the effective harness is bsc-agent — because the
// user chose it on the fleet-harness toggle; the PROVIDER no longer decides this, see
// `effectiveHarness` — the planner
// launches `bsc-agent` with the SAME context, prompt, state, and permissions a Claude planner gets:
//   • context — `bsc-agent` composes its system prompt from the planning dir's CLAUDE.md chain +
//     CLAUDE.local.md + skills (compose_system), identical to what Claude Code loads.
//   • state   — the per-session BSC_* env (plan.db / data.db / skills.db + their CLIs) is wired by
//     pty_create's wire_bsc_env for every pane regardless of harness.
//   • prompt  — the planner intro is baked as the agent's task (BscAgentAdapter.launch_command).
//   • perms   — BSC_AGENT_PERMS carries the plan-only role gate (its analogue of the claude
//     settings.json deny rules), and BSC_AGENT_MCP the planner's MCP servers.
//
// Pure + React-free so both planner launch sites (initial mount + restart) share one definition.

import { resolveLlmConfig, bscAgentEnv, effectiveHarness } from "@/shared/lib/core/llmConfig";
import { roleCapability, bscAgentPerms, sessionScopes } from "@/shared/lib/session/sessionRoles";
import { resolveAllInstalledMcp, toBscAgentMcp, toSessionPayloads } from "@/features/mcp";
import type { AppStore } from "@/store/types";

/** The harness-dependent fields of the planner's `pty_create` call. */
export interface PlannerLaunch {
  /** Console provider id passed to pty_create — `"bsc-agent"` selects the runtime + its session
   *  file; `undefined` keeps Claude Code, the default. */
  providerId?: string;
  /** The fallback init command (used only if no startup prompt is baked). */
  initCmd: string;
  /** GH token env + the planner role's `BSC_SCOPES` store-scope doc (#2470) plus, for bsc-agent,
   *  the BSC_AGENT_* provider/model/base-url/perms/MCP vars. */
  env: Record<string, string>;
  /** Whether the intro is suppressed on a resumed session (#1240). Claude keeps the fresh-only
   *  greeting; bsc-agent (a one-shot agent loop, not a REPL) always bakes the intro as its task. */
  startupPromptFreshOnly: boolean;
  /** Request conversation resume — the backend ANDs it with "history actually exists", so a fresh
   *  project is unaffected (Claude resumes via `--continue`; bsc-agent via its $BSC_AGENT_SESSION
   *  continuity). */
  continueSession?: boolean;
}

/**
 * Resolve how the planner session launches for the current provider + fleet harness.
 *
 * @param s      the app-store snapshot (reads `llmProvider`, `fleetHarness`, `mcpServers`)
 * @param ghEnv  the GitHub token env already resolved for the planner (`GH_TOKEN` / `GITHUB_TOKEN`)
 */
export function plannerLaunchConfig(s: AppStore, ghEnv: Record<string, string>): PlannerLaunch {
  const harness = effectiveHarness(s.llmProvider, s.fleetHarness ?? "claude");
  // Store scopes (#2470, defense-in-depth): the planner role's per-store access tiers (ui: read) for
  // the store CLIs' runtime write check — on BOTH harnesses (the launch-time deny rules are the
  // boundary; this guards accidents + the bsc-agent runtime).
  const scopes = JSON.stringify(sessionScopes(roleCapability("director")));
  if (harness !== "bsc-agent") {
    return {
      providerId: undefined,
      initCmd: "claude --continue 2>/dev/null || claude",
      env: { ...ghEnv, BSC_SCOPES: scopes },
      startupPromptFreshOnly: true,
      // Defensive (#2396): request resume explicitly. With the fresh-only intro guard a baked prompt
      // only ever fires when there's no history (where resume is a no-op), but if a caller ever bakes
      // a prompt onto a cwd WITH history this resumes it instead of silently forking a fresh session.
      continueSession: true,
    };
  }
  // The planner sees every installed MCP server (#1054); pass them to the runtime as $BSC_AGENT_MCP.
  const plannerMcp = toSessionPayloads(resolveAllInstalledMcp(s.mcpServers), []).mcp;
  const bscMcp = toBscAgentMcp(plannerMcp);
  const env: Record<string, string> = {
    ...ghEnv,
    ...bscAgentEnv(resolveLlmConfig(s)),
    // Plan-only role gate (#219) for the bsc-agent runtime: deny code writes + the mutating git/gh
    // commands the planner role forbids — the runtime's analogue of the claude settings.json denies.
    BSC_AGENT_PERMS: JSON.stringify(bscAgentPerms(roleCapability("director"))),
    BSC_SCOPES: scopes,
  };
  if (bscMcp.length > 0) env.BSC_AGENT_MCP = JSON.stringify(bscMcp);
  return {
    providerId: "bsc-agent",
    initCmd: "bsc-agent", // fallback only; the baked intro prompt always wins
    env,
    startupPromptFreshOnly: false,
    continueSession: true,
  };
}

