import { describe, it, expect } from "vitest";
import { plannerLaunchConfig } from "@/features/planner/session/plannerLaunch";
import type { AppStore } from "@/store/types";

// Minimal store snapshot — plannerLaunchConfig reads only the LLM-config + harness + MCP fields.
function store(over: Partial<AppStore>): AppStore {
  return {
    llmProvider: "anthropic",
    llmModel: "claude-sonnet-4-6",
    claudeApiKey: "ant-key",
    openaiKey: "",
    geminiKey: "",
    localBaseUrl: "http://localhost:11434/v1",
    fleetHarness: "claude",
    mcpServers: [],
    ...over,
  } as unknown as AppStore;
}

const GH = { GH_TOKEN: "t", GITHUB_TOKEN: "t" };

describe("plannerLaunchConfig", () => {
  it("launches Claude Code for anthropic + the default harness", () => {
    const l = plannerLaunchConfig(store({}), GH);
    expect(l.providerId).toBeUndefined();
    expect(l.initCmd).toContain("claude");
    expect(l.startupPromptFreshOnly).toBe(true);
    // Defensive (#2396): resume is requested explicitly; the backend ANDs it with real history.
    expect(l.continueSession).toBe(true);
    // No BSC_AGENT_* env for a Claude planner — just the GH tokens + the store-scope doc (#2470).
    expect(l.env).toEqual({ ...GH, BSC_SCOPES: JSON.stringify({ ui: "read" }) });
  });

  it("carries the planner's BSC_SCOPES store-scope doc on both harnesses (#2470)", () => {
    // The runtime write check the store CLIs read: the planner may USE the component kit (`bsc ui`
    // reads) but its mutating verbs refuse — on Claude and on the bsc-agent runtime alike.
    const claude = plannerLaunchConfig(store({}), GH);
    expect(JSON.parse(claude.env.BSC_SCOPES)).toEqual({ ui: "read" });
    const agent = plannerLaunchConfig(store({ llmProvider: "ollama" }), GH);
    expect(JSON.parse(agent.env.BSC_SCOPES)).toEqual({ ui: "read" });
  });

  // THE TOGGLE IS THE SECOND SWITCH, and it has to be. This read "no second toggle" and passed
  // `fleetHarness: "claude"` to prove the provider overrode it — which is precisely what put every
  // studio, architect and un-designated fleet pane on the local model as soon as ONE project was
  // designated local. The provider still supplies the MODEL; the toggle decides the harness.
  it("runs the planner on bsc-agent + Ollama when the fleet harness selects it", () => {
    const l = plannerLaunchConfig(store({ llmProvider: "ollama", llmModel: "llama3", fleetHarness: "bsc-agent" }), GH);
    expect(l.providerId).toBe("bsc-agent");
    expect(l.env.BSC_AGENT_PROVIDER).toBe("ollama");
    expect(l.env.BSC_AGENT_MODEL).toBe("llama3");
    expect(l.env.BSC_AGENT_BASE_URL).toBe("http://localhost:11434/v1");
    expect(l.env.GH_TOKEN).toBe("t"); // GH env preserved
    // bsc-agent is a one-shot loop, not a REPL → always bake the intro + request resume.
    expect(l.startupPromptFreshOnly).toBe(false);
    expect(l.continueSession).toBe(true);
  });

  // A LOCAL PROVIDER DOES NOT CONSCRIPT THE PLANNER. This case was unreachable while the provider
  // overrode the toggle, and it is the one the maintainer actually runs: a local model configured so
  // that individually designated panes can reach it, with everything else on Claude Code.
  it("leaves the planner on claude when the toggle says claude, whatever the provider is", () => {
    const l = plannerLaunchConfig(store({ llmProvider: "ollama", llmModel: "llama3", fleetHarness: "claude" }), GH);
    // `undefined` IS claude — the field only ever names a non-default harness (see `PlannerLaunch`).
    expect(l.providerId).toBeUndefined();
  });

  it("carries the plan-only role gate to the bsc-agent runtime via BSC_AGENT_PERMS", () => {
    const l = plannerLaunchConfig(store({ llmProvider: "ollama", fleetHarness: "bsc-agent" }), GH);
    const perms = JSON.parse(l.env.BSC_AGENT_PERMS);
    // Planner is plan-only: writes are SCOPED to the plan-file globs (not arbitrary code), and the
    // mutating git/gh commands are denied — the runtime's analogue of the claude role gate.
    expect(Array.isArray(perms.write_globs)).toBe(true);
    expect(perms.write_globs.length).toBeGreaterThan(0);
    expect(Array.isArray(perms.deny_bash)).toBe(true);
    expect(perms.deny_bash.length).toBeGreaterThan(0);
  });

  it("also runs on bsc-agent when the user explicitly chose it for a cloud provider", () => {
    const l = plannerLaunchConfig(store({ llmProvider: "openai", llmModel: "gpt-5", openaiKey: "k", fleetHarness: "bsc-agent" }), GH);
    expect(l.providerId).toBe("bsc-agent");
    expect(l.env.BSC_AGENT_PROVIDER).toBe("openai");
    expect(l.env.BSC_AGENT_API_KEY).toBe("k");
  });
});

implementations.code:
// plannerSandbox (#1988) — the opt-in WSL2-sandbox launch overrides shared by BOTH planner launch
// sites (the initial mount in usePlannerTerminal AND the restart in usePlanningSession), so they can't
// drift apart (the restart path used to skip the sandbox entirely). When the sandbox toggle is on AND
// the planner runs on bsc-agent — the only runtime baked into the sealed distro — the hub is relocated
// into the distro (setup_sandbox_hub) and the session spawns INSIDE it; otherwise it's the host launch.
//
// The launch reads the toggle only at spawn time, so flipping it while a planner is OPEN does nothing
// to the live session — Planning.tsx restarts the open planner on a flip so it converts.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";

/** Whether a planner `pty_create` should spawn into the sandbox: the toggle is on, the harness is
 *  bsc-agent (baked into the distro), and there's a host hub to relocate. Pure — unit-testable. */
export function wantsSandboxLaunch(
  sandboxConsoles: boolean,
  providerId: string | undefined,
  planningDir: string,
): boolean {
  return sandboxConsoles && providerId === "bsc-agent" && !!planningDir;
}

/** Resolve the `cwd` + `wslDistro` for a planner `pty_create`. When the sandbox is wanted, relocate the
 *  hub into the distro (`setup_sandbox_hub`) and spawn at the distro cwd; on failure — or when not
 *  wanted — fall back to the host hub (no distro). Reads the current `sandboxConsoles` from the store. */
export async function resolvePlannerSandbox(
  providerId: string | undefined,
  planningDir: string,
  projectKey: string,
): Promise<{ cwd: string; wslDistro: string | undefined }> {
  const wants = wantsSandboxLaunch(useAppStore.getState().sandboxConsoles, providerId, planningDir);
  const sandboxHub = wants
    ? await safeInvoke<string | null>(
        "setup_sandbox_hub", { key: projectKey }, null,
        (e: unknown) => console.error("sandbox hub setup failed (falling back to host):", e),
      )
    : null;
  return { cwd: sandboxHub ?? planningDir, wslDistro: sandboxHub ? "bsc-agent-sandbox" : undefined };
}

