    const issues: PlanIssue[] = [
      { ref: "S1", title: "schema", acceptance: [], owns: [], dependsOn: [], labels: [], stream: "schema" },
      { ref: "A1", title: "auth", acceptance: [], owns: [], dependsOn: ["S1"], labels: [], stream: "auth" },
