import { describe, it, expect } from "vitest";
import { recoverIssue, recoverIssues, type GitHubIssueLike } from "@/features/planner/issues/recoverIssues";
import { renderIssueBody, type PlanIssue } from "@/features/planner/issues/planIssues";

const issue = (p: Partial<PlanIssue>): PlanIssue => ({
  ref: "F1", title: "Do the thing", acceptance: [], owns: [], dependsOn: [], labels: [], ...p,
});

/** Build the GitHub issue a publish would create from a PlanIssue (body + stream label). */
const published = (iss: PlanIssue, number: number, state: "open" | "closed"): GitHubIssueLike => ({
  number,
  title: iss.title,
  body: renderIssueBody(iss),
  state,
  labels: [
    ...iss.labels.map((name) => ({ name })),
    ...(iss.stream ? [{ name: `stream:${iss.stream}` }] : []),
  ],
});

describe("recoverIssue (GitHub → plan.db)", () => {
  it("round-trips a published issue back to its PlanIssue (lossless via the ref marker)", () => {
    const original = issue({
      ref: "auth-login",
      title: "Add POST /sessions",
      acceptance: ["returns 200 on valid creds", "sets the session cookie"],
      owns: ["src/auth/", "src/api/sessions.ts"],
      dependsOn: ["schema", "auth-config"],
      labels: ["scope:core", "area:api"],
      stream: "auth",
      body: "Prose context about the endpoint.",
    });
    const recovered = recoverIssue(published(original, 42, "open"), "acme/web");

    expect(recovered.ref).toBe("auth-login");                 // from the hidden marker, not #42
    expect(recovered.title).toBe("Add POST /sessions");
    expect(recovered.acceptance).toEqual(original.acceptance);
    expect(recovered.owns).toEqual(original.owns);            // backticks stripped
    expect(recovered.dependsOn).toEqual(original.dependsOn);  // the refs survive — the whole point
    expect(recovered.labels).toEqual(["scope:core", "area:api"]); // stream label excluded
    expect(recovered.stream).toBe("auth");
    expect(recovered.body).toBe("Prose context about the endpoint.");
    expect(recovered.repo).toBe("acme/web");
    expect(recovered.status).toBe("open");
  });

  it("maps a closed issue to verified and an open one to open", () => {
    const iss = issue({ ref: "F1", title: "x" });
    expect(recoverIssue(published(iss, 1, "closed"), "a/b").status).toBe("verified");
    expect(recoverIssue(published(iss, 1, "open"), "a/b").status).toBe("open");
  });

  it("falls back to #<number> when an issue has no ref marker (not planner-published)", () => {
    const gh: GitHubIssueLike = { number: 7, title: "Hand-filed bug", body: "just prose", state: "open" };
    const r = recoverIssue(gh, "a/b");
    expect(r.ref).toBe("#7");
    expect(r.body).toBe("just prose");
    expect(r.acceptance).toEqual([]);
  });

  it("recovers a bare-string label shape", () => {
    const gh: GitHubIssueLike = { number: 3, title: "t", state: "open", labels: ["scope:core", "stream:ui"] };
    const r = recoverIssue(gh, "a/b");
    expect(r.stream).toBe("ui");
    expect(r.labels).toEqual(["scope:core"]);
  });
});

describe("recovered issues carry their GitHub identity", () => {
  it("records the issue number it was recovered from", () => {
    // Recovery is the one path holding a real GitHub issue, so a rehydrated plan.db must come back
    // ALREADY linked — otherwise the next publish sees unlinked rows and offers to create a second
    // issue for every one it just restored.
    const r = recoverIssue({ number: 3898, title: "Invite teammates", state: "open" }, "a/b");
    expect(r.ghNumber).toBe(3898);
  });

  it("leaves the identity unset for a nonsense number rather than storing 0", () => {
    expect(recoverIssue({ number: 0, title: "t", state: "open" }, "a/b").ghNumber).toBeUndefined();
  });
});

describe("recoverIssues (bulk)", () => {
  it("drops pull requests and titleless rows", () => {
    const rows: GitHubIssueLike[] = [
      { number: 1, title: "real issue", state: "open" },
      { number: 2, title: "a PR", state: "open", pull_request: { url: "..." } },
      { number: 3, title: "", state: "open" },
    ];
    const out = recoverIssues(rows, "a/b");
    expect(out.map((i) => i.title)).toEqual(["real issue"]);
  });
});

implementations.code:
// The recovery ladder — the versions of a record's source the runtime may fall back to when the current
// one does not work.
//
// WHY THE EXISTING GATE WAS NOT ENOUGH. `renderGate`'s `lastGood` already prefers "the last version that
// rendered" over an empty surface, and that is the right instinct — but its memory is per SESSION, and a
// session that has only just booted has none. That is exactly the shape of the 02:00 incident: a designer
// rewrote five rendering-critical records at 01:39, the app was restarted, and on the fresh boot the first
// version of each record the gate ever saw was the broken one. Nothing had rendered yet, so there was
// nothing to fall back TO, and 8 of 9 workspaces render from these records.
//
// The rungs come from the record's own change history, which the Rust stamp boundary now populates with
// the `srcText` each write replaced. That is durable — it is in the store, not in a module-level Map — so
// it survives the restart that empties `lastGood`, and it is the same data `bsc ui revert` restores from.
// Together they mean a bad write degrades the surface it broke instead of the whole app, and the way back
// exists whether or not the record was ever packaged with a seed.
import type { ChangeEntry } from "@/features/designs/lib/model";

/** A record's retained earlier sources, NEWEST-FIRST — the versions to try after the current one fails.
 *
 *  Deduped, because a metadata-only write between two source edits leaves the same bytes reachable twice
 *  and re-compiling an identical source cannot produce a different outcome. Empty when the record has no
 *  history, no retained content, or has only ever been written once.
 *
 *  `current` is excluded when supplied: the ladder is what to try INSTEAD, and offering back the version
 *  that just failed would spend a compile to reach the same error. */
export function recoveryLadder(history: ChangeEntry[] | undefined, current?: string): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  // History is stored oldest-first; walk it backwards so the most recent rung is tried first.
  for (let i = (history?.length ?? 0) - 1; i >= 0; i--) {
    const prev = history?.[i]?.prevSrc;
    if (typeof prev !== "string" || !prev.trim()) continue;
    if (prev === current || seen.has(prev)) continue;
    seen.add(prev);
    out.push(prev);
  }
  return out;
}

/** Does this record have any way back at all? The question the Design Studio asks to warn BEFORE a write,
 *  rather than after: a record with no rung and no packaged seed is one whose next bad write is
 *  unrecoverable, which is the state `graphprimitive` / `kitrenderer` / `insights` were in. */
export function hasRecoveryPath(record: { history?: ChangeEntry[]; builtin?: boolean }): boolean {
  return Boolean(record.builtin) || recoveryLadder(record.history).length > 0;
}

