import { describe, it, expect } from "vitest";
import { openPaneIds, reconcileSessions, type DiscoveredSession, type ReconcileTab } from "@/app/console/lib/sessionRecovery";

const sess = (paneId: string, status: string, extra: Partial<DiscoveredSession> = {}): DiscoveredSession => ({
  paneId, sources: ["ledger"], status, ...extra,
});

describe("openPaneIds (#1266)", () => {
  it("uses minted paneIds for fleet/triage tabs", () => {
    const tab: ReconcileTab = { id: "b", kind: "build", paneIds: ["proj:director", "proj:auth"], layout: "2×1" };
    expect(openPaneIds([tab])).toEqual(new Set(["proj:director", "proj:auth"]));
  });

  it("derives man: ids per cell for a manual tab from its layout", () => {
    const tab: ReconcileTab = { id: "scratch", layout: "2×1" }; // no kind, no paneIds ⇒ manual
    expect(openPaneIds([tab])).toEqual(new Set(["man:scratch:p0", "man:scratch:p1"]));
  });

  it("falls back to positional ids for an id-less legacy tab", () => {
    expect(openPaneIds([{ layout: "1×1" }])).toEqual(new Set(["t0p0"]));
  });

  it("indexes tabs by position (man: ids stay per-tab, positional ids track the index)", () => {
    const tabs: ReconcileTab[] = [
      { id: "b", kind: "build", paneIds: ["proj:director"] },
      { layout: "1×1" }, // legacy at index 1
    ];
    expect(openPaneIds(tabs)).toEqual(new Set(["proj:director", "t1p0"]));
  });
});

describe("reconcileSessions (#1266)", () => {
  it("keeps only sessions not represented by an open pane, enriched with kind + reapOnly", () => {
    const tabs: ReconcileTab[] = [{ id: "b", kind: "build", paneIds: ["proj:director", "proj:auth"] }];
    const discovered = [
      sess("proj:director", "running"),                 // OPEN → dropped
      sess("proj:auth", "dormant"),                     // OPEN → dropped
      sess("proj:api", "planned", { repo: "own/api" }), // not open → kept (worker)
      sess("other:owner/web:triage", "running"),        // not open → kept (triage)
      sess("man:gone:p0", "running"),                   // not open → kept (manual, reap-only)
    ];

    const out = reconcileSessions(discovered, tabs);
    expect(out.map((s) => s.paneId)).toEqual(["proj:api", "other:owner/web:triage", "man:gone:p0"]);

    const byId = Object.fromEntries(out.map((s) => [s.paneId, s]));
    expect(byId["proj:api"].kind).toBe("worker");
    expect(byId["proj:api"].reapOnly).toBe(false);
    expect(byId["other:owner/web:triage"].kind).toBe("triage");
    expect(byId["man:gone:p0"].kind).toBe("manual");
    expect(byId["man:gone:p0"].reapOnly).toBe(true); // manual scratch shells are never restored
  });

  it("returns everything when no tabs are open", () => {
    const discovered = [sess("proj:director", "dormant"), sess("proj:auth", "dormant")];
    expect(reconcileSessions(discovered, []).map((s) => s.paneId)).toEqual(["proj:director", "proj:auth"]);
  });

  it("marks an unparseable id as unknown (not reap-only)", () => {
    const out = reconcileSessions([sess("garbage", "running")], []);
    expect(out[0].kind).toBe("unknown");
    expect(out[0].reapOnly).toBe(false);
  });

  it("flags an orphaned (deleted-project) shell reap-only, but not a restorable one (#1279)", () => {
    const out = reconcileSessions(
      [sess("gone:auth", "orphaned"), sess("proj:auth", "dormant")],
      [],
    );
    const byId = Object.fromEntries(out.map((s) => [s.paneId, s]));
    // The deleted project's live shell is reaped, never restored — nothing to rehydrate.
    expect(byId["gone:auth"].reapOnly).toBe(true);
    // A genuinely restorable worker is unaffected.
    expect(byId["proj:auth"].reapOnly).toBe(false);
  });

  it("excludes the dedicated planner pane (planning_<key>) entirely (#1579)", () => {
    const out = reconcileSessions(
      [sess("planning_proj", "running"), sess("proj:auth", "dormant")],
      [],
    );
    // The planning session is re-entered from the Projects page, not the recovery banner —
    // it never appears in the recoverable list, while a real worker still does.
    expect(out.map((s) => s.paneId)).toEqual(["proj:auth"]);
  });

  it("excludes the app-owned studio sessions (designer/librarian/architect) (#3137)", () => {
    // Their ids share the `<key>:<tail>` worker grammar, so before #3137 they were surfaced as
    // restorable workers. They're app-owned singletons re-created when their workspace opens —
    // never restored — so they must never appear, while a real worker still does.
    const out = reconcileSessions(
      [
        sess("design-studio:designer-react", "running"),
        sess("algorithms-studio:librarian-rust", "dormant"),
        sess("teams-studio:architect", "running"),
        sess("proj:auth", "dormant"),
      ],
      [],
    );
    expect(out.map((s) => s.paneId)).toEqual(["proj:auth"]);
  });
});

implementations.code:
// Role-scoped session capabilities (#219) — least-privilege per session type. A
// session's abilities are bounded by its ROLE, so the planner can shape the plan but
// can't mutate the repo or GitHub, and any out-of-scope action is blocked (or
// escalated to an explicit user confirmation) rather than run freely.
//
// This is the pure enforcement core (command classification + path scoping); the
// gate that USES it is the role's denied-command set plus a write-path guard on the
// write tool, applied alongside the per-agent profile (#1457). Free of React / xterm /
// Tauri imports so it's unit-testable in isolation.
//
// This file is the PUBLIC BARREL (#2151): the enforcement core was decomposed into colocated,
// concern-scoped modules, layered types/data ← rules ← derivations to avoid cycles —
//   - `roleModel.ts`   — types (SessionRole/AccessTier/RoleCapability) + the externalized
//                        role→capability data (ROLE_DEFAULTS + the write-glob / db-owned /
//                        dep-manifest lists) + core accessors (roleCapability, hasScopedWriteCarveOut).
//   - `commandGate.ts` — command classification (classifyCommand) + the role command check (checkCommand).
//   - `writeScope.ts`  — glob matching (matchGlob) + write-path/boundary scoping (canWritePath, scopeWriteGlobs).
//   - `launchRules.ts` — launch wiring: write-tool rules (roleWriteRules), whole-tool denies
//                        (roleDeniedTools), command-prefix denies (roleDeniedCommands), and the
//                        bsc-agent-native permission doc (bscAgentPerms).
// The full public API is re-exported here unchanged, so every importer keeps working.
//
// The role→capability TABLE + the write-glob / db-owned / dep-manifest lists are externalized to
// `@data/permissions/role-capabilities.json` (#2027 P1) — the single source (Rust does NOT duplicate
// it: TS computes each session's permissions here and passes them to `ensure_session_settings`).

export type { SessionRole, AccessTier, RoleCapability } from "@/shared/lib/session/roleModel";
export {
  ROLE_DEFAULTS,
  PLAN_WRITE_GLOBS,
  DOC_GLOBS,
  DB_OWNED_PLAN_FILES,
  DEP_MANIFEST_FILES,
  roleCapability,
  hasScopedWriteCarveOut,
  restrictedRoleCommands,
  // The DECLARED command-surface set (`a-persona-declares-its-command-surfaces`): what a persona
  // says it drives, the derivation that reads it off a confined role's `allow`, and the
  // capability-level accessor the launch path uses so a per-assignment narrowing is honoured.
  surfacesFromAllow, capabilitySurfaces, personaSurfaces,
  mayFileToolingRequest,
  TOOLING_REQUEST_COMMAND,
  isRestrictedRole, HARVEST_ROOT_APP_REPO, HARVEST_ROOT_PROJECTS,
} from "@/shared/lib/session/roleModel";

