// The frontend ↔ global skills.db bridge (#1338 ph2). The desktop Skills library and every live
// console session share ONE global store (`~/.base-studio-code/skills.db`), reached here — and from a
// session's own shell — through the SAME `bsc skill …` CLI, over the generic `bsc` bridge (#2114/#2142;
// it replaced the parallel per-verb `skill_store_*`/`skill_group_*` Tauri commands). Skills are GLOBAL
// (no project key) so every call passes `null` as the bridge's `projectKey`. This is the only place the
// skills feature touches Tauri, so the pure model in `skills.ts` stays React/Tauri-free.
//
// Source-of-truth: skills.db. The Zustand slice is a write-through cache — `loadLibrary` hydrates it
// on boot; each library mutation pushes through here. Per-session toggles (overrides / toggled-on
// groups) are NOT part of the global library and stay store-local; only skills + groups round-trip.
//
// Mapping: the Rust `Skill` omits the display-only telemetry (`invocations`/`success`/`avgTokensK`/
// `trend`), so a loaded skill is re-defaulted to a full {@link SkillDef} here; pushing a SkillDef is
// serde-safe because the Rust side ignores the extra telemetry fields. `list --full` (#2142) emits the
// COMPLETE skill objects (prompt + tools/profiles/packaged), matching the old `skill_store_list` shape
// — the lean paginated `list` would drop the `prompt` body that a write-through would then blank.

import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { SkillDef, SkillGroup } from "@/features/skills/lib/skills";
import type { SkillKind, SkillSource, SkillProfile } from "@/shared/data/skills";

/** The library as stored in skills.db (telemetry re-defaulted to zero on the way in). */
export interface Library {
  skills: SkillDef[];
  groups: SkillGroup[];
}

/** A skill row from the bridge → a full {@link SkillDef} (zero telemetry; packaged defaults false). */
function toDef(s: Partial<SkillDef> & { id: string; name: string }): SkillDef {
  return {
    id: s.id,
    name: s.name,
    kind: (s.kind as SkillKind) ?? "workflow",
    source: (s.source as SkillSource) ?? "first-party",
    desc: s.desc ?? "",
    prompt: s.prompt ?? "",
    tools: s.tools ?? [],
    profiles: (s.profiles as SkillProfile[]) ?? [],
    projects: s.projects ?? [],
    enabled: !!s.enabled,
    pinned: !!s.pinned,
    packaged: !!s.packaged,
    invocations: 0, success: 0, avgTokensK: 0, trend: [],
  };
}

/**
 * Hydrate the library from skills.db. Returns `null` when the bridge is unreachable (no Tauri host —
 * tests, the web shell, or an old binary), so the caller keeps its seeded in-memory set rather than
 * blanking the UI. Any single bad row is tolerated (the command itself either succeeds with the full
 * set or rejects).
 */
export async function loadLibrary(): Promise<Library | null> {
  // NOT `bscJson` here: its graceful degrade-to-fallback would return an EMPTY library when the bridge
  // is unreachable, and hydrate would then blank the seeded set. We need the explicit `null` (keep the
  // seeded set) the store depends on — so raw `bsc` + catch, exactly like the old per-command version.
  try {
    const [skillsOut, groupsOut] = await Promise.all([
      bsc(null, ["skill", "list", "--full"]), // full-fidelity array (incl. prompt) — the #2142 read
      bsc(null, ["skill", "group", "list"]),
    ]);
    const skills = JSON.parse(skillsOut.trim() || "[]") as Array<Partial<SkillDef> & { id: string; name: string }>;
    const groups = JSON.parse(groupsOut.trim() || "[]") as SkillGroup[];
    return { skills: (skills ?? []).map(toDef), groups: groups ?? [] };
  } catch {
    return null;
  }
}

/** Write-through a skill upsert (`bsc skill add` reads the JSON on stdin). Fire-and-forget; never throws. */
export async function pushSkill(skill: SkillDef): Promise<void> {
  await bscWrite(null, ["skill", "add"], skill);
}

/** Write-through a skill removal (`bsc skill remove <id>`). */
export async function dropSkill(id: string): Promise<void> {
  await bscRun(null, ["skill", "remove", id]);
}

/** Write-through a group upsert (`bsc skill group add` reads the JSON on stdin). */
export async function pushGroup(group: SkillGroup): Promise<void> {
  await bscWrite(null, ["skill", "group", "add"], group);
}

/** Write-through a group removal (`bsc skill group remove <id>`). */
export async function dropGroup(id: string): Promise<void> {
  await bscRun(null, ["skill", "group", "remove", id]);
}

// Task groups (#skills-groups): named, reusable bundles of skills toggled as one,
// their expansion into a member-id set, membership counting, and the planner's
// `skill_groups.json` parser.

import { skillSlug, type SkillDef } from "@/features/skills/lib/skillsModel";

// ── Task groups (#skills-groups) ────────────────────────────────────────────────
// A "task group" is a named, reusable bundle of skills (the redesign's ⬡). Many-to-many with
// skills (a skill can belong to several groups), keyed by stable skill id. A group is the unit of
// bulk toggling: toggle a group onto a session (manually, Workspace B) or onto a fleet stream (the
// planner) and every member skill is enabled at once. Groups are LIVE references — editing a
// group's membership updates every session/stream that has it on, rather than freezing the set.

/** A named bundle of skills, toggled as one. */
export interface SkillGroup {
  id: string;
  name: string;
  /** Accent hue (a `--token` ref or oklch literal) for the group's ⬡ chip/tile. */
  hue: string;
  /** Member skill ids (stable — never names, which can change). */
  skillIds: string[];
}

/** The DISTINCT member skill ids across a set of enabled group ids (order-stable, de-duped). An
 *  unknown group id contributes nothing. Used to expand a session's/stream's toggled-on groups
 *  into the `groupSkillIds` set that {@link effectiveSessionSkills} folds in. */
export function expandGroups(groupIds: readonly string[], groups: SkillGroup[]): string[] {
  const byId = new Map(groups.map((g) => [g.id, g]));
  const out = new Set<string>();
  for (const gid of groupIds) for (const sid of byId.get(gid)?.skillIds ?? []) out.add(sid);
  return [...out];
}

/** Membership count of a group whose member skills still exist in `all` (the chip count). */
export function groupSkillCount(group: SkillGroup, all: SkillDef[]): number {
  const ids = new Set(all.map((s) => s.id));
  return group.skillIds.filter((id) => ids.has(id)).length;
}

/** Parse the planner's `skill_groups.json` (a JSON array of `{name, hue?, skills?: string[]}`) into
 *  clean groups. `skills` may be skill ids OR name-slugs (the planner authors by name); they're
 *  resolved against the library here so the stored group keys by id. Tolerant: malformed input →
 *  []; a row without a usable name is dropped. Mirrors {@link parseSkillsFile}. */
export function parseSkillGroupsFile(raw: string, all: SkillDef[]): Array<Omit<SkillGroup, "id"> & { id?: string }> {
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(data)) return [];
  const bySlug = new Map(all.map((s) => [skillSlug(s.name), s.id]));
  const byId = new Set(all.map((s) => s.id));
  const out: Array<Omit<SkillGroup, "id"> & { id?: string }> = [];
  for (const row of data) {
    if (!row || typeof row !== "object") continue;
    const r = row as Record<string, unknown>;
    const name = typeof r.name === "string" ? r.name.trim() : "";
    if (!name) continue;
    const refs = Array.isArray(r.skills) ? r.skills.filter((x): x is string => typeof x === "string") : [];
    const skillIds = Array.from(new Set(
      refs.map((ref) => (byId.has(ref) ? ref : bySlug.get(skillSlug(ref)))).filter((x): x is string => !!x),
    ));
    out.push({
      id: typeof r.id === "string" && r.id ? r.id : undefined,
      name,
      hue: typeof r.hue === "string" && r.hue ? r.hue : "var(--accent)",
      skillIds,
    });
  }
  return out;
}

// Shared inline-style factories for the Skills screen (#1706). Pulled out of SkillsWorkspace.tsx so
// the screen, the view-mode renderers (SkillsViews.tsx), and the edit drawer all share one source
// of the pill / tile / scope-color styling. Pure CSSProperties builders (the only React coupling is
// the type import).

import type { CSSProperties } from "react";
import { KIND, type SkillKind, type SkillSource } from "@/shared/data/skills";

/** Success-rate → color: dim when unknown, success/accent/danger by threshold. */
export const successColor = (s: number | null): string =>
  s == null ? "var(--fg-dim)" : s >= 95 ? "var(--success)" : s >= 85 ? "var(--accent)" : "var(--danger)";

/** A translucent tint of `hue` (a `--token` ref or oklch literal). */
export function tintBg(hue: string, t = 88): string { return `color-mix(in oklch, ${hue}, transparent ${t}%)`; }

/** A small pill chip in `hue` (or a neutral "plain" chip). */
export function pill(hue: string, plain = false): CSSProperties {
  const base: CSSProperties = { fontFamily: "var(--mono)", fontSize: 9.5, padding: "2px 7px", borderRadius: 99, lineHeight: 1.1, whiteSpace: "nowrap", display: "inline-flex", alignItems: "center" };
  if (plain) return { ...base, background: tintBg("var(--fg-dim)"), border: "1px solid " + tintBg("var(--fg-dim)", 80), color: "var(--fg-muted)" };
  return { ...base, background: tintBg(hue), border: `1px solid ${tintBg(hue, 74)}`, color: hue };
}

/** A square glyph tile in an arbitrary hue (a `--token` ref or oklch literal). */
export function hueTile(c: string, lg = false): CSSProperties {
  const d = lg ? 30 : 22;
  return { width: d, height: d, flex: "0 0 auto", display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 6, fontFamily: "var(--mono)", fontSize: lg ? 15 : 12, color: c, background: `color-mix(in oklch, ${c} 22%, var(--bg-elev))`, border: `1px solid ${tintBg(c, 70)}` };
}

/** A glyph tile colored by the skill kind. */
export function glyphTile(kind: SkillKind, lg = false): CSSProperties {
  return hueTile(KIND[kind].color, lg);
}

/** Source pill: info for team, accent for imported, neutral otherwise. */
export const sourcePill = (src: SkillSource): CSSProperties =>
  src === "team" ? pill("var(--info)") : src === "imported" ? pill("var(--accent)") : pill("", true);

/** Scope pill: info when project-scoped, neutral when global. */
export const scopePill = (projects: string[]): CSSProperties => (projects.length ? pill("var(--info)") : pill("", true));

// Skill-invocation telemetry — parse + aggregate the `skills.log` written by the
// `bsc-skill` hook on gated panes (see lib.rs). Each invocation appends a
// PreToolUse line; each success appends a PostToolUse line. Both are tagged with
// the skill name. Pure + unit-testable (the `now` clock is injected). (#406)
//
// Mirrors the Agents audit-log model (features/agents/lib/auditLog.ts): a flat TSV
// `ts \t pane \t event \t skill`, read newest-first via `bsc logs tail skill`.

import { skillSlug } from "@/features/skills/lib/skills";

/** One parsed `bsc-skill` line. `event` is the hook event name (PreToolUse =
 *  one per invocation; PostToolUse = one per success). `skill` is the raw
 *  `skill_name` from the hook payload. */
export interface SkillUsageRecord {
  ts: string;     // ISO-8601 (UTC, "Z")
  pane: string;   // paneId
  event: string;  // "PreToolUse" | "PostToolUse" | …
  skill: string;  // raw skill_name
}

/** Per-skill aggregates, keyed by skill-name slug. */
export interface SkillStats {
  /** total invocations (PreToolUse lines). */
  invocations: number;
  /** successful invocations (PostToolUse lines). */
  success: number;
  /** success rate 0–100 (0 when never invoked). */
  successRate: number;
  /** invocations whose timestamp falls on the current UTC day. */
  today: number;
  /** invocation counts per day for the last 7 UTC days, oldest→newest. */
  trend: number[];
}

/** Parse the TSV skill-usage log into records, skipping malformed lines. */
export function parseSkillLog(text: string): SkillUsageRecord[] {
  const out: SkillUsageRecord[] = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const [ts, pane, event, ...rest] = line.split("\t");
    if (ts && pane && event) {
      out.push({ ts, pane, event, skill: rest.join("\t") });
    }
  }
  return out;
}

/** The UTC calendar day (YYYY-MM-DD) of an ISO timestamp. */
function dayKey(iso: string): string {
  return iso.slice(0, 10);
}

/** The 7 UTC day-keys ending today (oldest→newest). */
function last7Days(now: Date): string[] {
  const days: string[] = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 86_400_000);
    days.push(d.toISOString().slice(0, 10));
  }
  return days;
}

/**
 * Aggregate usage records into per-skill stats, keyed by the skill-name slug so
 * a record's raw `skill_name` (whether the directory slug or the display name)
 * resolves to the same bucket as a {@link SkillDef} via {@link skillSlug}.
 */
export function aggregateSkillTelemetry(
  records: SkillUsageRecord[],
  now: Date,
): Record<string, SkillStats> {
  const today = now.toISOString().slice(0, 10);
  const days = last7Days(now);
  const dayIndex = new Map(days.map((d, i) => [d, i]));

  const acc: Record<string, { inv: number; ok: number; today: number; trend: number[] }> = {};
  const bucket = (key: string) => (acc[key] ??= { inv: 0, ok: 0, today: 0, trend: [0, 0, 0, 0, 0, 0, 0] });

  for (const r of records) {
    const key = skillSlug(r.skill);
    if (!key) continue;
    const b = bucket(key);
    if (r.event === "PreToolUse") {
      b.inv += 1;
      if (dayKey(r.ts) === today) b.today += 1;
      const di = dayIndex.get(dayKey(r.ts));
      if (di !== undefined) b.trend[di] += 1;
    } else if (r.event === "PostToolUse") {
      b.ok += 1;
    }
  }

  const out: Record<string, SkillStats> = {};
  for (const [key, b] of Object.entries(acc)) {
    // Clamp successes to invocations — a PostToolUse without a captured PreToolUse
    // (e.g. log truncation) must never push the rate above 100%.
    const success = Math.min(b.ok, b.inv);
    out[key] = {
      invocations: b.inv,
      success,
      successRate: b.inv > 0 ? Math.round((success / b.inv) * 100) : 0,
      today: b.today,
      trend: b.trend,
    };
  }
  return out;
}

/**
 * Status-bar KPIs for the Skills page, from the real telemetry (replaces the mock
 * `SKILL_KPIS`). `loaded` is the library size; `invToday` sums today's invocations across
 * skills; `worst` is the lowest-success-rate skill among those actually invoked (the quality
 * flag shown with a warning), or `null` when nothing has been invoked. Pure + unit-tested.
 */
export function skillStatusKpis(
  skillCount: number,
  stats: Record<string, SkillStats>,
): { loaded: number; invToday: number; worst: { skill: string; rate: number } | null } {
  let invToday = 0;
  let worst: { skill: string; rate: number } | null = null;
  for (const [skill, s] of Object.entries(stats)) {
    invToday += s.today;
    if (s.invocations > 0 && (worst == null || s.successRate < worst.rate)) {
      worst = { skill, rate: s.successRate };
    }
  }
  return { loaded: skillCount, invToday, worst };
}

