// The seeded sort proof (#3177) — `sortSteps` yields a monotonically-improving (by inversion count)
// sequence that ends fully sorted, and `sort` returns the sorted array (draining the same generator).
import { describe, it, expect } from "vitest";
import { sortSteps, sort, SORT_MOCK, parseSortInput } from "@/features/algorithms/viz/examples/sort";
import { programVizForImpl } from "@/features/algorithms/viz/examples/registry";
import type { ArrayFrame } from "@/features/algorithms/lib/trace";

/** The number of inversions in `a` — pairs out of order. A perfect measure of "sortedness": strictly
 *  decreases toward 0 as an ascending sort makes progress, and is 0 exactly when `a` is sorted. */
function inversions(a: number[]): number {
  let n = 0;
  for (let i = 0; i < a.length; i++) for (let j = i + 1; j < a.length; j++) if (a[i] > a[j]) n++;
  return n;
}

const asc = (a: readonly number[]) => [...a].sort((x, y) => x - y);
/** Last element (this tsconfig's lib target predates Array.prototype.at). */
const last = <T,>(a: readonly T[]): T => a[a.length - 1];

describe("sortSteps (#3177)", () => {
  it("yields a non-worsening (by inversion count) sequence ending fully sorted", () => {
    const frames = [...sortSteps([...SORT_MOCK])];
    const invs = frames.map((f) => inversions(f.data as number[]));

    // Monotonically improving: inversion count never increases from one frame to the next.
    for (let i = 1; i < invs.length; i++) expect(invs[i]).toBeLessThanOrEqual(invs[i - 1]);

    // It starts unsorted (there is real work to show) and ends sorted (0 inversions).
    expect(invs[0]).toBeGreaterThan(0);
    expect(last(invs)).toBe(0);
    expect(last(frames).data).toEqual(asc(SORT_MOCK));
  });

  it("each swap frame removes exactly one inversion (the swap verb === one exchange)", () => {
    const frames = [...sortSteps([...SORT_MOCK])];
    for (let i = 1; i < frames.length; i++) {
      const prev = inversions(frames[i - 1].data as number[]);
      const cur = inversions(frames[i].data as number[]);
      const isSwap = frames[i].ops?.some((o) => o.op === "swap");
      if (isSwap) expect(cur).toBe(prev - 1);
      else expect(cur).toBe(prev);
    }
  });

  it("carries the contract verbs + cursors: compare/swap ops with i,j cursors, and a terminal sorted mark", () => {
    const frames = [...sortSteps([...SORT_MOCK])];
    // Every op-bearing mid-run frame is a compare or swap and carries both cursors.
    const mid = frames.slice(1, -1).filter((f) => f.ops && f.ops.length > 0);
    expect(mid.length).toBeGreaterThan(0);
    for (const f of mid) {
      expect(f.ops!.every((o) => o.op === "compare" || o.op === "swap")).toBe(true);
      expect(f.cursors).toMatchObject({ i: expect.any(Number), j: expect.any(Number) });
    }
    // The terminal frame marks every cell sorted.
    const terminal = last(frames);
    expect(terminal.ops).toHaveLength(SORT_MOCK.length);
    expect(terminal.ops!.every((o) => o.op === "mark" && (o as { as: string }).as === "sorted")).toBe(true);
  });

  it("is a pure function of its input across replays (identical frame sequence each call)", () => {
    const a = [4, 2, 5, 1, 3];
    const first = [...sortSteps([...a])].map((f) => f.data);
    const second = [...sortSteps([...a])].map((f) => f.data);
    expect(second).toEqual(first);
  });

  it("is idempotent on an already-sorted input (a compare-only pass, no swaps)", () => {
    const frames: ArrayFrame[] = [...sortSteps([1, 2, 3, 4])];
    expect(frames.some((f) => f.ops?.some((o) => o.op === "swap"))).toBe(false);
    expect(last(frames).data).toEqual([1, 2, 3, 4]);
  });
});

describe("sort (#3177)", () => {
  it("returns the ascending-sorted array by draining the generator", () => {
    expect(sort(SORT_MOCK)).toEqual(asc(SORT_MOCK));
    expect(sort([3, 1, 2])).toEqual([1, 2, 3]);
    expect(sort([])).toEqual([]);
    expect(sort([9])).toEqual([9]);
    expect(sort([2, 2, 1, 1])).toEqual([1, 1, 2, 2]);
  });

  it("does not mutate its input (pure)", () => {
    const input = [5, 3, 1, 4, 2];
    const copy = [...input];
    sort(input);
    expect(input).toEqual(copy);
  });
});

describe("parseSortInput (#3199 custom state)", () => {
  it("parses comma- and/or whitespace-separated numbers", () => {
    expect(parseSortInput("5, 2, 9, 1")).toEqual([5, 2, 9, 1]);
    expect(parseSortInput("3 1 2")).toEqual([3, 1, 2]);
    expect(parseSortInput(" 4 ,5,  6 ")).toEqual([4, 5, 6]);
    expect(parseSortInput("-2, 0, 3.5")).toEqual([-2, 0, 3.5]);
  });

  it("throws a helpful Error on empty input, a non-number, or an unwatchable length", () => {
    expect(() => parseSortInput("   ")).toThrow(/at least one number/i);
    expect(() => parseSortInput("5, abc, 2")).toThrow(/"abc" is not a number/);
    expect(() => parseSortInput(Array.from({ length: 41 }, () => "1").join(","))).toThrow(/under 40/i);
  });
});

describe("sort example input seam (#3199/#3216)", () => {
  it("resolves each named sort algorithm to its OWN program, and nothing for an unknown one", () => {
    // Program-driven (#3216): keyed by the algorithm's base name, not by kind — each sort has its own.
    expect(programVizForImpl({ id: "sort.ts", name: "sort" })).toBeDefined();
    expect(programVizForImpl({ id: "merge-sort.rs", name: "merge_sort" })).toBeDefined();
    expect(programVizForImpl({ id: "quick-sort.rs", name: "quick_sort" })).toBeDefined();
    expect(programVizForImpl({ id: "nope.rs", name: "nope" })).toBeUndefined(); // no program
  });

  it("make(parse(default)) reproduces the default factory trace", async () => {
    const viz = programVizForImpl({ id: "sort.ts", name: "sort" })!;
    const factory = await viz.input.make(viz.input.parse(viz.input.default)); // async now (#3233)
    const fromDefault = [...factory()].map((f) => (f as ArrayFrame).data);
    const fromFactory = [...viz.factory()].map((f) => (f as ArrayFrame).data);
    expect(fromDefault).toEqual(fromFactory);
  });
});

implementations.code:
// The sort family as REAL trace-programs (#3216, epic #3215) — each is the genuine algorithm written
// against a TracedArray, so its animation is DERIVED from its own execution and looks distinct: bubble's
// adjacent swaps, insertion's shifting prefix, quick's partitions, heap's sift-downs, merge's writes.
// There are no hand-drawn frames — the tracer records what the code does.
//
// Keyed by the algorithm's BASE NAME (`merge-sort`, not `merge-sort.rs`), so a Rust reference impl and any
// TypeScript twin share one visualization (the JS trace-program is the visualizable form; the Rust stays
// shown in the code panel). `programForImpl` normalizes an impl id to that key.
import { TracedArray } from "@/features/algorithms/lib/tracer";
import { SORT_MOCK } from "@/features/algorithms/viz/examples/sort";

/** A visualizable algorithm — its real logic over a {@link TracedArray} + the default input to seed it. */
export interface AlgoProgram {
  /** The algorithm, written against the traced structure (its ops become the animation). */
  run: (a: TracedArray) => void;
  /** The default input the inline preview + "your input" field seed from. */
  defaultInput: readonly number[];
}

// ── the sort family (each the real algorithm) ──

/** Bubble sort — repeatedly swap adjacent out-of-order pairs; stop early once a pass makes no swap. */
export function bubbleSort(a: TracedArray): void {
  for (let i = 0; i < a.length; i++) {
    let swapped = false;
    for (let j = 0; j < a.length - i - 1; j++) {
      a.cursor("j", j);
      if (a.compare(j, j + 1) > 0) {
        a.swap(j, j + 1);
        swapped = true;
      }
    }
    if (!swapped) break;
  }
  a.markSorted();
}

/** Insertion sort — grow a sorted prefix, swapping each new element down into place. */
export function insertionSort(a: TracedArray): void {
  for (let i = 1; i < a.length; i++) {
    a.cursor("i", i);
    let j = i;
    while (j > 0 && a.compare(j - 1, j) > 0) {
      a.swap(j - 1, j);
      j--;
    }
  }
  a.markSorted();
}

/** Quick sort — Lomuto partition around the last element, recurse each side. */
export function quickSort(a: TracedArray): void {
  const part = (lo: number, hi: number): void => {
    if (lo >= hi) return;
    a.mark(hi, "pivot"); // the pivot for this partition
    let i = lo;
    for (let j = lo; j < hi; j++) {
      a.cursor("j", j);
      if (a.compare(j, hi) < 0) {
        a.swap(i, j);
        i++;
      }
    }
    a.swap(i, hi); // drop the pivot into its final slot
    part(lo, i - 1);
    part(i + 1, hi);
  };
  part(0, a.length - 1);
  a.markSorted();
}

/** Heap sort — build a max-heap in place (sift-down), then swap the root to the end and re-sift. */
export function heapSort(a: TracedArray): void {
  const n = a.length;
  const siftDown = (start: number, end: number): void => {
    let root = start;
    while (root * 2 + 1 <= end) {
      let child = root * 2 + 1;
      if (child + 1 <= end && a.compare(child, child + 1) < 0) child += 1; // larger child
      if (a.compare(root, child) < 0) {
        a.swap(root, child);
        root = child;
      } else return;
    }
  };
  for (let start = Math.floor((n - 2) / 2); start >= 0; start--) siftDown(start, n - 1);
  for (let end = n - 1; end > 0; end--) {
    a.swap(0, end); // largest to the end
    siftDown(0, end - 1);
  }
  a.markSorted();
}

/** Merge sort — bottom-up: merge adjacent runs of growing width, writing the merged result back with
 *  `set` (so the animation shows the merge writes, distinct from the swap-based sorts). */
export function mergeSort(a: TracedArray): void {
  const n = a.length;
  for (let width = 1; width < n; width *= 2) {
    for (let lo = 0; lo < n; lo += 2 * width) {
      const mid = Math.min(lo + width, n);
      const hi = Math.min(lo + 2 * width, n);
      // Snapshot the two runs (silent reads), then write the merged order back into place.
      const left: number[] = [];
      const right: number[] = [];
      for (let k = lo; k < mid; k++) left.push(a.get(k));
      for (let k = mid; k < hi; k++) right.push(a.get(k));
      let i = 0;
      let j = 0;
      let k = lo;
      while (i < left.length && j < right.length) {
        if (left[i] <= right[j]) a.set(k++, left[i++]);
        else a.set(k++, right[j++]);
      }
      while (i < left.length) a.set(k++, left[i++]);
      while (j < right.length) a.set(k++, right[j++]);
    }
  }
  a.markSorted();
}

/** The visualizable algorithms, keyed by BASE NAME. The generic `sort` (the TypeScript kit's insertion
 *  sort) maps to insertion. Grows as more algorithms are authored as trace-programs (or, #3215 slice B,
 *  loaded from the impl's stored code). */
export const TRACE_PROGRAMS: Record<string, AlgoProgram> = {
  "bubble-sort": { run: bubbleSort, defaultInput: SORT_MOCK },
  "insertion-sort": { run: insertionSort, defaultInput: SORT_MOCK },
  "quick-sort": { run: quickSort, defaultInput: SORT_MOCK },
  "heap-sort": { run: heapSort, defaultInput: SORT_MOCK },
  "merge-sort": { run: mergeSort, defaultInput: SORT_MOCK },
  sort: { run: insertionSort, defaultInput: SORT_MOCK },
};

/** Normalize an impl id/name to its base-algorithm key — strip the extension, lowercase, and unify
 *  separators — so `merge-sort.rs`, `merge_sort`, and `merge-sort.ts` all resolve to `merge-sort`. */
export function programKey(impl: { id: string; name?: string }): string {
  return impl.id
    .replace(/\.[a-z0-9]+$/i, "") // drop the extension (".rs"/".ts")
    .toLowerCase()
    .replace(/[_\s]+/g, "-");
}

/** The trace-program for an implementation, or `undefined` when the algorithm has none yet (so it simply
 *  shows no animation — never a wrong category one). */
export function programForImpl(impl: { id: string; name?: string }): AlgoProgram | undefined {
  return TRACE_PROGRAMS[programKey(impl)];
}

