describe("sourceConfig — scan visualizations view-model (#1209)", () => {
  const plat = (over: Partial<PlatformScanView>): PlatformScanView => ({ automations: [], businessProcesses: [], derivedLogic: [], ...over });
  const vizCfg: SourceConfig = {
    dataModelName: "Acme Core", proposed: [],
    sources: [
      src({
        uid: "a", connectorId: "salesforce", status: "scanned",
        objects: [
          { name: "Account", count: 12431, fields: ["domain", "name"] },
          { name: "Contact", count: 28902, fields: ["email", "account"] }, // account → ref Account
        ],
        platform: plat({
          automations: [{ source: "salesforce", kind: "validation", name: "Acct type", object: "Account", active: true, trigger: "onSave", condition: "ISBLANK(Type)", actions: ["reject"] }],
          businessProcesses: [{ source: "salesforce", name: "Discount Approval", object: "Opportunity", active: true, steps: ["Submitted", "Approved"] }],
        }),
      }),
      src({
        uid: "b", connectorId: "quickbase", status: "scanned",
        objects: [{ name: "Project", count: 1884, fields: ["id", "account"] }], // account → ref Account
        platform: plat({ derivedLogic: [{ source: "quickbase", kind: "formula", name: "spend_pct", object: "Project", expression: "[Spent]/[Budget]" }] }),
      }),
    ],
  };

  it("scanEntities carries counts + source + inferred refs", () => {
    const ents = scanEntities(vizCfg);
    expect(ents.map((e) => e.key).sort()).toEqual(["account", "contact", "project"]);
    const account = ents.find((e) => e.key === "account")!;
    expect(account.count).toBe(12431);
    expect(account.source).toBe("salesforce");
    expect(account.srcColor).toBe(connectorColor("salesforce"));
    const contact = ents.find((e) => e.key === "contact")!;
    const acctField = contact.fields.find((f) => f.key === "account")!;
    expect(acctField.type).toBe("ref");
    expect(acctField.ref).toBe("account");
    expect(acctField.refLabel).toBe("Account");
  });

  it("scanEdges resolves the ref relationships into edges", () => {
    const edges = scanEdges(scanEntities(vizCfg));
    // Contact.account → Account and Project.account → Account
    expect(edges.length).toBe(2);
    expect(edges.every((e) => e.to === "account")).toBe(true);
    expect(edges.some((e) => e.from === "contact")).toBe(true);
    expect(edges.some((e) => e.from === "project")).toBe(true);
  });

  it("aggregatePlatform merges behaviors across sources; isMultiSource detects ≥2 sources", () => {
    const p = aggregatePlatform(vizCfg);
    expect(p.automations.length).toBe(1);
    expect(p.businessProcesses.length).toBe(1);
    expect(p.derivedLogic.length).toBe(1);
    expect(isMultiSource(vizCfg)).toBe(true);
    expect(isMultiSource({ ...vizCfg, sources: [vizCfg.sources[0]] })).toBe(false);
  });

  it("honors typed discovered fields — real types + enum values flow to the model + view (#1219)", () => {
    const cfg: SourceConfig = {
      dataModelName: "M", proposed: [],
      sources: [src({
        uid: "x", connectorId: "sql", status: "scanned",
        objects: [{ name: "Account", count: 5, fields: [
          { name: "id", type: "string" },
          { name: "revenue", type: "money" },
          { name: "tier", type: "enum", enumValues: ["A", "B", "C"] },
        ] }],
      })],
    };
    const acct = deriveDataModel(cfg).entities[0];
    const byKey = Object.fromEntries(acct.fields.map((f) => [f.key, f]));
    expect(byKey.revenue.type).toBe("money");
    expect(byKey.tier.type).toBe("enum");
    expect(byKey.tier.enum_values).toEqual(["A", "B", "C"]);

    const tier = scanEntities(cfg)[0].fields.find((f) => f.key === "tier")!;
    expect(tier.type).toBe("enum");
    expect(tier.enumValues).toEqual(["A", "B", "C"]);
  });

  it("resolves connector-declared lookups into refs (target by object name), drops dangling ones (#1219)", () => {
    const cfg: SourceConfig = {
      dataModelName: "M", proposed: [],
      sources: [src({
        uid: "sf", connectorId: "salesforce", status: "scanned",
        objects: [
          { name: "Account", count: 3, fields: [
            { name: "Id", type: "string" },
            { name: "OwnerId", type: "ref", ref: "User" },   // declared lookup → scanned object
            { name: "TerritoryId", type: "ref", ref: "Territory" }, // lookup to an un-scanned object
          ] },
          { name: "User", count: 2, fields: [{ name: "Id", type: "string" }] },
        ],
      })],
    };
    const model = deriveDataModel(cfg);
    const account = model.entities.find((e) => e.key === "account")!;
    const byKey = Object.fromEntries(account.fields.map((f) => [f.key, f]));
    // declared lookup resolves to the target entity's key — name-matching never would (ownerid≠user)
    expect(byKey.ownerid.type).toBe("ref");
    expect(byKey.ownerid.ref).toBe("user");
    // lookup to an object that wasn't scanned: dangling link dropped, left a plain field
    expect(byKey.territoryid.ref).toBeUndefined();
    expect(byKey.territoryid.type).toBe("string");
    // the resolved lookup becomes a graph edge
    const edges = scanEdges(scanEntities(cfg));
    expect(edges).toContainEqual({ from: "account", to: "user", label: "ownerid → User" });
  });
});

describe("proposeFromPitch (#1349)", () => {
  it("returns [] for an empty / blank pitch", () => {
    expect(proposeFromPitch("")).toEqual([]);
    expect(proposeFromPitch("   ")).toEqual([]);
    expect(proposeFromPitch(undefined)).toEqual([]);
  });

  it("proposes connectors named in the pitch, in catalog order, deduped", () => {
    const ids = proposeFromPitch("We're migrating off QuickBooks and Salesforce into one app.");
    // catalog order: quickbooks precedes salesforce
    expect(ids).toEqual(["quickbooks", "salesforce"]);
  });

  it("is case-insensitive and matches common aliases", () => {
    expect(proposeFromPitch("everything lives in SFDC today")).toEqual(["salesforce"]);
    expect(proposeFromPitch("Replace our QBO bookkeeping")).toEqual(["quickbooks"]);
    expect(proposeFromPitch("our data is in postgres")).toEqual(["sql"]);
  });

  it("matches on word boundaries — an unrelated substring does not propose a source", () => {
    // "sapling" contains "sap" but is not the SAP system.
    expect(proposeFromPitch("a fast-growing sapling of a startup")).toEqual([]);
    // "summons" / "monsoon" must not trip the "monday" alias by substring.
    expect(proposeFromPitch("a monsoon of summons paperwork")).toEqual([]);
  });

  it("returns no duplicates when an alias appears multiple times", () => {
    expect(proposeFromPitch("Salesforce here, Salesforce there, all Salesforce")).toEqual(["salesforce"]);
  });
});

implementations.code:
// Discovery-declared integrations → the Source pane's proposals (#4054).
//
// The pane's "Confirm N sources" banner used to be seeded by scanning the PITCH for keywords
// (`proposeFromPitch`). That was the best signal available when it was written, and it no longer is:
// since #4024 the planner records the integrations the user actually CONFIRMED in conversation, each
// with a `direction`, and `direction: "source"` means exactly "data migrates FROM this" — which is what
// the Source pane exists to offer.
//
// Guessing from keywords when the answer has been stated is the wrong input: the scan can omit a system
// the user named and propose one they never mentioned. These helpers are pure so the precedence and the
// direction filter are unit-testable without the pane.

/** One declared integration as `bsc plan discovery integration list --json` emits it (camelCase wire,
 *  matching the Rust `PlanIntegration`). Every field but `id` may be absent. */
export interface DeclaredIntegration {
  id: string;
  name?: string;
  /** `source` = data migrates FROM it | `runtime` = the built app talks to it while running. */
  direction?: string;
  docs?: string;
  baseUrl?: string;
  /** The auth SCHEME in prose ("OAuth2 client credentials"). Never a secret. */
  auth?: string;
  purpose?: string;
}

/** The `direction` the Source pane cares about — a migration source, not a runtime dependency. */
export const SOURCE_DIRECTION = "source";

/**
 * The migration sources among `rows`, in declaration order.
 *
 * Filters defensively rather than trusting the caller's `--direction` flag: a runtime integration must
 * NEVER reach the Source pane. That is the entire point of the split — a payment API is not something
 * you migrate off, and offering it as one sends the user down a pointless connect-and-scan path.
 * Rows without a usable `id` are dropped (they cannot be keyed), and duplicate ids collapse to the
 * first, so a re-declared integration proposes once.
 */
export function migrationSources(rows: readonly DeclaredIntegration[]): DeclaredIntegration[] {
  const seen = new Set<string>();
  const out: DeclaredIntegration[] = [];
  for (const r of rows ?? []) {
    const id = (r?.id ?? "").trim();
    if (!id || r?.direction !== SOURCE_DIRECTION || seen.has(id)) continue;
    seen.add(id);
    out.push({ ...r, id });
  }
  return out;
}

/**
 * The connector ids to seed the pre-declare banner with, and where they came from.
 *
 * **Discovery wins.** The pitch scan survives only as the fallback for a project whose Discovery
 * predates #4024 (or that never worked the `integrations` topic) — so a proposal is traceable to a
 * decision whenever one exists, and the older behaviour is preserved exactly where it isn't. Pure.
 */
export function proposedSourceIds(
  declared: readonly DeclaredIntegration[],
  fromPitch: readonly string[],
): { ids: string[]; origin: "discovery" | "pitch" | "none" } {
  const sources = migrationSources(declared);
  if (sources.length > 0) return { ids: sources.map((s) => s.id), origin: "discovery" };
  const pitch = (fromPitch ?? []).filter(Boolean);
  return pitch.length > 0 ? { ids: [...pitch], origin: "pitch" } : { ids: [], origin: "none" };
}

/**
 * The non-secret connect fields Discovery already captured for `id`, ready to seed a newly declared
 * source — so an agent authoring its connector starts from the vendor reference the user gave instead
 * of a blank form.
 *
 * ONLY `baseUrl` and `docs` cross: both are plain URLs. `auth` is deliberately excluded even though it
 * is a prose scheme rather than a credential — `DeclaredSource.fields` is the connect-form's value bag,
 * and a scheme string is not a field value. Nothing secret exists on this path to begin with.
 */
export function connectFieldsFor(
  id: string,
  declared: readonly DeclaredIntegration[],
): Record<string, string> {
  const row = migrationSources(declared).find((r) => r.id === id);
  if (!row) return {};
  const fields: Record<string, string> = {};
  const baseUrl = (row.baseUrl ?? "").trim();
  const docs = (row.docs ?? "").trim();
  if (baseUrl) fields.baseUrl = baseUrl;
  if (docs) fields.docs = docs;
  return fields;
}

