// Stack detection (#848 / #1710): the single regex-based matcher over a project's stack-section
// prose. Two consumers share it — `deriveTopics` (→ GitHub repo topics) and `gettingStartedCmds`
// (→ the README's install/run commands). Kept as TS (RegExp literals, not JSON) so the patterns
// stay first-class and case-insensitive whole-word matching is expressible.

/**
 * Test a stack-pattern against already-lowercased stack text. Centralizes the match step so both
 * the topic map and the getting-started toolchains run through one place.
 */
function matchesStack(lowerText: string, re: RegExp): boolean {
  return re.test(lowerText);
}

// Curated stack-keyword → GitHub-topic-slug map. Matched case-insensitively as whole words
// against the stack section text, so prose like "React 18 + TypeScript, Rust (Tauri)" yields
// `react`, `typescript`, `rust`, `tauri`. Lowercase-hyphenated per the topic-hygiene guide.
export const STACK_TOPICS: [RegExp, string][] = [
  [/\breact\b/, "react"], [/\bnext\.?js\b/, "nextjs"], [/\bvue\b/, "vue"], [/\bsvelte\b/, "svelte"],
  [/\bangular\b/, "angular"], [/\btypescript\b/, "typescript"], [/\bjavascript\b/, "javascript"],
  [/\bnode(\.?js)?\b/, "nodejs"], [/\bdeno\b/, "deno"], [/\bbun\b/, "bun"], [/\bvite\b/, "vite"],
  [/\brust\b/, "rust"], [/\btauri\b/, "tauri"], [/\bgo(lang)?\b/, "go"], [/\bpython\b/, "python"],
  [/\bdjango\b/, "django"], [/\bflask\b/, "flask"], [/\bfastapi\b/, "fastapi"], [/\bruby\b/, "ruby"],
  [/\brails\b/, "rails"], [/\bjava\b/, "java"], [/\bspring\b/, "spring-boot"], [/\bkotlin\b/, "kotlin"],
  [/\bswift\b/, "swift"], [/\bc\+\+\b/, "cpp"], [/\bc#\b/, "csharp"], [/\b\.net\b/, "dotnet"],
  [/\bpostgres(ql)?\b/, "postgresql"], [/\bmysql\b/, "mysql"], [/\bsqlite\b/, "sqlite"],
  [/\bmongo(db)?\b/, "mongodb"], [/\bredis\b/, "redis"], [/\bduckdb\b/, "duckdb"],
  [/\bgraphql\b/, "graphql"], [/\bdocker\b/, "docker"], [/\bkubernetes\b|\bk8s\b/, "kubernetes"],
  [/\btailwind\b/, "tailwindcss"], [/\bexpo\b/, "expo"], [/\breact native\b/, "react-native"],
];

// Toolchain → install/run commands, matched against the stack text the same way as STACK_TOPICS.
// First entry whose pattern hits contributes its commands; multiple may match (e.g. Tauri → both
// npm and cargo). Falls back to a generic comment when nothing is recognized.
const STACK_TOOLCHAINS: [RegExp, string[]][] = [
  [/\bnode(\.?js)?\b|\bnpm\b|\bvite\b|\breact\b|\bnext\b|\btypescript\b|\btauri\b/, ["npm install", "npm run dev"]],
  [/\bcargo\b|\brust\b|\btauri\b/, ["cargo build", "cargo run"]],
  [/\bpython\b|\bdjango\b|\bflask\b|\bfastapi\b/, ["pip install -r requirements.txt"]],
  [/\bgo(lang)?\b/, ["go mod download", "go run ."]],
];

/**
 * Derive GitHub repo topics from the stack section text, plus any explicit extras. Whole-word,
 * case-insensitive; deduped; lowercase-hyphenated; capped at GitHub's 20-topic limit. NB: these
 * are GitHub *repo topics*, distinct from the planner's discovery "topics".
 */
export function deriveTopics(stackText: string, extra: string[] = []): string[] {
  const found: string[] = [];
  const text = stackText.toLowerCase();
  for (const [re, topic] of STACK_TOPICS) {
    if (matchesStack(text, re)) found.push(topic);
  }
  const clean = (t: string) => t.trim().toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "");
  const all = [...found, ...extra.map(clean)].filter(Boolean);
  return [...new Set(all)].slice(0, 20);
}

/**
 * A stack-aware Getting-started body. Detects the toolchain from the stack text and emits the
 * right install/run commands (npm / cargo / pip / go), falling back to a generic comment when
 * nothing is recognized. Returns the lines *inside* the ```bash fence (clone is added by the caller).
 */
export function gettingStartedCmds(stackText: string): string[] {
  const s = stackText.toLowerCase();
  const out: string[] = [];
  for (const [re, cmds] of STACK_TOOLCHAINS) {
    if (matchesStack(s, re)) out.push(...cmds);
  }
  return out.length ? out : ["# install dependencies and run the project's build/test/dev commands"];
}

// The `stack` viz kit's MOTION wiring (#3266, epic #3220/#2942) — injects the compiled motion CSS
// (push / pop / peek) into the live StackView. The animation DATA lives in a SHARED, feature-agnostic home
// (`@/shared/ui/kit/stackVizAnimations`) so BOTH consumers read ONE definition: this renderer AND a
// (later) `stack-viz` Designs builtin kit. `StackView`'s root carries the applying classes ({@link
// STACK_VIZ_ANIM_CLASSES}); its cells only stamp `data-op`. Mirrors matrixViewMotion / arrayViewMotion.
import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { STACK_VIZ_KIT_ID, STACK_VIZ_ANIMATIONS } from "@/shared/ui/kit/stackVizAnimations";

// Re-export the shared data so this renderer's public surface (and the algorithms barrel) is unchanged.
export { STACK_VIZ_KIT_ID, STACK_VIZ_ANIMATIONS };

/** The applying classes the renderer's root carries so the state-scoped rules match its cells. */
export const STACK_VIZ_ANIM_CLASSES: string = STACK_VIZ_ANIMATIONS.map((a) =>
  animClassName({ kit: STACK_VIZ_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS — produced ONCE from {@link STACK_VIZ_ANIMATIONS}. Pure. */
export const STACK_VIZ_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: STACK_VIZ_KIT_ID, animations: STACK_VIZ_ANIMATIONS }]),
);

const STYLE_ID = "bsc-stack-viz-animations";

/** Inject the compiled stack motion CSS into a dedicated managed `<style>` (idempotent). `doc` param'd for
 *  tests. Mirrors `ensureArrayViewMotion` on its own style id. */
export function ensureStackViewMotion(doc: Document = document): void {
  if (!STACK_VIZ_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== STACK_VIZ_MOTION_CSS) el.textContent = STACK_VIZ_MOTION_CSS;
}

// The `stack-viz` kit's MOTION library as DATA (#3266, epic #3171/#2942) — the push / pop / peek
// animations for the stack/queue/deque renderer, authored as {@link KitAnimation} data and compiled by
// the kit-motion engine. The FIFO/LIFO twin of the array/matrix/graph motion sets.
//
// ── WHY THIS LIVES IN shared/ui/kit ──────────────────────────────────────────────────────────────────
// Like the array (#3194) + matrix/graph (#3242) sets: two consumers in two features, one definition — the
// Algorithms StackView renderer (`features/algorithms/.../stackViewMotion.ts`) injects the compiled CSS,
// and the Designs seed can register `stack-viz` as a recoverable builtin kit (a later slice). Feature-
// agnostic viz-motion, so it lives HERE to avoid a designs↔algorithms cycle.
//
// STATE-TRIGGER SEAM (#3058): each selector IS the data-state StackView stamps on the active-end cell
// (`[data-op="push"]`, …) — so a rule fires exactly when a cell enters/leaves the active end.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The stack-visualization motion kit id — `.stack-viz-anim-<name>` + `@keyframes bsc-stack-viz-<name>`. */
export const STACK_VIZ_KIT_ID = "stack-viz";

/** The stack kit's animations as DATA — push (a cell drops in at the active end), pop (the cell leaving
 *  flashes as it goes), peek (a ring on the inspected cell). Token-based; the engine wraps each in
 *  `prefers-reduced-motion: no-preference`. The single source the StackView renderer + the (later)
 *  `stack-viz` Designs kit both consume. */
export const STACK_VIZ_ANIMATIONS: KitAnimation[] = [
  // push — a new entry drops in at the active end (scales up + fades in from the top).
  {
    name: "push",
    selector: '[data-op="push"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": { transform: "translateY(-10px) scale(0.7)", opacity: "0.25", "border-color": "var(--accent)" },
      "100%": { transform: "translateY(0) scale(1)", opacity: "1" },
    },
  },
  // pop — the entry now exposed at the active end flashes as the top one leaves.
  {
    name: "pop",
    selector: '[data-op="pop"]',
    duration: "400ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { "border-color": "var(--accent)", background: "color-mix(in oklch, var(--accent), var(--bg-elev) 60%)" },
      "100%": { background: "var(--bg-elev)" },
    },
  },
  // peek — a quick ring on the inspected cell (a read that doesn't move the ends).
  {
    name: "peek",
    selector: '[data-op="peek"]',
    duration: "450ms",
    easing: "var(--ease-standard)",
    set: { "z-index": "1" },
    keyframes: {
      "0%": { "box-shadow": "0 0 0 0 transparent" },
      "45%": { "box-shadow": "0 0 0 2px color-mix(in oklch, var(--state-wait), transparent 45%)" },
      "100%": { "box-shadow": "0 0 0 0 transparent" },
    },
  },
];

// Stage command bus — the thin router between Claude's standardized commands and a stage
// module's OWN behavior. A stage module is a self-contained plugin: it owns its state,
// result keying/accumulation, navigation, and persistence (it calls writeProjectFile
// inside its own save/confirm). The framework owns nothing here but the routing.
//
// A stage module registers itself here (registerStageModule) and the framework routes the
// standardized commands into it — never a module's internals. Pure + framework-free so it's
// unit-testable in isolation. (The render-preview module is the live consumer.)

export type StageCommand =
  | "run" | "save" | "confirm" | "restart" | "prev" | "next" | "goto" | "delete";

export const STAGE_COMMANDS: StageCommand[] =
  ["run", "save", "confirm", "restart", "prev", "next", "goto", "delete"];

export function isStageCommand(value: string): value is StageCommand {
  return (STAGE_COMMANDS as string[]).includes(value);
}

/** What a command handler receives: the project + free-form args parsed from the tag
 *  (e.g. `screen`, `mode`, `index`, `rid`). The pipeline interprets them. */
export interface StageCommandCtx {
  projectKey: string;
  args: Record<string, string>;
}

export type StageCommandHandler =
  (cmd: StageCommand, ctx: StageCommandCtx) => Promise<void> | void;

/** A stage module's command surface. One registration per stage id; the handler is the
 *  stage module's behavior for every command it supports (it may ignore ones it doesn't). */
export interface StageModule {
  id: string;
  command: StageCommandHandler;
}

const MODULES = new Map<string, StageModule>();

/** Register (or replace) a stage module's command module. Idempotent — last wins. */
export function registerStageModule(module: StageModule): void {
  MODULES.set(module.id, module);
}
export function hasStageModule(id: string): boolean {
  return MODULES.has(id);
}

export interface StageDispatchResult {
  ok: boolean;
  error?: string;
}

/**
 * Route a command to its stage module's module. Never throws: an unknown stage module or a
 * handler that throws resolves to a structured failure, so the tag-dispatch layer (and
 * any loop over commands) is safe to await.
 */
export async function dispatchStageCommand(
  id: string, cmd: StageCommand, ctx: StageCommandCtx,
): Promise<StageDispatchResult> {
  const mod = MODULES.get(id);
  if (!mod) return { ok: false, error: `no stage module registered for "${id}"` };
  try {
    await mod.command(cmd, ctx);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

/** Test helper — reset the module registry between cases. */
export function _resetStageModules(): void {
  MODULES.clear();
}

