import { describe, it, expect, beforeEach, vi, afterEach } from "vitest";
import { useAppStore } from "@/store";
import type { EndedInfo } from "@/store/types";

const done = (streamId = "api"): EndedInfo => ({ state: "done", streamId, summary: "2/2 complete", at: 1 });

describe("endedPanes — auto-end a finished worker (#920)", () => {
  beforeEach(() => {
    useAppStore.setState({ endedPanes: {}, paneStatus: {}, paneWasClaude: {}, disabledPanes: {}, restoreRequested: {} });
  });

  it("markPaneEnded records the resting state and drops the pane's live status", () => {
    useAppStore.setState({ paneStatus: { t0p1: "run" } });
    useAppStore.getState().markPaneEnded("t0p1", done());
    expect(useAppStore.getState().endedPanes["t0p1"]).toMatchObject({ state: "done", streamId: "api" });
    expect(useAppStore.getState().paneStatus["t0p1"]).toBeUndefined();
  });

  it("never re-marks an already-ended pane", () => {
    useAppStore.getState().markPaneEnded("t0p1", done("api"));
    const before = useAppStore.getState().endedPanes;
    useAppStore.getState().markPaneEnded("t0p1", { ...done("other"), state: "blocked" });
    expect(useAppStore.getState().endedPanes).toBe(before); // same ref — no churn, keeps first verdict
    expect(useAppStore.getState().endedPanes["t0p1"].streamId).toBe("api");
  });

  it("reopenPane clears the ended state so the worker can relaunch", () => {
    useAppStore.getState().markPaneEnded("t0p1", done());
    useAppStore.getState().reopenPane("t0p1");
    expect(useAppStore.getState().endedPanes["t0p1"]).toBeUndefined();
  });

  describe("crash recovery never re-opens an ended worker", () => {
    beforeEach(() => vi.useFakeTimers());
    afterEach(() => vi.useRealTimers());

    it("restoreSessionsFromCrash skips a pane in the ended state", () => {
      useAppStore.setState({
        tabs: [{ id: "t", name: "build", layout: "2×1", state: "idle", runId: 0 }] as never,
        paneWasClaude: { t0p0: true, t0p1: true },
        endedPanes: { t0p1: done() },
        restoreRequested: {},
      });

      const count = useAppStore.getState().restoreSessionsFromCrash();
      // ONE, not two. This used to assert 2 — "both were claude panes" — and then rely on the
      // staggered relaunch to drop the ended one at fire time. That gap is the bug the banner
      // exposed: the count and the act disagreed, so the offer advertised work it would not do.
      // The return value now means "how many will actually be restored".
      expect(count).toBe(1);
      vi.advanceTimersByTime(1000); // the staggered relaunch still runs, and still gates

      const restore = useAppStore.getState().restoreRequested;
      expect(restore["t0p0"]).toBe(true);       // live worker → relaunched
      expect(restore["t0p1"]).toBeUndefined();  // ended worker → NOT relaunched
    });
  });
});

// resumePaneSession (#glance-resume) — resume ONE dormant fleet/agent pane in place, non-disruptively.
import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "@/store";
import type { EndedInfo } from "@/store/types";

const ended = (streamId = "api"): EndedInfo => ({ state: "done", streamId, summary: "2/2 complete", at: 1 });

// A build tab that owns the `proj:*` identity ids (findPaneOwnerTab matches on paneIds).
const buildTab = () => [{
  id: "t", name: "Proj · build", layout: "2×1", state: "idle", runId: 0, kind: "build",
  paneIds: ["proj:director", "proj:api"],
}] as never;

describe("resumePaneSession (#glance-resume)", () => {
  beforeEach(() => {
    useAppStore.setState({
      tabs: buildTab(),
      endedPanes: {}, disabledPanes: {}, dormantPanes: {}, restoreRequested: {},
      paneStatus: {}, paneLastActivity: {},
    });
  });

  it("clears the pane's ended/disabled/dormant flags and stamps restoreRequested (→ claude --continue)", () => {
    useAppStore.setState({ endedPanes: { "proj:api": ended() }, disabledPanes: { "proj:api": true } });
    const ok = useAppStore.getState().resumePaneSession("proj:api");
    expect(ok).toBe(true);
    const s = useAppStore.getState();
    expect(s.endedPanes["proj:api"]).toBeUndefined();
    expect(s.disabledPanes["proj:api"]).toBeUndefined();
    expect(s.restoreRequested["proj:api"]).toBe(true);
  });

  it("returns false and changes nothing when no open tab hosts the pane id (caller falls back)", () => {
    const before = useAppStore.getState().restoreRequested;
    const ok = useAppStore.getState().resumePaneSession("gone:worker");
    expect(ok).toBe(false);
    expect(useAppStore.getState().restoreRequested).toBe(before); // untouched
  });

  it("touches ONLY the target pane — a live sibling in the same tab is left running", () => {
    useAppStore.setState({ endedPanes: { "proj:api": ended() }, paneStatus: { "proj:director": "run" } });
    useAppStore.getState().resumePaneSession("proj:api");
    const s = useAppStore.getState();
    // The director keeps its live status and never gets a restore request — no whole-tab remount.
    expect(s.paneStatus["proj:director"]).toBe("run");
    expect(s.restoreRequested["proj:director"]).toBeUndefined();
  });
});

