import { nudgeSizes } from "@/app/console/lib/terminalNudge";

describe("terminalNudge — nudgeSizes (#1221)", () => {
  it("shrinks by exactly one column for the transient, restores the true fitted size", () => {
    const s = nudgeSizes(80, 24)!;
    expect(s.transient).toEqual({ cols: 79, rows: 24 }); // delta != 0 → guaranteed SIGWINCH
    expect(s.restore).toEqual({ cols: 80, rows: 24 });    // net unchanged after the nudge
    // rows are untouched (avoids the #1158 input clip box)
    expect(s.transient.rows).toBe(s.restore.rows);
  });

  it("returns null when there's nothing safe to shrink", () => {
    expect(nudgeSizes(1, 24)).toBeNull();
    expect(nudgeSizes(0, 24)).toBeNull();
    expect(nudgeSizes(NaN, 24)).toBeNull();
  });
});

implementations.code:
// Terminal tuning shared across console panes.

import { clamp } from "@/shared/lib/core/math";

/**
 * Scrollback line budget for one pane, scaled down as the total mounted-pane
 * count across ALL tabs grows.
 *
 * xterm retains every scrollback line in renderer memory, so N panes each
 * holding a deep buffer multiplies fast — a 4×4 triage (16 panes) at a flat
 * 10k lines is ~160k buffered lines and a prime suspect for renderer OOM.
 * #187 made every tab's panes stay mounted (so xterm + scrollback survive tab
 * switches), which means a 2-tab × 16-pane workspace is now 32 mounted panes,
 * not 16. The buckets below preserve the single-tab budgets so existing
 * workflows don't regress, then extend downward for the cross-tab reality.
 *
 * @param paneCount total panes mounted across every tab in the workspace.
 */
export function scrollbackForPaneCount(paneCount: number): number {
  if (paneCount <= 1)  return 10000;
  if (paneCount <= 4)  return 6000;
  if (paneCount <= 9)  return 3000;
  if (paneCount <= 16) return 1500; // single 4×4 tab — unchanged
  if (paneCount <= 32) return 1000; // ~two heavy tabs
  return 500;                       // 33+ — large fleets across many tabs
}

/**
 * Sum every tab's `cols × rows` so {@link scrollbackForPaneCount} can size each
 * pane's buffer against the workspace-wide load, not just its own tab's grid.
 * Layout values that don't parse fall back to a 1×1 cell.
 */
export function totalMountedPaneCount(tabs: ReadonlyArray<{ layout: string }>): number {
  return tabs.reduce((sum, tab) => {
    const [c, r] = tab.layout.split("×").map(Number);
    return sum + (c || 1) * (r || 1);
  }, 0);
}

// ── Terminal font zoom (Ctrl++ / Ctrl+- / Ctrl+0) ──────────────────────────────

/** Default xterm font size (px) for console panes — matches the unzoomed baseline. */
export const DEFAULT_TERMINAL_FONT_SIZE = 12;
/** Legible floor: below this, rows fit but the text isn't worth reading. */
export const MIN_TERMINAL_FONT_SIZE = 8;
/** Practical ceiling so a single pane can't swallow the whole grid. */
export const MAX_TERMINAL_FONT_SIZE = 28;
/** Pixels added/removed per zoom step. */
export const TERMINAL_FONT_STEP = 1;

/**
 * Clamp a font size to the legible range, rounded to whole px. Non-finite input
 * (corrupt persisted value) falls back to the default rather than breaking xterm.
 */
export function clampFontSize(size: number): number {
  if (!Number.isFinite(size)) return DEFAULT_TERMINAL_FONT_SIZE;
  return clamp(Math.round(size), MIN_TERMINAL_FONT_SIZE, MAX_TERMINAL_FONT_SIZE);
}

/**
 * Resolve the next terminal font size when zooming by `steps` (e.g. +1 in, -1 out),
 * clamped to the legible range. Stepping past a bound is a no-op (stays clamped).
 */
export function adjustFontSize(current: number, steps: number): number {
  return clampFontSize(current + steps * TERMINAL_FONT_STEP);
}

tests.src:
import { describe, it, expect } from "vitest";
import {
  scrollbackForPaneCount,
  totalMountedPaneCount,
  clampFontSize,
  adjustFontSize,
  DEFAULT_TERMINAL_FONT_SIZE,
  MIN_TERMINAL_FONT_SIZE,
  MAX_TERMINAL_FONT_SIZE,
} from "@/app/console/lib/terminal";

describe("scrollbackForPaneCount", () => {
  it("keeps a deep buffer for a single pane", () => {
    expect(scrollbackForPaneCount(1)).toBe(10000);
  });

  it("scales scrollback down as the workspace grows", () => {
    const single = scrollbackForPaneCount(1);
    const quad   = scrollbackForPaneCount(4);
    const nine   = scrollbackForPaneCount(9);
    const grid16 = scrollbackForPaneCount(16);
    const heavy32 = scrollbackForPaneCount(32);
    const wide50  = scrollbackForPaneCount(50);
    expect(single).toBeGreaterThan(quad);
    expect(quad).toBeGreaterThan(nine);
    expect(nine).toBeGreaterThan(grid16);
    expect(grid16).toBeGreaterThan(heavy32);
    expect(heavy32).toBeGreaterThan(wide50);
  });

  it("preserves the single-tab 4×4 budget (no regression for the common case)", () => {
    expect(scrollbackForPaneCount(16)).toBe(1500);
  });

  it("trims further for cross-tab workspaces — 17+ panes drops below the 16-pane budget (#52 / #187)", () => {
    // Two heavy tabs (e.g. one triage + one fleet) shouldn't double the
    // workspace-wide scrollback budget vs. a single tab.
    expect(scrollbackForPaneCount(17)).toBeLessThan(scrollbackForPaneCount(16));
    // And large fleets across many tabs trim again.
    expect(scrollbackForPaneCount(33)).toBeLessThan(scrollbackForPaneCount(32));
  });
});

describe("totalMountedPaneCount", () => {
  it("sums every tab's grid size", () => {
    const tabs = [{ layout: "2×2" }, { layout: "4×4" }, { layout: "1×1" }];
    expect(totalMountedPaneCount(tabs)).toBe(4 + 16 + 1);
  });

  it("returns 0 for no tabs", () => {
    expect(totalMountedPaneCount([])).toBe(0);
  });

  it("falls back to 1×1 for an unparseable layout (robust against corrupt persisted state)", () => {
    expect(totalMountedPaneCount([{ layout: "garbage" }])).toBe(1);
  });
});

describe("clampFontSize", () => {
  it("leaves a size within range untouched", () => {
    expect(clampFontSize(14)).toBe(14);
  });

  it("clamps below the legible floor", () => {
    expect(clampFontSize(MIN_TERMINAL_FONT_SIZE - 5)).toBe(MIN_TERMINAL_FONT_SIZE);
  });

  it("clamps above the ceiling", () => {
    expect(clampFontSize(MAX_TERMINAL_FONT_SIZE + 10)).toBe(MAX_TERMINAL_FONT_SIZE);
  });

  it("rounds to whole pixels", () => {
    expect(clampFontSize(12.6)).toBe(13);
  });

  it("falls back to the default for non-finite input", () => {
    expect(clampFontSize(NaN)).toBe(DEFAULT_TERMINAL_FONT_SIZE);
    expect(clampFontSize(Infinity)).toBe(DEFAULT_TERMINAL_FONT_SIZE);
  });
});

describe("adjustFontSize", () => {
  it("steps up and down by whole pixels", () => {
    expect(adjustFontSize(12, +1)).toBe(13);
    expect(adjustFontSize(12, -1)).toBe(11);
  });

  it("stays clamped when stepping past a bound", () => {
    expect(adjustFontSize(MAX_TERMINAL_FONT_SIZE, +1)).toBe(MAX_TERMINAL_FONT_SIZE);
    expect(adjustFontSize(MIN_TERMINAL_FONT_SIZE, -1)).toBe(MIN_TERMINAL_FONT_SIZE);
  });
});

