  });

  it("keys manual-tab panes by their man:<tabId> identity ids with kind console", () => {
    const { panes, sessions } = buildPanePayload({
      tabs: [{ layout: "1×1", id: "tab-uuid" }],
      paneNames: {},
      paneCwds: { "man:tab-uuid:p0": "/repo" },
