// UI-kit pins (#2465) — the blueprint↔kit-store link. A blueprint REFERENCES a UI kit as a
// lockfile entry (`Blueprint.uiKit = { id, version, hash, source? }`, exact pins only) against the
// GLOBAL versioned kit store (`~/.base-studio-code/kits/<id>/<version>/`, the Rust `bsc ui release`
// CLI), so one copy serves every blueprint that pins it and the same kit is never downloaded twice.
//
//  · PACKAGED_UI_KIT_PIN — the packaged `bsc/react-ui` kit's pin (id/version/hash read from the
//    generated `@data/ui/react-ui-kit.meta.json` sidecar). Default-pinned onto every NEW blueprint
//    (`addBlueprint`); it resolves against the store's embedded fallback, so it needs no fetch.
//  · resolveUiKitPin — the resolve flow on blueprint open/import: local store lookup → fetch the
//    typed gist ONLY when `id@version` is missing → verify sha256 BEFORE the store write (a
//    mismatch is rejected loudly and nothing is stored). Never re-fetches an existing id@version.
//  · importKitByGistUrl — the authoring picker's import path: fetch a `component-kit` gist, derive
//    its store identity, add it to the store (trust-on-first-import; the returned pin then locks
//    the exact bytes for everyone downstream).
//
// Pure of React; store access goes through the generic `bsc` bridge (#2114), the same surface a
// live session reaches with `bsc ui release …` from its own shell.

import packagedKitMeta from "@data/ui/react-ui-kit.meta.json";
import { bsc, bscJson } from "@/shared/lib/core/bsc";
import { sha256Hex } from "@/shared/lib/core/sha256";
import { log } from "@/shared/lib/core/log";
import { fetchGistManifestText } from "@/features/planner/lib/gist/gist";
import { parseManifest } from "@/features/planner/lib/gist/manifest";
import type { Blueprint, BlueprintUiKit } from "@/features/planner/stages/blueprints";

/** A kit-store entry's manifest, as `bsc ui release list|get|add` emit it. */
export interface KitStoreManifest {
  id: string;
  version: string;
  sha256: string;
  kind: "component-kit" | "design-files";
  /** The typed-gist URL it was fetched from, or `"packaged"` for the embedded default. */
  source?: string;
}

/** The packaged default kit's pin — a FRESH object per call (pins live inside blueprint JSON, so
 *  handing out one shared instance would alias state across blueprints). */
export function packagedUiKitPin(): BlueprintUiKit {
  return { id: packagedKitMeta.id, version: packagedKitMeta.version, hash: packagedKitMeta.sha256 };
}

/** `id@version` — the store ref a pin resolves as. */
export function kitRef(pin: Pick<BlueprintUiKit, "id" | "version">): string {
  return `${pin.id}@${pin.version}`;
}

/** Every kit in the local store (incl. the packaged default). Empty when the bridge is absent. */
export async function listStoreKits(): Promise<KitStoreManifest[]> {
  return bscJson<KitStoreManifest[]>(null, ["ui", "release", "list"], []);
}

/** One store entry's manifest, or null when `id@version` isn't in the store. */
export async function getStoreKit(pin: Pick<BlueprintUiKit, "id" | "version">): Promise<KitStoreManifest | null> {
  return bscJson<KitStoreManifest | null>(null, ["ui", "release", "get", kitRef(pin)], null);
}

export type UiKitResolution =
  /** `cached` — the id@version was already in the store (zero downloads). */
  | { ok: true; cached: boolean }
  | { ok: false; error: string };

/**
 * Resolve a blueprint's UI-kit pin against the local store (#2465): store hit ⇒ done (an existing
 * `id@version` is NEVER re-fetched — immutable versions make the local copy valid forever); miss ⇒
 * fetch the typed gist at `pin.source`, verify its sha256 against `pin.hash` BEFORE anything is
 * written, and only then add it to the store. A hash mismatch (or a missing source) is a loud
 * `{ ok: false }` and the store is untouched. The `--sha256` handed to `bsc ui release add` makes the
 * Rust store re-verify, so the no-write-on-mismatch guarantee holds even if this caller is wrong.
 */
export async function resolveUiKitPin(pin: BlueprintUiKit, token = ""): Promise<UiKitResolution> {
  if (await getStoreKit(pin)) return { ok: true, cached: true };
  if (!pin.source) {
    return { ok: false, error: `UI kit ${kitRef(pin)} is not in the local kit store and the pin has no source to fetch it from` };
  }
  const raw = await fetchGistManifestText(pin.source, token);
  if (!raw.ok) return raw;
  const hash = await sha256Hex(raw.text);
  if (hash !== pin.hash.toLowerCase()) {
    return {
      ok: false,
      error: `UI kit ${kitRef(pin)} REJECTED: fetched content hashes to ${hash} but the pin expects ${pin.hash} — refusing to store it`,
    };
  }
  try {
    await bsc(
      null,
      ["ui", "release", "add", pin.id, pin.version, "--kind", "component-kit", "--sha256", pin.hash, "--source", pin.source],
      raw.text,
    );
  } catch (e) {
    return { ok: false, error: `UI kit ${kitRef(pin)} could not be stored: ${String(e)}` };
  }
  return { ok: true, cached: false };
}

/**
 * Fire-and-forget resolve for a blueprint being OPENED or IMPORTED — the store-slice wire point.
 * No pin ⇒ no-op (blueprints without one are unaffected); a failure is logged loudly (the
 * authoring picker additionally surfaces it inline).
 */
export function resolveBlueprintUiKit(bp: Pick<Blueprint, "name" | "uiKit"> | undefined, token = ""): void {
  const pin = bp?.uiKit;
  if (!pin) return;
  void resolveUiKitPin(pin, token).then(
    (res) => {
      if (!res.ok) log.error(`blueprint "${bp?.name ?? "?"}": ${res.error}`);
    },
    // Fire-and-forget: an unexpected throw must land in the log, never as an unhandled rejection (#2515).
    (e) => log.error(`blueprint "${bp?.name ?? "?"}": UI-kit resolve failed: ${String(e)}`),
  );
}

/** The store-identity block a published kit gist carries in its payload (`payload.store`). */
export interface KitStoreIdentity {
  id: string;
  version: string;
}

const STORE_ID_RE = /^[a-z0-9][a-z0-9-]*\/[a-z0-9][a-z0-9-]*$/;
const slug = (s: string): string =>
  s.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "") || "kit";

/** Derive a fetched kit gist's store identity: the stamped `payload.store` when present + valid
 *  (what `publishKitToGist` writes since #2465), else `<gist-owner>/<manifest-id>` slugs with the
 *  envelope's own version — so pre-#2465 kit gists stay importable. Exported for tests. */
export function deriveKitIdentity(
  manifest: { id?: unknown; version?: unknown; payload?: unknown },
  owner?: string,
): KitStoreIdentity {
  const store = (manifest.payload as { store?: { id?: unknown; version?: unknown } } | undefined)?.store;
  const stamped = typeof store?.id === "string" ? store.id : "";
  const id = STORE_ID_RE.test(stamped)
    ? stamped
    : `${slug(owner ?? "gist")}/${slug(typeof manifest.id === "string" ? manifest.id : "kit")}`;
  const version =
    (typeof store?.version === "string" && store.version) ||
    (typeof manifest.version === "string" && manifest.version) ||
    "1.0.0";
  return { id, version };
}

export type KitImportResult =
  | { ok: true; pin: BlueprintUiKit }
  | { ok: false; error: string };

/**
 * Import a kit by gist URL into the global store, returning the pin to record on the blueprint
 * (#2465, the authoring picker's import path). Fetch → validate it IS a `component-kit` manifest →
 * derive the store identity → add to the store (the store enforces id@version immutability — a
 * conflict with different content is surfaced, not overwritten) → pin `{ id, version, hash, source }`.
 */
export async function importKitByGistUrl(url: string, token = ""): Promise<KitImportResult> {
  const raw = await fetchGistManifestText(url, token);
  if (!raw.ok) return raw;
  const parsed = parseManifest(raw.text);
  if (!parsed.ok) return parsed;
  if (parsed.manifest.kind !== "component-kit") {
    return { ok: false, error: `that gist holds a '${parsed.manifest.kind}', not a component kit` };
  }
  const { id, version } = deriveKitIdentity(parsed.manifest, raw.owner);
  const hash = await sha256Hex(raw.text);
  try {
    await bsc(null, ["ui", "release", "add", id, version, "--kind", "component-kit", "--source", url], raw.text);
  } catch (e) {
    return { ok: false, error: `could not add ${id}@${version} to the kit store: ${String(e)}` };
  }
  return { ok: true, pin: { id, version, hash, source: url } };
}

tests.src:
// UI-kit pin machinery tests (#2465): the packaged default pin, the default-pin on new-blueprint
// authoring (existing/no-pin blueprints unaffected), and the resolve flow — store hit ⇒ zero
// downloads · miss ⇒ fetch + sha256-verify BEFORE the store write · hash mismatch ⇒ loud rejection
// with nothing stored. The fetch (github_request) and the store (`bsc ui release …`) are both behind
// the mocked Tauri `invoke`, so every path is asserted at the wire.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { createHash, webcrypto } from "node:crypto";
import packagedKitMeta from "@data/ui/react-ui-kit.meta.json";
import {
  packagedUiKitPin, kitRef, resolveUiKitPin, importKitByGistUrl, deriveKitIdentity, listStoreKits,
} from "@/features/planner/blueprints/uiKitPin";
import type { BlueprintUiKit } from "@/features/planner/stages/blueprints";
import { makeBlueprints } from "@/features/planner/stages/blueprints";
import { useAppStore } from "@/store";

// sha256Hex rides WebCrypto; the jsdom test env may not expose `crypto.subtle` — back it with
// Node's webcrypto so the digests are the real thing (identical to the Rust store's sha2).
if (!globalThis.crypto?.subtle) vi.stubGlobal("crypto", webcrypto);

const sha256 = (text: string) => createHash("sha256").update(text, "utf8").digest("hex");

/** Route the mocked `invoke` — `bsc ui release get` returns `storeGet`, github_request returns `gist`,
 *  everything else null. Records nothing itself; assertions read vi.mocked(invoke).mock.calls. */
function wire({ storeGet = null as unknown, gist = null as unknown } = {}) {
  vi.mocked(invoke).mockImplementation(async (cmd, payload) => {
    const p = payload as { args?: string[] } | undefined;
    if (cmd === "bsc" && p?.args?.[0] === "ui" && p.args[1] === "release") {
      if (p.args[2] === "get") return JSON.stringify(storeGet);
      if (p.args[2] === "add") return JSON.stringify({ ok: true });
      if (p.args[2] === "list") return JSON.stringify(storeGet ? [storeGet] : []);
    }
    if (cmd === "github_request") return gist;
    return null;
  });
}

const addCalls = () =>
  vi.mocked(invoke).mock.calls.filter((c) => c[0] === "bsc" && (c[1] as { args?: string[] })?.args?.[2] === "add");
const fetchCalls = () => vi.mocked(invoke).mock.calls.filter((c) => c[0] === "github_request");

const GIST_URL = "https://gist.github.com/acme/0123456789abcdef";
const gistWith = (text: string, owner = "acme") => ({
  files: { "extension.json": { content: text, filename: "extension.json" } },
  owner: { login: owner },
});

beforeEach(() => {
  vi.mocked(invoke).mockClear();
});

describe("packaged default pin (#2465)", () => {
  it("mirrors the generated meta sidecar (id/version/hash) and mints fresh objects", () => {
    const pin = packagedUiKitPin();
    expect(pin).toEqual({ id: packagedKitMeta.id, version: packagedKitMeta.version, hash: packagedKitMeta.sha256 });
    expect(pin.id).toBe("bsc/react-ui");
    expect(pin.hash).toMatch(/^[0-9a-f]{64}$/);
    expect(packagedUiKitPin()).not.toBe(pin); // fresh per call — pins never alias across blueprints
    expect(kitRef(pin)).toBe("bsc/react-ui@1.0.0");
  });
});

describe("default-pin on new-blueprint authoring", () => {
  it("addBlueprint pins the packaged kit; built-ins and no-pin imports stay unpinned", () => {
    useAppStore.setState({ blueprints: makeBlueprints(), activeBlueprintId: "default" });
    // Grandfathering: no built-in library blueprint grew a pin.
    for (const b of useAppStore.getState().blueprints) expect(b.uiKit).toBeUndefined();

    const id = useAppStore.getState().addBlueprint();
    const created = useAppStore.getState().blueprints.find((b) => b.id === id)!;
    expect(created.uiKit).toEqual(packagedUiKitPin());
    useAppStore.getState().removeBlueprint(id);

    // An imported blueprint WITHOUT a pin is untouched (no default injected after creation time)…
    const plain = useAppStore.getState().blueprints.find((b) => b.id === "default")!;
    const importedId = useAppStore.getState().importBlueprint(plain);
    expect(useAppStore.getState().blueprints.find((b) => b.id === importedId)!.uiKit).toBeUndefined();
    useAppStore.getState().removeBlueprint(importedId);

    // …and an imported blueprint WITH a pin keeps it verbatim.
    const pin: BlueprintUiKit = { id: "acme/neon", version: "1.0.0", hash: sha256("x"), source: GIST_URL };
    const pinnedId = useAppStore.getState().importBlueprint({ ...plain, uiKit: pin });
    expect(useAppStore.getState().blueprints.find((b) => b.id === pinnedId)!.uiKit).toEqual(pin);
    useAppStore.getState().removeBlueprint(pinnedId);
  });

  it("opening a pinned blueprint fires the store resolve (setActiveBlueprint)", async () => {
    const plain = makeBlueprints().find((b) => b.id === "default")!;
    const pinned = { ...plain, id: "bp-pinned", uiKit: packagedUiKitPin() };
    useAppStore.setState({ blueprints: [plain, pinned], activeBlueprintId: "default" });
    wire({ storeGet: { id: "bsc/react-ui", version: "1.0.0", sha256: packagedKitMeta.sha256, kind: "component-kit", source: "packaged" } });
    useAppStore.getState().setActiveBlueprint("bp-pinned");
    await vi.waitFor(() => {
      const gets = vi.mocked(invoke).mock.calls.filter((c) => c[0] === "bsc" && (c[1] as { args?: string[] })?.args?.[2] === "get");
      expect(gets.length).toBeGreaterThan(0);
      expect((gets[0][1] as { args: string[] }).args).toEqual(["ui", "release", "get", "bsc/react-ui@1.0.0"]);
    });
    // Cached in the store ⇒ zero downloads, nothing added.
    expect(fetchCalls()).toHaveLength(0);
    expect(addCalls()).toHaveLength(0);
    useAppStore.setState({ activeBlueprintId: "default" });
  });
});

describe("resolveUiKitPin — the resolve flow", () => {
  const text = JSON.stringify({ manifest: 1, kind: "component-kit", id: "neon", name: "Neon", version: "2.0.0", payload: {} }, null, 2);
  const pin = (): BlueprintUiKit => ({ id: "acme/neon", version: "2.0.0", hash: sha256(text), source: GIST_URL });

  it("store hit ⇒ cached, never re-fetched", async () => {
    wire({ storeGet: { id: "acme/neon", version: "2.0.0", sha256: sha256(text), kind: "component-kit" } });
    const res = await resolveUiKitPin(pin());
    expect(res).toEqual({ ok: true, cached: true });
    expect(fetchCalls()).toHaveLength(0);
    expect(addCalls()).toHaveLength(0);
  });

  it("miss ⇒ fetches the source gist, verifies the hash, and writes the store entry", async () => {
    wire({ storeGet: null, gist: gistWith(text) });
    const res = await resolveUiKitPin(pin(), "tok");
    expect(res).toEqual({ ok: true, cached: false });
    expect(fetchCalls()).toHaveLength(1);
    const [, payload] = addCalls()[0];
    const { args, stdin } = payload as { args: string[]; stdin: string };
    expect(args).toEqual(["ui", "release", "add", "acme/neon", "2.0.0", "--kind", "component-kit", "--sha256", sha256(text), "--source", GIST_URL]);
    expect(stdin).toBe(text); // the EXACT fetched bytes are what gets stored
  });

  it("hash mismatch ⇒ loud rejection, store untouched", async () => {
    wire({ storeGet: null, gist: gistWith(text + "tampered") });
    const res = await resolveUiKitPin(pin());
    expect(res.ok).toBe(false);
    if (!res.ok) expect(res.error).toMatch(/REJECTED.*refusing to store/s);
    expect(addCalls()).toHaveLength(0);
  });

  it("miss without a source ⇒ a loud, actionable error", async () => {
    wire({ storeGet: null });
    const noSource: BlueprintUiKit = { id: "acme/neon", version: "2.0.0", hash: sha256(text) };
    const res = await resolveUiKitPin(noSource);
    expect(res.ok).toBe(false);
    if (!res.ok) expect(res.error).toContain("no source");
    expect(fetchCalls()).toHaveLength(0);
  });

  it("a store-write refusal (immutability) surfaces instead of passing silently", async () => {
    vi.mocked(invoke).mockImplementation(async (cmd, payload) => {
      const p = payload as { args?: string[] } | undefined;
      if (cmd === "bsc" && p?.args?.[2] === "get") return "null";
      if (cmd === "bsc" && p?.args?.[2] === "add") throw new Error("already exists with different content");
      if (cmd === "github_request") return gistWith(text);
      return null;
    });
    const res = await resolveUiKitPin(pin());
    expect(res.ok).toBe(false);
    if (!res.ok) expect(res.error).toContain("could not be stored");
  });
});

describe("importKitByGistUrl — the picker's import path", () => {
  const kitManifest = (extra: object = {}) =>
    JSON.stringify({
      manifest: 1, kind: "component-kit", id: "neon", name: "Neon", version: "3.1.0",
      payload: { kit: { id: "neon", name: "Neon" }, components: [], ...extra },
    }, null, 2);

  it("adds to the store under the STAMPED identity and returns the matching pin", async () => {
    const text = kitManifest({ store: { id: "acme/neon", version: "3.1.0" } });
    wire({ storeGet: null, gist: gistWith(text) });
    const res = await importKitByGistUrl(GIST_URL);
    expect(res.ok).toBe(true);
    if (!res.ok) return;
    expect(res.pin).toEqual({ id: "acme/neon", version: "3.1.0", hash: sha256(text), source: GIST_URL });
    const { args, stdin } = addCalls()[0][1] as { args: string[]; stdin: string };
    expect(args.slice(2, 5)).toEqual(["add", "acme/neon", "3.1.0"]);
    expect(stdin).toBe(text);
  });

  it("falls back to <owner>/<manifest-id> for a pre-#2465 kit gist", async () => {
    const text = kitManifest();
    wire({ storeGet: null, gist: gistWith(text, "Acme Corp") });
    const res = await importKitByGistUrl(GIST_URL);
    expect(res.ok).toBe(true);
    if (res.ok) expect(res.pin.id).toBe("acme-corp/neon");
  });

  it("rejects a gist that is not a component kit", async () => {
    const text = JSON.stringify({ manifest: 1, kind: "blueprint", id: "b", name: "B", version: "1", payload: {} });
    wire({ storeGet: null, gist: gistWith(text) });
    const res = await importKitByGistUrl(GIST_URL);
    expect(res.ok).toBe(false);
    if (!res.ok) expect(res.error).toContain("not a component kit");
    expect(addCalls()).toHaveLength(0);
  });

  it("deriveKitIdentity prefers a VALID stamped identity, else slugs owner/id", () => {
    expect(deriveKitIdentity({ id: "neon", version: "1.2.3", payload: { store: { id: "acme/neon", version: "9.0.0" } } }, "other"))
      .toEqual({ id: "acme/neon", version: "9.0.0" });
    // An invalid stamped id (not publisher-scoped) falls back to the derived one.
    expect(deriveKitIdentity({ id: "neon", version: "1.2.3", payload: { store: { id: "NOT VALID" } } }, "Acme"))
      .toEqual({ id: "acme/neon", version: "1.2.3" });
    expect(deriveKitIdentity({ id: "My Kit!" }, undefined)).toEqual({ id: "gist/my-kit", version: "1.0.0" });
  });
});

describe("listStoreKits", () => {
  it("parses the bridge list and degrades to [] when the bridge is absent", async () => {
    wire({ storeGet: { id: "bsc/react-ui", version: "1.0.0", sha256: "h", kind: "component-kit", source: "packaged" } });
    expect(await listStoreKits()).toEqual([{ id: "bsc/react-ui", version: "1.0.0", sha256: "h", kind: "component-kit", source: "packaged" }]);
    vi.mocked(invoke).mockRejectedValue(new Error("no bridge"));
    expect(await listStoreKits()).toEqual([]);
  });
});

implementations.code:
// Pure, non-mutating immutable-update helpers for the Zustand slices (#1704).
//
// The slices repeat the same immutable idioms hundreds of times — `{ ...map, [key]: val }` to set a
// record entry, `const n = { ...map }; delete n[key]` to drop one, and `arr.map((x, i) => i === idx
// ? { ...x, ...patch } : x)` to patch one array item. These helpers name those idioms so the call
// sites read by intent. Each returns a NEW value and never mutates its argument, so they're safe to
// use directly inside a Zustand `set((s) => …)` updater.

/** Return a NEW record with `key` set to `value`; the input map is not mutated. */
export function setMapEntry<K extends PropertyKey, V>(
  map: Record<K, V>,
  key: K,
  value: V,
): Record<K, V> {
  return { ...map, [key]: value } as Record<K, V>;
}

/** Return a NEW record with `key` removed; the input map is not mutated. A missing key is a no-op. */
export function deleteMapEntry<K extends PropertyKey, V>(
  map: Record<K, V>,
  key: K,
): Record<K, V> {
  const next: Record<K, V> = { ...map };
  delete (next as Partial<Record<K, V>>)[key];
  return next;
}

/** Return a NEW record with every key in `keys` removed; the input map is not mutated. Missing keys
 *  are no-ops. */
export function deleteMapEntries<K extends PropertyKey, V>(
  map: Record<K, V>,
  keys: Iterable<K>,
): Record<K, V> {
  const next: Record<K, V> = { ...map };
  for (const key of keys) delete (next as Partial<Record<K, V>>)[key];
  return next;
}

/** Return a NEW array with the item at `index` shallow-merged with `patch`; the input array is not
 *  mutated. An out-of-range index leaves the array unchanged (a fresh copy with identical items). */
export function updateArrayItem<T extends object>(
  arr: T[],
  index: number,
  patch: Partial<T>,
): T[] {
  return arr.map((item, i) => (i === index ? { ...item, ...patch } : item));
}

