import { useEffect } from "react";
import { useAppStore } from "@/store";

/**
 * Report the navigated ENTITY label for a graph to the titlebar location crumb (#3041) — the thing you're
 * INSIDE the graph: the drilled project (Glance), the entered team (Teams), the active kit (Components),
 * the active language (Algorithms). `key` is the page id (`glance`/`teams`/`designs`/`algorithms`);
 * `label` is the current entity name, `""` when none (e.g. a graph overview). `locationCrumb` appends it
 * after the page name, so the crumb reads e.g. "Planner — Components — react-ui".
 *
 * The graph resolves the label itself (it has the local selection + the data), so the store just carries
 * the resolved string — App.tsx needs no per-graph knowledge. The store write is idempotent, so calling
 * this every render is cheap.
 */
export function useCrumbEntity(key: string, label: string): void {
  const setCrumbEntity = useAppStore((s) => s.setCrumbEntity);
  // Block body (not `() => setCrumbEntity(...)`) so the effect returns undefined — an implicit return of
  // the action's value would be mistaken for a cleanup fn ("destroy is not a function" on unmount).
  useEffect(() => { setCrumbEntity(key, label); }, [key, label, setCrumbEntity]);
}

// useDebugChannel (#3437, epic #3260) — answer `bsc debug` from the live view, and ACK it.
//
// THE ROUND TRIP
//   bsc debug → request file → Rust watcher → `bsc://debug` → HERE → inspect → `debug_ack` → reply
//
// This is the thin adapter: it supplies the real DOM capabilities and ALWAYS acks — success or a stated
// error. Silence would strand the Rust waiter until its timeout and surface as "the frontend did not
// answer", sending someone to debug the channel instead of their actual bug. The decisions live in the
// pure `debugBridge.ts`.
//
// SEEING INTO THE PREVIEW
// A preview iframe is an OPAQUE origin (`sandbox="allow-scripts"`, no `allow-same-origin`), so
// `contentDocument` is null and nothing here can read it. That is a real trust boundary and is not
// weakened: the pan/zoom engine is ASKED to describe itself over `postMessage` (`{__probe:1}`), and a
// preview that never answers is reported as silent — which is itself the diagnosis.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { mountedPreviewFrames } from "@/features/designs";
import { log } from "@/shared/lib/core/log";
import {
  inspectDebug, readStyleValue, REPORTED_STYLES,
  type DebugRequest, type DebugResult, type EngineProbe, type InspectDeps,
} from "@/app/debugBridge";

/** How long to wait for one preview engine's `__probeReply`. Short: the engine answers in the same tick
 *  when it is alive, so anything longer only delays reporting a SILENT engine — the interesting case. */
const ENGINE_PROBE_MS = 250;

/** Ask one preview's engine to describe itself; `null` when it does not answer in time. */
function probeEngine(iframe: HTMLIFrameElement): Promise<EngineProbe | null> {
  const win = iframe.contentWindow;
  if (!win) return Promise.resolve(null);
  return new Promise((resolve) => {
    let done = false;
    const finish = (v: EngineProbe | null) => {
      if (done) return;
      done = true;
      window.removeEventListener("message", onMsg);
      clearTimeout(timer);
      resolve(v);
    };
    const onMsg = (e: MessageEvent) => {
      // Correlate by SOURCE WINDOW, as the preview frame + runtime probe already do (#2908): several
      // previews can be mounted, and taking the first reply would attribute one engine's state to another.
      if (e.source !== win) return;
      const d = e.data as { __probeReply?: EngineProbe } | null;
      if (d?.__probeReply) finish(d.__probeReply);
    };
    const timer = setTimeout(() => finish(null), ENGINE_PROBE_MS);
    window.addEventListener("message", onMsg);
    try {
      win.postMessage({ __probe: 1 }, "*");
    } catch {
      finish(null); // a cross-origin refusal is "no answer", not a crash
    }
  });
}

/** The real-DOM capability set handed to the pure inspector. */
function liveDeps(): InspectDeps {
  return {
    at: (x, y) => document.elementFromPoint(x, y),
    rectOf: (el) => {
      const r = el.getBoundingClientRect();
      return { x: r.x, y: r.y, width: r.width, height: r.height };
    },
    stylesOf: (el) => {
      const cs = getComputedStyle(el);
      const out: Record<string, string> = {};
      for (const k of REPORTED_STYLES) out[k] = readStyleValue((prop) => cs.getPropertyValue(prop), k);
      return out;
    },
    query: (selector) => Array.from(document.querySelectorAll(selector)),
    frames: () => mountedPreviewFrames(),
    probeEngine,
  };
}

/**
 * Listen for `bsc://debug` and answer it. Mounted once by the shell.
 *
 * An invalid selector is a STATED error, not a crash: `querySelectorAll` throws on bad syntax, and the
 * caller needs "that selector is malformed" rather than a timeout.
 */
export function useDebugChannel(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<DebugRequest & { id: string }>("bsc://debug", (e) => {
      const { id, ...req } = e.payload;
      void (async () => {
        let result: DebugResult | null = null;
        let error: string | null = null;
        try {
          result = await inspectDebug(req as DebugRequest, liveDeps());
        } catch (err) {
          error = err instanceof Error ? err.message : String(err);
        }
        if (disposed) return;
        try {
          await invoke("debug_ack", { ack: { id, ...(error ? { error } : { result }) } });
        } catch (err) {
          // The waiter will time out; log so the failure is attributable rather than mysterious.
          log.error(`debug: could not ack ${id}: ${String(err)}`);
        }
      })();
    });
    return () => {
      disposed = true;
      void un.then((f) => f());
    };
  }, []);
}

// The designer-loop PUMP (#3292/#3304, epic #3260) — the app-side driver that keeps the live Design Studio
// session iterating on a `bsc loop`. It is to a designer loop what `useDirectorPump` is to a fleet: poll →
// decide (a pure decider) → actuate. It drives the LIVE PTY (not a headless agent) because the designer
// live-restyles the RUNNING app — the actor has to be the running session.
//
// TWO MODES over one poll:
//  · INTERACTIVE (#3292, the default) — on the DRIVER's turn post "continue" and inject a GENERIC
//    next-change prompt; the human picks what gets worked on by talking to the session.
//  · OVERNIGHT / QUEUE (#3304) — opt-in, started from the banner. The run carries a ranked directive
//    queue built ONCE from the design system's own measured gaps (`buildDesignerQueue` over
//    `bsc ui components --coverage` + `bsc ui resolve`), and each driver turn captures a fresh
//    `bsc shot`, posts the directive as the driver's turn (shot attached), injects it, and advances the
//    cursor. It stops on the directive ceiling or when the queue drains.
//
// One tick: find the open `driver ↔ designer` loop (`bsc loop list`), read its turns (`bsc loop show`), and
// decide. On a stall either mode re-injects; otherwise it waits — the turn-flip the designer causes by
// recording is the "prompt me again" signal, so the pump never floods.
//
// STOPPING (the property that matters most for an unattended run). Four independent brakes, so no single
// failure leaves a loop spending money:
//  1. `bsc loop stop` — the banner's Stop pill, out-of-band, reachable at any time.
//  2. The pump's own ceiling — `decideOvernightAction` returns `stop` at the directive cap or on a drained
//     queue, and the pump then requests the halt. Because that verdict is recomputed every tick from
//     durable state, a swallowed CLI error simply RETRIES on the next tick rather than being lost.
//  3. The loop store's `--max-turns`/`--budget`, enforced inside `say` — durable, and it outlives this
//     process, so even a killed app cannot leave the loop runnable.
//  4. The run state is never persisted, so overnight mode cannot auto-start or survive a restart.
// The local run state is cleared only once the loop is OBSERVABLY gone, so a "stopping" run never silently
// hands its still-open loop back to the interactive path (which has no ceiling of its own).

//
// INERT since #app-stops-pushing-prompts. Its body drove the designer's iteration loop by typing each directive into the design-studio session. REMOVED WITH THE LOOP: the maintainer accepted that cost explicitly rather than carve out an exception, because an exception here is the app pushing prompts on a schedule, which is the whole of what this directive forbids.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime — the shape
// useFleetGate took for the same reason.

/** Does nothing. See the note above. */
export function useDesignerLoopPump(): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// The director pump (#366, #369, #371): drives the fleet's async-integrator "director"
// session so it does not just idle after its kickoff. Two delivery paths, injected via
// pty_write into the director pane:
//
//  1. PENDING WORKER QUESTIONS (state-based) -- unanswered `bsc-ask` questions are
//     re-derived from the FULL coord log every tick (ingestCoordLog -> state.asking), so a
//     question is delivered even if it was logged before the pump first saw the director or
//     across an app restart. Each (pane, ask) is surfaced once; the key is pruned when the
//     ask is answered/woken so a re-ask re-surfaces. Delivered when the director is idle, or
//     after ASK_FALLBACK_MS even if it is not (the TUI may never trip the 1.5s idle gate;
//     Claude Code queues input typed mid-turn). This is the must-not-drop case.
//  2. NOTIFICATIONS + HEARTBEAT (cursor-based) -- landed/blocked/failed activity and the
//     periodic sweep, via decideDirectorAction (idle-gated).
//
// Mounted once in ConsoleWorkspace (which stays mounted across screens). Pure logic lives in
// directorDrive.ts + coordination.ts; this is the thin Tauri/React actuator.
//
// INERT since #app-stops-pushing-prompts. Its body polled coord.log and typed pending asks, briefs, requests and routed actions into the director's pane. The events are still WRITTEN to coord.log by the bsc-* emitters; the director reads them on its own cadence instead of being poked.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime — the shape
// useFleetGate took for the same reason.

import type { RefObject } from "react";

/** Does nothing. See the note above. */
export function useDirectorPump(_paneStatusesRef: RefObject<Record<string, "run" | "on" | "idle">>): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// useDockBack (#3919) — the main window's half of "drag a torn-off tab home".
//
// A detached window cannot deliver its drop to this window's DOM: the tab drag is HTML5 drag-and-drop,
// scoped to one webview (#3917). So it emits over the Tauri app-global bus instead, and this clears the
// detached flag — which is what makes the tab reappear in its persisted place (`usePageTabs` filters the
// strip by `detachedSections`).
//
// Idempotent by construction: `setSectionDetached(..., false)` filters an id out of a list, so the event
// arriving alongside the window's own `tauri://destroyed` re-dock (the pre-existing backstop) is harmless.
import { useEffect } from "react";
import { useAppStore } from "@/store";
import { onDockBack } from "@/shared/lib/core/dockBack";

/** Install the dock-back listener. Main window only — a detached window must not re-dock its own page. */
export function useDockBack(enabled: boolean): void {
  const setSectionDetached = useAppStore((s) => s.setSectionDetached);
  useEffect(() => {
    if (!enabled) return;
    let unlisten: (() => void) | undefined;
    let cancelled = false;
    void onDockBack(({ page, section }) => setSectionDetached(page, section, false)).then((fn) => {
      // The listener resolves asynchronously; if the effect already tore down, drop it immediately rather
      // than leaking a subscription onto an unmounted shell.
      if (cancelled) fn();
      else unlisten = fn;
    });
    return () => { cancelled = true; unlisten?.(); };
  }, [enabled, setSectionDetached]);
}

