// The runtime fault-fix loop actuator (#2265, part of #2258). Polls each live project's runtime-fault
// store (`bsc errors list --unresolved --json`, the errordb #2260) on a slow cadence and, when the
// per-project auto-triage toggle is ON, routes a bounded, deduped set of fixes into that project's
// DIRECTOR pane — which captures + assigns each via the existing coordination emitters (bsc-issue →
// bsc-assign) and resolves it on land. The gate/dedup/rate-limit decisions are the pure
// `planFaultDispatch` (shared/lib/fleet/faultTriage.ts); this is the thin Tauri/React poll+inject layer,
// mounted once in ConsoleWorkspace (stays mounted across screens) beside useDirectorPump / useCoordinator.
// It lives in app/console (not shared/) because it reads the app's pane-identity + director-drive state.
//
// Projects with the toggle OFF (the default) are SURFACE-ONLY here — nothing is dispatched; the fault
// count still shows on the Glance node (useGlanceFaults). A project with no live director pane is also
// effectively surface-only (there's nowhere to route), which is the correct degrade.
//
// INERT since #app-stops-pushing-prompts. Its entire body was a poll that dispatched threshold-crossing runtime faults into the owning lane's pane. The fault store (errordb) is unchanged and the director protocol already tells the director to read it on its own cadence with `bsc errors list --unresolved`.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime. Inert-but-
// exported is the shape useFleetGate took for the same reason when its launch pump was killed —
// deleting the hook is not the fix, doing nothing is.

/** Does nothing. See the note above. */
export function useFaultTriage(): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// useFleetDirectorBridge (#architect-creates-a-director-with-discovery) — apply a
// `bsc fleet director new` request and ACK it.
//
// THE ROUND TRIP
//   bsc fleet director new <key> → request file → Rust watcher (resolves the project, refuses a live
//   director, seeds prompts/director-kickoff.md) → `bsc://fleet-director` → HERE → fleetStartProject
//   → `fleet_director_ack`
//
// A thin adapter: the DECISION lives in `fleetDirectorBridge.ts`, unit-testable without Tauri.
//
// THIS IS NOT AN INJECTION PATH. The director's context is BAKED INTO THE LAUNCH as claude's
// initial-message argument — the same delivery the kickoff doc always used. Nothing is typed into a
// running session, and `injectCallers.test.ts` stays green on its empty set.
//
// WHY THE DOC IS READ HERE RATHER THAN AT LAUNCH (#the-director-launches-with-no-kickoff-prompt)
// `fleetStartProject` seeds the kickoff as a doc PATH, which TerminalView resolves once inside its
// launch effect. That is the route whose silent-loss failure is documented on the `startupPrompt`
// prop — the one that left every debug session "a bare `claude` with nothing to do" until debug and
// studio sessions were migrated off it. The director never was.
//
// So this resolves the doc to text FIRST and hands it to `applyDirectorNew`, which seeds it before any
// pane exists. `read_document` failing is not fatal: the launch proceeds and the doc route stays as
// the fallback, because a director delivered the old way beats no director at all.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { scriptDocRelpath } from "@/features/planner/session/planningSession";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import { applyDirectorNew, type DirectorRequest, type DirectorAck } from "@/app/fleetDirectorBridge";

/** The hub-relative kickoff every director launch reads, resolved in Rust before the emit. */
const KICKOFF_RELPATH = "prompts/director-kickoff.md";

/** Listen for `bsc://fleet-director` and launch it. Mounted once by the shell. */
export function useFleetDirectorBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<DirectorRequest>("bsc://fleet-director", (e) => {
      const req = e.payload;
      void (async () => {
        // Resolve the kickoff BEFORE the launch. A failure is logged and carried as `undefined` — the
        // launch still happens and falls back to the doc route rather than refusing to create the
        // director the architect asked for.
        let kickoffText: string | undefined;
        try {
          const relpath = scriptDocRelpath(sanitizeProjectKey(req.projectKey ?? ""), KICKOFF_RELPATH);
          const text = await invoke<string>("read_document", { relpath });
          kickoffText = typeof text === "string" && text.trim() ? text : undefined;
          if (!kickoffText) log.warn(`fleet director ${req.id}: ${relpath} is empty — falling back to the doc route`);
        } catch (err) {
          log.warn(`fleet director ${req.id}: kickoff read failed (${String(err)}) — falling back to the doc route`);
        }

        let ack: DirectorAck;
        try {
          ack = applyDirectorNew(
            req,
            {
              // Read off a LIVE getState, not a captured snapshot — zustand hands out a new object per
              // update, so a stale closure could launch against an older tab list.
              fleetStartProject: (name, fleet, key, paths) =>
                useAppStore.getState().fleetStartProject(name, fleet, key, paths),
              seedStartupPromptText: (paneId, text) =>
                useAppStore.setState((s) => ({
                  paneStartupPromptText: { ...s.paneStartupPromptText, [paneId]: text },
                })),
            },
            kickoffText,
          );
        } catch (err) {
          ack = {
            id: req.id,
            error: `fleet director threw: ${err instanceof Error ? err.message : String(err)}`,
            created: false,
          };
          log.error(`fleet director ${req.id} threw: ${String(err)}`);
        }
        void invoke("fleet_director_ack", { ack: { ...ack, id: req.id } }).catch((e2) => {
          // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
          log.error(`fleet_director_ack failed for ${req.id}: ${String(e2)}`);
        });
      })();
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// The launch pump (#3931 slice 3) — start a HELD stream once its upstreams land.
//
// The gate (streamGate.ts) decides at resume time which streams may start; without a pump the held ones
// would stay held until the user pressed Resume again. This closes the loop: when the evidence changes,
// re-evaluate and launch whatever just became ready.
//
// It is EVENT-DRIVEN on the coordination log, not polled. A worker finishing emits `bsc-maintain`
// (#1957) and the director's merge/close emits its own line, so every transition that can release a
// downstream stream writes to that log first — which `useLogStream("coord", …)` already surfaces for
// free. That matters: the alternative (polling `fleet_landed_streams`) is a git subprocess per repo per
// tick, and this app is already spawn-bound (#3871). The pump therefore costs ONE extra git probe per
// coord-log CHANGE, and nothing at all while the fleet is quiet.
//
// It never parks anything and never wakes a running session — the only action it can take is to launch a
// stream that was never started, which is exactly what #1039 left room for.

// The pump's own imports (the coord read, the landed-evidence probes, the partition) went with its body
// when it was disabled — see `useFleetGate` below. The PURE core above keeps only what it needs, so the
// helpers and their tests survive for whoever re-enables this.
import type { GateStream } from "@/shared/lib/fleet/streamGate";

/** Launch the streams that just became ready for one project. Injected so the pump is testable. */
export type GateLauncher = (projectKey: string) => Promise<unknown>;

/**
 * Which projects the pump should evaluate: those with a fleet roster in the store. A project with no
 * roster has never launched, so there is nothing to release. Pure.
 */
export function gatedProjects(fleetPaneStreams: Record<string, unknown>): string[] {
  const keys = new Set<string>();
  for (const paneId of Object.keys(fleetPaneStreams)) {
    const key = paneId.split(":")[0];
    if (key) keys.add(key);
  }
  return [...keys];
}

/**
 * Stream ids the pump should launch: every READY stream that isn't quarantined.
 *
 * #3971 — this used to also subtract "live" panes, which broke recovery at exactly the moment it was
 * needed. The liveness signal was tab membership (`in a tab && !ended && !disabled`), so at boot every
 * persisted pane counted as live — including the 25 that had come up as BARE SHELLS (`init=<none>`,
 * `LaunchPlan::None`, no agent). The pump skipped them as already-running and released 3 streams
 * against a fleet with 13 dependency-free roots.
 *
 * That definition is right where it came from — Glance's node colouring and #3954's warden scoping
 * both ask "does a session cell exist?" — and wrong here, where the question is "is an AGENT running?".
 * A bare shell answers no.
 *
 * Rather than teach the pump to detect a bare shell, drop the filter: `resumeProject.ts` settled this
 * in #3923 — "a live pane is safe to include in the relaunch: `pty_create` reconnects to an existing
 * session and returns before spawning, so it never re-sends `claude --continue` to a running agent."
 * The pump's actuator IS `resumeProjectFleet`, so it inherits that guarantee, and the caution I added
 * had already been deliberately removed from that path.
 *
 * Repeat-firing is owned by the caller's `lastFired` fingerprint, which is the honest mechanism for it
 * — not a liveness proxy that is wrong precisely when recovery matters. Quarantine still excludes: a
 * quarantined worker is surfaced, never relaunched (#3916). Pure.
 */
export function newlyLaunchable(
  ready: readonly GateStream[],
  projectKey: string,
  quarantined: Record<string, unknown>,
): string[] {
  return ready.map((s) => s.id).filter((id) => !quarantined[`${projectKey}:${id}`]);
}

/**
/**
 * DISABLED (#fleet-gate-stops-launching-on-its-own). Mounted, and does nothing.
 *
 * WHAT IT USED TO DO. Mounted once from the `consolepage` record, it re-evaluated each project's
 * dependency gate on every coord-log change and called `launch` — `resumeProjectFleet` — for any
 * project with a newly-released stream.
 *
 * WHY IT IS OFF. `useLogStream` READS ON MOUNT, and `lastFired` is a fresh ref each app run, so the
 * first evaluation could not be deduped against anything and always fired. Starting the app therefore
 * relaunched whole fleets: measured in the process table seconds after boot as
 * `claude --model sonnet --continue "You are the OPNsense adapter worker…"` — a fleetStartProject
 * kickoff, not a reconnect — with matching bursts of 6 and 13 panes in activity.log. Both of this
 * machine's projects arm it (37 of 38 and 27 of 40 streams carry `dependsOn`), and `planFleet` +
 * `fleetPaneStreams` are persisted, so the gate is loaded and ready the moment the app opens.
 *
 * The header above used to claim "the only action it can take is to launch a stream that was never
 * started". Its actuator relaunches the WHOLE fleet, and for any pane whose PTY did not survive the
 * app close that is a genuine cold start.
 *
 * NOTHING IS STRANDED. A user-initiated Resume still partitions by the SAME dependency gate
 * (`resumeProjectFleet` → `streamGate`), so a held stream is released the moment the user asks for
 * the fleet — it just is not released for them while they are not looking.
 *
 * Disabled rather than deleted, and the signature is kept, so the `consolepage` record's call site
 * (`useFleetGate(fleetGateLaunch)`) needs no edit and re-enabling is restoring one body. If it ever
 * comes back it must NOT act on the mount read — a gate release is an EVENT, and replaying it at boot
 * is the same defect the coordinator's freshness window had.
 *
 * @param _launch the actuator, retained for the signature; never called.
 */
export function useFleetGate(_launch: GateLauncher): void {
  // Intentionally empty: no subscription, no evaluation, no launch.
}

