// useFleetHeld (#3931 slice 4) — which of a drilled project's streams the dependency gate is holding,
// so the Glance node can SAY SO instead of rendering as an anonymous dark node.
//
// Same probe the resume runs (`fleet_landed_streams` + the coord `maintaining` list + plan.db issues),
// evaluated read-only: this hook never launches anything. It is scoped to the DRILLED project and
// re-runs on coord-log changes, so a stream that gets released stops being marked held without a poll.

import { useState } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJsonShared } from "@/shared/lib/core/bscShared";

/** How stale a plan read this hook accepts (#five-callers-one-spawn-for-the-same-plan-read). Matched to
 *  the other plan readers' 20s cadence so the five of them collapse onto ONE process launch per window;
 *  a held/blocked signal minutes old would be stale, seconds old is not. */
const HELD_TTL_MS = 20_000;
import { useLogStream } from "@/shared/hooks/useLogStream";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import { resolveClosedRefs } from "@/features/glance/lib/fleetIssueState";
import { partitionByDeps, heldReason, sessionDoneStreams, type GateStream, type LandedEvidence } from "@/shared/lib/fleet/streamGate";
import type { PlanIssue } from "@/features/planner/issues/planIssues";

/** Stream id → why it is held. Empty when nothing is gated (the common case once a fleet is flowing). */
export type HeldMap = Record<string, { reason: string; deadlocked: boolean }>;

/**
 * Held streams for `projectKey`. Returns an empty map when there is no project, no fleet, or no stream
 * declares a `dependsOn` — the last check is what keeps this off the git probe entirely for the many
 * fleets that have no dependency graph at all.
 */
export function useFleetHeld(projectKey: string | null, streams: readonly GateStream[] | undefined): HeldMap {
  const [held, setHeld] = useState<HeldMap>({});
  const hasDeps = !!streams?.some((s) => (s.dependsOn ?? []).length > 0);

  useLogStream("coord", async (isCancelled) => {
    if (!projectKey || !streams || !hasDeps) { setHeld({}); return; }
    const [merged, dbIssues, coord, closedRefs] = await Promise.all([
      safeInvoke<string[]>("fleet_landed_streams", { projectKey }, []),
      bscJsonShared<PlanIssue[]>(projectKey, ["plan", "list", "--full", "--json"], [], HELD_TTL_MS),
      readCoordState(),
      // #4103: plan.db's issue rows are empty for a hand-assembled fleet, so the done-set was empty and
      // the gate held streams whose upstreams had actually landed. GitHub is the other evidence source.
      resolveClosedRefs(streams),
    ]);
    if (isCancelled()) return;
    const evidence: LandedEvidence = {
      doneIssues: new Set([...doneIssueRefs(dbIssues ?? []), ...closedRefs]),
      mergedBranches: new Set(merged ?? []),
      // A failed coord read contributes no session evidence rather than fabricating it — the same rule
      // the resume and the pump follow. Over-reporting held is safe here (it is display only); claiming
      // a stream landed when the log could not be read is not.
      sessionDone: sessionDoneStreams(coord?.state.maintaining ?? [], projectKey),
    };
    const { held: h } = partitionByDeps(streams, evidence);
    setHeld(Object.fromEntries(h.map((x) => [x.streamId, { reason: heldReason(x), deadlocked: x.deadlocked }])));
  }, [projectKey, hasDeps, streams?.length]);

  return held;
}

// The drilled fleet's issue states, overlaid from GitHub (#4102).
//
// Scoped to the DRILLED project and batched into ONE query per repo (see `issueStateQuery.ts`), so the
// cost is bounded by what the user is actually looking at and stops entirely when they leave the drill
// — the same discipline `useStreamProgress` documents.
//
// ── LOCAL-FIRST, NEVER TOKEN-GATED (#2444) ──────────────────────────────────────────────────────
// With no token this returns an empty map and NOTHING breaks: issue OWNERSHIP comes from the fleet
// plan, so the plan screen still lists every worker's issues and the progress bar simply shows no
// completions yet. The overlay adds state; it is never the reason the list is empty.
import { useMemo } from "react";
import { githubGraphql } from "@/shared/lib/github/github";
import { useGithubQuery } from "@/shared/lib/github/useGithubQuery";
import { groupRefsByRepo, buildIssueStateQuery, parseIssueStates, closedRefs } from "@/features/glance/lib/issueStateQuery";

/** Issue open/closed moves at human speed — a worker closing one is a minutes-scale event. Served from
 *  the backend's ETag cache within this window, so a re-drill costs no network call at all. */
const MAX_AGE_SECS = 120;

export interface FleetIssueState {
  /** ref (unprefixed, e.g. `3898`) → closed. Empty while loading, without a token, or on error. */
  states: Map<string, boolean>;
  /** Just the closed refs — what `fleetPlanProgress` consumes. */
  done: Set<string>;
  loading: boolean;
  /** Set when the overlay could not be fetched. The caller still renders the list; this only explains
   *  absent state chips, so a disconnected user is told why rather than shown a silent zero. */
  error: string | null;
}

/**
 * Resolve open/closed for every issue ref owned by `streams`.
 *
 * `streams` should be the drilled project's fleet (or empty when not drilled — then nothing is fetched).
 */
export function useFleetIssueState(
  streams: readonly { repo?: string; issues?: readonly string[] }[],
): FleetIssueState {
  // The query is derived, not stored, and keyed by its own text: two renders yielding the same refs
  // produce the same string, so `useGithubQuery` does not refetch on every parent re-render.
  const query = useMemo(() => buildIssueStateQuery(groupRefsByRepo(streams)), [streams]);

  const { data, loading, error } = useGithubQuery<unknown>(
    () => githubGraphql<unknown>(query!, null, { maxAgeSecs: MAX_AGE_SECS }),
    [query],
    // A fleet with no addressable refs must not spend a request — nor show a spinner for an answer
    // that would be empty either way.
    !!query,
  );

  return useMemo(() => {
    const states = parseIssueStates(data);
    return { states, done: closedRefs(states), loading, error };
  }, [data, loading, error]);
}

// Live Fleet view model (#412). Reads the running fleet from the store
// (`fleetPaneStreams` roster + live `paneStatus`) and polls the coordination log
// (`read_coord_log` → `ingestCoordLog`) for blocked/asking/waiting, then assembles
// the worker roster via the pure mappers in lib/fleetLive.
import { useMemo } from "react";
import { useAppStore } from "@/store";
import { useCoordLog } from "@/shared/lib/fleet/useCoordLog";
import { buildLiveWorkers, deriveFleetKpis, statusCounts, type LiveWorker, type FleetKpis } from "@/shared/lib/fleet/fleetLive";

export interface UseFleetLive {
  workers: LiveWorker[];
  kpis: FleetKpis;
  counts: Partial<Record<LiveWorker["status"], number>>;
  hasFleet: boolean;
}

export function useFleetLive(): UseFleetLive {
  const fleetPaneStreams = useAppStore(s => s.fleetPaneStreams);
  const paneStatus       = useAppStore(s => s.paneStatus);
  const tabs             = useAppStore(s => s.tabs);
  const disabledPanes    = useAppStore(s => s.disabledPanes);
  const profiles         = useAppStore(s => s.agentProfiles);

  // The coordination log is the fleet's own activity feed (blocked/asking/waiting,
  // landed/merged). Polled while the screen is mounted — no store wiring needed.
  const { state: coord } = useCoordLog({ limit: 1000 });

  const workers = useMemo(
    () => buildLiveWorkers({ fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles }),
    [fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles],
  );
  const kpis = useMemo(() => deriveFleetKpis(workers), [workers]);
  const counts = useMemo(() => statusCounts(workers), [workers]);

  return { workers, kpis, counts, hasFleet: workers.length > 0 };
}

// useFleetWakeBridge (#4101) — apply a `bsc fleet wake` request to the store and ACK it.
//
// WHY THIS EXISTS
// `bsc fleet list` (#4098) gave the director eyes on its workers; nothing gave it the one lever it
// actually needs — waking a parked one. A director that spots a stopped worker with open issues on its
// stream could only tell the user about it.
//
// THE ROUND TRIP
//   bsc fleet wake → request file → Rust watcher → `bsc://fleet-wake` → HERE → store → `fleet_wake_ack`
//
// The ack is load-bearing rather than ceremony: the wake KILLS the PTY before relaunching (see
// `applyWake`), so a wake that silently failed would leave a dead worker behind a caller that believes
// it is running. That is #4025 exactly. So this ALWAYS acks — success or a stated error.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { findPaneOwnerTab } from "@/app/console/lib/paneIdentity";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { applyWake, wakePrecheckCwd, type WakeRequest, type WakeAck } from "@/app/fleetWakeBridge";

/**
 * Listen for `bsc://fleet-wake` and apply it. Mounted once by the shell.
 *
 * A thin adapter: the DECISION lives in `fleetWakeBridge.ts`, unit-testable without Tauri.
 */
export function useFleetWakeBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<WakeRequest & { id: string }>("bsc://fleet-wake", async (e) => {
      const { id, ...req } = e.payload;
      let ack: WakeAck;
      try {
        // Read the action off a LIVE getState, not a captured snapshot: zustand hands out a new object
        // per update, so a stale closure could call a wakePane bound to an older tab list.
        ack = await applyWake(id, req, {
          // EVERY argument, forwarded. This arrow used to take `(p, t)` and drop the third — the plan
          // row Rust resolves for a stream that has never launched
          // (#the-wake-adapter-drops-the-stream-it-was-handed). The failure was invisible twice over:
          // TypeScript accepts a 2-arg function where a 3-arg type is wanted (sound, and deliberate),
          // and both sides of this seam were tested — the bridge against a MOCK wakePane, the store by
          // calling wakePane directly — so the only untested thing was the join, which is where the
          // value went. The result was indistinguishable from the bug the row exists to fix: the store
          // saw no stream and refused with "resolved to no open tab".
          wakePane: (p, t, s) => useAppStore.getState().wakePane(p, t, s),
      // The store is the only place that knows WHICH condition refused, and each has a different fix.
      refusalReason: (paneId) => {
        const s = useAppStore.getState();
        if (!findPaneOwnerTab(s.tabs, paneId)) {
          return (
            `fleet wake: '${paneId}' belongs to no open tab, so there is nowhere to bring it back. ` +
            `Relaunch the project's fleet rather than waking this one pane.`
          );
        }
        if (!s.fleetPaneStreams[paneId]) {
          return (
            `fleet wake: '${paneId}' has no stream in the roster and plan.db did not name one either, ` +
            `so the app cannot tell what to start. Check \`bsc plan fleet get\` for this project.`
          );
        }
        return undefined;
      },
          // Kill before the bump so the remount spawns instead of reconnecting to a live shell whose
          // agent has exited — the same order `actuateWake` uses. `fireInvoke` swallows the "no such
          // session" case, which is the normal one for an already-reaped pane.
          killPane: async (p) => { await safeInvoke("pty_kill", { paneId: p }, undefined); },
          // Ask whether the LAUNCH would refuse this pane, before the kill above destroys anything.
          // `pty_launch_refusal` calls the WAKE-relaxed predicate `pty_create` itself does not use
          // (`wake_precheck_refusal`), so the answer here and the answer at the real spawn can
          // legitimately differ for exactly one recoverable shape — see the Rust doc.
          //
          // `wakePrecheckCwd` (pure, tested alongside `applyWake`) picks `req.stream?.cwd` — Rust's
          // fresh `ensure_worktree` resolution for a pane that is NOT live
          // (`the-director-cannot-start-a-stream-that-never-launched`) — over the store's `paneCwds`,
          // which is EMPTY for a stream `wakePane` has not yet adopted (that only happens a few lines
          // below, inside `wakePane` itself). Asking about the store cwd here for a never-launched or
          // freshly-rebuilt stream could only ever answer "refused" — the gate file the check wants
          // genuinely does not exist until the wake this precheck gates has actually run. Requests
          // #142/#150.
          //
          // `safeInvoke`'s fallback is `undefined` = "admitted", so a missing command or a backend
          // mid-restart leaves the wake behaving exactly as it did before rather than refusing
          // everything: this guards against killing a pane we KNOW cannot relaunch, not against
          // every uncertainty.
          launchRefusal: async (p) => await safeInvoke<string | null>(
            "pty_launch_refusal",
            { paneId: p, cwd: wakePrecheckCwd(req, useAppStore.getState().paneCwds[p] ?? "") },
            null,
          ) ?? undefined,
        });
      } catch (err) {
        // A throw here would strand the Rust waiter until its timeout. State it instead.
        ack = { id, error: `fleet wake threw: ${err instanceof Error ? err.message : String(err)}`, woke: false };
        log.error(`fleet wake ${id} threw: ${String(err)}`);
      }
      void invoke("fleet_wake_ack", { ack: { ...ack, id } }).catch((e2) => {
        // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
        log.error(`fleet_wake_ack failed for ${id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

tests.src:
// The SEAM (#the-wake-adapter-drops-the-stream-it-was-handed).
//
// `the-director-cannot-start-a-stream-that-never-launched` taught three things to carry a stream row:
// Rust resolves it, `fleetWakeBridge` forwards it, `wakePane` adopts it. This adapter binds the last
// two, and it bound them with `wakePane: (p, t) => …wakePane(p, t)` — a two-parameter arrow. The row
// arrived and was dropped on the floor, and the store refused exactly as it had before the fix, so the
// symptom was identical to the bug and the diagnosis went to the frontend twice and to Rust once.
//
// NEITHER GATE COULD SEE IT:
//   · TypeScript accepts a 2-arg function where a 3-arg type is expected. That is sound and
//     deliberate, so `tsc` was right to stay green.
//   · Both SIDES were tested — the bridge's own test asserts `deps.wakePane` is called with the row,
//     against a mock; the store's test calls `wakePane` directly with one. The join was the only
//     untested thing, and the join is where the value went.
//
// So this test exists at the seam and nowhere else: it drives the REAL listener with a REAL payload
// and asserts what the REAL store action received.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook } from "@testing-library/react";
import { listen } from "@tauri-apps/api/event";
import { useFleetWakeBridge } from "@/app/useFleetWakeBridge";
import { useAppStore } from "@/store";

type Handler = (e: { payload: Record<string, unknown> }) => Promise<void> | void;

/** Mount the hook and hand back the listener it registered for `bsc://fleet-wake`. */
async function mountAndCapture(): Promise<Handler> {
