// useLogStream (#3638) — the event-driven replacement for `usePoll` over a `bsc logs` stream. The
// frontend used to poll each unified log stream every ~1s; instead, the backend watcher
// (`observability::log_watch`) emits `logs://<stream>` when a stream file changes, and this hook
// re-reads (via the in-process `logs_*` commands, #3630) ONLY on that event. So reads happen on
// CHANGE, not on a clock — an idle app makes zero log reads.
//
// It keeps `usePoll`'s callback contract (an `isCancelled()` guard) so the pump bodies move over
// unchanged. A slow safety-net interval (default 60s) is the sole remaining "poll", a backstop against
// a missed change event — 60× rarer than the ~1s polls it replaces, and effectively silent.

import { useEffect, useRef, type DependencyList } from "react";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import { usePoll } from "@/shared/hooks/usePoll";
import { logEventName } from "@/shared/lib/core/logsBridge";

interface LogStreamOptions {
  /** Safety-net re-read interval (ms) — a backstop against a missed change event. Default 60000. */
  safetyMs?: number;
  /** When false, don't subscribe or read at all — the caller-side gate (e.g. page visibility, #3627).
   *  Default true. */
  active?: boolean;
}

/**
 * Re-run `fn` when any of `streams` changes (the `logs://<stream>` event), plus once on mount and on a
 * slow safety-net interval. `fn` gets the same `isCancelled` guard as {@link usePoll}. Pass the read
 * alias(es) the body reads (`"coord"`, `"activity"`, `"audit"`, …) — canonicalized to match the emit.
 *
 * @param streams one stream alias, or several (a body that reads more than one stream re-runs on any).
 * @param fn the read/process body — identical shape to a `usePoll` callback.
 * @param deps re-subscribe deps (like `usePoll`'s).
 * @param opts `safetyMs` (backstop interval) and `active` (caller-side gate).
 */
export function useLogStream(
  streams: string | string[],
  fn: (isCancelled: () => boolean) => void | Promise<void>,
  deps: DependencyList = [],
  opts: LogStreamOptions = {},
): void {
  const { safetyMs = 60_000, active = true } = opts;
  const list = Array.isArray(streams) ? streams : [streams];
  const key = list.join(",");
  const fnRef = useRef(fn);
  useEffect(() => { fnRef.current = fn; });

  // Initial read on mount + a slow backstop poll. `immediate` gives the current state right away;
  // `active:false` short-circuits both this and the subscription below.
  usePoll((isCancelled) => (active ? fnRef.current(isCancelled) : undefined), safetyMs, [key, active, ...deps]);

  // Re-read on any watched stream's change event.
  useEffect(() => {
    if (!active) return;
    let cancelled = false;
    const isCancelled = () => cancelled;
    const uns: UnlistenFn[] = [];
    // EVERY promise here is swallowed on purpose, and none of them was before.
    //
    // `UnlistenFn` RETURNS A PROMISE, and Tauri's `unregisterListener` rejects whenever the listener
    // is already gone — the ordinary case during teardown, when the backend has dropped the channel
    // or the webview is unmounting. Nothing awaited it, so it surfaced as an unhandled rejection
    // whose whole stack was inside Tauri:
    //
    //     @user-script:8:11:75
    //     unregisterListener@user-script:8:13:9
    //     _unlisten@…/@tauri-apps_api_event.js:40:60
    //     @…/.bsc-records/shared/hooks/useLogStream.tsx:54:22
    //
    // — which the crash overlay then reported as a FATAL BOOT ERROR (see `fatalOverlay`), because a
    // rejection with no message and a foreign stack is indistinguishable from a real one. A hook
    // that unsubscribes cleanly should never be able to do that.
    //
    // `listen` itself is caught too: it rejects when the window is torn down mid-subscribe, and that
    // is a normal race on a fast unmount, not a fault.
    const quietly = (p: unknown) => { void Promise.resolve(p).catch(() => {}); };
    for (const s of list) {
      void listen(logEventName(s), () => { if (!cancelled) void fnRef.current(isCancelled); })
        .then((un) => { if (cancelled) quietly(un()); else uns.push(un); })
        .catch(() => { /* the window went away before the subscription landed */ });
    }
    return () => { cancelled = true; uns.forEach((un) => quietly(un())); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, active, ...deps]);
}

tests.src:
// useLogStream (#3638) — event-driven log reads.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, act } from "@testing-library/react";
import { listen } from "@tauri-apps/api/event";
import { useLogStream } from "@/shared/hooks/useLogStream";

// Capture each `listen(name, cb)` so a test can FIRE the stream-change event, and count unlistens.
const handlers: Record<string, () => void> = {};
let unlistened = 0;

beforeEach(() => {
  for (const k of Object.keys(handlers)) delete handlers[k];
  unlistened = 0;
  vi.mocked(listen).mockImplementation((name, cb) => {
    handlers[name] = () => (cb as (e: { payload: unknown }) => void)({ payload: null });
    return Promise.resolve(() => { unlistened++; });
  });
});


describe("useLogStream: the unlisten rejection is handled", () => {
  /** An unlisten that rejects the way Tauri's does, and REPORTS whether anyone attached a handler. */
  function rejectingUnlisten() {
    const state = { caught: false };
    const fn = () => {
      const p = Promise.reject(new Error("listener not found"));
      const realCatch = p.catch.bind(p);
      (p as unknown as { catch: unknown }).catch = (...a: Parameters<typeof realCatch>) => {
        state.caught = true;
        return realCatch(...a);
      };
      return p as unknown as void;
    };
    return { fn, state };
  }

  it("attaches a catch when unsubscribing on unmount", async () => {
    const { fn, state } = rejectingUnlisten();
    vi.mocked(listen).mockImplementation(() => Promise.resolve(fn as unknown as () => void));
    const { unmount } = renderHook(() => useLogStream("coord", () => {}));
    await act(async () => { await Promise.resolve(); await Promise.resolve(); });
    await act(async () => { unmount(); });
    await new Promise((r) => setTimeout(r, 0));
    expect(state.caught).toBe(true);
  });

  it("attaches a catch on the CANCELLED path too", async () => {
    const { fn, state } = rejectingUnlisten();
    let resolveListen: ((un: () => void) => void) | undefined;
    vi.mocked(listen).mockImplementation(() => new Promise((res) => { resolveListen = res as (un: () => void) => void; }));
    const { unmount } = renderHook(() => useLogStream("coord", () => {}));
    unmount();
    resolveListen?.(fn as unknown as () => void);
    await new Promise((r) => setTimeout(r, 0));
    await new Promise((r) => setTimeout(r, 0));
    expect(state.caught).toBe(true);
  });
});

