// useRailSections (#2797) — the open/closed state for a left rail's collapsible sections, keyed by a
// stable section id. Sections default OPEN (the common case); toggling a key flips it. Shared so every
// graph rail (Algorithms, Teams, …) manages its sections identically. Pairs with `RailSection`.
import { useState } from "react";

export interface RailSections {
  /** Whether the section `key` is expanded (defaults to `defaultOpen`). */
  isOpen: (key: string) => boolean;
  /** Flip the section `key`. */
  toggle: (key: string) => void;
}

/** Collapsible-section open state for a rail. `defaultOpen` (default true) is the state before any
 *  toggle. See {@link RailSections}. */
export function useRailSections(defaultOpen = true): RailSections {
  const [open, setOpen] = useState<Record<string, boolean>>({});
  return {
    isOpen: (key) => open[key] ?? defaultOpen,
    toggle: (key) => setOpen((o) => ({ ...o, [key]: !(o[key] ?? defaultOpen) })),
  };
}

// Shared OS-sandbox readiness + one-click install (#1916 / #1982 / #1988). Probes whether the Bash
// sandbox can engage on this host and drives its install (`provision_sandbox`), which streams
// `sandbox-install` progress events so callers can show live progress. On completion it re-probes so
// `sandbox.ready` reflects the result. Used by BOTH the Settings posture card and the first-run setup
// banner, so the detect + install logic lives in one place.
import { useCallback, useEffect, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { listen } from "@tauri-apps/api/event";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** Mirror of the Rust `SandboxReadiness` (#1982) — the OS-sandbox probe result. */
export interface SandboxReadiness {
  platform: string;
  needsWsl: boolean;
  wslInstalled: boolean;
  sandboxDistro: string | null;
  /** The app can install the missing piece itself (Linux package manager / WSL rootfs import). */
  autoInstallable: boolean;
  ready: boolean;
  detail: string;
  /** Which agent runtimes the imported sealed distro carries (#4260); null when it isn't imported. */
  agentSandboxRuntimes: SandboxRuntimes | null;
  /**
   * Set when the imported distro is missing runtimes it needs to host the fleet — a distro built
   * before #4260 has the sidecars but no `claude` (the DEFAULT harness) and no `gh`. Reported
   * separately from `ready`, which is about whether the Bash sandbox can engage at all: the two
   * are different axes and folding them would make "not ready" ambiguous.
   */
  agentSandboxGap: string | null;
}

/** Mirror of the Rust `SandboxRuntimes` (#4260) — what the sealed distro can actually run. */
export interface SandboxRuntimes {
  claude: boolean;
  bscAgent: boolean;
  gh: boolean;
  git: boolean;
}

export interface UseSandboxReadiness {
  sandbox: SandboxReadiness | null;
  installing: boolean;
  installLog: string[];
  installMsg: string | null;
  /** Run the one-click install (`provision_sandbox`), streaming progress, then re-probe. */
  install: () => Promise<void>;
}

/**
 * @param enabled — when `false`, skip the readiness probe entirely (the caller won't render the
 *   sandbox UI). Lets a posture-gated card avoid the `wsl_sandbox_status` probe in the allow-list
 *   posture, so it isn't paid on every mount of a page that hosts the card.
 */
export function useSandboxReadiness(enabled = true): UseSandboxReadiness {
  const [sandbox, setSandbox] = useState<SandboxReadiness | null>(null);
  const [installing, setInstalling] = useState(false);
  const [installLog, setInstallLog] = useState<string[]>([]);
  const [installMsg, setInstallMsg] = useState<string | null>(null);

  const probe = useCallback(async () => {
    setSandbox(await safeInvoke<SandboxReadiness | null>("wsl_sandbox_status", undefined, null));
  }, []);

  useEffect(() => {
    if (!enabled) return;
    let alive = true;
    void safeInvoke<SandboxReadiness | null>("wsl_sandbox_status", undefined, null).then((r) => {
      if (alive) setSandbox(r);
    });
    return () => {
      alive = false;
    };
  }, [enabled]);

  // Raw `invoke` (not safeInvoke) so the final Ok/Err text surfaces; `sandbox-install` events stream the
  // package manager / rootfs-import output live into `installLog`.
  const install = useCallback(async () => {
    setInstalling(true);
    setInstallMsg(null);
    setInstallLog([]);
    const unlisten = await listen<{ phase: string; line?: string }>("sandbox-install", (e) => {
      const { phase, line } = e.payload;
      if ((phase === "start" || phase === "log") && line) setInstallLog((prev) => [...prev, line]);
    });
    try {
      setInstallMsg(await invoke<string>("provision_sandbox"));
    } catch (e) {
      setInstallMsg(String(e));
    }
    unlisten();
    await probe();
    setInstalling(false);
  }, [probe]);

  return { sandbox, installing, installLog, installMsg, install };
}

// The Automations runtime (#142) — a frontend tick that fires the schedules PERSONAS carry.
//
// Mounted once at the app root so it runs regardless of the active screen, but only while the app is
// open (which is also the only time a target pane exists).
//
// STATELESS BETWEEN TICKS. Due-ness comes from the automation LOG: the last fire of each schedule is
// a line in it, and the next is computed from that. There is no `nextRunAt` to keep correct, and so
// no way for the bookkeeping and the history to disagree about whether something ran.
import { useCallback, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import {
  duePersonaSchedules, scheduleKey,
  type CarriedSchedule, type AutomationWhen,
} from "@/features/automations/lib/scheduler";
import { dispatchSchedule } from "@/features/automations/lib/dispatch";

/** How often the scheduler checks for due schedules. */
const TICK_MS = 20_000;

/** The persona fields the scheduler reads — kept structural so it needs no cross-feature import. */
interface SchedulingPersona {
  id: string;
  schedules?: { name: string; when: unknown; command: string; armed?: boolean }[];
}

/** Every armed schedule every persona carries, flattened. */
export function carriedSchedules(personas: SchedulingPersona[]): CarriedSchedule[] {
  const out: CarriedSchedule[] = [];
  for (const p of personas ?? []) {
    for (const s of p.schedules ?? []) {
      // `armed` defaults to TRUE: a schedule written into a persona is meant to run, so disarming is
      // the explicit act. A hand-authored persona does not silently carry a dead job.
      if (s.armed === false) continue;
      if (!s.name || !s.command) continue;
      out.push({ personaId: p.id, name: s.name, when: s.when as AutomationWhen, command: s.command });
    }
  }
  return out;
}

/**
 * The last fire time per schedule, from the automation log.
 *
 * A schedule with NO line has never fired; it is deliberately ABSENT from the map rather than 0, so
 * `duePersonaSchedules` can anchor it forward instead of treating it as decades overdue.
 */
export function lastRunsFromLog(lines: string[]): Record<string, number> {
  const out: Record<string, number> = {};
  for (const line of lines ?? []) {
    const [ts, , key] = line.split("\t");
    if (!ts || !key) continue;
    const at = Date.parse(ts);
    if (Number.isNaN(at)) continue;
    if (!(key in out) || at > out[key]) out[key] = at;
  }
  return out;
}

export function useScheduler() {
  const tick = useCallback(async (isCancelled: () => boolean) => {
    const s = useAppStore.getState();
    const carried = carriedSchedules((s.personas ?? []) as SchedulingPersona[]);
    if (carried.length === 0) return;   // nothing carried: do not even read the log

    const lines = await logsTail("automation", 2000);
    if (isCancelled()) return;
    const lastRuns = lastRunsFromLog(lines ?? []);

    // FIRST-SIGHT ANCHORING. A schedule with no history is stamped once, as skipped, so the next
    // tick has something to compute from. Without it a never-run schedule would never become due,
    // because due-ness is derived from a last run that does not exist.
    for (const c of carried) {
      if (lastRuns[scheduleKey(c.personaId, c.name)] == null) {
        fireInvoke("append_automation_run", {
          pane: "", schedule: scheduleKey(c.personaId, c.name),
          status: "skipped", note: "first seen — scheduling from now",
        });
      }
    }

    const deps = {
      panePersonas: s.panePersonas ?? {},
      disabledPanes: s.disabledPanes,
      write: (paneId: string, data: string) => invoke<void>("pty_write", { paneId, data }),
      recordRun: (pane: string, schedule: string, status: string, note: string) =>
        fireInvoke("append_automation_run", { pane, schedule, status, note }),
    };
    for (const c of duePersonaSchedules(carried, lastRuns, Date.now())) {
      if (isCancelled()) return;
      await dispatchSchedule(c, deps);
    }
  }, []);

  // A beat after mount (so the store has hydrated): the first tick. usePoll runs the rest on the
  // fixed interval (immediate:false — the grace tick covers mount).
  useEffect(() => {
    let cancelled = false;
    const initial = setTimeout(() => void tick(() => cancelled), 1000);
    return () => { cancelled = true; clearTimeout(initial); };
  }, [tick]);

  usePoll(tick, TICK_MS, [], { immediate: false });
}

