// The drilled project's per-stream issue progress (#4050).
//
// ONE read per project on a slow cadence, partitioned in memory — never one read per node. That
// fan-out shape has cost real time in this app before (#3908 / #3912 / #3944 / #3954), and a graph of
// twenty workers would make twenty spawns of the same query.
//
// Scoped to the DRILLED project because that is the only fleet whose nodes are on screen: the cost is
// bounded by what the user is actually looking at, and it stops entirely when they leave the drill.
//
// It cannot piggyback on `useWorkerAutoEnd`'s read of the same data — that one is event-gated on panes
// that just went idle, so it says nothing while a fleet is steadily working, which is exactly when a
// progress bar is worth having.
import { useEffect, useState } from "react";
import { bscJsonShared } from "@/shared/lib/core/bscShared";
import { usePoll } from "@/shared/hooks/usePoll";
import type { OwnedIssue } from "@/shared/lib/fleet/workerEnd";
import { streamProgress, planDbDoneRefs, planDbClosedByRef, projectProgress, type StreamProgress } from "@/features/glance/lib/streamProgress";
import { knownRefAliases } from "@/features/glance/lib/fleetPlanProgress";

/** Issue counts move at human speed — a worker closing one is a minutes-scale event, so a fast poll
 *  would spend spawns to re-read an unchanged answer. */
export const PROGRESS_POLL_MS = 20_000;

/** What one poll of plan.db yields. #4102 added `doneRefs`: the same read now also feeds the
 *  ref-based progress path, which needs to know WHICH issues are finished rather than just how many —
 *  so plan.db statuses and the GitHub overlay can be unioned into one done-set. One read, two shapes;
 *  a second hook over the same query would be the fan-out this file's header warns about. */
export interface PlanDbProgress {
  byStream: Map<string, StreamProgress>;
  /** Refs of issues plan.db considers finished (`complete` | `verified`). */
  doneRefs: Set<string>;
  /** Per-ref closed-ness — `true` finished, `false` known-unfinished, ABSENT when plan.db has no such
   *  row. The Plan dock renders per-issue state from this, so a project that never uses GitHub still
   *  shows real states instead of "state unknown" on every row. */
  closedByRef: Map<string, boolean>;
  /** Every ref plan.db can be asked about, in each spelling it answers to (`knownRefAliases`).
   *
   *  `glance-progress-ref-namespace-split`: a fleet stream's `issues` are a SEPARATE ownership record
   *  and may be written in another namespace entirely — on `studio-code` they are bare GitHub numbers
   *  while plan.db is all slugs, so nothing matched and every owning node showed `0/N`. This is what
   *  lets the ref path tell "owned and unfinished" apart from "owned and unknowable", and stand aside
   *  for plan.db in the second case. */
  knownRefs: Set<string>;
  /** The project's progress across EVERY issue, stream-owned or not — the same `complete | verified`
   *  over the same rows that `bsc project progress` counts for the L0 project node.
   *
   *  `glance-progress-ref-namespace-split`: L0 and L1 disagreed (24 vs 56 on `studio-code`) because they
   *  counted different ownership records and neither said so. This gives the DIRECTOR — the one node
   *  accountable for the whole board rather than a lane — the same number L0 shows, from the same read,
   *  so the two levels agree by construction instead of by coincidence. */
  overall: StreamProgress;
}

const EMPTY: PlanDbProgress = {
  byStream: new Map(), doneRefs: new Set(), closedByRef: new Map(), knownRefs: new Set(),
  overall: { done: 0, total: 0 },
};

/** Per-stream `done / total` for `projectKey` plus its done refs, or empty when not drilled / no plan
 *  store. */
export function useStreamProgress(projectKey: string | null): PlanDbProgress {
  const [state, setState] = useState<PlanDbProgress>(EMPTY);

  // Clear on a project switch so the previous fleet's numbers never render against this one's nodes.
  useEffect(() => { setState(EMPTY); }, [projectKey]);

  usePoll(async (isCancelled) => {
    if (!projectKey) return;
    const issues = await bscJsonShared<OwnedIssue[] | null>(projectKey, ["plan", "list", "--full", "--json"], null, PROGRESS_POLL_MS);
    if (isCancelled() || !issues) return;   // read failed / no plan.db ⇒ keep the last good answer
    setState({
      byStream: streamProgress(issues),
      doneRefs: planDbDoneRefs(issues),
      closedByRef: planDbClosedByRef(issues),
      knownRefs: knownRefAliases(issues),
      overall: projectProgress(issues),
    });
  }, PROGRESS_POLL_MS, [projectKey]);

  return state;
}

// The studio-network pump (#2940): drives the app-owned studio-session network so a `bsc-commission`
// emitted by one session (the planner, or the designer) is fulfilled by another (designer/librarian)
// and the authored artifact id is delivered back — all while the user stays in the planning surface.
//
// Two actuations, both re-derived from the FULL coord log every tick (restart-safe), guarded so each
// message injects exactly once:
//   1. AUTHOR TASK  — an open commission's spec → the TARGET studio pane, once the target has been
//      reachable for the settle window (the lazy-mount host has had time to launch the session; Claude
//      queues input typed mid-boot). Pure decision: studioNetworkDrive.authorInjections.
//   2. DELIVER-BACK — a `deliver`-stamped commission's artifact id → the REQUESTER's pane (a live
//      session). Pure decision: studioNetworkDrive.deliverBackInjections.
//
// REACHABILITY is on-demand: the pump publishes `activeStudioTargets` (targets with open commissions)
// to the store; ConsoleWorkspace's <StudioNetworkHosts> lazy-mounts each target's terminal (launching
// the session) and unmounts it when the list empties (ending the session). No idle studio sessions.
//
// Mounted once in ConsoleWorkspace (stays mounted across screens). Pure logic lives in
// studioNetworkDrive.ts; this is the thin Tauri/React actuator, like useDirectorPump.
//
// INERT since #app-stops-pushing-prompts. Its entire body was a poll that injected studio commissions and deliver-backs — and it also LAZY-MOUNTED a commission target, which is the app launching a session, forbidden twice over.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime. Inert-but-
// exported is the shape useFleetGate took for the same reason when its launch pump was killed —
// deleting the hook is not the fix, doing nothing is.

/** Does nothing. See the note above. */
export function useStudioNetworkPump(): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// useStudioPageShowing (#3357) — is a studio's own page actually ON SCREEN right now?
//
// The studio pages are KEPT MOUNTED (`KeptMountedPage`): once visited they stay in the tree and are only
// CSS-hidden when the user switches away. So "my dock component is mounted" is NOT "the user is looking at
// this studio" — if the viewer ref-count keyed off mounting, it would stay ≥1 forever after the first visit
// and the idle reaper could never fire. This derives the real answer from the shell's page state.
import { useAppStore } from "@/store";
import { detachedSection } from "@/app/console/lib/detachWindow";
import { STUDIO_SESSIONS, type StudioId } from "@/features/studio-sessions/lib/studioSessions";

/** Pure rule: which page is showing, given the shell state and (for a tear-off) this window's identity. */
export function studioPageShowing(
  id: StudioId | null | undefined,
  s: { activeWorkspace: string },
  detached: { page: string; section: string } | null,
): boolean {
  // Null-tolerant for the same reason `useStudioViewer` is (#system-sessions-are-per-technology): a
  // per-technology dock resolves its session from the page's current selection, and a technology with
  // no session yields null. The rules of hooks require the call to be unconditional, so the NULL has to
  // be absorbed here rather than at the call site.
  //
  // UNRECOGNISED-tolerant too, which is a DIFFERENT case and the one that actually bit
  // (#a-stale-studio-id-in-a-record-must-not-kill-a-page). Callers include components compiled from
  // component RECORDS, whose source is data the type system never checked — so `id` can be a
  // non-null string naming a studio that no longer exists. `STUDIO_SESSIONS[retired]` is `undefined`,
  // and reading `.sectionId` off it threw all the way out to `GraphErrorBoundary`, which fell the
  // WHOLE page back: one stale id in one dock took down Algorithms entirely.
  //
  // A record is untrusted input by construction — the loader error-boundaries a render throw for
  // exactly that reason — so a helper it calls degrades instead of throwing. The dock shows nothing;
  // the page renders.
  const def = id ? STUDIO_SESSIONS[id] : undefined;
  if (!def) return false;
  // A torn-off section window renders exactly ONE page and has no rail — it is showing iff it IS this page.
  if (detached) return detached.page === def.pageKey && detached.section === def.sectionId;
  // The studio's page is its own WORKSPACE now (`five-graphs-become-rail-workspaces`); it used to be a
  // tab inside the Planner, which is why this once compared `projectsPageMode`. Left that way, every
  // studio's dock reports false forever — and because `openStudio` is the lazy launch, that is not a
  // reaper leak but a total failure to start.
  //
  // There is deliberately NO tab dimension here yet. Two designers share the Components workspace and
  // three librarians share Algorithms, so both report showing while their workspace is open — exactly
  // what they did before, when they shared one Planner tab. The technology tabs are what will
  // distinguish them, and narrowing this before those exist would stop four of the five from starting.
  return s.activeWorkspace === def.pageKey;
}

export function useStudioPageShowing(id: StudioId | null | undefined): boolean {
  const activeWorkspace = useAppStore((st) => st.activeWorkspace);
  return studioPageShowing(id, { activeWorkspace }, detachedSection());
}

// useStudioReaper (#3357) — the idle reaper for the app-owned studio sessions.
//
// A studio session deliberately OUTLIVES the surface that opened it: leaving the Design Studio page keeps
// the designer warm on TerminalHost so the Glance node can still morph into it. Something has to reclaim
// it eventually, or every studio ever opened runs a Claude process until the app quits.
//
// The rule: while a studio is wanted but NO surface is showing it (viewer count 0), a 30-minute timer runs.
// On expiry the session is killed and the studio leaves the wanted list, so its persistent mount unmounts
// with it. Anything that shows it again before expiry cancels the timer, and because the pane id is stable
// a later re-open resumes the same conversation (`claude --continue`) either way.
//
// NOTE: dropping the last TerminalHost claim is NOT itself a teardown — `TerminalView`'s cleanup keeps the
// backend PTY alive on purpose (a console tab-switch must reconnect, not respawn). So the reaper issues the
// `pty_kill` explicitly; the unmount only reclaims the xterm.
//
// ONE exception, checked at expiry rather than at arm time: if Claude is actively running in the session
// (`paneClaudeActive`), killing it would cut off work in flight. The reaper then RE-ARMS on a short recheck
// instead of reaping, so a busy session is deferred (indefinitely, while it stays busy) and reclaimed as
// soon as it goes quiet.
import { useEffect, useRef } from "react";
import { useAppStore } from "@/store";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
// The reaping policy is ONE user-facing setting (Settings → Planner → "Reap idle background sessions"),
// so the studio threshold lives alongside the console pane thresholds in `ReaperConfig` rather than in a
// second config the user would have to find separately. Pure leaf import, like `detachWindow` above.
import { DEFAULT_STUDIO_IDLE_MS, studioIdleMs } from "@/app/console/lib/idleReaper";
import { STUDIO_IDS, STUDIO_SESSIONS, type StudioId } from "@/features/studio-sessions/lib/studioSessions";

/** Default idle grace before an unwatched studio session is reclaimed. The EFFECTIVE value is the
 *  user's `idleReaper.studioIdleMs` setting; this is the packaged default (and the test baseline). */
export const STUDIO_IDLE_MS = DEFAULT_STUDIO_IDLE_MS;
/** Recheck interval while a due-to-be-reaped session still has Claude working in it. */
export const STUDIO_BUSY_RECHECK_MS = 60 * 1000;

export function useStudioReaper(): void {
  const wantedStudios = useAppStore((s) => s.wantedStudios);
  const studioViewers = useAppStore((s) => s.studioViewers);
  // The user's reaping policy (Settings → Planner). `enabled` is the master switch for ALL idle
  // reaping, so turning it off keeps studio sessions warm indefinitely too — one predictable rule.
  const reaperCfg = useAppStore((s) => s.idleReaper);
  const idleMs = studioIdleMs(reaperCfg);
  const enabled = reaperCfg.enabled;
  // studio id → its armed reap timer + the duration it was armed with. A ref (not state) so re-arming
  // never re-renders; the effect below reconciles it against the current wanted/viewer/config state.
  // The duration is tracked so a settings change re-arms rather than silently keeping the old clock.
  const timers = useRef<Map<StudioId, { t: ReturnType<typeof setTimeout>; ms: number; busy?: boolean }>>(new Map());

  useEffect(() => {
    const armed = timers.current;
    for (const id of STUDIO_IDS) {
      const idle = enabled && wantedStudios.includes(id) && (studioViewers[id] ?? 0) === 0;
      const timer = armed.get(id);
      if (!idle) {
        // Watched again, already reaped, or reaping switched off → cancel. This is the
        // "re-opening before expiry" path (and the master-switch-off path).
        if (timer) { clearTimeout(timer.t); armed.delete(id); }
        continue;
      }
      // Already counting down at the CURRENT threshold → leave it alone; an unrelated change (another
      // studio's churn) must not restart this clock. A changed threshold DOES re-arm, so editing the
      // setting takes effect immediately rather than only on the next idle transition. A BUSY deferral
      // is left alone either way: it is on the short recheck loop and re-evaluates itself, so treating
      // its recheck interval as a "changed threshold" would reset a working session to a full idle wait.
      if (timer && (timer.busy || timer.ms === idleMs)) continue;
      if (timer) { clearTimeout(timer.t); armed.delete(id); }

      const fire = () => {
        const st = useAppStore.getState();
        // Re-read at expiry: the arm-time snapshot is as stale as the configured threshold (30 min by
        // default, and the user can set it much longer).
        if (!st.wantedStudios.includes(id) || (st.studioViewers[id] ?? 0) > 0) { armed.delete(id); return; }
        if (!st.idleReaper.enabled) { armed.delete(id); return; } // switched off while counting down
        if (st.paneClaudeActive[STUDIO_SESSIONS[id].paneId]) {
          // Busy → defer, never cut off a turn. Re-armed at the RECHECK interval, so `ms` records that
          // (a settings change during a deferral re-arms it at the new threshold on the next reconcile).
          armed.set(id, { t: setTimeout(fire, STUDIO_BUSY_RECHECK_MS), ms: STUDIO_BUSY_RECHECK_MS, busy: true });
          return;
        }
        armed.delete(id);
        // Kill the PTY EXPLICITLY. Dropping the last TerminalHost claim only unmounts the <TerminalView>
        // (its cleanup deliberately leaves the backend session alive so a console tab-switch reconnects
        // rather than respawns) — so without this the xterm would go away while the `claude` process kept
        // running forever. Killing first, then dropping the mount, means the reclaim is complete.
        fireInvoke("pty_kill", { paneId: STUDIO_SESSIONS[id].paneId }, console.error);
        st.closeStudio(id);
      };
      armed.set(id, { t: setTimeout(fire, idleMs), ms: idleMs });
    }
  }, [wantedStudios, studioViewers, idleMs, enabled]);

  // Drop every pending timer when the host unmounts (app teardown / a test cleanup).
  useEffect(() => {
    const armed = timers.current;
    return () => { for (const { t } of armed.values()) clearTimeout(t); armed.clear(); };
  }, []);
}

