// The pluggable structure-renderer registry (#3176, epic #3171) — the injection point every per-structure
// renderer (#3178–#3185) plugs into WITHOUT editing the player. The player takes a `RendererRegistry`
// (a `Partial<Record<StructureName, StructureRenderer>>`) and dispatches each panel to its structure's
// renderer, or the `fallbackRenderer` when none is registered — so a missing renderer degrades, never
// crashes.
//
// A renderer for structure `S` is a React component over that structure's OWN frame type (`FrameOf<S>`),
// so a `StructureRenderer<"array">` receives an `ArrayFrame`. The registry map is typed per-key, so
// authoring is type-safe: `const registry: RendererRegistry = { array: ArrayView }`.

import type { ComponentType } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import type { FrameOf, StructureFrame, StructureName } from "@/features/algorithms/lib/trace";

/** A renderer for structure `S` — a React component over that structure's frame type (`FrameOf<S>`).
 *  Defaulting `S` to the whole union yields the erased shape the player dispatches through
 *  (a component over any `StructureFrame`), which the {@link fallbackRenderer} satisfies. */
export type StructureRenderer<S extends StructureName = StructureName> = ComponentType<{ frame: FrameOf<S> }>;

/** The injected map the player consumes — a per-structure renderer for zero or more structures. Each
 *  entry is typed to its own frame (`array` → a renderer over `ArrayFrame`). Equivalent to
 *  `Partial<Record<StructureName, StructureRenderer>>` but key-precise. The renderer issues add entries
 *  here; the player never changes. */
export type RendererRegistry = { [S in StructureName]?: StructureRenderer<S> };

/**
 * Resolve the renderer for a panel's structure — the registered one, else the {@link fallbackRenderer}.
 * The single, guarded cast site: the player looks a renderer up by the panel's OWN `structure`, so the
 * runtime frame always matches the resolved renderer's narrowed frame type even though the map's union
 * value type can't prove it statically.
 */
export function resolveRenderer(registry: RendererRegistry, structure: StructureName): StructureRenderer {
  return (registry[structure] as StructureRenderer | undefined) ?? fallbackRenderer;
}

/**
 * The default renderer for any structure with no registered renderer — prints the structure name + a
 * JSON dump of the frame. Keeps the player useful before the concrete renderers (#3178–#3185) land, and
 * makes an unregistered structure legible instead of a crash.
 */
export const fallbackRenderer: StructureRenderer = ({ frame }: { frame: StructureFrame }) => (
  <Stack gap={4} className="trace-fallback">
    <Eyebrow size={10}>{frame.structure}</Eyebrow>
    <Box as="pre" className="trace-fallback-json mono">
      {JSON.stringify(frame, null, 2)}
    </Box>
  </Stack>
);

// The vizCode SANDBOX worker (#3233) — a dedicated module Web Worker that compiles + runs a stored
// trace-program in an ISOLATED global scope (no DOM, no app state) and posts the recorded frames back.
// This is where untrusted stored `vizCode` executes, so `new Function` (in compileVizProgram) and the
// algorithm's `run` never touch the main thread. Spawned lazily by `vizSandbox.runInSandbox`.

import { runVizProgram } from "@/features/algorithms/viz/examples/vizProgram";
import type { VizWorkerRequest, VizWorkerResponse } from "@/features/algorithms/viz/examples/vizSandbox";

// `self` is the worker global. Typed loosely (a minimal shape) to avoid pulling in the TS "webworker" lib,
// which would clash with the app-wide "dom" lib (duplicate `self`/`postMessage` declarations). The message
// types are shared with the client via `import type` (erased — no runtime cycle with vizSandbox).
const ctx = self as unknown as {
  postMessage(message: VizWorkerResponse): void;
  onmessage: ((event: { data: VizWorkerRequest }) => void) | null;
};

ctx.onmessage = ({ data }) => {
  try {
    const { datatype, input, frames, source } = runVizProgram(data.code, data.input);
    ctx.postMessage({ id: data.id, ok: true, datatype, input, frames, source });
  } catch (err) {
    ctx.postMessage({ id: data.id, ok: false, error: err instanceof Error ? err.message : String(err) });
  }
};

// The warden's LLM-judge escalation (#1102, slice 3). The deterministic check (conformance.ts)
// is the hard gate — an out-of-lane edit or a gate-denied command hard-pauses immediately. But it
// can't see SEMANTIC drift: a worker that stays in its lane and runs only allowed commands yet is
// doing the wrong thing (e.g. following an injected instruction that touches nothing rule-visible).
// This module escalates a SAMPLED worker to an LLM judge — given only trusted telemetry (the plan
// anchor + the recent diff + the recent commands, never the worker-ingested prose) — for a fuzzy
// "on-task or drifted?" second opinion, off the deterministic hot path.
//
// Pure: prompt building + verdict parsing + sampling. The useWarden loop owns the llm_complete call and
// the quarantine actuation. Fail-OPEN by design — a parse failure or model wobble must NOT pause a
// legit worker (the deterministic check is the trustworthy gate); the judge only ADDS coverage.

import wardenJudgeEmbedded from "@data/fleet/warden-judge.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

export interface JudgeInput {
  streamId: string;
  /** File globs the stream owns — what it's SUPPOSED to be touching. */
  ownedGlobs: string[];
  /** Issue refs the stream owns (e.g. `#42`), for context on its assignment. */
  issues: string[];
  /** Files the worker changed (trusted: from git diff). */
  changedFiles: string[];
  /** Commands the worker ran (trusted: from the bsc-audit log). */
  commands: string[];
}

export interface JudgeVerdict {
  drifted: boolean;
  reason: string;
}

// The system prompt DATA is externalized to `@data/fleet/warden-judge.json` (#2145, epic #2027 tail) —
// editable without touching code + part of the exportable config bundle; the config-dir copy (#2047)
// overlays the embedded default via `overlayFile`. Only the literal text moved; the user-prompt BUILDER
// below stays in TS (it interpolates the runtime telemetry).
const JUDGE_SYSTEM = overlayFile("fleet/warden-judge.json", wardenJudgeEmbedded).system;

/** Build the judge prompt from trusted telemetry only. */
export function buildJudgePrompt(input: JudgeInput): { system: string; user: string } {
  const list = (xs: string[]) => (xs.length ? xs.map((x) => `  - ${x}`).join("\n") : "  (none)");
  const user =
    `Assignment\n` +
    `  stream: ${input.streamId}\n` +
    `  owns (file globs it should stay within):\n${list(input.ownedGlobs)}\n` +
    `  assigned issues:\n${list(input.issues)}\n\n` +
    `Observed activity\n` +
    `  files changed:\n${list(input.changedFiles)}\n` +
    `  commands run:\n${list(input.commands)}\n\n` +
    `Is this worker on-task for its assignment, or drifted/hijacked? Reply with the JSON object only.`;
  return { system: JUDGE_SYSTEM, user };
}

/** Parse the judge's reply. Tolerant + FAIL-OPEN: anything but a clear `"drifted": true` is
 *  treated as not-drifted, so a malformed reply never quarantines a legit worker. */
export function parseJudgeVerdict(text: string): JudgeVerdict {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const obj = JSON.parse(match[0]) as { drifted?: unknown; reason?: unknown };
      if (obj.drifted === true) {
        const reason = typeof obj.reason === "string" && obj.reason.trim() ? obj.reason.trim() : "off-task activity";
        return { drifted: true, reason };
      }
      return { drifted: false, reason: typeof obj.reason === "string" ? obj.reason.trim() : "" };
    } catch {
      // fall through to fail-open
    }
  }
  return { drifted: false, reason: "" };
}

/** Pick one worker to spot-check this round, round-robin, excluding already-quarantined panes.
 *  Returns null when there's nothing eligible. The loop controls HOW OFTEN this is called
 *  (judging every tick would be needlessly expensive); this only picks WHICH one. */
export function selectForJudging(
  paneIds: string[],
  cycle: number,
  skip: ReadonlySet<string>,
): string | null {
  const eligible = paneIds.filter((p) => !skip.has(p));
  if (eligible.length === 0) return null;
  return eligible[Math.abs(cycle) % eligible.length];
}

