// Role gate (#219) — write-path scoping. Translates the role's `writeGlobs` into an anchored
// matcher and answers the two write-scope questions: may a role write a given PATH
// ({@link canWritePath}), and what is the effective write-scope boundary for a pane
// ({@link scopeWriteGlobs}, what the `bsc-scope` PreToolUse hook hard-limits to). Pure enforcement
// core, free of React / xterm / Tauri. Re-exported from `sessionRoles.ts`.

import type { RoleCapability, SessionRole } from "@/shared/lib/session/roleModel";
import { roleCapability, hasScopedWriteCarveOut } from "@/shared/lib/session/roleModel";

/**
 * The effective write-scope globs for a pane's role (#1297) — what the `bsc-scope` PreToolUse hook
 * hard-limits writes to. Uses the pane's assigned owned globs when it has them, else the role's
 * default boundary, so the planner falls back to {@link PLAN_WRITE_GLOBS} rather than being
 * overridden to `[]`. Empty ⇒ the role has no write boundary (a `code: "none"` role with no
 * carve-out, or a worker with no lane yet) and so gets no scope hook. A `code: "none"` role WITH an
 * explicit carve-out (the director's commons, #851) is scoped to exactly those globs — so the
 * scope hook hard-blocks any director write outside the commons.
 */
export function scopeWriteGlobs(role: SessionRole, ownGlobs: string[]): string[] {
  const cap = roleCapability(role, ownGlobs.length ? { writeGlobs: ownGlobs } : {});
  if (cap.code === "write") return cap.writeGlobs;
  return hasScopedWriteCarveOut(cap) ? cap.writeGlobs : [];
}

// ── Write-path scoping ──────────────────────────────────────────────────────────

/**
 * Translate a path glob into an anchored RegExp: `*` = non-slash run, `**` = any, `?` = exactly one
 * non-slash character, `[abc]` / `[!abc]` / `[a-c]` = a character class, and an UNTERMINATED `[` is a
 * literal bracket.
 *
 * `?` and `[` used to be metacharacter leaks in a security predicate
 * (`the-two-write-scope-glob-engines-disagree`). `?` was simply not handled: it fell through to the
 * `else` branch unescaped, so `src/a?.ts` compiled to `/^src\/a?\.ts$/` — "optional a" — and matched
 * `src/.ts` while failing to match `src/ab.ts`. `[` and `]` were ESCAPED, making a bracket expression
 * literal text. Both were the opposite of what the Rust matcher (`bsc_util::scope::fnmatch`) and the
 * shell hook (`scope.sh`'s `case`) do, and those are the engines that ENFORCE.
 *
 * Nothing in the packaged floors uses either character today, so this closes a latent divergence
 * rather than changing a live lane — six of the eight measured disagreements, none of them a real
 * glob. The remaining two are `*` crossing a separator, which cannot be settled here: see
 * `glob_parity.rs`.
 */
function globToRegExp(glob: string): RegExp {
  let out = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*") {
      if (glob[i + 1] === "*") {
        out += ".*";
        i += 1;
      } else {
        out += "[^/]*";
      }
    } else if (c === "?") {
      // One character, and a separator is not one of them — the same rule `*` follows.
      out += "[^/]";
    } else if (c === "[" && closingBracket(glob, i) > i) {
      const end = closingBracket(glob, i);
      out += bracketClass(glob.slice(i, end + 1));
      i = end;
    } else if (/[.+^${}()|[\]\\?]/.test(c)) {
      out += `\\${c}`;
    } else {
      out += c;
    }
  }
  return new RegExp(`^${out}$`);
}

/** Index of the `]` closing the bracket expression opening at `from`, or `-1` when unterminated.
 *
 *  A `]` IMMEDIATELY after the opener (or after a leading `!`) is a literal member, not the close —
 *  the POSIX rule, and the same one `bsc_util::scope::bracket` follows. Without it `[]]` reads as an
 *  empty unterminated class. */
function closingBracket(glob: string, from: number): number {
  let i = from + 1;
  if (glob[i] === "!" || glob[i] === "^") i += 1;
  if (glob[i] === "]") i += 1;
  for (; i < glob.length; i++) if (glob[i] === "]") return i;
  return -1;
}

/** One bracket expression (`[abc]`, `[!abc]`, `[a-c]`) as a RegExp character class.
 *
 *  Only the negation marker is translated (`!` → `^`, which JS wants); the members are passed through
 *  because a glob class and a RegExp class already agree on ranges. A `^` inside is escaped so it
 *  cannot smuggle in a negation the glob did not write. */
function bracketClass(expr: string): string {
  let body = expr.slice(1, -1);
  let negated = false;
  if (body.startsWith("!") || body.startsWith("^")) {
    negated = true;
    body = body.slice(1);
  }
  const members = body.replace(/\\/g, "\\\\").replace(/\^/g, "\\^").replace(/\]/g, "\\]");
  return `[${negated ? "^" : ""}${members}]`;
}

/** True when `path` matches `glob`. */
export function matchGlob(glob: string, path: string): boolean {
  return globToRegExp(glob).test(path);
}

/**
 * Whether a role may write `path`: it needs `code` access AND the path must fall
 * inside one of its `writeGlobs`. No globs ⇒ no boundary ⇒ no code writes (a worker
 * must be assigned its ownership boundary first).
 *
 * The one exception is the scoped carve-out (#851): a `code: "none"` role that carries explicit
 * `writeGlobs` (the director's commons) may write paths inside those globs and nothing else — the
 * carve-out grants exactly the listed paths while every other write stays denied.
 */
export function canWritePath(cap: RoleCapability, path: string): boolean {
  if (cap.code === "none" && !hasScopedWriteCarveOut(cap)) return false;
  return cap.writeGlobs.some((g) => matchGlob(g, path));
}

// personaUseBridge (#change-a-panes-persona-from-the-cli) — decide what a `bsc persona use` request
// does to the store.
//
// Pure on purpose: the DECISION (does the persona exist, what was it before, does this need a relaunch)
// is testable without Tauri or a rendered app, and the listener stays a thin adapter — the same split
// `fleetWakeBridge` and `navigateBridge` use.
//
// WHY A RELAUNCH IS PART OF THE VERB
// The persona is the LAUNCH primitive: capability, MCP servers and hooks are all resolved from it when
// the session starts (`session-launch.ts` reads `panePersonas` before `paneRoles`, because a persona's
// floor may be narrower than its role's). So writing the map under a running session changes nothing the
// agent can observe. A `use` that only wrote the map would report success for a no-op, which is the same
// class of lie #4025 was: a caller told the thing landed when it had not.
//
// WHY THE KILL IS HERE
// `wakePane` does NOT kill — it bakes the startup prompt and bumps the owning tab's runId, and on
// reconnect `pty_create` discards the baked prompt (the #3998 init_cmd-on-reconnect trap). So a pane
// whose shell outlived its agent would reconnect to bash and never relaunch under the new identity.
// Kill first, exactly as `applyWake` does, so the remount SPAWNS.

/** The request as it arrives from Rust (`bsc://persona-use`). */
export interface PersonaUseRequest {
  paneId: string;
  personaId: string;
  /** Restart the session so the new identity is in effect. */
  relaunch: boolean;
  /** Carried for completeness; the BUSY refusal it governs is applied in Rust, before this is emitted. */
  force?: boolean;
}

/** What we send back via `persona_use_ack`. */
export interface PersonaUseAck {
  id: string;
  error?: string;
  applied: boolean;
  previous?: string;
  relaunched: boolean;
}

/** The store surface this needs — narrowed so the pure fn stays decoupled from the slice. */
export interface PersonaUseDeps {
  /** Every persona id the library holds. The CLI checks the STORE; this checks what the app actually
   *  hydrated, which is the set a launch can resolve against. */
  personaIds: () => string[];
  /** The pane's current persona, or undefined. Reported back so the change is reversible. */
  currentPersona: (paneId: string) => string | undefined;
  /** The real `setPanePersona`. */
  setPanePersona: (paneId: string, personaId: string) => void;
  /** `pty_kill` for this pane. MUST run before the wake so the remount spawns rather than reconnecting
   *  — see the header. A no-op when there is no PTY. */
  killPane: (paneId: string) => Promise<void>;
  /** The real `wakePane` — bumps the owning tab's runId, which remounts the pane. Returns whether it
   *  resolved a tab at all. */
  wakePane: (paneId: string, prompt: string) => boolean;
}

/**
 * What a relaunched session is told. A persona change is not a task, so this states the change rather
 * than inventing work — an empty prompt would drop the agent at a prompt with nothing to do.
 */
export const PERSONA_CHANGE_PROMPT =
  "Your persona has been changed. Re-read your instructions and continue under the new identity.";

/**
 * Apply one request. Total over its OWN paths — bad input, an unknown persona and a kill that fails all
 * produce an ack rather than an exception, because silence would strand the Rust waiter until its
 * timeout and surface as "the frontend did not apply the persona", sending someone to debug the wrong
 * thing. A DEP that throws propagates on purpose: swallowing it here would hide a real bug, and the
 * listener wraps the call so an ack still goes back.
 */
export async function applyPersonaUse(
  id: string,
  req: PersonaUseRequest,
  deps: PersonaUseDeps,
): Promise<PersonaUseAck> {
  const paneId = (req.paneId ?? "").trim();
  const personaId = (req.personaId ?? "").trim();
  if (!paneId) return { id, error: "persona use: no pane id", applied: false, relaunched: false };
  if (!personaId) return { id, error: "persona use: no persona id", applied: false, relaunched: false };

  // Checked again HERE, and not only in the CLI: the CLI reads the store on disk, while a launch
  // resolves against the library the app hydrated. Those can differ (a persona written after this app
  // started, one removed since), and the set that matters is the one a launch can actually find.
  const known = deps.personaIds();
  if (!known.includes(personaId)) {
    return {
      id,
      error:
        `persona use: the app's library has no persona '${personaId}'` +
        (known.length ? ` — known: ${known.join(", ")}` : " — its persona library is empty"),
      applied: false,
      relaunched: false,
    };
  }

  const previous = deps.currentPersona(paneId);
  deps.setPanePersona(paneId, personaId);

  if (!req.relaunch) {
    // Staged, not applied. The CLI says which happened, so this is not a silent half-measure.
    return { id, applied: true, previous, relaunched: false };
  }

  // A kill failure must not abort the relaunch: the common reason is that there was nothing to kill,
  // and refusing to relaunch a dormant pane because its absent PTY could not be killed would break
  // exactly the case where changing a persona is cheapest.
  await deps.killPane(paneId).catch(() => {});
  const relaunched = deps.wakePane(paneId, PERSONA_CHANGE_PROMPT);
  // The assignment landed either way — `applied` is about the map, `relaunched` about the session — so a
  // pane with no open tab still reports the truth rather than looking like a total failure.
  return { id, applied: true, previous, relaunched };
}

