// usePersonaUseBridge (#change-a-panes-persona-from-the-cli) — apply a `bsc persona use` request to the
// store and ACK it.
//
// THE ROUND TRIP
//   bsc persona use → request file → Rust watcher → `bsc://persona-use` → HERE → store → `persona_use_ack`
//
// The ack is load-bearing rather than ceremony: applying a persona RELAUNCHES the pane (see
// `applyPersonaUse`), so a change that silently failed would leave a killed session behind a caller that
// believes it came back under a new identity. So this ALWAYS acks — success or a stated error.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { applyPersonaUse, type PersonaUseRequest, type PersonaUseAck } from "@/app/personaUseBridge";

/**
 * Listen for `bsc://persona-use` and apply it. Mounted once by the shell.
 *
 * A thin adapter: the DECISION lives in `personaUseBridge.ts`, unit-testable without Tauri.
 */
export function usePersonaUseBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<PersonaUseRequest & { id: string }>("bsc://persona-use", async (e) => {
      const { id, ...req } = e.payload;
      let ack: PersonaUseAck;
      try {
        // Read every action off a LIVE getState, not a captured snapshot: zustand hands out a new
        // object per update, so a stale closure could call into an older tab list.
        ack = await applyPersonaUse(id, req, {
          personaIds: () => (useAppStore.getState().personas ?? []).map((p) => p.id),
          currentPersona: (p) => useAppStore.getState().panePersonas?.[p],
          setPanePersona: (p, persona) => useAppStore.getState().setPanePersona(p, persona),
          killPane: async (p) => { await safeInvoke("pty_kill", { paneId: p }, undefined); },
          wakePane: (p, t) => useAppStore.getState().wakePane(p, t),
        });
      } catch (err) {
        // A throw here would strand the Rust waiter until its timeout. State it instead.
        ack = {
          id,
          error: `persona use threw: ${err instanceof Error ? err.message : String(err)}`,
          applied: false,
          relaunched: false,
        };
        log.error(`persona use ${id} threw: ${String(err)}`);
      }
      void invoke("persona_use_ack", { ack: { ...ack, id } }).catch((e2) => {
        // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
        log.error(`persona_use_ack failed for ${id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// personaWhatamiBridge (#a-session-can-ask-what-it-is) — answer "what is this pane running as".
//
// The READ beside `personaUseBridge`'s write, and it needs the same round trip for the same reason:
// `paneRoles` and `panePersonas` are zustand state, so Rust cannot see them.
//
// WHY AN AGENT NEEDS THIS
// A worker and a director have different capability floors, different git/gh permissions and different
// protocols. Without a way to ask, an agent has to INFER its role from its kickoff prose — the kind of
// guess that is confidently wrong. `$BSC_AUDIT_PANE` already tells a session its own pane id; this
// turns that id into an identity.
//
// Pure, so the decision is testable without Tauri — the same split `fleetWakeBridge` uses.

/** The request as it arrives from Rust (`bsc://persona-whatami`). */
export interface WhatamiRequest {
  paneId: string;
}

/** What we send back via `persona_whatami_ack`. */
export interface WhatamiAck {
  id: string;
  error?: string;
  personaId?: string;
  personaName?: string;
  role?: string;
  startPrompt?: string;
  /** WHAT THE USER IS LOOKING AT, worded as the titlebar words it — e.g. `Components — React — bsc-kit`.
   *
   *  A studio's launch prompt names its TECHNOLOGY and stops there. That is a real partition but a
   *  coarse one: within `react` there are many kits, and the tab plus the rail selection is what says
   *  which. It is also fixed at launch while the tab is not — and the studios whose axis is NOT
   *  technology (Teams by team, Sounds by kit, Data by language) run ONE session across every value,
   *  so their prompt can never name the current one. Told to "simplify the graph", the designer had to
   *  ask which one. */
  viewing?: string;
  /** The rail destination — `components`, `algorithms`, `teams`, `data`, `sounds`, … */
  workspace?: string;
  /** The active tab id: the graph's own AXIS VALUE (a technology, a team, a kit, a language). The
   *  structured half of `viewing`, for a session that wants to act on it rather than print it. */
  pageTab?: string;
}

/** The store surface this needs — narrowed so the pure fn stays decoupled from the slice. */
export interface WhatamiDeps {
  /** The pane's persona id, or undefined. */
  personaFor: (paneId: string) => string | undefined;
  /** The pane's session role, or undefined. */
  roleFor: (paneId: string) => string | undefined;
  /** The persona record, for its display name and start prompt. */
  personaRecord: (id: string) => { name?: string; startPrompt?: string } | undefined;
  /** Where the user currently IS. Supplied by the caller rather than computed here, so this stays a
   *  pure decision AND so the string comes from `locationCrumb` — the same function the titlebar
   *  renders. One source is what stops the answer and the screen from drifting apart. */
  view: () => { viewing?: string; workspace?: string; pageTab?: string };
}

/**
 * Describe one pane. Never throws on its own paths.
 *
 * A pane with NEITHER a role nor a persona is a real state — a plain interactive console — so it is
 * reported as such rather than as an error. Inventing an identity would defeat the purpose: the verb
 * exists so nothing has to guess.
 */
export function describePane(id: string, req: WhatamiRequest, deps: WhatamiDeps): WhatamiAck {
  const paneId = (req.paneId ?? "").trim();
  if (!paneId) return { id, error: "persona whatami: no pane id" };

  const personaId = deps.personaFor(paneId);
  const role = deps.roleFor(paneId);
  const rec = personaId ? deps.personaRecord(personaId) : undefined;

  // Reported for EVERY pane, including one with no persona and no role: what is on screen is a
  // property of the app, not of the pane's identity, and a plain console asking is reason enough.
  const view = deps.view();

  return {
    id,
    ...view,
    personaId,
    // Only when the record actually resolves: a persona id whose record is gone should report the id
    // rather than a made-up name, so a dangling assignment is visible instead of smoothed over.
    personaName: rec?.name,
    role,
    startPrompt: rec?.startPrompt,
  };
}

