// usePersonaWhatamiBridge (#a-session-can-ask-what-it-is) — answer `bsc persona whatami` and ACK it.
//
//   bsc persona whatami → request file → Rust watcher → `bsc://persona-whatami` → HERE → store → ack
//
// Mounted once by the shell, beside `usePersonaUseBridge`. It ALWAYS acks — a throw here would strand
// the Rust waiter until its timeout and surface as "the frontend did not answer", sending someone to
// debug the app instead of the question they asked.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { describePane, type WhatamiRequest, type WhatamiAck } from "@/app/personaWhatamiBridge";
// The titlebar's own "you are here" builder. Reused rather than re-derived, so a session is told
// EXACTLY what the user can see — two independent answers to "where am I" would eventually disagree,
// and the one the agent got would be the one nobody was looking at.
import { locationCrumb } from "@/app/chrome/locationCrumb";
// The RENDERED workspace, not the raw store field: with the legacy Console page off, a persisted
// `console` renders Glance (#3575). Reporting the raw value would tell a session the user is on a
// screen that is not on screen.
import { effectiveWorkspace } from "@/app/registry";

/**
 * Listen for `bsc://persona-whatami` and answer it.
 *
 * A thin adapter: the decision lives in `personaWhatamiBridge.ts`, unit-testable without Tauri.
 */
export function usePersonaWhatamiBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<WhatamiRequest & { id: string }>("bsc://persona-whatami", (e) => {
      const { id, ...req } = e.payload;
      let ack: WhatamiAck;
      try {
        // Read off a LIVE getState rather than a captured snapshot: a persona can change mid-session
        // (that is what `bsc persona use` does), and a stale closure would answer with the old one.
        const s = () => useAppStore.getState();
        ack = describePane(id, req, {
          personaFor: (p) => s().panePersonas?.[p],
          roleFor: (p) => s().paneRoles?.[p],
          personaRecord: (pid) => s().personas?.find((x) => x.id === pid),
          // Live, like the reads above, and for a sharper reason: the user can switch tabs at any
          // point in a session, so a launch-time snapshot is wrong exactly when it matters. This is
          // why the view is answered through the round trip instead of baked into the prompt.
          view: () => {
            const st = s();
            const workspace = effectiveWorkspace(st.activeWorkspace, st.showConsolePage);
            return {
              viewing: locationCrumb({ ...st, activeWorkspace: workspace }),
              workspace,
              pageTab: st.activePageTab?.[workspace],
            };
          },
        });
      } catch (err) {
        ack = { id, error: `persona whatami threw: ${err instanceof Error ? err.message : String(err)}` };
        log.error(`persona whatami ${id} threw: ${String(err)}`);
      }
      void invoke("persona_whatami_ack", { ack: { ...ack, id } }).catch((e2) => {
        log.error(`persona_whatami_ack failed for ${id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// The fleet feature's graph-platform surface (#3606, epic #3604) — the fleet-INTERNAL modules a graph-loaded
// FleetPage imports but does NOT redraw: the `WorkerDetail` drill-in (a behavioural leaf kept as code per the
// dashboard-only scope) and the `useFleetGithub` / `fleetCost` logic (injected for #3606). The PURE dashboard
// computations were harvested into the algorithms graph and these libs now DELEGATE to those nodes (#3607:
// fleetCost→llmEnergy+groupTotals, fleetHealth→streamMerge, fleetGithub→windowedTally+orderByRank,
// fleetLive→precedenceResolve); what's injected here is the thin typed store-glue the loader wires the real
// store into — a React hook can't be a no-import graph node, so this injection IS "the loader injects the store".
// Registered HERE, inside the feature, because the shell must not reach a
// feature's internals (#1545) and eager-importing them from `app/` would de-lazy the whole planner at boot.
// The fleet host calls this synchronously before the graph page loads, so the modules are present when the
// compiled page's `require()` runs.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Skills from "@/features/skills"; // FleetLessons reads loadPendingLessons/lessonTitle from the skills barrel
import * as FleetCost from "@/features/glance/fleet/lib/fleetCost";
import * as FleetHealthLib from "@/features/glance/fleet/lib/fleetHealth";
// #4238 — `WorkerDetail` is now a `provides` RECORD, so the loader vendors its source rather than
// handing back this module (which stays as the fallback). Vendoring makes the loader responsible for
// what the detail panel reaches, and these five are what it reaches.
import * as FleetWorker from "@/features/glance/fleet/fleetWorker";
import * as WorkerDetailHelpers from "@/features/glance/fleet/workerDetail.helpers";
import * as WorkerDetailPlaceholder from "@/features/glance/fleet/WorkerDetailPlaceholder";
import * as WorkerModals from "@/features/glance/fleet/WorkerModals";
// FleetLessons/WorkerDetail read parseAuditLog from the logs barrel (it was the security barrel
// until the Security workspace dissolved into Logs -- same symbols, new owner).
import * as Logs from "@/features/logs";

/** Register the fleet's injected graph-platform modules by the specifiers its graph page imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerFleetPlatform(): void {
  registerAppModule("@/features/skills", Skills);
  registerAppModule("@/features/glance/fleet/lib/fleetCost", FleetCost);
  registerAppModule("@/features/glance/fleet/lib/fleetHealth", FleetHealthLib);
  registerAppModule("@/features/glance/fleet/fleetWorker", FleetWorker);
  registerAppModule("@/features/glance/fleet/workerDetail.helpers", WorkerDetailHelpers);
  registerAppModule("@/features/glance/fleet/WorkerDetailPlaceholder", WorkerDetailPlaceholder);
  registerAppModule("@/features/glance/fleet/WorkerModals", WorkerModals);
  registerAppModule("@/features/logs", Logs);
}

// Fleet GitHub-derived analytics (#415): throughput, merge queue, time-to-land,
// aggregated across the fleet's repos via the ETag-cached githubRequest. Pure
// mapping is in lib/fleetGithub; this is the fetch orchestration.
import { useState, useEffect } from "react";
import { githubRequest, isGithubAuthError } from "@/shared/lib/github/github";
import { useAppStore } from "@/store";
import {
  mapThroughput, mapMergeQueue, mapTimeToLand, deriveThroughputKpis,
  type ThroughputSlice, type MergeQueueRow, type FleetThroughputKpis,
  type GhIssueItem, type GhStatusState,
} from "@/shared/lib/github/fleetGithub";
import type { GhPull } from "@/shared/lib/github/repoPulseLive";

const WINDOW_DAYS = 14;
/** Cap on open PRs we fetch a CI status for (one call each). */
const STATUS_CAP = 12;

/** A PR with the head sha we need for the combined-status call. */
interface GhPullFull extends GhPull { head: { ref: string; sha: string } }

export interface FleetGithub {
  throughput: ThroughputSlice;
  mergeQueue: MergeQueueRow[];
  timeToLand: Array<{ label: string; v: number }>;
  medianLandH: number;
  kpis: FleetThroughputKpis;
  loading: boolean;
  error: string | null;
  /** how many repos were aggregated. */
  repoCount: number;
}

const EMPTY: FleetGithub = {
  throughput: { labels: [], landed: [], merged: [] },
  mergeQueue: [], timeToLand: [], medianLandH: 0,
  kpis: { landedToday: 0, prsMergedWeek: 0, avgLandH: 0 },
  loading: false, error: null, repoCount: 0,
};

export function useFleetGithub(repos: string[], refreshNonce = 0): FleetGithub {
  const githubToken = useAppStore(s => s.githubToken);
  const [data, setData] = useState<FleetGithub>(EMPTY);
  const key = repos.join(",");

  useEffect(() => {
    if (!githubToken || repos.length === 0) { setData(EMPTY); return; }
    let cancelled = false;
    setData(d => ({ ...d, loading: true, error: null }));

    (async () => {
      try {
        const since = new Date(Date.now() - WINDOW_DAYS * 86_400_000).toISOString();
        const get = <T,>(path: string, fallback: T): Promise<T> =>
          githubRequest<T>(path).catch((e) => { if (isGithubAuthError(e)) throw e; return fallback; });

        // Pulls (all states) + recently-closed issues, per repo.
        const perRepo = await Promise.all(repos.map(async slug => {
          const [pulls, issues] = await Promise.all([
            get<GhPullFull[]>(`repos/${slug}/pulls?state=all&per_page=100&sort=updated&direction=desc`, []),
            get<GhIssueItem[]>(`repos/${slug}/issues?state=closed&per_page=100&since=${since}`, []),
          ]);
          return { slug, pulls, issues };
        }));
        if (cancelled) return;

        const allPulls: GhPull[] = perRepo.flatMap(r => r.pulls);
        const allIssues: GhIssueItem[] = perRepo.flatMap(r => r.issues);

        // Open PRs → fetch combined CI status for the head sha (bounded).
        const open = perRepo.flatMap(r => r.pulls.filter(p => p.state === "open").map(p => ({ pr: p, repo: r.slug })));
        const capped = open.slice(0, STATUS_CAP);
        const statuses = await Promise.all(capped.map(({ pr, repo }) =>
          get<{ state: GhStatusState }>(`repos/${repo}/commits/${pr.head.sha}/status`, { state: null as unknown as GhStatusState })
            .then(s => ({ pr, repo, status: s?.state ?? null }))));
        if (cancelled) return;

        const now = new Date();
        const throughput = mapThroughput(allPulls, allIssues, WINDOW_DAYS, now);
        const live: FleetGithub = {
          throughput,
          mergeQueue: mapMergeQueue(statuses),
          timeToLand: mapTimeToLand(allPulls),
          medianLandH: deriveThroughputKpis(throughput, allPulls, now).avgLandH,
          kpis: deriveThroughputKpis(throughput, allPulls, now),
          loading: false, error: null, repoCount: repos.length,
        };
        if (!cancelled) setData(live);
      } catch (e) {
        if (cancelled) return;
        setData({ ...EMPTY, error: isGithubAuthError(e) ? "GitHub authorization failed — reconnect in Settings." : "Couldn't load fleet activity from GitHub." });
      }
    })();

    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, githubToken, refreshNonce]);

  return data;
}

// The STOP LEDGER (#a-stopped-session-says-why) — why each pane stopped, kept just long enough to
// tell the user and logged so the answer outlives the telling.
//
// WHY THIS EXISTS AS A MODEL RATHER THAN A BANNER'S LOCAL STATE. A pane can stop for reasons that
// arrive from three different directions, and only together do they answer "why did my worker go
// away":
//   · the PROCESS ended — carried on `pty_exit_` + the pane id from Rust, which knows the exit code, the
//     signal, and whether the cage's launcher failed before the agent ever ran;
//   · the APP stopped it — the idle reaper, worker auto-end, a warden quarantine, a pane disabled;
//   · nothing stopped it and it FINISHED, which must not be reported as a fault.
// A banner owning this would only ever see the direction it happened to subscribe to.
//
// The reason for an app-side stop is the ACTION that ran, so it is recorded at the sink — inside
// `reapPane`, `markPaneEnded`, `markQuarantine`, `setPaneDisabled` — rather than at each of their
// many call sites. One edit per cause, and a new call site cannot forget to report.

/** Why a pane stopped. The first six mirror Rust's `EndReason` on the `pty_exit` payload verbatim
 *  (kebab-case, so the wire spelling and this union are the same string); the rest are app-side
 *  decisions the frontend already knows it made. */
export type StopReason =
  | "finished"        // exit 0 — the agent completed. NOT a fault.
  | "failed"          // a non-zero exit from whatever ran.
  | "signalled"       // killed by a fatal signal (the shell's 128+N).
  | "launcher-failed" // bwrap / systemd-run died before the agent started.
  | "app-closed"      // pty_kill, a project teardown, app exit.
  | "unknown"         // the pty closed and the status could not be read.
  | "reaped"          // the idle reaper reclaimed it (#849).
  | "auto-ended"      // the worker finished its lane and auto-ended (#920).
  | "quarantined"     // the warden hard-paused it (#1102).
  | "disabled";       // the pane was switched off — by the user, or the boot GC.

/** One stop, as the banner shows it and the log records it. */
export interface PaneStop {
  paneId: string;
  reason: StopReason;
  /** One sentence, already phrased for a human. Rust supplies this for a process end. */
  detail: string;
  /** Epoch ms. The banner's own clock — see `activeStops`. */
  at: number;
  /** What the session last PRINTED, when it ended badly (#a-stopped-session-shows-its-last-words).
   *
   *  Rust sanitizes and bounds it before it crosses. Only ever set for a fault: quoting a clean
   *  session's output is how the notice becomes noise. `undefined` on a fault means the session
   *  printed nothing legible, which the banner SAYS rather than rendering an empty quote. */
  lastOutput?: string;
}

/** How long a stop notice stays on screen. The maintainer asked for "5 seconds max just to inform
 *  the user": this is an INFORMATIONAL notice, not a decision, so it must never wait for a click.
 *  The log line is what makes the short life affordable. */
export const STOP_NOTICE_MS = 5_000;

/** How many stops the ledger keeps. Bounded because this is transient state on a hot path: a fleet
 *  relaunch can stop a dozen panes at once, and nothing here is worth unbounded growth. Well above
 *  what can be legible in five seconds, so the cap is a safety floor rather than a policy. */
export const MAX_STOPS = 12;

/** Stops that are NORMAL — a session that finished, or one the app/user deliberately closed.
 *
 *  This split is the whole reason the feature does not become noise. Every session ends eventually,
 *  so a banner that fires on all of them is one the user learns to ignore, and the nine real
 *  failures hide among them. `finished` in particular is a SUCCESS. */
const ROUTINE: readonly StopReason[] = ["finished", "app-closed", "auto-ended", "reaped", "disabled"];

/** Is this stop something went WRONG, as opposed to something ending? */
export function isFaultStop(reason: StopReason): boolean {
  return !ROUTINE.includes(reason);
}

/** The banner tone for a stop. `launcher-failed` is the loudest because the agent never ran at all
 *  and the fix is on the host, not in the session. */
export function stopTone(reason: StopReason): "danger" | "warn" | "neutral" {
  if (reason === "launcher-failed" || reason === "quarantined") return "danger";
  return isFaultStop(reason) ? "warn" : "neutral";
}

/** The short phrase naming the stop, for the banner's lead. Kept separate from `detail` so the
 *  banner can read "PANE stopped: HEADLINE — DETAIL" without Rust having to phrase both halves.
 *
 *  (Written in caps rather than angle brackets on purpose: `emit-records` picks a record's emitted
 *  extension by scanning for an angle-bracketed identifier, and a placeholder in a COMMENT is enough
 *  to make this module emit as `.tsx` — which then breaks the packaged kit's runtime closure, since
 *  it lists modules by their `.ts` path.) */
export function stopHeadline(reason: StopReason): string {
  switch (reason) {
    case "finished": return "finished";
    case "failed": return "the agent exited with an error";
    case "signalled": return "killed";
    case "launcher-failed": return "the sandbox never started";
    case "app-closed": return "closed by the app";
    case "reaped": return "reclaimed while idle";
    case "auto-ended": return "finished its work";
    case "quarantined": return "paused by the warden";
    case "disabled": return "switched off";
    case "unknown": return "stopped for an unknown reason";
  }
}

/**
 * Append a stop, replacing any earlier one for the SAME pane, and drop what has expired.
 *
 * Replacing rather than stacking is load-bearing: the reported worker stopped NINE times in one
 * run, and nine notices for one pane is the same information nine times over while whatever else
 * stopped scrolls out of reach. The newest answer for a pane is the one worth showing.
 *
 * Pure, and takes `now` rather than reading the clock, so expiry is testable without waiting.
 */
export function recordStop(list: readonly PaneStop[], stop: PaneStop, now: number): PaneStop[] {
  const kept = list.filter((s) => s.paneId !== stop.paneId && now - s.at < STOP_NOTICE_MS);
  return [...kept, stop].slice(-MAX_STOPS);
}

/** The stops still inside their notice window, newest first — what the banner renders. */
export function activeStops(list: readonly PaneStop[], now: number): PaneStop[] {
  return list.filter((s) => now - s.at < STOP_NOTICE_MS).sort((a, b) => b.at - a.at);
}

/** The single line written to the app log for a stop. Always written, whether or not a banner was
 *  on screen — the banner lasts five seconds and this is what answers the question afterwards. */
export function stopLogLine(stop: PaneStop): string {
  const base = `pane[${stop.paneId}] stopped · ${stop.reason} · ${stop.detail}`;
  // The last words go in the LOG as well as the banner: the banner lasts five seconds and this is
  // the copy still there tomorrow. Only for a fault, and "printed nothing" is stated rather than
  // left as an absence — a session that died silently is itself the finding.
  if (!isFaultStop(stop.reason)) return base;
  return `${base} · last output: ${stop.lastOutput ?? "(printed nothing)"}`;
}

