import { describe, it, expect } from "vitest";
import { ROLE_DEFAULTS, roleCapability, roleWriteRules, hasScopedWriteCarveOut, type SessionRole } from "@/shared/lib/session/sessionRoles";
import { roleProfileId } from "@/shared/lib/session/roleProfile";
import { PROFILES, APP_ROLES, type AgentProfile } from "./agentProfiles";

// Role → profile consistency (the unified model). Every session role maps to a DEFAULT profile
// (roleProfile.ROLE_PROFILE), which must (a) exist in the packaged set and (b) not escalate past the
// role's code tier — a code:none role's profile must never auto-ALLOW the file-write tools. The role
// gate is the backstop: it hard-denies the write tools for code:none roles regardless of the profile.

const ROLES = Object.keys(ROLE_DEFAULTS) as SessionRole[];
const ALL: AgentProfile[] = [...PROFILES, ...APP_ROLES];
const profileFor = (role: SessionRole) => ALL.find((p) => p.id === roleProfileId(role));
const WRITE_TOOLS = ["Edit", "Write", "NotebookEdit"]; // no MultiEdit — removed tool (#3534)

describe("role → profile consistency (sessionRoles ↔ roleProfile)", () => {
  it("every role maps to a packaged profile that exists", () => {
    for (const role of ROLES) {
      expect(profileFor(role), `role '${role}' → '${roleProfileId(role)}' resolves to no profile`).toBeTruthy();
    }
  });

  it("no code:'none' role's profile auto-allows the file-write tools", () => {
    for (const role of ROLES) {
      if (ROLE_DEFAULTS[role].code !== "none") continue;
      // A scoped carve-out role (documentor's DOC_GLOBS) intentionally allows writes, hard-limited to
      // its globs by the bsc-scope hook — its profile allow is by design, not an escalation (#2326).
      if (hasScopedWriteCarveOut(roleCapability(role))) continue;
      const p = profileFor(role)!;
      expect(p.tools.edit, `${role}: code:none profile must not allow edit`).not.toBe("allow");
      expect(p.tools.write, `${role}: code:none profile must not allow write`).not.toBe("allow");
    }
  });

  it("the role gate hard-denies the write tools for every code:none role (backstop)", () => {
    // Makes a looser profile safe: at launch the sessionRoles gate denies the file-write tools
    // outright for every code:none role (no commons carve-out), and Claude precedence is deny > allow.
    for (const role of ROLES) {
      if (ROLE_DEFAULTS[role].code !== "none") continue;
      // Carve-out roles (documentor) lift the whole-tool deny so their per-glob doc allows aren't
      // masked; the bsc-scope hook is their backstop instead. Every OTHER code:none role keeps the deny.
      if (hasScopedWriteCarveOut(roleCapability(role))) continue;
      const deny = roleWriteRules(roleCapability(role)).deny;
      for (const t of WRITE_TOOLS) {
        expect(deny, `${role}: role gate must deny ${t}`).toContain(t);
      }
    }
  });
});

import { describe, it, expect } from "vitest";
import { registerProvider, getProvider, listProviders } from "@/app/console/lib/providers/registry";
import type { ConsoleProvider } from "@/app/console/lib/providers/types";

// Import index to trigger built-in provider registration
import "@/app/console/lib/providers";

describe("provider registry", () => {
  it("getProvider returns undefined for an unknown id", () => {
    expect(getProvider("unknown-provider-xyz")).toBeUndefined();
  });

  it("registerProvider + getProvider round-trips a provider", () => {
    const p: ConsoleProvider = {
      id: "test-custom",
      displayName: "Test Custom",
      buildLaunchCmd: () => "test-cmd",
    };
    registerProvider(p);
    expect(getProvider("test-custom")).toBe(p);
  });

  it("listProviders includes all registered providers", () => {
    const ids = listProviders().map((p) => p.id);
    expect(ids).toContain("claude");
    expect(ids).toContain("gemini");
    expect(ids).toContain("codex");
    expect(ids).toContain("aider");
    expect(ids).toContain("ollama");
    expect(ids).toContain("amazonq");
    expect(ids).toContain("bsc-agent");
  });

  it("registerProvider overwrites an existing entry with the same id", () => {
    const original = getProvider("claude");
    const replacement: ConsoleProvider = { id: "claude", displayName: "Claude Replacement", buildLaunchCmd: () => "replaced" };
    registerProvider(replacement);
    expect(getProvider("claude")).toBe(replacement);
    // Restore
    if (original) registerProvider(original);
  });
});

describe("built-in Claude provider", () => {
  it("has isClaude = true", () => {
    const p = getProvider("claude");
    expect(p?.isClaude).toBe(true);
  });

  it("buildLaunchCmd returns 'claude' — parity with the hardcoded prior path", () => {
    const p = getProvider("claude");
    expect(p?.buildLaunchCmd()).toBe("claude");
  });

  it("has a prereqProbe", () => {
    const p = getProvider("claude");
    expect(p?.prereqProbe).toBeTruthy();
  });
});

describe("non-Claude built-in providers", () => {
  it.each(["gemini", "codex", "aider", "ollama", "amazonq"])("%s does not set isClaude", (id) => {
    const p = getProvider(id);
    expect(p).toBeDefined();
    expect(p?.isClaude).toBeFalsy();
  });

  it("gemini buildLaunchCmd returns 'gemini'", () => {
    expect(getProvider("gemini")?.buildLaunchCmd()).toBe("gemini");
  });

  it("codex buildLaunchCmd returns 'codex'", () => {
    expect(getProvider("codex")?.buildLaunchCmd()).toBe("codex");
  });

  it("aider buildLaunchCmd defaults to fleet-safe git (#1172) — auto-commit off", () => {
    // First-class Aider always disables auto-commit/dirty-commit so it never surprise-commits on a
    // pane's branch; the fleet's flow owns commits/PRs (full builder tested in aider.test.ts).
    const cmd = getProvider("aider")?.buildLaunchCmd();
    expect(cmd).toContain("aider");
    expect(cmd).toContain("--no-auto-commits");
    expect(cmd).toContain("--no-dirty-commits");
  });

  it("amazonq buildLaunchCmd returns 'q'", () => {
    expect(getProvider("amazonq")?.buildLaunchCmd()).toBe("q");
  });

  it("ollama uses default model when none supplied", () => {
    const cmd = getProvider("ollama")?.buildLaunchCmd();
    expect(cmd).toMatch(/^ollama run /);
  });

  it("ollama uses the supplied model", () => {
    const cmd = getProvider("ollama")?.buildLaunchCmd({ model: "mistral" });
    expect(cmd).toBe("ollama run mistral");
  });
});

// The algorithms folder tree (#4107, reshaped by #4128) — the SAME nested model the components kit
// renders, down to the trailing "ungrouped" bucket and the caller-preserved ordering.
import { describe, it, expect } from "vitest";
import { UNGROUPED_KEY, UNGROUPED_LABEL } from "@/shared/lib/core/folderTree";
import { folderTree, folderImplCount, type AlgoImpl } from "@/features/algorithms/lib/knowledge";

const im = (id: string, folder?: string, role: "primitive" | "algorithm" = "algorithm"): AlgoImpl =>
  ({ id, name: id.replace(/\..*$/, ""), tech: "rust", role, composes: [], folder }) as AlgoImpl;

describe("folderTree", () => {
  it("nests folders the way the source tree nests", () => {
    // The real shape a repo-root harvest produces (measured: 1982 candidates across 62 folders).
    const t = folderTree([
      im("job.rs", "src-tauri/src/console/pty"),
      im("mod.rs", "src-tauri/src/console"),
      im("perf.rs", "src-tauri/src/observability"),
    ])!;
    expect(t.map((r) => r.label)).toEqual(["src-tauri"]);
    const src = t[0].folders[0];
    expect(src.label).toBe("src");
    expect(src.folders.map((c) => c.label)).toEqual(["console", "observability"]);
    const console_ = src.folders[0];
    expect(console_.items.map((i) => i.id)).toEqual(["mod.rs"]);
    expect(console_.folders[0].key).toBe("src-tauri/src/console/pty");
    expect(console_.folders[0].items.map((i) => i.id)).toEqual(["job.rs"]);
  });

  it("buckets unfoldered impls LAST instead of spilling them flat (#4128 — the components rule)", () => {
    // Before #4128 these came back in a separate `unfoldered` array the rail rendered beside the tree;
    // the components rail has always bucketed them, so a partially-foldered library now reads the same
    // in both. The seeded classics carry no `src`, so this is the COMMON case here, not an edge one.
    const t = folderTree([im("merge.rs"), im("bfs.rs"), im("job.rs", "src-tauri/src/console/pty")])!;
    expect(t.map((f) => f.label)).toEqual(["src-tauri", UNGROUPED_LABEL]);
    const bucket = t[t.length - 1];
    expect(bucket.ungrouped).toBe(true);
    expect(bucket.key).toBe(UNGROUPED_KEY);
    expect(bucket.items.map((i) => i.id)).toEqual(["merge.rs", "bfs.rs"]);
  });

  it("returns null when NOTHING carries a folder — the rail renders its flat list unchanged", () => {
    // Every impl in the live store was unfoldered before #4119; those must come back as a flat list,
    // NOT collapsed under one blank folder. The change stays additive.
    expect(folderTree([im("merge.rs"), im("bfs.rs")])).toBeNull();
    expect(folderTree([])).toBeNull();
  });

  it("treats a blank folder as unfoldered rather than a `\"\"` node", () => {
    expect(folderTree([im("a.rs", "   ")])).toBeNull();
    const t = folderTree([im("a.rs", "   "), im("b.rs", "core")])!;
    expect(t.map((f) => f.label)).toEqual(["core", UNGROUPED_LABEL]);
    expect(t[1].items.map((i) => i.id)).toEqual(["a.rs"]);
  });

  it("preserves the CALLER's order — primitives before algorithms survives into every folder", () => {
    // `groupImplsByLanguage` sorts primitives first; the tree must not re-sort that away (the pre-#4128
    // algorithms builder sorted folders alphabetically and impls by role+name itself, which silently
    // overrode whatever order the rail had chosen).
    const t = folderTree([
      im("rust.vec", "core", "primitive"),
      im("zeta.rs", "core", "algorithm"),
      im("alpha.rs", "core", "algorithm"),
      im("b.rs", "bar"),
    ])!;
    expect(t.map((r) => r.label)).toEqual(["core", "bar"]); // first-appearance, not alphabetical
    expect(t[0].items.map((i) => i.id)).toEqual(["rust.vec", "zeta.rs", "alpha.rs"]);
  });

  it("places two impls sharing a folder side by side, and counts a subtree transitively", () => {
    const t = folderTree([im("a.rs", "crates/x/src"), im("b.rs", "crates/x/src")])!;
    const leaf = t[0].folders[0].folders[0];
    expect(leaf.key).toBe("crates/x/src");
    expect(leaf.items).toHaveLength(2);
    expect(folderImplCount(t[0])).toBe(2);
  });
});

// THE TECHNOLOGY TAB IS A LENS, NOT A PARTITION (`the-tab-is-a-lens-not-a-partition`) — the Components
// half of the guard, mirroring `features/algorithms/algorithmsLens.test.ts`.
//
// The claim a tab bar must never make is that technologies cannot cooperate. They can, and the model
// already says so: `@bsc/algorithms/fibonacci` is kit-less, so a React component resolves a TypeScript
// implementation across both pillar and technology (epic #3114, whose purpose was ending that siloing).
// Technology here is a CURATION scope — `studioScopeDirective` splits the designer per technology,
// governing who may WRITE a kit's components — and nothing more.
//
// What that obliges: scoping the rail to one technology must not make any kit, component or
// `composes` edge unreachable. That holds structurally rather than by luck, because a component's
// `composes` graph never leaves its kit and a kit belongs to exactly one technology — but "it holds
// today" is what a guard is for.
import { describe, it, expect } from "vitest";
import { groupKits, OTHER_BUCKET, type KitGroup, type KitTreeNode } from "@/features/designs/lib/kitGroups";
import type { Kit } from "@/features/designs/lib/model";

const kit = (id: string, tech?: string, style?: string): Kit =>
  ({ id, name: id, stack: "?", dot: "var(--accent)", ...(tech ? { tech } : {}), ...(style ? { style } : {}) }) as Kit;

/** Every kit id reachable by walking one technology group's subtree — what its tab can show. */
const kitsUnder = (node: KitTreeNode): string[] => {
  if (node.kind === "kit") return [node.kit.id];
  const own = node.kit ? [node.kit.id] : [];
  return [...own, ...node.children.flatMap(kitsUnder)];
};

const techGroups = (kits: Kit[]): KitGroup[] =>
  groupKits(kits).filter((n): n is KitGroup => n.kind === "group");

describe("the technology tab is a lens over the component library", () => {
  it("every kit is reachable from exactly one technology tab", () => {
    // Total and unambiguous. A kit under no tab is invisible in the UI; a kit under two is two copies
    // of one record, and edits to it would depend on which tab you happened to be on.
    const kits = [
      kit("studio", "react", "studio"),
      kit("fleet", "react", "studio"),
      kit("viz", "react", "data-viz"),
      kit("mobile", "react-native", "mobile"),
      kit("bare"), // no tech at all
    ];
    const seen = new Map<string, number>();
    for (const g of techGroups(kits)) {
      for (const id of g.children.flatMap(kitsUnder)) seen.set(id, (seen.get(id) ?? 0) + 1);
    }
    expect([...seen.keys()].sort()).toEqual(["bare", "fleet", "mobile", "studio", "viz"]);
    expect([...seen].filter(([, n]) => n > 1)).toEqual([]);
  });

  it("a kit with no technology still gets a tab rather than disappearing", () => {
    // The `other` bucket was a trailing rail GROUP; as a tab it must still exist, or an imported or
    // hand-authored kit that never set `tech` becomes unreachable — silently, since nothing errors.
    const groups = techGroups([kit("studio", "react", "studio"), kit("bare")]);
    const other = groups.find((g) => g.key === `tech:${OTHER_BUCKET}`);
    expect(other, "a kit with no `tech` must still have a tab").toBeTruthy();
    expect(other!.children.flatMap(kitsUnder)).toEqual(["bare"]);
    // …and it sorts LAST, so the real technologies lead.
    expect(groups[groups.length - 1].key).toBe(`tech:${OTHER_BUCKET}`);
  });

  it("scoping to one technology never splits a kit across tabs", () => {
    // The edge case that would sever something real: a kit's components compose only within that kit,
    // so a kit landing whole on one tab is what makes "no edge is lost" structural here rather than
    // coincidental. Two technologies sharing a STYLE name must not merge into one group.
    const groups = techGroups([kit("a", "react", "studio"), kit("b", "react-native", "studio")]);
    expect(groups.map((g) => g.key)).toEqual(["tech:react", "tech:react-native"]);
    expect(groups[0].children.flatMap(kitsUnder)).toEqual(["a"]);
    expect(groups[1].children.flatMap(kitsUnder)).toEqual(["b"]);
  });
});

/**
 * @vitest-environment jsdom
 *
 * This file lives under `lib/`, which vitest's `node` project covers, but it genuinely needs a DOM.
 * A per-file docblock beats the project's environment, so the requirement is stated where a reader
 * meets it. See the `projects` split in vitest.config.ts for why the default is `node` here.
 */
import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { KitRenderer, type GeneralNode } from "@/shared/ui/spec";
import { makeAnalyticsEmit, componentAnalyticsLookup, collectingSink } from "@/features/designs/lib/analyticsEmit";

// The end-to-end proof: a spec composed from an INSTRUMENTED component auto-emits its declared event when
// the action fires — through the SAME renderer studio pages + generated specs use. Nothing in the spec
// says "record"; emission is derived from the manifest at the render seam (#3816, epic #3809 slice 3).

const buttonSpec: GeneralNode = {
  type: "Button",
  props: { children: "Go" },
  actions: { onClick: "go" },
};

const lookup = componentAnalyticsLookup([
  { name: "Button", analytics: [{ event: "click", props: [{ name: "label", type: "string", req: false, desc: "" }] }] },
]);

describe("KitRenderer analytics emit seam", () => {
  it("records the declared event when the action fires, and still dispatches the handler", () => {
    const go = vi.fn();
    const sink = collectingSink();
    render(<KitRenderer node={buttonSpec} on={{ go }} emit={makeAnalyticsEmit(lookup, sink)} />);

    fireEvent.click(screen.getByText("Go"));

    // Dispatch to the host callback is unaffected.
    expect(go).toHaveBeenCalledTimes(1);
    // And the manifest-driven event was recorded. A click's MouseEvent carries no analytics payload, so
    // props is empty — the runtime records the event name without fabricating a payload it cannot see.
    expect(sink.records).toEqual([{ event: "click", props: {} }]);
  });

  it("is inert with no emit hook — the default render path is unchanged", () => {
    const go = vi.fn();
    render(<KitRenderer node={buttonSpec} on={{ go }} />);
    expect(() => fireEvent.click(screen.getByText("Go"))).not.toThrow();
    expect(go).toHaveBeenCalledTimes(1);
  });

  it("does not record when the component declares no matching event", () => {
    const go = vi.fn();
    const sink = collectingSink();
    // A lookup with no `click` event for Button → the fire resolves to nothing.
    const emptyLookup = componentAnalyticsLookup([{ name: "Button" }]);
    render(<KitRenderer node={buttonSpec} on={{ go }} emit={makeAnalyticsEmit(emptyLookup, sink)} />);

    fireEvent.click(screen.getByText("Go"));

    expect(go).toHaveBeenCalledTimes(1);
    expect(sink.records).toEqual([]);
  });
});

// #glance-architect-band + #architect-sits-with-the-projects + #architects-own-projects — the funnel's
// tier 1 on the L0 graph.
//
// The architect renders as a node IN the project network, edged to the projects it OWNS — not lifted
// into the fenced band the library and external-contract dimensions use. That band is for shared
// DEPENDENCIES a project consumes; an architect OWNS its projects, which is the opposite relationship,
// so it sits with them.
//
// #architects-own-projects narrowed the edge set: it used to be every architect to EVERY project (the
// first cut, because no ownership field existed), and the edge was called `created-by`. It is now
// `owned-by`, because an edge that can be REASSIGNED cannot claim to record who created the thing.
//
// The property that makes the placement safe is pinned below: the architect is a SINK (every `owned-by`
// edge points AT it), so it cannot close a cycle. Cycle regressions here have blanked the whole graph
// before (glance-planner-edge-isolation), so it is asserted rather than assumed.
import { describe, it, expect } from "vitest";
import { buildGlanceData, type ArchitectLite, type ProjectLite } from "@/features/glance/lib/glanceData";
import {
  buildGraph, isBandNode, isBandEdge, bandNodeMeta, architectNodeId, architectIdOfNode, ownedByEdgeId,
} from "@/features/glance/lib/glanceGraph";

const projects: ProjectLite[] = [
  { id: "app-a", name: "App A" },
  { id: "app-b", name: "App B" },
];
const architect: ArchitectLite[] = [{ id: "persona-architect", name: "Team architect" }];
const build = (p: ProjectLite[] = projects, a: ArchitectLite[] = architect) =>
  buildGlanceData(p, [], [], [], [], [], a);

describe("the architect node", () => {
  it("is emitted once per architect persona, namespaced so it cannot collide with a project key", () => {
    const d = build();
    const node = d.rawNodes.find((n) => n.id === architectNodeId("persona-architect"));
    expect(node).toBeTruthy();
    expect(node!.kind).toBe("architect");
    expect(node!.slug).toBe("Team architect");
    // A project key is a `[a-z0-9-]` slug with no colon, so the prefix is what makes this collision-proof.
    expect(node!.id).toContain(":");
    expect(architectIdOfNode(node!.id)).toBe("persona-architect");
  });

  it("is NOT a band node — it lays out WITH the projects (#architect-sits-with-the-projects)", () => {
    // The fenced band is for shared DEPENDENCIES (kits, algorithms, MCP servers), which is the wrong
    // relationship: an architect OWNS these projects rather than being consumed by them. Its
    // presentation row is kept, so a surface that wants the label/colour still has one.
    const d = build();
    const node = d.rawNodes.find((n) => n.id === architectNodeId("persona-architect"))!;
    expect(isBandNode(node)).toBe(false);
    expect(bandNodeMeta(node).bandLabel).toBe("ARCHITECTS");
  });

  it("adopts every UNASSIGNED project when it is the only architect, project as `from`", () => {
    // The sole-architect rule (#architects-own-projects): with one architect there is no choice to
    // make, so unassigned projects belong to it — which is what keeps a single-architect install
    // looking exactly as it did before ownership existed.
    const d = build();
    const edges = d.rawEdges.filter((e) => e.kind === "owned-by");
    expect(edges).toHaveLength(2);
    expect(edges.map((e) => e.from).sort()).toEqual(["app-a", "app-b"]);
    for (const e of edges) expect(e.to).toBe(architectNodeId("persona-architect"));
    expect(edges[0].id).toBe(ownedByEdgeId("app-a", "persona-architect"));
  });

  it("its edge is NOT a band edge — it routes in the project network like any other", () => {
    expect(isBandEdge("owned-by")).toBe(false);
  });
});

describe("the degenerate cases render rather than break", () => {
  it("no architect persona ⇒ no node and no edge (the graph is exactly as it was)", () => {
    const d = buildGlanceData(projects, [], [], [], [], [], []);
    expect(d.rawNodes.some((n) => n.kind === "architect")).toBe(false);
    expect(d.rawEdges.some((e) => e.kind === "owned-by")).toBe(false);
  });

  it("an architect with NO projects still renders — an orphan band node, not a crash", () => {
    const d = build([], architect);
    expect(d.rawNodes.filter((n) => n.kind === "architect")).toHaveLength(1);
    expect(d.rawEdges.filter((e) => e.kind === "owned-by")).toHaveLength(0);
    expect(() => buildGraph(d.rawNodes, d.rawEdges)).not.toThrow();
  });

  it("TWO architects each draw ONLY the projects assigned to them, ids staying distinct", () => {
    // Multiple architects are a first-class case (funnel-architect-front-door), so this must not
    // assume a singleton — and the band must not collapse them onto one node. This is the case
    // #architects-own-projects exists for: the old first cut drew 4 edges here (every architect to
    // every project), which said nothing about who owns what.
    const two: ArchitectLite[] = [{ id: "persona-architect", name: "A1" }, { id: "persona-architect-2", name: "A2" }];
    const owned: ProjectLite[] = [
      { id: "app-a", name: "App A", architect: "persona-architect" },
      { id: "app-b", name: "App B", architect: "persona-architect-2" },
    ];
    const d = build(owned, two);
    expect(d.rawNodes.filter((n) => n.kind === "architect")).toHaveLength(2);
    const edges = d.rawEdges.filter((e) => e.kind === "owned-by");
    expect(edges).toHaveLength(2);
    expect(edges.find((e) => e.from === "app-a")!.to).toBe(architectNodeId("persona-architect"));
    expect(edges.find((e) => e.from === "app-b")!.to).toBe(architectNodeId("persona-architect-2"));
  });

  it("leaves an UNASSIGNED project with no architect once there are several to choose from", () => {
    // The honest answer is none: adopting it under some architect would put a project under one that
    // never claimed it. The missing edge is the graph asking which.
    const two: ArchitectLite[] = [{ id: "persona-architect", name: "A1" }, { id: "persona-architect-2", name: "A2" }];
    const d = build([{ id: "app-a", name: "App A" }], two);
    expect(d.rawEdges.filter((e) => e.kind === "owned-by")).toHaveLength(0);
    expect(d.rawNodes.filter((n) => n.kind === "architect"), "both still render").toHaveLength(2);
  });

  it("treats an assignment to a VANISHED architect as unassigned, not as an edge to nothing", () => {
    // A persona can be deleted or re-roled out from under an assignment. A stale id is a MISSING
    // owner, so it falls through to the unassigned rules — here, the sole architect adopts it.
    const d = build([{ id: "app-a", name: "App A", architect: "persona-deleted" }], architect);
    const edges = d.rawEdges.filter((e) => e.kind === "owned-by");
    expect(edges).toHaveLength(1);
    expect(edges[0].to).toBe(architectNodeId("persona-architect"));
  });
});

describe("the band lift keeps the graph sound", () => {
  it("introduces no cycle — the architect is a SINK, and a cycle needs a path back out", () => {
    // The load-bearing safety property now that it is inside the project network. Cycle regressions
    // in this graph have blanked it before (glance-planner-edge-isolation), so this is asserted rather
    // than assumed.
    const d = build();
    const m = buildGraph(d.rawNodes, d.rawEdges);
    expect(m.cyclePairs).toHaveLength(0);
    expect(m.cycleNodeIds.size).toBe(0);
    expect(d.rawEdges.every((e) => e.kind !== "owned-by" || e.to === architectNodeId("persona-architect"))).toBe(true);
  });

  it("does not disturb the band for the dimensions that DO belong in it", () => {
    // Removing the architect must leave the kit/library/contract lift exactly as it was.
    const withKit = buildGlanceData(projects, [], [{ projectKey: "app-a", kitId: "react-ui" }], [{ id: "react-ui", name: "React UI" }], [], [], architect);
    const m = buildGraph(withKit.rawNodes, withKit.rawEdges);
    expect(m.bandZone, "the kit band still forms").toBeTruthy();
    const arch = m.nodes.find((n) => n.id === architectNodeId("persona-architect"))!;
    const kit = m.nodes.find((n) => n.kind === "kit")!;
    expect(isBandNode(kit)).toBe(true);
    expect(isBandNode(arch)).toBe(false);
  });
});

// Completion outranks idle on the quiet branches (#4124).
//
// `complete` was derived only from RUNTIME session signals — an `ended` verdict of `done`, or an
// explicit maintenance park. Both describe a session, and sessions end. The issues do not. So a worker
// that finished its lane read `idle` (live but quiet) or `off` (session reclaimed) — the same words a
// node with nothing to do reports, which is how "idle won against completed".
import { describe, it, expect } from "vitest";
import { applyFleetLiveStatus } from "@/features/glance/lib/agentStall";
import type { GRawNode } from "@/features/glance/lib/glanceGraph";

const node = (id: string, progress?: { done: number; total: number }): GRawNode =>
  ({ id, slug: id, role: "service", health: "off", activity: "idle", progress }) as GRawNode;

const sig = (over: Partial<Parameters<typeof applyFleetLiveStatus>[2]> = {}) => ({
  livePaneIds: new Set<string>(), paneStatus: {}, waiting: [], now: 0, ...over,
}) as Parameters<typeof applyFleetLiveStatus>[2];

const only = (nodes: GRawNode[], s = sig()) => applyFleetLiveStatus(nodes, "proj", s)[0];

describe("a finished worker never reads idle (#4124)", () => {
  it("reads COMPLETE when its session is gone, not `off`", () => {
    // `off` means never launched. A worker that finished and was then reclaimed is not that.
    const out = only([node("api", { done: 3, total: 3 })]);
    expect(out.health).toBe("complete");
    expect(out.activity).toBe("complete");
  });

  it("reads COMPLETE when its session is live but quiet, not `idle`", () => {
    const out = only([node("api", { done: 2, total: 2 })], sig({ livePaneIds: new Set(["proj:api"]) }));
    expect(out.health).toBe("complete");
    expect(out.activity).toBe("complete");
  });

  it("still reads OFF when there is no session AND work remains", () => {
    const out = only([node("api", { done: 1, total: 3 })]);
    expect(out.health).toBe("off");
    expect(out.activity).toBe("idle");
  });

  it("still reads IDLE when a live session has work left", () => {
    const out = only([node("api", { done: 1, total: 3 })], sig({ livePaneIds: new Set(["proj:api"]) }));
    expect(out.health).toBe("healthy");
    expect(out.activity).toBe("idle");
  });

  it("a node owning NO issues is unaffected — completion is not vacuously true", () => {
    // 0/0 must not read as finished, or every unplanned node in the graph would claim completion.
    expect(only([node("standing", { done: 0, total: 0 })]).health).toBe("off");
    expect(only([node("standing")]).health).toBe("off");
  });

  it("a session actively BUILDING still reads building", () => {
    // What it is doing right now is the more urgent fact — even with its planned issues closed, which
    // is exactly the maintenance case.
    const out = only(
      [node("api", { done: 2, total: 2 })],
      sig({ livePaneIds: new Set(["proj:api"]), paneStatus: { "proj:api": "run" } }),
    );
    expect(out.activity).toBe("building");
  });

  it("a QUARANTINED worker still reads error — completion never hides something to act on", () => {
    const out = only(
      [node("api", { done: 2, total: 2 })],
      sig({ quarantined: { "proj:api": { summary: "drifted" } } } as never),
    );
    expect(out.health).toBe("error");
  });

  it("a worker parked on a QUESTION still reads waiting", () => {
    // Blocked on a person outranks finished: the park is what needs resolving.
    const out = only(
      [node("api", { done: 2, total: 2 })],
      sig({ livePaneIds: new Set(["proj:api"]), waiting: [{ session: "proj:api", at: 0, reason: "which repo?" }] } as never),
    );
    expect(out.activity).toBe("waiting");
  });

  it("a MAINTAINING worker reads complete even after its session is reclaimed (#4124)", () => {
    // THE ONE THAT WAS ACTUALLY BITING. The maintaining branch sat BELOW the `!livePaneIds` gate, so it
    // was unreachable for exactly the worker it describes: a maintenance park means "finished, standing
    // by", and a standing-by session is the first thing a reaper or a restart takes. Once the pane left
    // `livePaneIds` the node fell to `off`/`idle`. Measured: 34 panes have emitted `maintain`.
    const out = only(
      [node("api")],                                   // no progress data at all — the signal is the park
      sig({ maintaining: new Set(["proj:api"]) } as never),
    );
    expect(out.health).toBe("complete");
    expect(out.activity).toBe("complete");
  });

  it("a maintaining worker whose session IS live still reads complete", () => {
    const out = only(
      [node("api")],
      sig({ livePaneIds: new Set(["proj:api"]), maintaining: new Set(["proj:api"]) } as never),
    );
    expect(out.health).toBe("complete");
  });

  it("maintenance still loses to quarantine — something to act on outranks finished", () => {
    const out = only(
      [node("api")],
      sig({ maintaining: new Set(["proj:api"]), quarantined: { "proj:api": { summary: "drifted" } } } as never),
    );
    expect(out.health).toBe("error");
  });

  it("says WHY, so the state is discoverable from the node's own reason", () => {
    expect(only([node("api", { done: 3, total: 3 })]).reason).toMatch(/every owned issue complete/);
  });
});

import { describe, it, expect } from "vitest";
import { partAroundPanel, PUSH_MARGIN, type MorphRect } from "@/features/glance/lib/glancePush";
import { NW, NH } from "@/features/glance/lib/glanceGraph";

// The open terminal panel (#2534/#2662) makes room by PARTING the graph into four rigid curtains (#2671,
// replacing the soft d3-force relaxation). The two properties that matter — and that the old soft force
// could NOT guarantee — are: (1) every neighbour clears the panel (no clipping), and (2) nodes keep their
// spacing (no node-into-node clipping). These are the regression tests for exactly those.
const RECT: MorphRect = { left: 500, top: 400, w: 760, h: 520 };

/** Does a node whose top-left is (x,y) still intersect the panel box? (true = clipping) */
const intersectsPanel = (x: number, y: number, r: MorphRect) =>
  !(x + NW <= r.left || x >= r.left + r.w || y + NH <= r.top || y >= r.top + r.h);

/** Apply a computed shift to a node's top-left. */
const shifted = (n: { id: string; x: number; y: number }, m: Map<string, { dx: number; dy: number }>) => {
  const d = m.get(n.id) ?? { dx: 0, dy: 0 };
  return { x: n.x + d.dx, y: n.y + d.dy };
};

describe("partAroundPanel (#2671 — rigid curtains make room for the open panel)", () => {
  it("leaves a node clear of the panel untouched", () => {
    expect(partAroundPanel([{ id: "far", x: 5000, y: 5000 }], RECT).has("far")).toBe(false);
  });

  it("excludes the grown node (it lives under the panel)", () => {
    const cx = RECT.left + RECT.w / 2 - NW / 2, cy = RECT.top + RECT.h / 2 - NH / 2;
    const m = partAroundPanel([{ id: "g", x: cx, y: cy }, { id: "a", x: cx - 120, y: cy }], RECT, "g");
    expect(m.has("g")).toBe(false);
  });

  it("pushes a node above the panel straight UP, not sideways", () => {
    // Centred horizontally, just above the top edge → the up curtain (vertical, dy<0, dx=0).
    const n = { id: "n", x: RECT.left + RECT.w / 2 - NW / 2, y: RECT.top - NH / 2 };
    const d = partAroundPanel([n], RECT).get("n")!;
    expect(d.dy).toBeLessThan(0);
    expect(d.dx).toBe(0);
  });

  it("pushes a node beside the panel straight OUT, not vertically", () => {
    // Centred vertically, near the right edge → the right curtain (horizontal, dx>0, dy=0).
    const n = { id: "n", x: RECT.left + RECT.w - NW / 2, y: RECT.top + RECT.h / 2 - NH / 2 };
    const d = partAroundPanel([n], RECT).get("n")!;
    expect(d.dx).toBeGreaterThan(0);
    expect(d.dy).toBe(0);
  });

  it("GUARANTEE: every overlapping node in a dense ring around the panel fully clears it (no clipping)", () => {
    // A grid of nodes blanketing the panel and its surroundings — the exact scenario that used to leave
    // residual overlap with the soft force.
    const nodes: { id: string; x: number; y: number }[] = [];
    for (let gx = -1; gx <= 9; gx++)
      for (let gy = -1; gy <= 7; gy++)
        nodes.push({ id: `${gx},${gy}`, x: RECT.left - 200 + gx * 150, y: RECT.top - 200 + gy * 130 });
    // Exclude whatever node sits nearest the panel centre (the grown one).
    const cx0 = RECT.left + RECT.w / 2, cy0 = RECT.top + RECT.h / 2;
    let ex = nodes[0].id, best = Infinity;
    for (const n of nodes) { const d = Math.hypot(n.x + NW / 2 - cx0, n.y + NH / 2 - cy0); if (d < best) { best = d; ex = n.id; } }

    const m = partAroundPanel(nodes, RECT, ex);
    for (const n of nodes) {
      if (n.id === ex) continue;
      const s = shifted(n, m);
      expect(intersectsPanel(s.x, s.y, RECT)).toBe(false); // fully cleared — the hard guarantee
    }
  });

  it("keeps a curtain RIGID: members keep their exact spacing (no node-into-node clipping)", () => {
    // Two nodes stacked directly above the panel — both land in the up curtain and MUST move together, or
    // the lower one would ram the upper one. A rigid block preserves their gap exactly.
    const cx = RECT.left + RECT.w / 2 - NW / 2;
    const lower = { id: "lower", x: cx, y: RECT.top - NH - 10 };       // overlaps → drives the shift
    const upper = { id: "upper", x: cx, y: lower.y - (NH + 40) };      // clear, but must ride along
    const m = partAroundPanel([lower, upper], RECT);
    const dLo = m.get("lower")!, dUp = m.get("upper")!;
    expect(dLo).toEqual(dUp);                                          // identical shift → rigid
    // Spacing before === spacing after.
    const gapBefore = lower.y - upper.y;
    const gapAfter = (lower.y + dLo.dy) - (upper.y + dUp.dy);
    expect(gapAfter).toBeCloseTo(gapBefore, 6);
    // And the overlapping member actually cleared.
    expect(intersectsPanel(lower.x + dLo.dx, lower.y + dLo.dy, RECT)).toBe(false);
  });

  it("clears the panel by at least the margin", () => {
    const n = { id: "n", x: RECT.left + RECT.w - NW / 2, y: RECT.top + RECT.h / 2 - NH / 2 };
    const d = partAroundPanel([n], RECT).get("n")!;
    const clearedLeftEdge = n.x + d.dx;                                // the node's new left edge
    expect(clearedLeftEdge).toBeGreaterThanOrEqual(RECT.left + RECT.w + PUSH_MARGIN - 1e-6);
  });

  it("is deterministic — the same rect yields the same shift (no jitter between frames)", () => {
    const nodes = [{ id: "a", x: 480, y: 420 }, { id: "b", x: 900, y: 660 }, { id: "c", x: 1300, y: 500 }];
    expect(partAroundPanel(nodes, RECT)).toEqual(partAroundPanel(nodes, RECT));
  });
});

import { describe, it, expect } from "vitest";
import {
  filterBlueprints, makeBlueprints, resolveProjectSeed, refreshBuiltIns, RETIRED_BLUEPRINT_IDS,
  type Blueprint,
} from "@/features/planner/stages/blueprints";
import { blueprintIcon, blueprintHue } from "@/features/planner/list/blueprintLibrary.helpers";

const bp = (id: string, name: string, over: Partial<Blueprint> = {}): Blueprint =>
  ({ id, name, desc: "", sections: [], ...over });

describe("the built-in blueprint library (#645/#3785)", () => {
  it("carries no lifecycle category — that left the blueprint model for discovery (#3785)", () => {
    // A blueprint is a goal/domain ROUTE now; lifecycle is discovered per project
    // (`ClassifyConfig.lifecycle`, #3784). Guard that nothing re-introduces the field.
    for (const b of makeBlueprints()) {
      expect(b, `${b.id} carries no category`).not.toHaveProperty("category");
    }
  });

  it("gives every built-in a DISTINCT tile glyph (#3785)", () => {
    const all = makeBlueprints();
    expect(all.find((b) => b.id === "default")!.mode).toBe("create");
    // Distinct per-domain glyphs are what replaced the one category-derived icon every card shared.
    // `blueprintIcon` is what the card actually renders: the declared `icon`, else the generic
    // grid — so `default` (the blank route, which declares none) reads as generic, by design.
    const icons = all.map(blueprintIcon);
    expect(new Set(icons).size, `distinct glyphs: ${icons.join(", ")}`).toBe(all.length);
  });

  it("drops RETIRED blueprint ids, so a stale config mirror cannot resurrect one (#3840)", () => {
    // Deleting the packaged JSON is not enough: `overlayGlob` APPENDS any config-dir file whose stem
    // it does not recognise, so an orphaned mirror copy re-introduces the blueprint on every install
    // that once shipped it — and `refreshBuiltIns` then treats it as code-owned. The tombstone is
    // what actually retires an id.
    const ids = makeBlueprints().map((b) => b.id);
    for (const dead of RETIRED_BLUEPRINT_IDS) {
      expect(ids, `${dead} is retired`).not.toContain(dead);
    }
    // …and a persisted copy is pruned from the store, not just hidden from the fresh library.
    const persisted = RETIRED_BLUEPRINT_IDS.map((id) =>
      ({ id, name: id, desc: "", origin: "built-in" as const, sections: [] }));
    const kept = refreshBuiltIns(persisted).map((b) => b.id);
    for (const dead of RETIRED_BLUEPRINT_IDS) expect(kept).not.toContain(dead);
  });

  it("gives every built-in a DISTINCT tile COLOUR (#3838)", () => {
    // The glyph alone was doing all the work: no packaged blueprint declared `h`, so every card
    // fell through to `blueprintHue`'s single fallback and all six tiles rendered the same amber.
    // (Older than #3823 — before it the colour came from the equally-degenerate `category`, which
    // was "greenfield" on every built-in.) A new blueprint without a hue must fail here, loudly,
    // rather than silently joining the fallback.
    const all = makeBlueprints();
    for (const b of all) expect(b.h, `${b.id} declares an accent hue`).toBeTypeOf("number");
    const hues = all.map((b) => blueprintHue(b.h));
    expect(new Set(hues).size, `distinct colours: ${hues.join(", ")}`).toBe(all.length);
  });

  it("the default blueprint's deployment stage is enabled so it shows in the plan (#672/#1914)", () => {
    const def = makeBlueprints().find((b) => b.id === "default")!;
    const deployment = def.sections.find((s) => s.key === "deployment")!;
    expect(deployment.enabled).toBe(true);
  });

  it("the default blueprint's skills stage is optional; ui/source/mcps/automations are required (#3785/#3905/#4249)", () => {
    const def = makeBlueprints().find((b) => b.id === "default")!;
    // #4249: `ui` LEFT the optional set. It carried both flags — `optional: true` AND
    // `appliesWhen: requiresUi` — and they mean opposite things: `optional` makes a stage always
    // applicable but skippable, while `appliesWhen` makes it `na` unless its signal fires. Carrying
    // both meant a project that genuinely needs a UI could skip the whole in-app pipeline. Now
    // `requiresUi` (= the stage is on AND the appType has screens) is the only thing deciding, so the
    // stage is absent for a CLI/API/library and REQUIRED for an app — which is the point of migrating
    // the Default blueprint onto the in-app designer.
    expect(def.sections.find((s) => s.key === "ui")!.optional).not.toBe(true);
    // #3905: skills JOINED them. It was non-optional, so its gate blocked triage on any project that
    // had attached no skills — and there is nothing to confirm on an empty stage. It self-enables
    // instead: `needsSkills || projectSkillCount > 0` in usePlanGates, so attaching any skill brings
    // the stage back. Optional here means "not a gate", not "unreachable".
    expect(def.sections.find((s) => s.key === "skills")!.optional).toBe(true);
    // #3785: Default absorbed Complete's advanced stages. These stay non-optional — hidden by default
    // via their `appliesWhen` signals rather than the `optional` flag.
    for (const key of ["ui", "source", "mcps", "automations"]) {
      const sec = def.sections.find((s) => s.key === key);
      expect(sec, `default has ${key}`).toBeTruthy();
      expect(sec!.optional, `${key} is not optional`).not.toBe(true);
    }
  });

  it("refreshBuiltIns updates stale persisted built-ins but keeps user blueprints (#677)", () => {
    // a stale persisted built-in (a bare UI section) + a user blueprint
    const stale: Blueprint = { id: "default", name: "Default", desc: "old", origin: "built-in",
      sections: [{ uid: "x", key: "ui", name: "UI", glyph: "▣", icon: "design_services", hue: 350, gate: "", deps: [], blurb: "", prompt: "", enabled: true, expanded: false }] };
    const mine: Blueprint = { id: "mine", name: "Mine", desc: "", origin: "local", sections: [] };
    const out = refreshBuiltIns([stale, mine]);
    // the built-in is refreshed from code → the UI section picks the packaged def back up, which
    // since #4249 is NOT optional (`requiresUi` alone decides whether it applies).
    expect(out.find((b) => b.id === "default")!.sections.find((s) => s.key === "ui")!.optional).not.toBe(true);
    expect(out.find((b) => b.id === "default")!.sections.find((s) => s.key === "ui")!.appliesWhen?.signal).toBe("requiresUi");
    // the user blueprint's content is preserved (refreshBuiltIns now canonicalizes section keys, #1914,
    // so it's a content-equal copy rather than the same reference)
    expect(out.find((b) => b.id === "mine")).toStrictEqual(mine);
    // #3785 made `default` the greenfield superset; #3783 adds the domain greenfields. refreshBuiltIns
    // refreshes the persisted `default` and APPENDS the new code-owned built-ins (ordered by `order`).
    expect(out.filter((b) => b.origin === "built-in").map((b) => b.id))
      .toEqual(["default", "crm", "erp", "helpdesk", "hr", "project-management"]);
  });

  it("prunes persisted built-ins that no longer exist in code, keeps user blueprints (#923)", () => {
    // a removed built-in (fullstack) lingering in the persisted store + a user blueprint
    const removed: Blueprint = { id: "fullstack", name: "Full-stack", desc: "", origin: "built-in", sections: [] };
    const mine: Blueprint = { id: "mine", name: "Mine", desc: "", origin: "local", sections: [] };
    const out = refreshBuiltIns([removed, mine]);
    expect(out.some((b) => b.id === "fullstack")).toBe(false); // pruned
    expect(out.find((b) => b.id === "mine")).toStrictEqual(mine); // user blueprint content preserved (#1914)
  });

  it("tags every built-in blueprint origin=built-in (#658)", () => {
    const all = makeBlueprints();
    expect(all.every((b) => b.origin === "built-in")).toBe(true);
    // The packaged set after #3785 consolidation + #3783: the greenfield superset Default plus the
    // five domain greenfields. (Complete + the transform/harden/data blueprints were merged in / archived.)
    for (const id of ["default", "crm", "erp", "helpdesk", "hr", "project-management"]) {
      expect(all.find((b) => b.id === id)!.origin, id).toBe("built-in");
    }
  });
});

